insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 139, 'ഗുഹ്യസ്ഥാനത്തിന്റെയും കാഴ്ചയുടെയും കേൾവിയുടെയും നാശത്തിൽ നിന്ന് കാവൽ ചോദിക്കൽ', 'بَابٌ: الْاِسْتِعَاذَةُ مِنْ شَرِّ السَّمْعِ وَالْبَصَرِ وَمِنْ شَرِّ الذَّكَرِ', 988 from books where volume_id=2 and book_no=13 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 140, 'ലുബ്ധത, ഭീരുത്വം, ദുഃഖം, വ്യസനം, അശക്തത, മടി, കടഭാരം, വാർദ്ധക്യം (വാർദ്ധക്യ സഹജമായ വിഷമം), ഹൃദയത്തിന്റെ ഫിത്ന, ഖബ്റ് ശിക്ഷ എന്നിവയിൽനിന്ന് കാവൽ ചോദിക്കൽ', 'بَابٌ: الْاِسْتِعَاذَةُ مِنَ الْجُبْنِ وَالْبُخْلِ مِنَ الْهَمِّ وَالْحَزَنِ وَالْكَسَلِ ضِلَعِ الدَّيْنِ وَ الْهَرَمِ وَغَلَبَةِ الرِّجَالِ وَفِتْنَةِ الصَّدْرِ وَعَذَابِ الْقَبْرِ', 988 from books where volume_id=2 and book_no=13 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
