insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ لَمْ يَدْعُ اللَّهَ سُبْحَانَهُ غَضِبَ عَلَيْهِ". (ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "അല്ലാഹുവിനോട് ദുആ ചെയ്യാത്തവനെ അവൻ ദേഷ്യം വെച്ചിരിക്കുന്നു." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 891, 891, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَيْسَ شَيْءٌ أَكْرَمَ عَلَى اللَّهِ سُبْحَانَهُ مِنَ الدُّعَاءِ". (ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "അല്ലാഹുവിന്റെയടുക്കൽ പ്രാർത്ഥനയേക്കാൾ ഉദാത്തമായ ഒന്നും തന്നെയില്ല." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 891, 891, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الدُّعَاءُ مُخُّ الْعِبَادَةِ". (ت)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറയുന്നു: "പ്രാർത്ഥന ആരാധനയുടെ മജ്ജയാകുന്നു." (തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 891, 891, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الدُّعَاءُ هُوَ الْعِبَادَةُ". ثُمَّ قَرَأَ: {وَقَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ إِنَّ الَّذِينَ يَسْتَكْبِرُونَ عَنْ عِبَادَتِي سَيَدْخُلُونَ جَهَنَّمَ دَاخِرِينَ} [غافر: ٦٠] حَسَنٌ صَحِيحٌ. (د,ت,جه)', 'നുഅ്മാനുബ്നു ബശീർ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം പ്രാർത്ഥന ആരാധനയാണ്. പിന്നെ അവിടന്ന് ഓതി: ''നിങ്ങളുടെ രക്ഷിതാവ് പറഞ്ഞിരിക്കുന്നു: നിങ്ങൾ എന്നോട് ചോദിക്കുക. ഞാൻ നിങ്ങൾക്ക് ഉത്തരം നൽകുന്നതാണ്. നിശ്ചയം, എനിക്ക് ആരാധന ചെയ്യാതെ അഹങ്കാരം കാണിക്കുന്നവർ നീചരായി നരകത്തിൽ പ്രവേശിക്കുന്നതാണ്.'' (ഗാഫിർ:60) (ദ,തു,ജ)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്മാനുബ്നു ബശീർ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], 'غافر: ٦٠', null, 891, 891, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ فِي دُعَائِهِ: "رَبِّ أَعِنِّي وَلَا تُعِنْ عَلَيَّ، وَانْصُرْنِي وَلَا تَنْصُرْ عَلَيَّ، وَامْكُرْ لِي وَلَا تَمْكُرْ عَلَيَّ وَاهْدِنِي وَيَسِّرِ الْهُدَى لِي، وَانْصُرْنِي عَلَى مَنْ بَغَى عَلَيَّ، رَبِّ اجْعَلْنِي لَكَ شَكَّارًا، لَكَ ذَكَّارًا، لَكَ رَهَّابًا، لَكَ مُطِيعًا، إِلَيْكَ مُخْبِتًا، إِلَيْكَ أَوَّاهًا مُنِيبًا. رَبِّ، تَقَبَّلْ تَوْبَتِي، وَاغْسِلْ حَوْبَتِي، وَأَجِبْ دَعْوَتِي، وَاهْدِ قَلْبِي وَسَدِّدْ لِسَانِي، وَثَبِّتْ حُجَّتِي، وَاسْلُلْ سَخِيمَةَ قَلْبِي". (د,ت,جه)', 'ഇബ്‌നുഅബ്ബാസ്(റ): റസൂൽ(സ) അവിടത്തെ പ്രാർത്ഥനയിൽ പറയുമായിരുന്നു: "എന്റെ രക്ഷിതാവേ, എന്നെ സഹായിക്കേണമേ, എനിക്കെതിരിൽ സഹായിക്കരുതേ, എനിക്ക് നീ വിജയം നൽകണേ, എന്നെ നീ പരാജയപ്പെടുത്തരുതേ, എനിക്ക് നീ കൗശലം ചെയ്ത് തരേണമേ, എനിക്കെതിരിൽ നീ കൗശലം ചെയ്യരുതേ, എന്നെ നേർമാർഗ്ഗത്തിലാക്കേണമേ, എനിക്ക് സന്മാർഗ പ്രാപ്തി എളുപ്പമാക്കേണേ, എന്നോട് അക്രമം ചെയ്യുന്നവർക്കുമേൽ എനിക്ക് വിജയം നൽകേണമേ, എന്റെ രക്ഷിതാവേ, എന്നെ നിനക്ക് ഏറ്റവും നന്ദി ചെയ്യുന്നവനും, നിന്നെ കൂടുതൽ സ്മരിക്കുന്നവനും, നിന്നെ ഏറ്റവും ഭയക്കുന്നവനും, നിനക്ക് കീഴ്പ്പെടുന്നവനും നിന്നോട് താഴ്മ ചെയ്യുന്നവനും നിന്നിലേക്ക് കരഞ്ഞ് മടങ്ങുന്നവനും ആക്കേണമേ. എന്റെ രക്ഷിതാവേ, എന്റെ തൗബ നീ സ്വീകരിക്കേണമേ, എന്റെ പാപം നീ കഴുകിക്കളയേണമേ, എന്റെ പ്രാർത്ഥനക്ക് നീ ഉത്തരം നൽകേണമേ, എന്റെ ഹൃദയത്തെ നീ നേർമാർഗ്ഗത്തിലാക്കേണമേ, എന്റെ നാവിനെ നീ ശരിയായി നിർത്തേണമേ, എന്റെ പ്രമാണം നീ സ്ഥിരപ്പെടുത്തേണമേ, എന്റെ ഹൃദയത്തിലെ വിദ്വേഷം നീ അകറ്റേണമേ." (ദ,തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്‌നുഅബ്ബാസ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 891, 892, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ فَرْوَةَ بْنِ نَوْفَلِ الْأَشْجَعِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْتُ عَائِشَةَ رَضِيَ اللهُ عَنْهَا عَمَّا كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَدْعُو بِهِ اللهَ عَزَّ وَجَلَّ؟ قَالَتْ: كَانَ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا عَمِلْتُ وَمِنْ شَرِّ مَا لَمْ أَعْمَلْ". (م,د,ن,جه)', 'ഫർവതുബിൻ നൗഫലിനിൽ അശ്ജഇൗ(റ): അല്ലാഹുവിന്റെ റസൂൽ(സ)യുടെ പ്രാർത്ഥനയെക്കുറിച്ച് ഞാൻ ആഇശ(റ)യോട് ചോദിച്ചു. അവർ പറഞ്ഞു: അവിടുന്ന് പറയുമായിരുന്നു: "അല്ലാഹുവേ, ഞാൻ ചെയ്തതിന്റെയും ചെയ്യാത്തതിന്റെയും നാശത്തിൽ നിന്ന് നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു." (മു,ദ,ന,ജ)', 'فَرْوَةَ بْنِ نَوْفَلِ الْأَشْجَعِيِّ', 'ഫർവതുബിൻ നൗഫലിനിൽ അശ്ജഇൗ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 892, 892, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: "اللَّهُمَّ لَكَ أَسْلَمْتُ، وَبِكَ آمَنْتُ، وَعَلَيْكَ تَوَكَّلْتُ، وَإِلَيْكَ أَنَبْتُ، وَبِكَ خَاصَمْتُ. اللَّهُمَّ إِنِّي أَعُوذُ بِعِزَّتِكَ لَا إِلَهَ إِلَّا أَنْتَ أَنْ تُضِلَّنِي، أَنْتَ الْحَيُّ الَّذِي لَا يَمُوتُ، وَالْجِنُّ وَالْإِنْسُ يَمُوتُونَ". (م)', 'ഇബ്‌നുഅബ്ബാസ്(റ): അല്ലാഹുവിന്റെ റസൂൽ(സ) പറയുമായിരുന്നു: "അല്ലാഹുവേ, നിനക്ക് ഞാൻ കീഴ്‌പെട്ടു. നിന്നിൽ ഞാൻ വിശ്വസിച്ചു. നിന്റെ മേൽ ഞാൻ ഭരമേൽപ്പിച്ചു. നിന്നിലേക്ക് ഞാൻ മടങ്ങി, നിന്റെ വിഷയത്തിൽ ഞാൻ തർക്കിച്ചു. അല്ലാഹുവേ, നീ എന്നെ വഴി കേടാക്കുന്നതിൽ നിന്ന് - നിന്റെ മഹത്വത്തിൽ നീയല്ലാതെ ഒരു ആരാധ്യനുമില്ല - ഞാൻ അഭയം ചോദിക്കുന്നു. നീ മരണം സംഭവിക്കാത്ത, നിത്യം ജീവിച്ചിരിക്കുന്നവനാകുന്നു. മനുഷ്യവർഗവും ജിന്ന് വർഗവും മറിച്ച് പോകുന്നവരാകുന്നു." (മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്‌നുഅബ്ബാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 892, 892, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا كَانَ فِي سَفَرٍ وَأَسْحَرَ يَقُولُ: "سَمِعَ سَامِعٌ بِحَمْدِ اللهِ وَحُسْنِ بَلَائِهِ عَلَيْنَا، رَبَّنَا صَاحِبْنَا وَأَفْضِلْ عَلَيْنَا، عَائِذًا بِاللهِ مِنَ النَّارِ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) യാത്രവേളയിൽ അത്താഴസമയത്ത് ഉണർന്നാൽ ഇങ്ങനെ പറയുമായിരുന്നു: "നമുക്ക് ചെയ്തുതന്ന മഹത്തായ അനുഗ്രഹങ്ങൾക്കും നാം അല്ലാഹുവിനെ സ്തുതിക്കുന്നതിനും സാക്ഷിയായവനിത് കേൾക്കുകയും മറ്റുള്ളവർക്കെത്തിക്കുകയും ചെയ്യട്ടെ. ഞങ്ങളുടെ നാഥാ, നീ ഞങ്ങളുടെ കൂടെയുണ്ടാകണേ. ഞങ്ങൾക്ക് നീ ഉദാരത ചെയ്യണേ. നരക ശിക്ഷയിൽ നിന്ന് അല്ലാഹുവോട് കാവൽ ചോദിക്കുകയും ചെയ്യുന്നു." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 892, 892, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَتْ فَاطِمَةُ رَضِيَ اللهُ عَنْهَا النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَسْأَلُهُ خَادِمًا، فَقَالَ لَهَا: "مَا عِنْدِي مَا أُعْطِيكِ". فَرَجَعَتْ، فَأَتَاهَا بَعْدَ ذَلِكَ فَقَالَ: "الَّذِي سَأَلْتِ أَحَبُّ إِلَيْكِ، أَوْ مَا هُوَ خَيْرٌ مِنْهُ؟". فَقَالَ لَهَا عَلِيٌّ: قُولِي لَا، بَلْ مَا هُوَ خَيْرٌ مِنْهُ. فَقَالَتْ، فَقَالَ: "قُولِي: اللَّهُمَّ رَبَّ السَّمَاوَاتِ السَّبْعِ وَرَبَّ الْعَرْشِ الْعَظِيمِ، رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، مُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيلِ وَالْقُرْآنِ الْعَظِيمِ، أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الْآخِرُ فَلَيْسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اقْضِ عَنَّا الدَّيْنَ وَأَغْنِنَا مِنَ الْفَقْرِ". (م,جه)', 'അബൂഹുറൈറ(റ): നബി(സ)യുടെ തിരുസന്നിധിയിൽ ഫാത്വിമ(റ) പരിചാരകനെ ആവശ്യപ്പെട്ട് വന്നു. അപ്പോൾ നബി(സ) അവരോട് പറഞ്ഞു: "നിനക്ക് തരാൻ എന്റെയടുക്കൽ ഒന്നുമില്ല." അപ്പോൾ ഫാത്വിമ(റ) മടങ്ങി. പിന്നീട് തിരുമേനി(സ) അവരുടെയടുത്ത് ചെന്ന് ചോദിച്ചു: "നീ ചോദിച്ചതാണോ നിനക്ക് ഏറ്റവും ഇഷ്ടപ്പെട്ടത് അതോ അതിനേക്കാൾ ഉത്തമമായ മറ്റു വല്ലതുമാണോ?" അപ്പോൾ അലി(റ) അവരോട് ഇപ്രകാരം പറയാൻ പറഞ്ഞു: അല്ല, അതിനേക്കാൾ ഉത്തമമായതാണ്. ഫാത്വിമ(റ) (അപ്രകാരം) പറഞ്ഞു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നീ പറയുക, അല്ലാഹുവേ, ഏഴാകാശങ്ങളുടെ രക്ഷിതാവേ, ഉന്നതമായ സിംഹാസനത്തിന്റെ രക്ഷിതാവേ, ഞങ്ങളുടെ രക്ഷിതാവേ, സർവ്വ വസ്തുക്കളുടെയും രക്ഷിതാവേ, തൗറാത്തും ഇൻജീലും മഹത്തായ ഖുർആനും ഇറക്കിയവനേ, നീയാണ് തുടക്കം, നിനക്ക് മുമ്പ് ഒന്നും ഇല്ല. നീ തന്നെയാണ് അന്ത്യവും. നിനക്ക് ശേഷം ഒന്നുമില്ല. നീയാണ് പ്രത്യക്ഷൻ. നിനക്ക് മുകളിലായി ഒന്നുമില്ല. നീയാണ് പരോക്ഷമായവൻ, നിനക്ക് താഴെ ഒന്നുമില്ല. നീ ഞങ്ങളുടെ കടം വീട്ടേണമേ; ദാരിദ്ര്യത്തിന് പകരം ഐശ്വര്യം ഞങ്ങൾക്ക് നീ നൽകേണമേ." (മു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 892, 893, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ كَانَ يَقُولُ: "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى". (م,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) പറയുമായിരുന്നു: "അല്ലാഹുവേ, സൻമാർഗവും, ഭക്തിയും, സദാചാരവും, ഐശ്വര്യവും നിന്നോട് ഞാൻ ചോദിക്കുന്നു." (മു,തു,ജ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 893, 893, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ كَانَ يَدْعُو بِهَذَا الدُّعَاءِ: "اللَّهُمَّ اغْفِرْ لِي خَطِيئَتِي وَجَهْلِي، وَإِسْرَافِي فِي أَمْرِي، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي. اللَّهُمَّ اغْفِرْ لِي جِدِّي وَهَزْلِي، وَخَطَئِي وَعَمْدِي، وَكُلُّ ذَلِكَ عِنْدِي. اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ، وَأَنْتَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ". (م)', 'അബൂമൂസൽ അശ്അരി(റ): നബി(സ) ഇങ്ങനെ പ്രാർത്ഥിക്കാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ, എന്റെ കുറ്റവും അറിവില്ലായ്മയും, എന്റെ കാര്യത്തിൽ ഞാൻ ചെയ്യുന്ന അമിതവ്യയവും നീ എന്നെക്കാൾ അറിയുന്ന കാര്യങ്ങളെയും എനിക്ക് നീ പൊറുത്ത് തരേണമേ, അല്ലാഹുവേ, ഞാൻ കാര്യമായി ചെയ്യുന്നതും, തമാശയായി ചെയ്യുന്നതും, തെറ്റായി സംഭവിക്കുന്നതും, അറിഞ്ഞു ചെയ്യുന്നതും എന്നിൽനിന്ന് വരുന്നതുമെല്ലാം എനിക്ക് പൊറുത്തു തരേണമേ. അല്ലാഹുവേ, ഞാൻ മുമ്പുചെയ്തതും ഇനി ചെയ്യാനുള്ളതും രഹസ്യമായി ചെയ്തതും പരസ്യമാക്കിയതും എന്നേക്കാൾ നിനക്കറിയാവുന്നവയും എനിക്ക് പൊറുത്തു തരേണമേ. നീയാണ് മുന്തിക്കുന്നവനും പിന്തിക്കുന്നവനും, എന്തിനും കഴിവുള്ളവനും നീ തന്നെയാണ്." (മു)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമൂസൽ അശ്അരി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 893, 893, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُكْثِرُ أَنْ يَقُولَ: "اللَّهُمَّ، ثَبِّتْ قَلْبِي عَلَى دِينِكَ" فَقَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ، تَخَافُ عَلَيْنَا، وَقَدْ آمَنَّا بِكَ وَصَدَّقْنَاكَ بِمَا جِئْتَ بِهِ؟ فَقَالَ: "إِنَّ الْقُلُوبَ بَيْنَ إِصْبَعَيْنِ مِنْ أَصَابِعِ الرَّحْمَنِ عَزَّ وَجَلَّ، يُقَلِّبُهَا". [ز: في سنده ضعيف] (جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) വളരെ കൂടുതലായി ഇപ്രകാരം പറയുമായിരുന്നു: "അല്ലാഹുവേ, എന്റെ ഹൃദയത്തെ നിന്റെ ദീനിൽ നീ ഉറപ്പിച്ച് നിർത്തേണമേ." അപ്പോൾ ഒരു വ്യക്തി ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അവിടത്തെ വിശ്വസിക്കുകയും അവിടുന്ന് കൊണ്ടുവന്നതിനെ വാസ്തവമാക്കുകയും ചെയ്ത ഞങ്ങളുടെ വിഷയത്തിൽ അവിടുന്ന് ഭയക്കുന്നുവോ? അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിശ്ചയം റഹ്മാന്റെ (അല്ലാഹുവിന്റെ) വിരലുകളിൽപ്പെട്ട രണ്ട് വിരലുകൾക്കിടയിലാണ് ഹൃദയങ്ങളുള്ളത്. അവൻ അവയെ മറിച്ച് കൊണ്ടിരിക്കും." (പരമ്പരയിൽ ഒരാൾ ദുർബ്ബലനാണ്.) (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', 'പരമ്പരയിൽ ഒരാൾ ദുർബ്ബലനാണ്.', 893, 894, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللَّهُ عَنْهُمَا، عَنْ أَبِي بَكْرِ الصِّدِّيقِ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ قَالَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: عَلِّمْنِي دُعَاءً أَدْعُو بِهِ فِي صَلَاتِي. قَالَ: "قُلْ: اللَّهُمَّ، إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا، وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ وَارْحَمْنِي، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ". (ق,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറുബ്നുൽആസ്(റ) അബൂബക്കർ(റ)വിൽ നിന്നും ഉദ്ധരിക്കുന്നു: അവർ റസൂൽ(സ)യോട് പറഞ്ഞു: എനിക്ക് നിസ്കാരത്തിൽ ദുആ ചെയ്യാൻ ഒരു പ്രാർത്ഥന പഠിപ്പിച്ച് തന്നാലും. അവിടനരുളി: "പറയുക: അല്ലാഹുവേ, ഞാൻ എന്റെ ശരീരത്തോട് ധാരാളം അക്രമം പ്രവർത്തിച്ചിരിക്കുന്നു. പാപങ്ങൾക്ക് മാപ്പ് തരുന്നവൻ നീ മാത്രമാണ്. അതിനാൽ നിന്റെ പക്കലുള്ള ഉന്നതമായ മാപ്പ് കൊണ്ട് എനിക്ക് നീ പൊറുത്ത് തരേണമേ. എന്നോട് കരുണ കാണിക്കുകയും ചെയ്യേണമേ, തീർച്ചയായും നീ അങ്ങേയറ്റം പൊറുത്തു കൊടുക്കുന്നവനും കരുണ കാണിക്കുന്നവനുമാകുന്നു." (ബു,മു,തു,ന,ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ', 'അബ്ദുല്ലാഹിബ്നു അംറുബ്നുൽആസ്(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 894, 894, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "اللَّهُمَّ أَصْلِحْ لِي دِينِي الَّذِي هُوَ عِصْمَةُ أَمْرِي، وَأَصْلِحْ لِي دُنْيَايَ الَّتِي فِيهَا مَعَاشِي، وَأَصْلِحْ لِي آخِرَتِي الَّتِي فِيهَا مَعَادِي، وَاجْعَلِ الْحَيَاةَ زِيَادَةً لِي فِي كُلِّ خَيْرٍ، وَاجْعَلِ الْمَوْتَ رَاحَةً لِي مِنْ كُلِّ شَرٍّ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ, എന്റെ കാര്യങ്ങളുടെ രക്ഷയായ എന്റെ ദീനിനെ നീ നന്നാക്കണേ, എന്റെ ജീവിതമാർഗമായ ദുനിയാവിനെയും, മടക്കസ്ഥലമായ ആഖിറത്തിനെയും നീ നന്നാക്കേണമേ. എന്റെ ജീവിതം സർവ്വനന്മകളാൽ നീ അധികരിപ്പിച്ച് തരേണമേ, മരണത്തെ മുഴുവൻ നാശങ്ങളിൽ നിന്നുമുള്ള ആശ്വാസവുമാക്കേണമേ." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 894, 894, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ أَبِي أُمَامَةَ الْبَاهِلِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ مُتَّكِئٌ عَلَى عَصًا، فَلَمَّا رَأَيْنَاهُ قُمْنَا. فَقَالَ: "لَا تَفْعَلُوا كَمَا يَفْعَلُ أَهْلُ فَارِسَ بِعُظَمَائِهَا". قُلْنَا: يَا رَسُولَ اللَّهِ، لَوْ دَعَوْتَ اللَّهَ لَنَا. قَالَ: "اللَّهُمَّ اغْفِرْ لَنَا، وَارْحَمْنَا، وَارْضَ عَنَّا. وَتَقَبَّلْ مِنَّا، وَأَدْخِلْنَا الْجَنَّةَ، وَنَجِّنَا مِنَ النَّارِ، وَأَصْلِحْ لَنَا شَأْنَنَا كُلَّهُ". قَالَ: فَكَأَنَّمَا أَحْبَبْنَا أَنْ يَزِيدَنَا. فَقَالَ: "أَوَلَيْسَ قَدْ جَمَعْتُ لَكُمُ الْأَمْرَ". (د,جه)', 'അബൂഉമാമതുൽ ബാഹിലി(റ): റസൂൽ(സ) ഒരു വടിയിൽ ചാരിക്കൊണ്ട് ഞങ്ങളുടെ അടുത്തേക്കു വന്നു. ഞങ്ങൾ അവിടത്തെ കണ്ടപ്പോൾ എണീറ്റ് നിന്നു. അപ്പോൾ അവിടനരുളി: "നിങ്ങൾ, പേർഷ്യക്കാർ അവരുടെ പ്രധാനികളോട് ചെയ്യുന്നത് പോലെ, ചെയ്യരുത്." ഞങ്ങൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞങ്ങൾക്ക് വേണ്ടി അല്ലാഹുവിനോട് ദുആ ചെയ്താലും. അവിടന്ന് ദുആഇരന്നു: "അല്ലാഹുവേ, നീ ഞങ്ങൾക്ക് മാപ്പ് നൽകി ഞങ്ങളുടെ കാര്യത്തിൽ കരുണ കാണിക്കേണമേ, ഞങ്ങളെ തൃപ്തിപ്പെടുകയും, ഞങ്ങളിൽ നിന്ന് മുഴുവൻ കാര്യങ്ങളും നീ സ്വീകരിക്കുകയും ചെയ്യേണമേ, ഞങ്ങളെ നരകത്തിൽ നിന്ന് രക്ഷപ്പെടുത്തി സ്വർഗത്തിൽ പ്രവേശിപ്പിക്കേണമേ, ഞങ്ങളുടെ മുഴുവൻ അവസ്ഥയും നന്മയിലാക്കേണമേ." അപ്പോൾ അവിടന്ന് കൂടുതലായി പ്രാർത്ഥിക്കാൻ ഞങ്ങൾ ആഗ്രഹിച്ചു. അപ്പോൾ തിരുമേനി(സ) ചോദിച്ചു: "ഞാൻ നിങ്ങളുടെ എല്ലാ കാര്യവും പറഞ്ഞില്ലയോ?" (ദ,ജ)', 'أَبِي أُمَامَةَ الْبَاهِلِيِّ', 'അബൂഉമാമതുൽ ബാഹിലി(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 894, 894, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ عَبْدِ اللَّهِ بْنِ جَعْفَرٍ رَضِيَ اللَّهُ عَنْهُمَا، عَنْ أُمِّهِ أَسْمَاءَ ابْنَةِ عُمَيْسٍ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: عَلَّمَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَلِمَاتٍ أَقُولُهُنَّ عِنْدَ الْكَرْبِ: "اللَّهُ، اللَّهُ رَبِّي، لَا أُشْرِكُ بِهِ شَيْئًا". (د)', 'അബ്ദുല്ലാബ്നു ജഅ്ഫർ(റ): തന്റെ മാതാവ് അസ്മാഅ്ബിൻത് ഉമൈസ്(റ)വിൽ നിന്ന് നിവേദനം ചെയ്യുന്നു: അവർ പറയുന്നു: റസൂൽ(സ) ചിലവാക്യങ്ങൾ എനിക്ക് പഠിപ്പിച്ചു. ബുദ്ധിമുട്ടുണ്ടാകുമ്പോൾ ഞാനത് ചൊല്ലാറുണ്ട്: "അല്ലാഹു, അല്ലാഹുവാണ് എന്റെ രക്ഷിതാവ്, അവനോട് ഞാൻ ഒന്നിനേയും പങ്ചേർക്കുകയില്ല." (ദ)', 'عَبْدِ اللَّهِ بْنِ جَعْفَرٍ', 'അബ്ദുല്ലാബ്നു ജഅ്ഫർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 894, 895, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ عِنْدَ الْكَرْبِ: "لَا إِلَهَ إِلَّا اللهُ الْحَلِيمُ الْكَرِيمُ، سُبْحَانَ اللهِ رَبِّ الْعَرْشِ الْعَظِيمِ، سُبْحَانَ اللهِ رَبِّ السَّمَوَاتِ السَّبْعِ وَرَبِّ الْعَرْشِ الْكَرِيمِ. وَفِي رِوَايَةٍ: "لَا إِلَهَ إِلَّا اللهُ،" فِيهَا كُلِّهَا. (ق,ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ബുദ്ധിമുട്ടുണ്ടാകുമ്പോൾ റസൂൽ(സ) ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: "സഹനശീലനും അത്യുദാരനുമായ അല്ലാഹുവല്ലാതെ ഒരു ആരാധ്യനുമില്ല, ശ്രേഷ്ഠമായ സിംഹാസനത്തിന്റെ രക്ഷിതാവായ അല്ലാഹു എത്ര പരിശുദ്ധനാകുന്നു. ഏഴാകാശങ്ങളുടെയും ഉന്നതമായ സിംഹാസനത്തിന്റെയും നാഥനായ അല്ലാഹു എത്ര പരിശുദ്ധനാകുന്നു."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=17), 1, 'وَفِي رِوَايَةٍ: "لَا إِلَهَ إِلَّا اللهُ،" فِيهَا كُلِّهَا. (ق,ت,جه)', 'മറ്റൊരു നിവേദനം: ഓരോ വാക്യത്തിലും "അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ല" എന്നുണ്ട്. (ബു,മു,തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ عِنْدَ الْكَرْبِ: "لَا إِلَهَ إِلَّا اللهُ الْعَظِيمُ الْحَلِيمُ، لَا إِلَهَ إِلَّا اللهُ رَبُّ الْعَرْشِ الْعَظِيمِ، لَا إِلَهَ إِلَّا اللهُ رَبُّ السَّمَوَاتِ وَرَبُّ الْأَرْضِ، وَرَبُّ الْعَرْشِ الْكَرِيمِ". (ق)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ)ക്ക് ബുദ്ധിമുട്ടുണ്ടാകുമ്പോൾ ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: "സഹനശീലനും ശ്രേഷ്ഠനുമായ അല്ലാഹുവല്ലാതെ ഒരു ആരാധ്യനുമില്ല, മഹത്തായ സിംഹാസനത്തിന്റെ രക്ഷിതാവായ അല്ലാഹുവല്ലാതെ മറ്റൊരു ആരാധ്യനുമില്ല, ആകാശങ്ങളുടെ രക്ഷിതാവായ, ഭൂമിയുടെ രക്ഷിതാവായ ശ്രേഷ്ഠമായ സിംഹാസനത്തിന്റെ രക്ഷിതാവായ അല്ലാഹുവല്ലാതെ ഒരു ആരാധ്യനുമില്ല." (ബു,മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 895, 895, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا أَهَمَّهُ الْأَمْرُ رَفَعَ رَأْسَهُ إِلَى السَّمَاءِ فَقَالَ: "سُبْحَانَ اللهِ الْعَظِيمِ". وَإِذَا اجْتَهَدَ فِي الدُّعَاءِ قَالَ: "يَا حَيُّ يَا قَيُّومُ". قَالَ تُرْمُذِي هَذَا حَدِيثٌ حَسَنٌ. (ت)', 'അബൂഹുറൈറ(റ): നബി(സ) വല്ല കാര്യത്തിലും അസ്വസ്ഥരായാൽ അവിടുന്ന് ആകാശത്തേക്ക് തിരുശിരസ്സുയർത്തി പറയാറുണ്ടായിരുന്നു. "ശ്രേഷ്ഠനായ അല്ലാഹു എത്ര പരിശുദ്ധനാകുന്നു." പ്രാർത്ഥനയിൽ അങ്ങേയറ്റമായാൽ അവിടുന്ന് പറയും: "എന്നെന്നും ജീവിക്കുന്നവനേ, എല്ലാം കൈകാര്യം ചെയ്യുന്നവനേ." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 895, 895, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهُ: "أَلَا أُعَلِّمُكَ كَلِمَاتٍ تَقُولُهَا إِذَا أَوَيْتَ إِلَى فِرَاشِكَ - وَفِي رِوَايَةٍ: وَأَنْتَ عَلَى وُضُوءٍ - فَإِنْ مِتَّ مِنْ لَيْلَتِكَ مِتَّ عَلَى الْفِطْرَةِ، وَإِنْ أَصْبَحْتَ أَصْبَحْتَ وَقَدْ أَصَبْتَ خَيْرًا؟ تَقُولُ: اللَّهُمَّ إِنِّي أَسْلَمْتُ نَفْسِي إِلَيْكَ، وَوَجَّهْتُ وَجْهِي إِلَيْكَ. وَفَوَّضْتُ أَمْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، لَا مَلْجَأَ وَلَا مَنْجَى مِنْكَ إِلَّا إِلَيْكَ. آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَنَبِيِّكَ الَّذِي أَرْسَلْتَ". قَالَ الْبَرَاءُ: فَقُلْتُ وَبِرَسُولِكَ الَّذِي أَرْسَلْتَ، قَالَ: فَطَعَنَ بِيَدِهِ فِي صَدْرِي ثُمَّ قَالَ: "وَنَبِيِّكَ الَّذِي أَرْسَلْتَ". حَسَنٌ صَحِيحٌ. (ق,د,ت)', 'ബറാഉബിൻ ആസിബ്(റ): നബി(സ) അവരോട് പറഞ്ഞു: "നീ വിരിപ്പിലേക്ക് പോകുമ്പോൾ പറയാൻ ചില വചനങ്ങൾ നിനക്ക് ഞാൻ പഠിപ്പിച്ച് തരട്ടെയോ. - മറ്റൊരു നിവേദനത്തിൽ: നീ വുളു ചെയ്ത് (വിരിപ്പിലേക്ക് പോകുമ്പോൾ) - അങ്ങനെ നീ രാത്രി മരിക്കുകയാണെങ്കിൽ ശുദ്ധ പ്രകൃതിയിൽ മരിക്കുകയും, നേരം പുലരുന്നുവെങ്കിൽ നന്മയോടെ നേരം പുലരുകയും ചെയ്യും. നീ പറയുക: അല്ലാഹുവേ, എന്റെ ശരീരത്തെ ഞാൻ നിന്നിലേൽപ്പിച്ചിരിക്കുന്നു. എന്റെ മുഖത്തെ ഞാൻ നിന്നിലേക്ക് തിരിക്കുന്നു. എന്റെ കാര്യങ്ങളെ ഞാൻ നിന്നെയേൽപ്പിക്കുന്നു. ആഗ്രഹത്തോട് കൂടെയും ഭക്തിയോട് കൂടെയും നിന്നിലേക്ക് വരുന്നു. എന്റെ മുതുകിനെ ഞാൻ നിന്നിലേൽപ്പിക്കുന്നു. നീയല്ലാതെ ഒരു അഭയ കേന്ദ്രമോ രക്ഷാ കേന്ദ്രമോ ഇല്ല. നീ ഇറക്കിയ ഗ്രന്ഥത്തിലും നീ അയച്ച നബിയിലും ഞാൻ വിശ്വസിക്കുന്നു." ബറാഅ്(റ) പറയുന്നു: അപ്പോൾ ഞാൻ പറഞ്ഞു: നീ അയച്ച റസൂലിലും. നിവേദകൻ തുടർന്നു: അപ്പോൾ അവിടുന്ന് എന്റെ നെഞ്ചിൽ തന്റെ കരങ്ങൾ കൊണ്ട് കുത്തി. എന്നിട്ട് പറഞ്ഞു: "നീ അയച്ച നബിയിലും." (ബു, മു,ദ,തു)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബിൻ ആസിബ്(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 895, 896, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=20), 1, 'وَفِي رِوَايَةٍ: وَأَنْتَ عَلَى وُضُوءٍ - فَإِنْ مِتَّ مِنْ لَيْلَتِكَ مِتَّ عَلَى الْفِطْرَةِ، وَإِنْ أَصْبَحْتَ أَصْبَحْتَ وَقَدْ أَصَبْتَ خَيْرًا؟ تَقُولُ: اللَّهُمَّ إِنِّي أَسْلَمْتُ نَفْسِي إِلَيْكَ، وَوَجَّهْتُ وَجْهِي إِلَيْكَ. وَفَوَّضْتُ أَمْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، لَا مَلْجَأَ وَلَا مَنْجَى مِنْكَ إِلَّا إِلَيْكَ. آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَنَبِيِّكَ الَّذِي أَرْسَلْتَ". قَالَ الْبَرَاءُ: فَقُلْتُ وَبِرَسُولِكَ الَّذِي أَرْسَلْتَ، قَالَ: فَطَعَنَ بِيَدِهِ فِي صَدْرِي ثُمَّ قَالَ: "وَنَبِيِّكَ الَّذِي أَرْسَلْتَ". حَسَنٌ صَحِيحٌ. (ق,د,ت)', 'മറ്റൊരു നിവേദനത്തിൽ: നീ വുളു ചെയ്ത് (വിരിപ്പിലേക്ക് പോകുമ്പോൾ) - അങ്ങനെ നീ രാത്രി മരിക്കുകയാണെങ്കിൽ ശുദ്ധ പ്രകൃതിയിൽ മരിക്കുകയും, നേരം പുലരുന്നുവെങ്കിൽ നന്മയോടെ നേരം പുലരുകയും ചെയ്യും. നീ പറയുക: അല്ലാഹുവേ, എന്റെ ശരീരത്തെ ഞാൻ നിന്നിലേൽപ്പിച്ചിരിക്കുന്നു. എന്റെ മുഖത്തെ ഞാൻ നിന്നിലേക്ക് തിരിക്കുന്നു. എന്റെ കാര്യങ്ങളെ ഞാൻ നിന്നെയേൽപ്പിക്കുന്നു. ആഗ്രഹത്തോട് കൂടെയും ഭക്തിയോട് കൂടെയും നിന്നിലേക്ക് വരുന്നു. എന്റെ മുതുകിനെ ഞാൻ നിന്നിലേൽപ്പിക്കുന്നു. നീയല്ലാതെ ഒരു അഭയ കേന്ദ്രമോ രക്ഷാ കേന്ദ്രമോ ഇല്ല. നീ ഇറക്കിയ ഗ്രന്ഥത്തിലും നീ അയച്ച നബിയിലും ഞാൻ വിശ്വസിക്കുന്നു." ബറാഅ്(റ) പറയുന്നു: അപ്പോൾ ഞാൻ പറഞ്ഞു: നീ അയച്ച റസൂലിലും. നിവേദകൻ തുടർന്നു: അപ്പോൾ അവിടുന്ന് എന്റെ നെഞ്ചിൽ തന്റെ കരങ്ങൾ കൊണ്ട് കുത്തി. എന്നിട്ട് പറഞ്ഞു: "നീ അയച്ച നബിയിലും." (ബു, മു,ദ,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ أَبِي أُمَامَةَ الْبَاهِلِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ أَوَى إِلَى فِرَاشِهِ طَاهِرًا، يَذْكُرُ اللَّهَ حَتَّى يُدْرِكَهُ النُّعَاسُ، لَمْ يَنْقَلِبْ سَاعَةً مِنَ اللَّيْلِ يَسْأَلُ اللَّهَ شَيْئًا مِنْ خَيْرِ الدُّنْيَا وَالْآخِرَةِ إِلَّا أَعْطَاهُ إِيَّاهُ". حَسَنٌ. (ت)', 'അബൂഉമാമതുൽ ബാഹിലിയ്യ്(റ): റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടിട്ടുണ്ട്: "ആരെങ്കിലും തന്റെ വിരിപ്പിലേക്ക് ശുദ്ധവാനായി പോകുകയും എന്നിട്ട് അല്ലാഹുവിനെ സ്മരിച്ച് കൊണ്ടിരിക്കെ ഉറങ്ങുകയും ചെയ്തു. പിന്നെ അവൻ ഉണർന്ന് അല്ലാഹുവിനോട് ദുൻയാവിന്റെയോ പരലോകത്തിന്റെയോ നന്മയിൽ നിന്ന് വല്ലതിനെയും ചോദിച്ചാൽ അല്ലാഹു നൽകുക തന്നെ ചെയ്യും." (തു)', 'أَبِي أُمَامَةَ الْبَاهِلِيِّ', 'അബൂഉമാമതുൽ ബാഹിലിയ്യ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 896, 896, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أَرَادَ أَحَدُكُمْ أَنْ يَضْطَجِعَ عَلَى فِرَاشِهِ فَلْيَنْزِعْ دَاخِلَةَ إِزَارِهِ، ثُمَّ لِيَنْفُضْ بِهَا فِرَاشَهُ، فَإِنَّهُ لَا يَدْرِي مَا خَلَفَهُ عَلَيْهِ. ثُمَّ لِيَضْطَجِعْ عَلَى شِقِّهِ الْأَيْمَنِ، ثُمَّ لِيَقُلْ: رَبِّ بِكَ وَضَعْتُ جَنْبِي وَبِكَ أَرْفَعُهُ، فَإِنْ أَمْسَكْتَ نَفْسِي فَارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا بِمَا حَفِظْتَ بِهِ عِبَادَكَ الصَّالِحِينَ". (خ,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "ആരെങ്കിലും തന്റെ വിരിപ്പിലേക്ക് കിടക്കാൻ പോകുകയാണെങ്കിൽ തന്റെ അടിവസ്ത്രം അഴിച്ച് വെക്കുകയും അത് കൊണ്ട് വിരിപ്പ് തട്ടി വൃത്തിയാക്കുകയും ചെയ്യട്ടെ, കാരണം അവൻ പോയതിനു ശേഷം ആ വിരിപ്പിൽ എന്തൊക്കെ കടന്നു വന്നു എന്ന് അവനറിയുകയില്ല. പിന്നെ തന്റെ വലതു ഭാഗത്തേക്ക് തിരിഞ്ഞ് കിടക്കുകയും ഇപ്രകാരം പറയുകയും ചെയ്യട്ടെ: നാഥാ, നിന്റെ നാമത്തിൽ എന്റെ ശരീരത്തെ ഞാനിതാ താഴെ വെക്കുന്നു. നിന്റെ നാമത്തിൽ തന്നെയായിരിക്കും ഞാൻ ഈ വിരിപ്പിൽ നിന്ന് എന്റെ ശരീരത്തെ ഉയർത്തുന്നതും. നീ എന്റെ ജീവനെ പിടിച്ചുവെക്കുന്നുവെങ്കിൽ അതിനോട് നീ കാരുണ്യം കാണിക്കേണമേ. (പിടിച്ചുവെക്കാതെ) അതിനെ വിട്ടയക്കുകയാണെങ്കിൽ സദ്വൃത്തരായ നിന്റെ ദാസൻമാരെ സംരക്ഷിക്കുന്ന വിധത്തിൽ അതിനെ നീ സംരക്ഷിക്കേണമേ.." (ബു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 896, 896, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا أَخَذَ مَضْجَعَهُ نَفَثَ فِي يَدَيْهِ، وَقَرَأَ بِالْمُعَوِّذَتَيْنِ، وَمَسَحَ بِهِمَا جَسَدَهُ. (خ,د,ت,جه)', 'ആഇശ(റ): നബി(സ) തന്റെ കിടപ്പറയിലേക്ക് ചെന്നാൽ ''മുഅവ്വിദതൈനി'' (സൂറതുൽ ഫലഖും, സൂറതുന്നാസും) ഓതി കയ്യിൽ ഊതുകയും അവിടുത്തെ തിരു മേനിയിൽ തടവുകയും ചെയ്യുമായിരുന്നു. (ബു,ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','د','ت','جه']::text[], array['ബു','ദ','തു','ജ']::text[], null, null, 896, 896, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ رَافِعِ بْنِ خَدِيجٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا اضْطَجَعَ أَحَدُكُمْ عَلَى جَنْبِهِ الْأَيْمَنِ ثُمَّ قَالَ: اللَّهُمَّ أَسْلَمْتُ نَفْسِي إِلَيْكَ، وَوَجَّهْتُ وَجْهِيَ إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، لَا مَلْجَأَ وَلَا مَنْجَى مِنْكَ إِلَّا إِلَيْكَ، أُومِنُ بِكِتَابِكَ وَبِرَسُولِكَ. فَإِنْ مَاتَ مِنْ لَيْلَتِهِ دَخَلَ الْجَنَّةَ". (ت)', 'റാഫിഉബിൻ ഖദീജ്(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ തന്റെ വലതു ഭാഗത്തേക്ക് തിരിഞ്ഞ് കിടക്കുകയും എന്നിട്ട് ഇങ്ങനെ പറയുകയും ചെയ്താൽ ആ രാത്രി അയാൾ മരിച്ചാൽ അവൻ സ്വർഗത്തിൽ പ്രവേശിക്കുന്നതാണ്: അല്ലാഹുവേ, എന്റെ ശരീരത്തെ നിന്നിലേൽപ്പിക്കുന്നു, എന്റെ മുഖത്തെ നിന്നിലേക്ക് ഞാൻ തിരിക്കുന്നു, എന്റെ മുതുകിനെ നിന്നിലേൽപ്പിക്കുന്നു, എന്റെ കാര്യങ്ങൾ മുഴുവനും നിന്നിലേൽപ്പിക്കുന്നു. നീയല്ലാതെ ഒരു രക്ഷാകേന്ദ്രവും ഒരു അഭയ കേന്ദ്രവും ഇല്ല തന്നെ. നിന്റെ കിതാബ് കൊണ്ടും നിന്റെ റസൂലിനെ കൊണ്ടും ഞാൻ വിശ്വസിക്കുകയും ചെയ്യുന്നു." (തു)', 'رَافِعِ بْنِ خَدِيجٍ', 'റാഫിഉബിൻ ഖദീജ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 896, 897, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا أَوَى إِلَى فِرَاشِهِ قَالَ "الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا وَكَفَانَا وَآوَانَا، فَكَمْ مِمَّنْ لَا كَافِيَ لَهُ وَلَا مُؤْوِيَ". حَسَنٌ صَحِيحٌ. (م,د,ت,ن)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) അവിടത്തെ വിരിപ്പിലേക്ക് പോകുമ്പോൾ ഇങ്ങനെ ചൊല്ലാറുണ്ടായിരുന്നു: "ഞങ്ങൾക്ക് മതിവരുവോളം ഭക്ഷണവും വെള്ളവും നൽകുകയും, ഞങ്ങളെ സംരക്ഷിക്കുകയും ചെയ്ത അല്ലാഹുവിനാണ് സർവ്വ സ്തുതിയും. ഒരു സംരക്ഷിക്കുന്നവനോ ഒരു മതിയായവനോ ഇല്ലാത്ത എത്രയെത്ര ആളുകളുണ്ട്." (മു,ദ,തു,ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 897, 897, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا أَوَى إِلَى فِرَاشِهِ، وَضَعَ يَدَهُ - يَعْنِي الْيُمْنَى - تَحْتَ خَدِّهِ، ثُمَّ قَالَ: "اللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ- أَوْ: تَجْمَعُ- عِبَادَكَ". [ز:منقطع] (جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) തന്റെ വിരിപ്പിലേക്ക് വന്നാൽ തന്റെ വലതുകരം കവിളിന് താഴെ വെക്കുകയും ഇപ്രകാരം പറയുകയും ചെയ്യുമായിരുന്നു: "അല്ലാഹുവേ, നിന്റെ അടിമകളെ പുനർജനിപ്പിക്കുന്ന - അല്ലെങ്കിൽ ഒരുമിച്ചുകൂട്ടുന്ന - ദിവസത്തിൽ നിന്റെ ശിക്ഷയിൽ നിന്ന് എന്നെ നീ രക്ഷപ്പെടുത്തേണമേ." (ഈ ഹദീസ് മുൻഖതിഅ് ആണ്). (ജ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز:منقطع', null, 897, 897, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُنَا يَأْمُرُنَا إِذَا أَخَذَ أَحَدُنَا مَضْجَعَهُ أَنْ يَقُولَ: "اللَّهُمَّ رَبَّ السَّمَوَاتِ وَرَبَّ الْأَرْضِينَ وَرَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، وَفَالِقَ الْحَبِّ وَالنَّوَى، وَمُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيلِ وَالْقُرْآنِ، أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ ذِي شَرٍّ أَنْتَ آخِذٌ بِنَاصِيَتِهِ، أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الْآخِرُ فَلَيْسَ بَعْدَكَ شَيْءٌ، وَالظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَالْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اقْضِ عَنِّي الدَّيْنَ وَأَغْنِنِي مِنَ الْفَقْرِ". حَسَنٌ صَحِيحٌ. (م,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): വിരിപ്പിൽ കിടക്കാൻ പോകുമ്പോൾ ഇപ്രകാരം പറയാൻ റസൂൽ(സ) ഞങ്ങളോട് കൽപിക്കാറുണ്ടായിരുന്നു: "ആകാശഭൂമികളുടെയും ഞങ്ങളുടെയും സർവ്വവസ്തുക്കളുടെയം രക്ഷിതാവായ, വിത്തുകളെയും ധാന്യങ്ങളെയും മുളപ്പിക്കുന്ന, തൗറാത്തിനേയും ഇൻജീലിനേയും ശ്രേഷ്ഠമായ ഖുർആനിനേയും ഇറക്കിയ അല്ലാഹുവേ, തിന്മചെയ്യുന്ന സർവ്വവസ്തുക്കളുടെയും തിന്മയിൽ നിന്ന് നിന്നോട് ഞാൻ കാവൽ ചോദിക്കൂ, അവ നിന്റെ അധീനതയിലാണ്. നീ ആദ്യവും അന്ത്യവുമാണ്, നിനക്ക് മുമ്പോ ശേഷമോ ഒന്നുമില്ല. നീയാണ് പ്രത്യക്ഷവും പരോക്ഷവും, നിനക്ക് മുകളിലോ നിനക്കപ്പുറമോ ഒന്നുമില്ല. എന്റെ കടം നീ വീട്ടുകയും, ദാരിദ്രത്തിന് പകരം എനിക്ക് ഐശ്വര്യം നൽകുകയും ചെയ്യേണമേ." (മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 897, 897, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا قَامَ أَحَدُكُمْ عَنْ فِرَاشِهِ ثُمَّ رَجَعَ إِلَيْهِ فَلْيَنْفُضْهُ بِصَنِفَةِ إِزَارِهِ ثَلَاثَ مَرَّاتٍ، فَإِنَّهُ لَا يَدْرِي مَا خَلَفَهُ عَلَيْهِ بَعْدُ، فَإِذَا اضْطَجَعَ فَلْيَقُلْ: بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي وَبِكَ أَرْفَعُهُ، فَإِنْ أَمْسَكْتَ نَفْسِي فَارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ. فَإِذَا اسْتَيْقَظَ فَلْيَقُلْ: الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي فِي جَسَدِي، وَرَدَّ عَلَيَّ رُوحِي، وَأَذِنَ لِي بِذِكْرِهِ". حسن. (خ،ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളാരെങ്കിലും വിരിപ്പിൽ നിന്ന് എഴുന്നേറ്റ് വീണ്ടും അതിൽ കിടക്കാൻ പോകുമ്പോൾ തന്റെ തുണിയുടെ കരകൊണ്ട് ആ വിരിപ്പ് മൂന്ന് തവണ തട്ടി വൃത്തിയാക്കട്ടെ. കാരണം എഴുന്നേറ്റ് പോയ ശേഷം ആ വിരിപ്പിൽ എന്തൊക്കെ കടന്നു വന്നു എന്ന് അവനറിയില്ല. അനന്തരം അവൻ ആ വിരിപ്പിൽ കിടന്നാൽ ഇപ്രകാരം പ്രാർത്ഥിച്ചു കൊള്ളട്ടെ: നാഥാ, നിന്റെ നാമത്തിൽ എന്റെ ശരീരത്തെ ഞാനിതാ താഴെ വെക്കുന്നു. നിന്റെ നാമത്തിൽ തന്നെയായിരിക്കും ഞാൻ ഈ വിരിപ്പിൽ നിന്ന് എന്റെ ശരീരത്തെ ഉയർത്തുന്നതും. നീ എന്റെ ജീവനെ പിടിച്ചുവെക്കുന്നുവെങ്കിൽ അതിനോട് നീ കാരുണ്യം കാണിക്കേണമേ. (പിടിച്ചുവെക്കാതെ) അതിനെ വിട്ടയക്കുകയാണെങ്കിൽ സദ്വൃത്തരായ നിന്റെ ദാസൻമാരെ സംരക്ഷിക്കുന്ന വിധത്തിൽ അതിനെ നീ സംരക്ഷിക്കേണമേ. അങ്ങനെ ഉറക്കമുണർന്നാൽ അവൻ പറയട്ടെ: എന്റെ ശരീരത്തിന് ആരോഗ്യം തന്ന, എന്നിലേക്ക് എന്റെ ആത്മാവിനെ മടക്കിത്തന്ന, തന്നെ സ്മരിക്കാൻ എനിക്ക് അനുവാദം തന്ന അല്ലാഹുവിനാണ് സർവ്വ സ്തുതിയും." (ബു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','ت']::text[], array['ബു','തു']::text[], null, null, 898, 898, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قَالَ حِينَ يَأْوِي إِلَى فِرَاشِهِ: أَسْتَغْفِرُ اللهَ الْعَظِيمَ، الَّذِي لَا إِلَهَ إِلَّا هُوَ الْحَيَّ الْقَيُّومَ وَأَتُوبُ إِلَيْهِ. ثَلَاثَ مَرَّاتٍ، غَفَرَ اللهُ لَهُ ذُنُوبَهُ وَإِنْ كَانَتْ مِثْلَ زَبَدِ الْبَحْرِ، وَإِنْ كَانَتْ عَدَدَ وَرَقِ الشَّجَرِ، وَإِنْ كَانَتْ عَدَدَ رَمْلِ عَالِجٍ، وَإِنْ كَانَتْ عَدَدَ أَيَّامِ الدُّنْيَا". حَدِيثٌ حَسَنٌ. (ت)', 'അബൂസഈദുൽ ഖുദ്‌രി(റ): നബി(സ) പറഞ്ഞു: "തന്റെ വിരിപ്പിലേക്ക് പോകുമ്പോൾ ആരെങ്കിലും: ഉന്നതനായ അല്ലാഹുവിനോട് ഞാൻ പാപമോചനം ചോദിക്കുന്നു, ജീവസ്സുറ്റവനും കൈകാര്യകർത്താവുമായ അവനല്ലാതെ ഒരു ആരാധ്യനില്ല, ഞാൻ അവനിലേക്ക് ഖേദിച്ച് മടങ്ങുന്നു, എന്ന് മൂന്ന് തവണ പറഞ്ഞാൽ അവന്റെ ദോശങ്ങൾ അല്ലാഹു പൊറുത്തു കൊടുക്കും, അത് കടലിലെ നുരയോളമുണ്ടായാലും, മരങ്ങളിലെ ഇലകളുടെ അത്രയായാലും, മണൽത്തരിയോളമുണ്ടായാലും, ദുനിയാവിലെ ദിവസങ്ങളുടെ എണ്ണത്തോളമായാലും." (തു)', 'أَبِي سَعِيدٍ', 'അബൂസഈദുൽ ഖുദ്‌രി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 898, 898, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ حُذَيْفَةَ بْنِ الْيَمَانِ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا أَرَادَ أَنْ يَنَامَ قَالَ: "اللَّهُمَّ بِاسْمِكَ أَمُوتُ وَأَحْيَا". وَإِذَا اسْتَيْقَظَ قَالَ: "الْحَمْدُ لِلَّهِ الَّذِي أَحْيَا نَفْسِي بَعْدَ مَا أَمَاتَهَا وَإِلَيْهِ النُّشُورُ". حَسَنٌ صَحِيحٌ. (خ،د،ت،جه)', 'ഹുദൈഫതുബ്നുൽ യമാൻ(റ): റസൂൽ(സ) ഉറങ്ങാൻ ഉദ്ദേശിച്ചാൽ പറയുമായിരുന്നു: "അല്ലാഹുവേ, നിന്റെ പേരു കൊണ്ട് ഞാൻ മരിക്കുകയും ജീവിക്കുകയും ചെയ്യുന്നു." ഉണർന്നാൽ അവിടന്ന് പറയും: "എന്റെ ശരീരത്തെ മരിപ്പിച്ചതിന് ശേഷം ജീവിപ്പിച്ച അല്ലാഹുവിനാണ് സർവ്വസ്തുതിയും, അവനിലേക്ക് തന്നെയാണ് മടക്കവും." (ബു,ദ,തു,ജ)', 'حُذَيْفَةَ بْنِ الْيَمَانِ', 'ഹുദൈഫതുബ്നുൽ യമാൻ(റ)', null, null, array['خ','د','ت','جه']::text[], array['ബു','ദ','തു','ജ']::text[], null, null, 898, 898, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا أَوَى إِلَى فِرَاشِهِ كُلَّ لَيْلَةٍ جَمَعَ كَفَّيْهِ ثُمَّ نَفَثَ فِيهِمَا، فَقَرَأَ فِيهِمَا: {قُلْ هُوَ اللَّهُ أَحَدٌ} {وَقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ} {وَقُلْ أَعُوذُ بِرَبِّ النَّاسِ} ثُمَّ يَمْسَحُ بِهِمَا مَا اسْتَطَاعَ مِنْ جَسَدِهِ، يَبْدَأُ بِهِمَا عَلَى رَأْسِهِ وَوَجْهِهِ وَمَا أَقْبَلَ مِنْ جَسَدِهِ، يَفْعَلُ ذَلِكَ ثَلَاثَ مَرَّاتٍ. حَسَنٌ. (ت)', 'ആഇശ(റ): എല്ലാ ദിവസവും ഉറങ്ങാൻ പോകുമ്പോൾ നബി(സ) മുൻകൈകൾ ഒരുമിച്ച് വെച്ച് ഇഖ്‌ലാസ്, ഫലഖ്, നാസ് എന്നീ സൂറത്തുകൾ ഓതി തിരുക്കയ്യിൽ ഊതും. എന്നിട്ട് തിരു ശരീരത്തിൽ സാധ്യമാവുന്നിടത്തെല്ലാം തടവും. ഇരുകൈകൊണ്ടുമുള്ള തടവൽ തല, മുഖം, ശരീരത്തിന്റെ മുൻഭാഗം എന്നിവയിൽ നിന്ന് ആരംഭിക്കും. ഇങ്ങനെ മൂന്ന് തവണ ചെയ്യും. (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 898, 899, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ فَرْوَةَ بْنِ نَوْفَلٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، عَلِّمْنِي شَيْئًا أَقُولُهُ إِذَا أَوَيْتُ إِلَى فِرَاشِي. قَالَ: "اقْرَأْ: {قُلْ يَا أَيُّهَا الْكَافِرُونَ} فَإِنَّهَا بَرَاءَةٌ مِنَ الشِّرْكِ". (ت)', 'ഫർവതുബ്നു നൗഫൽ(റ): അവർ നബി(സ)യെ സമീപിച്ച് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ ഉറങ്ങാൻ പോകുമ്പോൾ ചൊല്ലാനുള്ള എന്തെങ്കിലും എന്നെ പഠിപ്പിച്ചാലും. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ ''ഖുൽ യാ അയ്യുഹൽ കാഫിറൂൻ'' എന്ന അധ്യായം ഓതുക. കാരണം അത് പങ്ക് ചേർക്കലിൽ നിന്നുള്ള (ശിർക്കിൽ നിന്നുള്ള) രക്ഷയാണ്." (തു)', 'فَرْوَةَ بْنِ نَوْفَلٍ', 'ഫർവതുബ്നു നൗഫൽ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 899, 899, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا يَنَامُ حَتَّى يَقْرَأَ بِ: {تَنْزِيلُ} السَّجْدَةِ، وَ{تَبَارَكَ}. (ت)', 'ജാബിർ(റ): ''(തൻസീൽ)സജദഃ'', ''(തബാറക)മുൽക്'' എന്നീ രണ്ട് സൂറത്തുകൾ ഓതാതെ നബി(സ) ഉറങ്ങുമായിരുന്നില്ല. (തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 899, 899, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا يَنَامُ حَتَّى يَقْرَأَ الزُّمَرَ وَبَنِي إِسْرَائِيلَ. (ت)', 'ആഇശ(റ): സുമർ(റ), ബനൂഇസ്റാഈൽ എന്നീ സൂറത്തുകൾ ഓതാതെ നബി(സ) ഉറങ്ങുമായിരുന്നില്ല. (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 899, 899, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنِ الْعِرْبَاضِ بْنِ سَارِيَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ لَا يَنَامُ حَتَّى يَقْرَأَ الْمُسَبِّحَاتِ، وَيَقُولُ: "فِيهَا آيَةٌ خَيْرٌ مِنْ أَلْفِ آيَةٍ". حَسَنٌ. (ت)', 'ഹിർബാളുബ്നു സാരിയ(റ): ''മുസബ്വിഹാത്'' ഓതുന്നത് വരെ റസൂൽ(സ) ഉറങ്ങുമായിരുന്നില്ല. റസൂൽ(സ) ഇപ്രകാരം പറയുകയും ചെയ്യുമായിരുന്നു. "അതിൽ 1000 സൂക്തങ്ങളേക്കാൾ ഉത്തമമായ ഒരു സൂക്തമുണ്ട്." (തു)', 'الْعِرْبَاضِ بْنِ سَارِيَةَ', 'ഹിർബാളുബ്നു സാരിയ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 899, 899, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ بُرَيْدَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: شَكَا خَالِدُ بْنُ الْوَلِيدِ الْمَخْزُومِيُّ رَضِيَ اللَّهُ عَنْهُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، مَا أَنَامُ اللَّيْلَ مِنَ الْأَرَقِ؟ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا أَوَيْتَ إِلَى فِرَاشِكَ فَقُلِ: اللَّهُمَّ رَبَّ السَّمَوَاتِ السَّبْعِ وَمَا أَظَلَّتْ، وَرَبَّ الْأَرَضِينَ وَمَا أَقَلَّتْ، وَرَبَّ الشَّيَاطِينِ وَمَا أَضَلَّتْ، كُنْ لِي جَارًا مِنْ شَرِّ خَلْقِكَ كُلِّهِمْ جَمِيعًا أَنْ يَفْرُطَ عَلَيَّ أَحَدٌ مِنْهُمْ أَوْ أَنْ يَبْغِيَ، عَزَّ جَارُكَ وَجَلَّ ثَنَاؤُكَ، وَلَا إِلَهَ غَيْرُكَ، لَا إِلَهَ إِلَّا أَنْتَ". (ت)', 'ബുറൈദ(റ): ഖാലിദുബിൻ വലീദ് അൽ മഖ്സൂമീ(റ) റസൂൽ (സ)യോട് പരാതി പറഞ്ഞു: തിരുദൂതരേ, എനിക്ക് രാത്രി ഉറക്കമില്ലായ്മ വരുന്നു? തിരുമേനി(സ) പറഞ്ഞു: “നീ നിന്റെ വിരിപ്പിലേക്ക് ചെന്നാൽ പറയുക. ഏഴാകാശങ്ങളുടെയും തണലിടുന്ന വസ്തുക്കളുടെയും രക്ഷിതാവേ, ഭൂമികളുടെയും അത് ചുമന്നിരിക്കുന്ന എല്ലാ വസ്തുക്കളുടെയും രക്ഷിതാവേ, എല്ലാ പിശാചുക്കളുടെയും അവ പിഴപ്പിച്ചവയുടെയും രക്ഷിതാവേ, നിന്റെ എല്ലാ സൃഷ്ടികളുടെയും തിന്മയിൽ നിന്ന് നീ എനിക്ക് സഹായി ആകേണമേ. നിന്റെ എല്ലാ ഓരോ സൃഷ്ടികളുടെയും തിന്മയിൽ നിന്ന്, അവർ എന്റെ മേൽ അതിക്രമമോ, അക്രമമോ ചെയ്യുന്നതിൽ നിന്ന് നീ എനിക്ക് സഹായി ആകേണമേ, നിന്റെ സഹായം അന്തസ്സുറ്റതാകുന്നു, നിന്റെ കീർത്തനങ്ങൾ ഉന്നതമാണ്, നീ അല്ലാത്ത ഒരു ആരാധ്യനില്ല, ആരാധ്യൻ നീ മാത്രമാകുന്നു.” (തു)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 899, 900, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا فَزِعَ أَحَدُكُمْ فِي النَّوْمِ فَلْيَقُلْ: أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ غَضَبِهِ وَعِقَابِهِ وَشَرِّ عِبَادِهِ، وَمِنْ هَمَزَاتِ الشَّيَاطِينِ وَأَنْ يَحْضُرُونِ، فَإِنَّهَا لَنْ تَضُرَّهُ". وَكَانَ عَبْدُ اللَّهِ بْنُ عُمَرَ يُلَقِّنُهَا مَنْ بَلَغَ مِنْ وَلَدِهِ، وَمَنْ لَمْ يَبْلُغْ مِنْهُمْ كَتَبَهَا فِي صَكٍّ ثُمَّ عَلَّقَهَا فِي عُنُقِهِ. حَسَنٌ. (د,ت)', 'അബ്ദുല്ലാഹിബിനു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: “നിങ്ങളാരെങ്കിലും ഉറക്കത്തിൽ പേടിച്ചാൽ അവൻ പറയട്ടെ: അല്ലാഹുവിന്റെ ദേഷ്യത്തിൽ നിന്നും അവന്റെ ശിക്ഷയിൽ നിന്നും അവന്റെ അടിമകളുടെ നാശത്തിൽ നിന്നും പിശാചുക്കളുടെ ദുർബോധനത്തിൽ നിന്നും അവരുടെ വരവിൽ നിന്നും അല്ലാഹുവിന്റെ സമ്പൂർണ്ണമായ കലിമകൾ കൊണ്ട് ഞാൻ കാവൽ ചോദിക്കുന്നു. എങ്കിൽ അവനെ അവ തീരെ ഉപദ്രവിക്കുകയില്ല.” അബ്ദല്ലാഹിബ്നു ഉമർ(റ) തന്റെ പ്രായപൂർത്തിയെത്തിയ മക്കൾക്ക് ഇത് പഠിപ്പിച്ച് കൊടുക്കുകയും എത്താത്തവർക്ക് ഒരു കടലാസ് തുണ്ടിൽ അതഴുതി കഴുത്തിൽ കെട്ടികൊടുക്കുകയും ചെയ്യുമായിരുന്നു. (ദ,തു)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബിനു അംറ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 900, 900, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ تَعَارَّ مِنَ اللَّيْلِ، فَقَالَ حِينَ يَسْتَيْقِظُ: لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ. ثُمَّ دَعَا: رَبِّ اغْفِرْ لِي، غُفِرَ لَهُ". أَوْ قَالَ: "دَعَا، اسْتُجِيبَ لَهُ. فَإِنْ قَامَ فَتَوَضَّأَ ثُمَّ صَلَّى، قُبِلَتْ صَلَاتُهُ". (خ,د,ت,جه)', 'ഉബാദതുബ്നു സ്വാമിത്(റ): റസൂൽ(സ) പറഞ്ഞു: “ആരെങ്കിലും രാത്രി ഉണരുകയും എഴുന്നേൽക്കുന്ന സമയത്ത്: അല്ലാഹുവല്ലാതെ ഒരു ആരാധ്യനുമില്ല. അവൻ ഏകനാണ്. അവന് പങ്കുകാരില്ല. അവനാണ് സർവ്വാധികാരം, അവനാണ് സർവ്വസ്തുതികളും. അവൻ എല്ലാറ്റിനും കഴിവുള്ളവനാണ്. അല്ലാഹു വളരെ പരിശുദ്ധനാണ്. അല്ലാഹുവിനാണ് സർവ്വ സ്തുതിയും. അല്ലാഹുവല്ലാതെ ഇലാഹില്ല. അല്ലാഹു വലിയവനാകുന്നു. മഹാനും ഉന്നതനുമായ അല്ലാഹുവിനെക്കൊണ്ടല്ലാതെ ഒരു ശക്തിയും കഴിവുമില്ല. എന്ന് പറയുകയും പിന്നെ അവൻ: നാഥാ, എനിക്ക് പൊറുത്തു തരേണമേ, എന്ന് പ്രാർത്ഥിക്കുകയും ചെയ്താൽ അവന്റെ പാപങ്ങൾ പൊറുക്കപ്പെടും.”
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ رَبِيعَةَ بْنِ كَعْبٍ الْأَسْلَمِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ كَانَ يَبِيتُ عِنْدَ بَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَكَانَ يَسْمَعُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ مِنَ اللَّيْلِ: "سُبْحَانَ اللَّهِ رَبِّ الْعَالَمِينَ". الْهَوِيَّ، ثُمَّ يَقُولُ: "سُبْحَانَ اللَّهِ وَبِحَمْدِهِ". (م,د,ت,ن,جه)', 'റബീഉബ്‌നു കഅ്ബുൽ അസ്‌ലമി(റ): റസൂൽ(സ)യുടെ വാതിലിനരികിൽ അദ്ദേഹം ഉറങ്ങാറുണ്ടായിരുന്നു. രാത്രിയിൽ നബി(സ) ഇങ്ങനെ പതിഞ്ഞ സ്വരത്തിൽ പറയുന്നത് അവർ കേൾക്കുമായിരുന്നു. "ലോക രക്ഷിതാവായ അല്ലാഹുവിനെ ഞാൻ വാഴ്ത്തുന്നു." പിന്നെ റസൂൽ (സ) പറയുമായിരുന്നു: "അല്ലാഹുവിനെ ഞാൻ വാഴ്ത്തുന്നു. അവനാണ് സർവ്വ സ്തുതിയും." (മു,ദ,തു,ന,ജ)', 'رَبِيعَةَ بْنِ كَعْبٍ الْأَسْلَمِيِّ', 'റബീഉബ്‌നു കഅ്ബുൽ അസ്‌ലമി(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 900, 901, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ حُذَيْفَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا انْتَبَهَ مِنَ اللَّيْلِ قَالَ: "الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا، وَإِلَيْهِ النُّشُورُ". (خ,د,جه)', 'ഹുദൈഫ(റ): രാത്രിയുണർന്നാൽ റസൂൽ (സ) പറയുമായിരുന്നു. "നമ്മെ മരിപ്പിച്ച ശേഷം ജീവിപ്പിച്ച അല്ലാഹുവിനാണ് സർവ്വ സ്തുതിയും. അവനിലേക്ക് തന്നെയാണ് മടക്കവും." (ബു,ദ,ജ)', 'حُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, null, array['خ','د','جه']::text[], array['ബു','ദ','ജ']::text[], null, null, 901, 901, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ عَبْدٍ بَاتَ عَلَى طَهُورٍ، ثُمَّ تَعَارَّ مِنَ اللَّيْلِ، فَسَأَلَ اللَّهَ شَيْئًا مِنْ أَمْرِ الدُّنْيَا أَوْ مِنْ أَمْرِ الْآخِرَةِ، إِلَّا أَعْطَاهُ". (د,جه)', 'മുആദുബ്നു ജബൽ(റ): തിരുമേനി(സ) പറഞ്ഞു: "ആരെങ്കിലും ശുദ്ധനായി രാത്രി ഉറങ്ങി, രാത്രിയിൽ ഉറക്കമെഴുന്നേറ്റു. എന്നിട്ട് ദുനിയാവിന്റെയോ ആഖിറത്തിന്റെയോ കാര്യത്തിൽപ്പെട്ട വല്ലതും അല്ലാഹുവിനോട് ചോദിക്കുകയും ചെയ്താൽ അത് നൽകപ്പെടാത്ത ഒരു അടിമയുമില്ല." (ദ,ജ)', 'مُعَاذِ بْنِ جَبَلٍ', 'മുആദുബ്നു ജബൽ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 901, 901, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ حُذَيْفَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَخَذَ مَضْجَعَهُ مِنَ اللَّيْلِ، وَضَعَ يَدَهُ تَحْتَ خَدِّهِ، ثُمَّ يَقُولُ: "اللَّهُمَّ بِاسْمِكَ أَمُوتُ وَأَحْيَا". وَإِذَا اسْتَيْقَظَ قَالَ: "الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ". (خ)', 'ഹുദൈഫതുബ്നുൽ യമാൻ(റ): നബി(സ) രാത്രി തന്റെ കിടപ്പറയിലെത്തിയാൽ തന്റെ കൈ കവിളിന് അടിയിൽ വെക്കും. എന്നിട്ട് പറയും: "അല്ലാഹുവേ, നിന്റെ നാമത്തിൽ ഞാൻ മരിക്കുകയും, ജീവിക്കുകയും ചെയ്യും." ഉറക്കമുണർന്നാൽ പറയും: "നമ്മെ മരിപ്പിച്ച ശേഷം നമ്മെ ജീവിപ്പിച്ച അല്ലാഹുവിന് സർവ്വ സ്തുതിയും. അവനിലേക്ക് തന്നെയാണ് മടക്കം." (ബു)', 'حُذَيْفَةَ', 'ഹുദൈഫതുബ്നുൽ യമാൻ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 901, 901, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: بِتُّ عِنْدَ مَيْمُونَةَ، فَقَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَتَى حَاجَتَهُ، فَغَسَلَ وَجْهَهُ وَيَدَيْهِ، ثُمَّ نَامَ، ثُمَّ قَامَ، فَأَتَى الْقِرْبَةَ فَأَطْلَقَ شِنَاقَهَا، ثُمَّ تَوَضَّأَ وُضُوءًا بَيْنَ وُضُوءَيْنِ لَمْ يُكْثِرْ وَقَدْ أَبْلَغَ، فَصَلَّى، فَقُمْتُ فَتَمَطَّيْتُ، كَرَاهِيَةَ أَنْ يَرَى أَنِّي كُنْتُ أَتَّقِيهِ، فَتَوَضَّأْتُ: فَقَامَ يُصَلِّي، فَقُمْتُ عَنْ يَسَارِهِ، فَأَخَذَ بِأُذُنِي فَأَدَارَنِي عَنْ يَمِينِهِ، فَتَتَامَّتْ صَلَاتُهُ ثَلَاثَ عَشْرَةَ رَكْعَةً، ثُمَّ اضْطَجَعَ فَنَامَ حَتَّى نَفَخَ، وَكَانَ إِذَا نَامَ نَفَخَ. فَآذَنَهُ بِلَالٌ بِالصَّلَاةِ، فَصَلَّى وَلَمْ يَتَوَضَّأْ. وَكَانَ يَقُولُ فِي دُعَائِهِ: "اللَّهُمَّ اجْعَلْ فِي قَلْبِي نُورًا، وَفِي بَصَرِي نُورًا، وَفِي سَمْعِي نُورًا. وَعَنْ يَمِينِي نُورًا، وَعَنْ يَسَارِي نُورًا، وَفَوْقِي نُورًا، وَتَحْتِي نُورًا، وَأَمَامِي نُورًا، وَخَلْفِي نُورًا". (خ)', 'ഇബ്‌നുഅബ്ബാസ്(റ): മൈമൂന ബീവി(റ)യുടെ വീട്ടിൽ ഞാൻ അന്തിയുറങ്ങി. നബി(സ) ഉറക്കത്തിൽ നിന്നെഴുന്നേറ്റ് തന്റെ പ്രാഥമിക കർമ്മങ്ങൾ നിർവ്വഹിച്ചു. ശേഷം തന്റെ മുഖവും കൈകളും കഴുകി. എന്നിട്ട് നബി(സ) കിടന്നുറങ്ങി. പിന്നെ എഴുന്നേറ്റു. തോൽപാത്രം കൊണ്ടുവന്നു അതിന്റെ തോൽ വാർ അഴിച്ചു. ശേഷം അമിതമാകാത്തവിധം പരിപൂർണ്ണമായ ഒരു വുളൂഅ് എടുത്തു. എന്നിട്ട് നമസ്കരിച്ചു. അപ്പോൾ ഞാൻ എഴുന്നേറ്റു. ഞാൻ അവിടത്തെ നോക്കിക്കൊണ്ടിരിക്കുകയായിരുന്നുവെന്ന് തിരുമേനി(സ) മനസ്സിലാക്കുന്നതിനെ പേടിച്ച്, ഞാൻ വേഗം നടന്നു. അങ്ങനെ ഞാൻ വുളൂ എടുത്തു. അപ്പോൾ നബി(സ) നമസ്കരിക്കാൻ നിന്നു. ഞാൻ തിരുമേനി(സ)യുടെ ഇടതു ഭാഗത്ത് പോയി നിന്നു. അപ്പോൾ തിരുമേനി(സ) എന്റെ ചെവിക്ക് പിടിച്ച് എന്നെ വലതുഭാഗത്തു നിർത്തി. റസൂൽ(സ) പതിമൂന്ന് റക്അത്ത് നിസ്കാരം പൂർത്തിയാക്കി. ശേഷം ഉറങ്ങുകയും കൂർക്കം വലിക്കുകയും ചെയ്തു. നബി(സ) ഉറക്കത്തിൽ കൂർക്കം വലിക്കുക പതിവായിരുന്നു. പിന്നെ ബിലാൽ(റ) നമസ്കരിക്കാൻ ബാങ്ക് വിളിച്ചു. അപ്പോൾ തിരുമേനി(സ) വുളൂഅ് എടുക്കാതെ നമസ്കരിച്ചു. നബി(സ) തന്റെ പ്രാർത്ഥനയിൽ ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ, എന്റെ ഹൃദയത്തിലും കാഴ്ചയിലും എന്റെ കേൾവിയിലും എന്റെ വലത്ത് ഭാഗത്തും ഇടതു ഭാഗത്തും എനിക്ക് മുകളിലും താഴെയും എന്റെ മുമ്പിലും പിന്നിലും നീ പ്രകാശം നൽകേണമേ." (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്‌നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 901, 902, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ فَقَالَ: يَا رَسُولَ اللَّهِ، أَيُّ الدُّعَاءِ أَفْضَلُ؟ قَالَ: "سَلْ رَبَّكَ الْعَفْوَ وَالْعَافِيَةَ، فِي الدُّنْيَا وَالْآخِرَةِ". ثُمَّ أَتَاهُ فِي الْيَوْمِ الثَّانِي فَقَالَ: يَا رَسُولَ اللَّهِ، أَيُّ الدُّعَاءِ أَفْضَلُ؟ قَالَ: "سَلْ رَبَّكَ الْعَفْوَ وَالْعَافِيَةَ، فِي الدُّنْيَا وَالْآخِرَةِ". ثُمَّ أَتَاهُ فِي الْيَوْمِ الثَّالِثِ فَقَالَ: يَا نَبِيَّ اللَّهِ، أَيُّ الدُّعَاءِ أَفْضَلُ؟ قَالَ: "سَلْ رَبَّكَ الْعَفْوَ وَالْعَافِيَةَ، فِي الدُّنْيَا وَالْآخِرَةِ. فَإِذَا أُعْطِيتَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ فَقَدْ أَفْلَحْتَ". (ت,جه)', 'അനസുബ്നു മാലിക്(റ): ഒരാൾ നബി(സ)യെ സമീപിച്ച് ചോദിച്ചു: തിരുദൂതരേ, ഏത് പ്രാർത്ഥനയാണ് ഏറ്റവും ശ്രേഷ്ഠമായത്. തിരുമേനി(സ) പറഞ്ഞു: "ഇഹലോകത്തും പരലോകത്തും മാപ്പും ആരോഗ്യവും തരാൻ നിന്റെ രക്ഷിതാവിനോട് നീ ചോദിക്കുക." അദ്ദേഹം രണ്ടാം ദിവസവും നബി(സ)യെ സമീപിച്ച് ചോദിച്ചു. തിരുദൂതരേ, ഏത് പ്രാർത്ഥനയാണ് ഏറ്റവും ശ്രേഷ്ഠമായത്? തിരുമേനി(സ) പറഞ്ഞു: "ഇഹലോകത്തും, പരലോകത്തും മാപ്പും ആരോഗ്യവും തരാൻ നിന്റെ രക്ഷിതാവിനോട് നീ ചോദിക്കുക." മൂന്നാം ദിവസവും അദ്ദേഹം വന്നു കൊണ്ട് ചോദിച്ചു. തിരുദൂതരേ, ഏതാണ് ഏറ്റവും ശ്രേഷ്ഠമായ പ്രാർത്ഥന? റസൂൽ(സ) പറഞ്ഞു: "ഇഹലോകത്തും പരലോകത്തും മാപ്പും ആരോഗ്യവും തരാൻ നിന്റെ രക്ഷിതാവിനോട് നീ പ്രാർത്ഥിക്കുക. കാരണം ഇഹലോകത്തും പരലോകത്തും ആരോഗ്യവും മാപ്പും ലഭിച്ചാൽ നീ വിജയിച്ചിരിക്കുന്നു." (തു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 902, 902, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قُلْتُ يَا رَسُولَ اللَّهِ، أَرَأَيْتَ إِنْ عَلِمْتُ أَيَّ لَيْلَةٍ لَيْلَةُ الْقَدْرِ، مَا أَقُولُ فِيهَا؟ قَالَ: "قُولِي اللَّهُمَّ إِنَّكَ عَفُوٌّ كَرِيمٌ تُحِبُّ الْعَفْوَ، فَاعْفُ عَنِّي". حَسَنٌ صَحِيحٌ. (ت)', 'ആഇശ(റ): ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലെ, ലൈലതുൽ ഖദർ ഏത് രാത്രിയിലാണെന്ന് ഞാനറിഞ്ഞാൽ ആ രാത്രിയിൽ ഞാനെന്താണ് ചൊല്ലേണ്ടത്? റസൂൽ(സ) പറഞ്ഞു: "നീ ഇത് പറയുക: അല്ലാഹുവേ നീ മാപ്പ് നൽകുന്നവനാണ്, ഔദാര്യവാനാണ്, നീ മാപ്പിഷ്ടപ്പെടുന്നു. അത് കൊണ്ട് എനിക്ക് നീ മാപ്പ് നൽകിയാലും." (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 902, 902, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنِ الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، عَلِّمْنِي شَيْئًا أَسْأَلُهُ اللَّهَ عَزَّ وَجَلَّ. قَالَ: "سَلِ اللَّهَ الْعَافِيَةَ". فَمَكَثْتُ أَيَّامًا ثُمَّ جِئْتُ فَقُلْتُ: يَا رَسُولَ اللَّهِ، عَلِّمْنِي شَيْئًا أَسْأَلُهُ اللَّهَ؟ فَقَالَ لِي: "يَا عَبَّاسُ يَا عَمَّ رَسُولِ اللَّهِ، سَلِ اللَّهَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ". صَحِيحٌ. (ت)', 'അബ്ബാസുബ്നു അബ്ദുൽ മുത്വലിബ്(റ): ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അല്ലാഹുവിനോട് പ്രാർത്ഥിക്കാൻ വല്ലതും എനിക്ക് പഠിപ്പിച്ച് തരിക. റസൂൽ(സ) പറഞ്ഞു: "താങ്കൾ അല്ലാഹുവിനോട് ആരോഗ്യം ചോദിക്കുക." കുറച്ചു ദിവസങ്ങൾക്ക് ശേഷം ഞാൻ വീണ്ടും ചെന്നു ചോദിച്ചു. അല്ലാഹുവിന്റെ ദൂതരേ, അല്ലാഹുവിനോട് പ്രാർത്ഥിക്കാൻ വല്ലതും എനിക്ക് പഠിപ്പിച്ചു തരിക. അപ്പോൾ റസൂൽ(സ) എന്നോട് പറഞ്ഞു: "അബ്ബാസേ, അല്ലാഹുവിന്റെ ദൂതന്റെ പിതൃസഹോദരാ, ഇഹലോകത്തും പരലോകത്തും ആരോഗ്യം തരാൻ അല്ലാഹുവിനോട് നിങ്ങൾ പ്രാർത്ഥിക്കുക." (തു)', 'الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ', 'അബ്ബാസുബ്നു അബ്ദുൽ മുത്വലിബ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 902, 902, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, '.٤٧ عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا سُئِلَ اللهُ شَيْئًا أَحَبَّ إِلَيْهِ مِنْ أَنْ يُسْأَلَ الْعَافِيَةَ". (ت)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരോഗ്യത്തെ ചോദിക്കുന്നതിനേക്കാൾ അല്ലാഹുവിന് ഇഷ്ടപ്പെട്ട ഒരു തേട്ടവും ഇല്ല." (തു)', null, 'ഇബ്നുഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 903, 903, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, '.٤٨ عَنْ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُ، حِينَ قُبِضَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ: قَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي مَقَامِي هَذَا، عَامَ الْأَوَّلِ. ثُمَّ بَكَى أَبُو بَكْرٍ، ثُمَّ قَالَ: "عَلَيْكُمْ بِالصِّدْقِ، فَإِنَّهُ مَعَ الْبِرِّ، وَهُمَا فِي الْجَنَّةِ، وَإِيَّاكُمْ وَالْكَذِبَ، فَإِنَّهُ مَعَ الْفُجُورِ، وَهُمَا فِي النَّارِ. وَسَلُوا اللهَ الْمُعَافَاةَ، فَإِنَّهُ لَمْ يُؤْتَ أَحَدٌ بَعْدَ الْيَقِينِ خَيْرًا مِنَ الْمُعَافَاةِ. وَلَا تَحَاسَدُوا، وَلَا تَبَاغَضُوا، وَلَا تَقَاطَعُوا، وَلَا تَدَابَرُوا، وَكُونُوا عِبَادَ اللهِ إِخْوَانًا". (ت،جه)', 'അബൂബക്കർ(റ): റസൂൽ(സ) അന്ത്യ യാത്രയായ സമയത്ത് അബൂബക്കർ(റ) പ്രസംഗിച്ചു: നബി(സ) പ്രഥമ വർഷത്തിൽ ഞാനീ നിൽക്കുന്നിടത്ത് എഴുന്നേറ്റ് നിന്നു. (അത് പറഞ്ഞ് അബൂബക്കർ(റ) കരഞ്ഞു.) എന്നിട്ട് പറഞ്ഞു: "സത്യത്തെ മുറുകെപ്പിടിക്കുക. കാരണം അത് നന്മയോടൊപ്പമാണ്. അവ രണ്ടും സ്വർഗത്തിലുമാണ്. കളവ് സൂക്ഷിക്കുക. കാരണമത് തിന്മയോടൊപ്പമാണ്. അവ രണ്ടും നരകത്തിലുമാണ്. നിങ്ങൾ അല്ലാഹുവിനോട് ആരോഗ്യം ചോദിക്കുക. കാരണം യഖീനി(ദൃഢത)ന് ശേഷം ആരോഗ്യത്തേക്കാൾ ഉത്തമമായ ഒരു നന്മയും ആർക്കും നൽകപ്പെട്ടിട്ടില്ല. നിങ്ങൾ പരസ്പരം അസൂയ വെക്കുകയോ, ദേഷ്യപ്പെടുകയോ കുടുംബബന്ധം മുറിക്കുകയോ പുറം തിരിയുകയോ ചെയ്യരുത്. സഹോദരന്മാരായി നിങ്ങൾ അല്ലാഹുവിന്റെ അടിമകളാവുക." (തു,ജ)', null, 'അബൂബക്കർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 903, 903, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, '.٤٩ عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ دَعْوَةٍ يَدْعُو بِهَا الْعَبْدُ أَفْضَلَ مِنْ: اللَّهُمَّ إِنِّي أَسْأَلُكَ الْمُعَافَاةَ فِي الدُّنْيَا وَالْآخِرَةِ". (جه)', 'അബൂഹുറൈറ(റ): തിരുനബി(സ) പറഞ്ഞു: "അല്ലാഹുവേ, ഇഹത്തിലും പരത്തിലും ഞാൻ നിന്നോട് ആരോഗ്യത്തെ ചോദിക്കുന്നു എന്നതിനേക്കാൾ ശ്രേഷ്ഠമായി അടിമ നടത്തുന്ന ഒരു പ്രാർത്ഥനയുമില്ല." (ജ)', null, 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 903, 903, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, '.٥٠ عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الدُّعَاءُ لَا يُرَدُّ بَيْنَ الْأَذَانِ وَالْإِقَامَةِ". قَالُوا: فَمَاذَا نَقُولُ يَا رَسُولَ اللهِ؟ قَالَ: "سَلُوا اللهَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ". قَالَ تُرْمُذِي هَذَا حَدِيثٌ حَسَنٌ. (د،ت)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "ബാങ്കിനും ഇഖാമത്തിനുമിടയിൽ പ്രാർത്ഥന തട്ടപ്പെടുകയില്ല". അവർ ചോദിച്ചു: റസൂലേ, ഞങ്ങളെന്താണ് ചൊല്ലേണ്ടത്? റസൂൽ(സ) പറഞ്ഞു: "ഇഹത്തിലും പരത്തിലും ആരോഗ്യം തരാൻ അല്ലാഹുവിനോട് പ്രാർത്ഥിക്കുക." (ദ,തു)', null, 'അനസുബ്നു മാലിക്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 903, 903, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, '.٥١ عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "اللَّهُمَّ عَافِنِي فِي جَسَدِي، وَعَافِنِي فِي بَصَرِي، وَاجْعَلْهُ الْوَارِثَ مِنِّي. لَا إِلَهَ إِلَّا اللهُ الْحَلِيمُ الْكَرِيمُ، سُبْحَانَ اللهِ رَبِّ الْعَرْشِ الْعَظِيمِ، وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ". حَسَنٌ. (ت)', 'ആഇശ(റ): റസൂലുല്ലാഹി(സ) ഇപ്രകാരം പറയുമായിരുന്നു: "അല്ലാഹുവേ, എന്റെ ശരീരത്തിൽ നീ ആരോഗ്യം തരേണമേ. എന്റെ കാഴ്ചയിലും നീ ആരോഗ്യം തരേണമേ. അതിനെ എന്റെ അനന്തരമാക്കേണമേ. അത്യുദാരനും സഹനശീലനുമായ അല്ലാഹുവല്ലാതെ മറ്റൊരു ആരാധ്യനില്ല. മഹത്വമായ സിംഹാസനത്തിന്റെ രക്ഷിതാവായ അല്ലാഹുവിനെ ഞാൻ വാഴ്ത്തുന്നു. ലോക രക്ഷിതാവായ അല്ലാഹുവിനാകുന്നു സർവ്വ സ്തുതിയും." (തു)', null, 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 903, 904, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَقُولَنَّ أَحَدُكُمْ: اللَّهُمَّ اغْفِرْ لِي إِنْ شِئْتَ، اللَّهُمَّ ارْحَمْنِي إِنْ شِئْتَ، لِيَعْزِمْ فِي الدُّعَاءِ، فَإِنَّ اللَّهَ صَانِعٌ مَا شَاءَ، لَا مُكْرِهَ لَهُ". (ق,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളാരും ഇപ്രകാരം ദുആ ഇരക്കരുത്, അല്ലാഹുവേ, നീ ഉദ്ദേശിച്ചാൽ എനിക്ക് പൊറുത്ത് തരണേ, അല്ലാഹുവേ, നീ ഉദ്ദേശിച്ചാൽ എന്നോട് കരുണ കാണിക്കണേ. പ്രാർത്ഥിക്കുമ്പോൾ ആത്മവിശ്വാസത്തോടെ പ്രാർത്ഥിക്കട്ടെ. കാരണം അല്ലാഹു അവനുദ്ദേശിക്കുന്നത് ചെയ്യുന്നവനാണ്. അവനെ നിർബന്ധിപ്പിക്കുന്ന ഒരാളുമില്ല." (ബു,മു,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 904, 904, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ادْعُوا اللَّهَ وَأَنْتُمْ مُوقِنُونَ بِالْإِجَابَةِ، وَاعْلَمُوا أَنَّ اللَّهَ لَا يَسْتَجِيبُ دُعَاءً مِنْ قَلْبٍ غَافِلٍ لَاهٍ". (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിനോട് നിങ്ങൾ ദുആ ചെയ്യുക. ഉത്തരം കിട്ടുമെന്ന ഉറപ്പോടുകൂടെ. നിങ്ങളറിയുക, തീർച്ചയായും അശ്രദ്ധവാന്റെ ഹൃദയത്തിൽ നിന്നുള്ള പ്രാർത്ഥനക്ക് അല്ലാഹു ഉത്തരം നൽകുകയില്ല." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 904, 904, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ أَبِي مَالِكٍ الْأَشْجَعِيِّ عَنْ أَبِيهِ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَتَاهُ رَجُلٌ فَقَالَ: يَا رَسُولَ اللهِ، كَيْفَ أَقُولُ حِينَ أَسْأَلُ رَبِّي عَزَّ وَجَلَّ؟ قَالَ: "قُلِ: اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَعَافِنِي وَارْزُقْنِي - وَيَجْمَعُ أَصَابِعَهُ إِلَّا الْإِبْهَامَ - فَإِنَّ هَؤُلَاءِ تَجْمَعُ لَكَ دُنْيَاكَ وَآخِرَتَكَ". (م)', 'തന്റെ പിതാവിൽ നിന്ന് അബൂ മാലികിൽ അശ്ജഇൗ(റ): നബി(സ)യോട് ഒരാൾ വന്ന് ചോദിക്കുന്നത് അവർ കേട്ടു: തിരുദൂതരേ, എന്റെ രക്ഷിതാവിനോട് ചോദിക്കുമ്പോൾ ഞാൻ എന്താണ് ചോദിക്കേണ്ടത്? നബി(സ) പറഞ്ഞു: "നീ പറയുക, അല്ലാഹുവേ, നീ എനിക്ക് പൊറുത്ത് തരികയും എന്നോട് കരുണ കാണിക്കുകയും എനിക്ക് ആരോഗ്യം നൽകുകയും രിസ്ഖ് (ഭക്ഷണവും മറ്റു ആവശ്യങ്ങളും) പ്രദാനംചെയ്യുകയും ചെയ്യേണമേ. -നബി(സ) തന്റെ തള്ളവിരൽ അല്ലാത്ത വിരലുകൾ മടക്കി (ഇവ നാലെണ്ണം എണ്ണിക്കൊണ്ട്) - കാരണം ഇവ നിനക്ക് ഇഹവും പരവും ഒരുമിച്ചു കൂട്ടിത്തരും." (മു)', 'أَبِي مَالِكٍ الْأَشْجَعِيِّ عَنْ أَبِيهِ', 'തന്റെ പിതാവിൽ നിന്ന് അബൂ മാലികിൽ അശ്ജഇൗ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 904, 904, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَرْحَمُنَا اللهُ، وَأَخَا عَادٍ". (جه)', 'ഇബ്‌നുഅബ്ബാസ്(റ): തിരുനബി(സ) പറഞ്ഞു: "അല്ലാഹു നമുക്കും ആദിന്റെ സഹോദരനും കരുണ ചെയ്യട്ടെ". (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്‌നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 905, 905, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَا مِنْ أَحَدٍ يَدْعُو بِدُعَاءٍ إِلَّا آتَاهُ اللهُ مَا سَأَلَ، أَوْ كَفَّ عَنْهُ مِنَ السُّوءِ مِثْلَهُ، مَا لَمْ يَدْعُ بِإِثْمٍ أَوْ قَطِيعَةِ رَحِمٍ". (ت)', 'ജാബിർ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഒരാളും പ്രാർത്ഥിച്ചിട്ടില്ല, അവൻ ചോദിച്ചത് അല്ലാഹു നൽകിയിട്ടല്ലാതെ, അതല്ലെങ്കിൽ അതിനോട് തുല്യമായ ഒരു ബുദ്ധിമുട്ടിൽ നിന്ന് അവനെ രക്ഷപ്പെടുത്തിയിട്ടല്ലാതെ. തിന്മ കൊണ്ടുള്ളതും കുടുംബബന്ധം മുറിക്കാനുമുള്ളതുമായ പ്രാർത്ഥന ഒഴികെ" (തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 905, 905, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ سَرَّهُ أَنْ يَسْتَجِيبَ اللهُ لَهُ عِنْدَ الشَّدَائِدِ وَالْكُرَبِ فَلْيُكْثِرِ الدُّعَاءَ فِي الرَّخَاءِ". (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ബുദ്ധിമുട്ടിന്റെയും പ്രയാസത്തിന്റെയും സമയത്ത് തന്റെ പ്രാർത്ഥനക്ക് അല്ലാഹു ഉത്തരം നൽകുന്നത് ആരെയെങ്കിലും സന്തോഷിപ്പിക്കുന്നുവെങ്കിൽ ഐശ്വര്യത്തിന്റെ സമയത്ത് അവൻ പ്രാർത്ഥന അധികരിപ്പിച്ചു കൊള്ളട്ടെ." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 905, 905, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "أَفْضَلُ الذِّكْرِ لَا إِلَهَ إِلَّا اللهُ، وَأَفْضَلُ الدُّعَاءِ: لَا إِلَهَ إِلَّا اللهُ". حَسَنٌ. (ت,ن,جه)', 'ജാബിറുബ്‌നു അബ്ദുല്ലാ(റ): തിരുനബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഏറ്റവും ശ്രേഷ്ഠമായ ദിക്‌ർ ലാഇലാഹ ഇല്ലല്ലാഹു എന്നതാണ്, ഏറ്റവും ശ്രേഷ്ഠമായ പ്രാർത്ഥന ലാ ഇലാഹ ഇല്ലല്ലാഹു എന്നതാണ്." (തു,ന,ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്‌നു അബ്ദുല്ലാ(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 905, 905, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لِكُلِّ نَبِيٍّ دَعْوَةٌ مُسْتَجَابَةٌ يَدْعُو بِهَا، وَأُرِيدُ أَنْ أَخْتَبِئَ دَعْوَتِي شَفَاعَةً لِأُمَّتِي فِي الْآخِرَةِ". (خ)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഓരോ പ്രവാചകനും ഉത്തരം നൽകപ്പെടുന്ന ഓരോ പ്രാർത്ഥനയുണ്ട്. എന്റെ പ്രാർത്ഥന പരലോകത്ത് വെച്ച് എന്റെ സമുദായത്തിന് ശിപാർശ ചെയ്യാനായി സൂക്ഷിച്ചുവെക്കാനാണ് ഞാനുദ്ദേശിക്കുന്നത്." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 905, 905, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "لَا يَزَالُ يُسْتَجَابُ لِلْعَبْدِ مَا لَمْ يَدْعُ بِإِثْمٍ أَوْ قَطِيعَةِ رَحِمٍ، مَا لَمْ يَسْتَعْجِلْ". قِيلَ: يَا رَسُولَ اللَّهِ: مَا الاِسْتِعْجَالُ؟ قَالَ: "يَقُولُ: قَدْ دَعَوْتُ وَقَدْ دَعَوْتُ فَلَمْ أَرَ يَسْتَجِيبُ لِي، فَيَسْتَحْسِرُ عِنْدَ ذَلِكَ وَيَدَعُ الدُّعَاءَ". (ق, د, ت, جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "തിന്മക്ക് വേണ്ടിയും കുടുംബബന്ധം മുറിക്കുന്നതിന് വേണ്ടിയും പ്രാർത്ഥിക്കാത്ത കാലത്തോളം ഒരു അടിമക്ക് ഉത്തരം നൽകപ്പെടും, അവൻ ധൃതി കൂട്ടിയില്ലെങ്കിൽ." അപ്പോൾ ചോദിക്കപ്പെട്ടു: അല്ലാഹുവിന്റെ റസൂലേ, എന്താണ് ധൃതി കൂട്ടുകയെന്നാൽ? അവിടന്ന് പറഞ്ഞു: "അവൻ പറയലാണ്: ഞാൻ പ്രാർത്ഥിച്ചു, പിന്നെയും പ്രാർത്ഥിച്ചു. എനിക്ക് ഉത്തരം കിട്ടുമെന്ന് തോന്നുന്നില്ല. അങ്ങനെ അവൻ നിരാശനാകുകയും പ്രാർത്ഥന ഒഴിവാക്കുകയും ചെയ്യുന്നു." (ബു,മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 905, 906, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يُسْتَجَابُ لِأَحَدِكُمْ مَا لَمْ يَعْجَلْ، يَقُولُ: دَعَوْتُ فَلَمْ يُسْتَجَبْ لِي". حَسَنٌ. (ق, د, ت, جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "താൻ ധൃതി കാട്ടാത്ത കാലത്തോളം നിങ്ങളിലൊരുത്തന് ഉത്തരം നൽകപ്പെടും. അവൻ പറയും: ഞാൻ പ്രാർത്ഥിച്ചു; പക്ഷെ, എനിക്ക് ഉത്തരം നൽകപ്പെട്ടിട്ടില്ല." (ബു,മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 906, 906, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ فِي اللَّيْلِ لَسَاعَةً، لَا يُوَافِقُهَا رَجُلٌ مُسْلِمٌ يَسْأَلُ اللَّهَ خَيْرًا مِنْ أَمْرِ الدُّنْيَا وَالْآخِرَةِ إِلَّا أَعْطَاهُ إِيَّاهُ، وَذَلِكَ كُلَّ لَيْلَةٍ". (م)', 'ജാബിർ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "രാത്രിയിൽ ഒരു സമയമുണ്ട്. ഇഹപര ലോകത്തിലെ നന്മയെ ചോദിക്കുന്ന മുസ്‌ലിമായ മനുഷ്യന്റെ പ്രാർത്ഥന ആ സമയത്തോട് യോജിച്ചു വന്നാൽ അവന്റെ പ്രാർത്ഥനക്ക് ഉത്തരം ചെയ്യപ്പെടാതിരിക്കില്ല. ഈ സമയം എല്ലാ രാത്രിയിലുമുണ്ട്." (മു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 906, 906, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَادَ رَجُلًا مِنَ الْمُسْلِمِينَ قَدْ خَفَتَ فَصَارَ مِثْلَ الْفَرْخِ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَلْ كُنْتَ تَدْعُو بِشَيْءٍ أَوْ تَسْأَلُهُ إِيَّاهُ؟". قَالَ: نَعَمْ، كُنْتُ أَقُولُ: اللَّهُمَّ مَا كُنْتَ مُعَاقِبِي بِهِ فِي الْآخِرَةِ فَعَجِّلْهُ لِي فِي الدُّنْيَا. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "سُبْحَانَ اللَّهِ، لَا تُطِيقُهُ - أَوْ: لَا تَسْتَطِيعُهُ - أَفَلَا قُلْتَ: اللَّهُمَّ آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ". قَالَ: فَدَعَا اللَّهَ لَهُ فَشَفَاهُ. (م)', 'അനസ്(റ): അസുഖമായി ക്ഷീണിച്ച് കോഴിയെപ്പോലെ ആയിത്തീർന്ന ഒരു മുസ്‌ലിമിനെ റസൂൽ(സ) സന്ദർശിച്ചു. അവിടന്ന് അയാളോട് പറഞ്ഞു: "നീ അല്ലാഹുവിനോട് എന്തെങ്കിലും ചോദിക്കാറുണ്ടോ? അല്ലെങ്കിൽ അതിനു വേണ്ടി പ്രാർത്ഥിക്കാറുണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: അതെ. ഞാൻ പറയുമായിരുന്നു: അല്ലാഹുവേ, നീ എന്നെ പരലോകത്ത് വെച്ച് ശിക്ഷിക്കുമെങ്കിൽ അത് ഇഹലോകത്ത് വെച്ച് തന്നെ എനിക്ക് തരിക. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിനെ ഞാൻ വാഴ്ത്തുന്നു. അതിനെ താങ്ങാൻ നിനക്കാവില്ല. നിനക്ക് ഇപ്രകാരം പ്രാർത്ഥിച്ചു കൂടേ: ''അല്ലാഹുവേ, ഞങ്ങൾക്ക് ഇഹത്തിലും പരത്തിലും നല്ലത് തരേണമേ, നരക ശിക്ഷയിൽ നിന്ന് ഞങ്ങളെ രക്ഷിക്കേണമേ.'' എന്ന്". നിവേദകൻ പറയുന്നു: അങ്ങനെ റസൂൽ(സ) അദ്ദേഹത്തിന് വേണ്ടി പ്രാർത്ഥിച്ചു. അദ്ദേഹത്തിന്റെ അസുഖം മാറുകയും ചെയ്തു. (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 906, 907, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ لِلَّهِ تِسْعَةً وَتِسْعِينَ اسْمًا، مِائَةً غَيْرَ وَاحِدٍ، مَنْ أَحْصَاهَا دَخَلَ الْجَنَّةَ". حَسَنٌ صَحِيحٌ. (ق,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന് തൊണ്ണൂറ്റി ഒൻപത് നാമങ്ങളുണ്ട്. നൂറിന് ഒന്ന് കുറവ്. ആരെങ്കിലും അത് പൂർണ്ണമായി ചൊല്ലിയാൽ അവൻ സ്വർഗത്തിൽ പ്രവേശിക്കും." (ബു,മു,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 907, 907, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ لِلَّهِ تِسْعَةً وَتِسْعِينَ اسْمًا، مِائَةً إِلَّا وَاحِدًا، إِنَّهُ وِتْرٌ يُحِبُّ الْوِتْرَ، مَنْ حَفِظَهَا دَخَلَ الْجَنَّةَ، وَهِيَ: اللَّهُ، الْوَاحِدُ، الصَّمَدُ، الْأَوَّلُ، الْآخِرُ، الظَّاهِرُ، الْبَاطِنُ، الْخَالِقُ، الْبَارِئُ، الْمُصَوِّرُ، الْمَلِكُ، الْحَقُّ، السَّلَامُ، الْمُؤْمِنُ، الْمُهَيْمِنُ، الْعَزِيزُ، الْجَبَّارُ، الْمُتَكَبِّرُ، الرَّحْمَنُ، الرَّحِيمُ، اللَّطِيفُ، الْخَبِيرُ، السَّمِيعُ، الْبَصِيرُ، الْعَلِيمُ، الْعَظِيمُ، الْبَارُّ، الْمُتَعَالِ، الْجَلِيلُ، الْجَمِيلُ، الْحَيُّ، الْقَيُّومُ، الْقَادِرُ، الْقَاهِرُ، الْعَلِيُّ، الْحَكِيمُ، الْقَرِيبُ، الْمُجِيبُ، الْغَنِيُّ، الْوَهَّابُ، الْوَدُودُ، الشَّكُورُ، الْمَاجِدُ، الْوَاجِدُ، الْوَالِي، الرَّاشِدُ، الْعَفُوُّ، الْغَفُورُ، الْحَلِيمُ، الْكَرِيمُ، التَّوَّابُ، الرَّبُّ، الْمَجِيدُ، الْوَلِيُّ، الشَّهِيدُ، الْمُبِينُ، الْبُرْهَانُ، الرَّءُوفُ، الرَّحِيمُ، الْمُبْدِئُ، الْمُعِيدُ، الْبَاعِثُ، الْوَارِثُ، الْقَوِيُّ، الشَّدِيدُ، الضَّارُّ، النَّافِعُ، الْبَاقِي، الْوَاقِي، الْخَافِضُ، الرَّافِعُ، الْقَابِضُ، الْبَاسِطُ، الْمُعِزُّ، الْمُذِلُّ، الْمُقْسِطُ، الرَّزَّاقُ، ذُو الْقُوَّةِ، الْمَتِينُ، الْقَائِمُ، الدَّائِمُ، الْحَافِظُ، الْوَكِيلُ، الْفَاطِرُ، السَّامِعُ، الْمُعْطِي، الْمُحْيِي، الْمُمِيتُ، الْمَانِعُ، الْجَامِعُ، الْهَادِي، الْكَافِي، الْأَبَدُ، الْعَالِمُ، الصَّادِقُ، النُّورُ، الْمُنِيرُ، التَّامُّ، الْقَدِيمُ، الْوِتْرُ، الْأَحَدُ، الصَّمَدُ، الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ". (ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന് തൊണ്ണൂറ്റൊമ്പത് നാമങ്ങളുണ്ട്, നൂറിന് ഒന്ന് കുറവ്. അല്ലാഹു ഒറ്റയാണ്. അവൻ ഒറ്റയെ ഇഷ്ടപ്പെടുന്നു. ആരെങ്കിലും അവ മനഃപാഠമാക്കിയാൽ അവൻ സ്വർഗത്തിൽ പ്രവേശിക്കുക തന്നെ ചെയ്യും. അവ ഇപ്രകാരമാണ്: അല്ലാഹു, വാഹിദ്(ഏകൻ), സ്വമദ്(മറ്റുള്ളവരുടെ ആശ്രയവും സ്വയം നിരാശ്രയനും ആയവൻ), അവ്വൽ(ആദ്യം), ആഖിർ(അന്ത്യം), ളാഹിർ(പ്രത്യക്ഷമായവൻ), ബാതിൻ(പരോക്ഷമായവൻ), ഖാലിഖ്(സ്രഷ്ടാവ്), ബാരി(ശൂന്യതയിൽ നിന്ന് പടച്ചവൻ), മുസ്വവ്വിർ(രൂപപ്പെടുത്തുന്നവൻ), മാലിക്(ഉടമസ്ഥൻ), ഹഖ്(സത്യം), സലാം(രക്ഷ), മുഅ്മിൻ(അഭയം നൽകുന്നവൻ), മുഹൈമിൻ(സംരക്ഷകൻ), അസീസ്(പ്രതാപി), ജബ്ബാർ(പരമാധികാരി), മുതകബ്ബിർ(അഹങ്കാരമുള്ളവൻ), റഹ്മാൻ(കാരുണ്യവാൻ), റഹീം(കരുണാവാരിധി), ലത്വീഫ്(മൃദുലതയുള്ളവൻ), ഖബീർ(സൂക്ഷ്മജ്ഞാനി), സമീഅ്(കേൾക്കുന്നവൻ), ബസ്വീർ(കാണുന്നവൻ), അലീം(അറിയുന്നവൻ), ബർറ്(ഗുണവാൻ), മുതആൽ(ഔന്നിത്യമുള്ളവൻ), ജലീൽ(മഹാൻ), ജമീൽ(സുന്ദരൻ), ഹയ്യ്(ജീവിക്കുന്നവൻ), ഖയ്യൂം(കൈകാര്യകർത്താവ്), ഖാദിർ(കഴിവുള്ളവൻ), ഖാഹിർ(അടക്കിവാഴുന്നവൻ), അലിയ്യ്(ഉന്നതൻ), ഹകീം(തന്ത്രജ്ഞാനി), ഖരീബ്(അടുത്തവൻ), മുജീബ്(ഉത്തരം നൽകുന്നവൻ), ഗനിയ്യ്(ഐശ്വര്യവാൻ), വഹ്ഹാബ്(ധർമ്മിഷ്ഠൻ), വദുദ്(സ്നേഹനിധി), ശകൂർ(നന്ദിയുള്ളവൻ), മാജിദ്(മഹത്വമുടയവൻ), വാജിദ്(ഐശ്വര്യവാൻ), വാലി(സർവ്വാധിപൻ), റാഷിദ്(വഴികാട്ടി), അഫുവ്വ്(പൊറുത്ത് കൊടുക്കുന്നവൻ), ഗഫൂർ(പൊറുക്കുന്നവൻ), ഹലീം(വാത്സല്യവാൻ), കരീം(ഔദാര്യവാൻ), തവ്വാബ്(തൗബ സ്വീകരിക്കുന്നവൻ), റബ്ബ്(രക്ഷിതാവ്), മജീദ്(മഹത്വമുടയവൻ), വലിയ്യ്(രക്ഷിതാവ്), ശഹീദ്(സാക്ഷി), മുബീൻ(വ്യക്തമാക്കുന്നവൻ), ബുർഹാൻ(തെളിവ്), റഊഫ്(കൃപ ചൊരിയുന്നവൻ), റഹീം(കരുണാവാരിധി), മുബ്ദിഅ്(തുടങ്ങിപ്പടക്കുന്നവൻ), മുഈദ്(മടക്കുന്നവൻ), ബാഇസ്(പുനർ ജനിപ്പിക്കുന്നവൻ), വാരിസ്(അവകാശി), ഖവിയ്യ്(ശക്തൻ), ശദീദ്(ശക്തവാൻ), ളാർറ്(ഉപദ്രവിക്കുന്നവൻ), നാഫിഅ്(ഉപകാരം ചെയ്യുന്നവൻ), ബാഖി(എന്നെന്നും ശേഷിക്കുന്നവൻ), വാഖി(സംരക്ഷിക്കുന്നവൻ), ഖാഫിള്(താഴ്ത്തുന്നവൻ), റാഫിഅ്(ഉയർത്തുന്നവൻ), ഖാബിള്(പിടിച്ചെടുക്കുന്നവൻ), ബാസിത്വ്(വിശാലമാക്കുന്നവൻ), മുഇസ്സ്(പ്രതാപം നൽകുന്നവൻ), മുദില്ല്(നിന്ദ്യനാക്കുന്നവൻ), മുഖ്സിത്വ്(വിഹിതം വെക്കുന്നവൻ), റാസിഖ്(രിസ്ഖ് നൽകുന്നവൻ), ദുൽ ഖുവ്വഃ(ശക്തിയുടയവൻ), മതീൻ(പ്രബലൻ), ഖാഇം(നിൽക്കുന്നവൻ), ദാഇം(സ്ഥിരമായുള്ളവൻ), ഹാഫിള്(സംരക്ഷകൻ), വകീൽ(ഏറ്റെടുക്കുന്നവൻ), ഫാത്വിർ(സൃഷ്ടിക്കുന്നവൻ), സാമിഅ്(കേൾക്കുന്നവൻ), മുഅ്ത്വീ(നൽകുന്നവൻ), മുഹ്‌യീ(ജീവിപ്പിക്കുന്നവൻ), മുമീത്(മരിപ്പിക്കുന്നവൻ), മാനിഅ്(തടഞ്ഞുവെക്കുന്നവൻ), ജാമിഅ്(ഒരുമിച്ചുകൂട്ടുന്നവൻ), ഹാദീ(സൻമാർഗം കാണിക്കുന്നവൻ), കാഫി(മതിയായവൻ), അബദ്(എന്നെന്നുമുള്ളവൻ), ആലിം(അറിവുള്ളവൻ), സ്വാദിഖ്(സത്യസന്ധൻ), നൂർ(പ്രകാശം); മുനീർ(പ്രകാശം നൽകുന്നവൻ), താമ്മ്(പരിപൂർണ്ണൻ), ഖദീം(പണ്ടേയുള്ളവൻ), വിത്റ്(ഏകൻ), അഹദ്(ഏകൻ), സ്വമദ്(ആശ്രയമായിട്ടുള്ളവൻ), അല്ലദീ ലം യലിദ് വലം യൂലദ് വലം യകുൻ ലഹു കുഫുവൻ അഹദ്(അവൻ പിതാവല്ല, പുത്രനുമല്ല, അവന് തുല്യനായി ആരുമില്ല." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 907, 908, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا مَرَرْتُمْ بِرِيَاضِ الْجَنَّةِ فَارْتَعُوا". قُلْتُ: يَا رَسُولَ اللَّهِ، وَمَا رِيَاضُ الْجَنَّةِ؟ قَالَ: "الْمَسَاجِدُ". قُلْتُ: وَمَا الرَّتْعُ يَا رَسُولَ اللَّهِ؟ قَالَ: "سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ". حَسَنٌ. (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ സ്വർഗത്തോപ്പിന്നടുത്ത് കൂടെ നടന്നു പോകുമ്പോൾ നിങ്ങൾ അതിൽ ആനന്ദത്തോടെ മേഞ്ഞു നടക്കുക." അവർ ചോദിച്ചു: നബിയേ, ഏതാണ് സ്വർഗ്ഗത്തോപ്പുകൾ? റസൂൽ(സ) പ്രതിവചിച്ചു: "അവ പള്ളികളാകുന്നു." അവർ ചോദിച്ചു: നബിയേ, എന്താണ് ''രത്അ്''? നബി(സ) ഉത്തരം നൽകി: "അല്ലാഹുവിനെ ഞങ്ങൾ വാഴ്ത്തുന്നു, എല്ലാ സ്തുതികളും അവനാകുന്നു, അവനല്ലാതെ ആരാധ്യനില്ല, അവനെത്ര വലിയവൻ എന്നതാണ് രത്അ്." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 908, 908, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لِلَّهِ تِسْعَةٌ وَتِسْعُونَ اسْمًا، مَنْ حَفِظَهَا دَخَلَ الْجَنَّةَ، وَإِنَّ اللَّهَ وِتْرٌ يُحِبُّ الْوِتْرَ". (م)', 'അബൂഹുറൈറ(റ): "അല്ലാഹുവിന് തൊണ്ണൂറ്റി ഒമ്പത് പേരുകളുണ്ട്, ആരെങ്കിലും അത് ഹൃദിസ്ഥമാക്കിയാൽ അവൻ സ്വർഗത്തിൽ പ്രവേശിച്ചു. അല്ലാഹു ഏകനാണ്. അവൻ ഒറ്റയെ ഇഷ്ടപ്പെടുന്നു." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 908, 908, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: دَخَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَسْجِدَ وَرَجُلٌ قَدْ صَلَّى، وَهُوَ يَدْعُو وَهُوَ يَقُولُ فِي دُعَائِهِ: اللَّهُمَّ لَا إِلَهَ إِلَّا أَنْتَ الْمَنَّانُ، بَدِيعُ السَّمَوَاتِ وَالأَرْضِ، ذَا الْجَلَالِ وَالْإِكْرَامِ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَتَدْرُونَ بِمَ دَعَا اللَّهَ؟ دَعَا اللَّهَ بِاسْمِهِ الأَعْظَمِ: الَّذِي إِذَا دُعِيَ بِهِ أَجَابَ، وَإِذَا سُئِلَ بِهِ أَعْطَى". (د,ت,ن,جه)', 'അനസ്(റ): നബി(സ) പള്ളിയിൽ പ്രവേശിക്കുമ്പോൾ ഒരു മനുഷ്യൻ നിസ്കരിച്ച്, ദുആ ചെയ്യുന്നുണ്ടായിരുന്നു. അദ്ദേഹം ദുആയിൽ പറയുന്നുണ്ടായിരുന്നു. അല്ലാഹുവേ, ഏറ്റവും ഗുണം ചെയ്യുന്നവനും ആകാശഭൂമികളെ പടച്ചവനും, ഔന്നിത്യവും പ്രതാപവും ഉള്ളവനുമായ നീ അല്ലാതെ ഒരു ആരാധ്യനുമില്ല. നബി( സ) ചോദിച്ചു: "അദ്ദേഹം അല്ലാഹുവിനോട് ചോദിച്ചത് എന്ത് കൊണ്ടാണെന്ന് നിങ്ങൾക്കറിയുമോ? അദ്ദേഹം ദുആ ചെയ്തത്, അവന്റെ ശ്രേഷ്ഠമായ ഇസ്മ് (നാമം) കൊണ്ടാണ്. അത് കൊണ്ടാരെങ്കിലും ദുആ ചെയ്താൽ അവൻ ഉത്തരം നൽകുകയും ചോദിച്ചാൽ നൽകുകയും ചെയ്യും." (ദ,തു,ന,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 908, 909, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ أَسْمَاءَ بِنْتِ يَزِيدَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اسْمُ اللهِ الْأَعْظَمُ فِي هَاتَيْنِ الْآيَتَيْنِ: {وَإِلَهُكُمْ إِلَهٌ وَاحِدٌ لَا إِلَهَ إِلَّا هُوَ الرَّحْمَنُ الرَّحِيمُ} [البقرة: ١٦٣]. وَفَاتِحَةِ سُورَةِ آلِ عِمْرَانَ". (د,ت,جه)', 'അസ്മാഅ് ബിൻത് യസീദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ മഹോന്നത നാമം ഈ രണ്ട് സൂക്തങ്ങളിലുണ്ട്: ''നിങ്ങളുടെ ഇലാഹ് ഒരുവനാണ്. അവനല്ലാതെ ആരാധ്യനില്ല. അവൻ കാരുണ്യവാനും കരുണാവാരിധിയുമാണ്.'' (2:163), ''ആലുഇംറാൻ'' സൂറത്തിന്റെ തുടക്കത്തിലും." (ദ,തു,ജ)', 'أَسْمَاءَ بِنْتِ يَزِيدَ', 'അസ്മാഅ് ബിൻത് യസീദ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], 'البقرة: ١٦٣', null, 909, 909, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "اللَّهُمَّ، إِنِّي أَسْأَلُكَ بِاسْمِكَ الطَّاهِرِ الطَّيِّبِ الْمُبَارَكِ الْأَحَبِّ إِلَيْكَ، الَّذِي إِذَا دُعِيتَ بِهِ أَجَبْتَ، وَإِذَا سُئِلْتَ بِهِ أَعْطَيْتَ، وَإِذَا اسْتُرْحِمْتَ بِهِ رَحِمْتَ، وَإِذَا اسْتُفْرِجْتَ بِهِ فَرَّجْتَ". قَالَتْ: وَقَالَ ذَاتَ يَوْمٍ: "يَا عَائِشَةُ، هَلْ عَلِمْتِ أَنَّ اللهَ قَدْ دَلَّنِي عَلَى الِاسْمِ الَّذِي إِذَا دُعِيَ بِهِ أَجَابَ". قَالَتْ: فَقُلْتُ: يَا رَسُولَ اللهِ، بِأَبِي أَنْتَ وَأُمِّي، فَعَلِّمْنِيهِ. قَالَ: "إِنَّهُ لَا يَنْبَغِي لَكِ يَا عَائِشَةُ". قَالَتْ: فَتَنَحَّيْتُ وَجَلَسْتُ سَاعَةً، ثُمَّ قُمْتُ فَقَبَّلْتُ رَأْسَهُ، ثُمَّ قُلْتُ: يَا رَسُولَ اللهِ، عَلِّمْنِيهِ. قَالَ: "إِنَّهُ لَا يَنْبَغِي لَكِ يَا عَائِشَةُ أَنْ أُعَلِّمَكِ، إِنَّهُ لَا يَنْبَغِي لَكِ أَنْ تَسْأَلِينَ بِهِ شَيْئًا مِنَ الدُّنْيَا". قَالَتْ: فَقُمْتُ فَتَوَضَّأْتُ، ثُمَّ صَلَّيْتُ رَكْعَتَيْنِ، ثُمَّ قُلْتُ: اللَّهُمَّ إِنِّي أَدْعُوكَ اللهَ، وَأَدْعُوكَ الرَّحْمَنَ، وَأَدْعُوكَ الْبَرَّ الرَّحِيمَ، وَأَدْعُوكَ بِأَسْمَائِكَ الْحُسْنَى كُلِّهَا، مَا عَلِمْتُ مِنْهَا وَمَا لَمْ أَعْلَمْ: أَنْ تَغْفِرَ لِي وَتَرْحَمَنِي. قَالَتْ: فَاسْتَضْحَكَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثُمَّ قَالَ: "إِنَّهُ لَفِي الْأَسْمَاءِ الَّتِي دَعَوْتِ بِهَا". (جه)', 'ആഇശ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു. "അല്ലാഹുവേ, നിനക്ക് ഇഷ്ടപ്പെട്ട പരിശുദ്ധവും പരിപാവനവും നല്ലതുമായ നിന്റെ നാമം കൊണ്ട് ഞാൻ ചോദിക്കുന്നു, ആ പേർ കൊണ്ട് ചോദിച്ചാൽ നീ ഉത്തരം ചെയ്യും, ആ പേർ കൊണ്ട് ചോദിച്ചാൽ നീ നൽകും, ആ പേർ കൊണ്ട് നിന്റെ കാരുണ്യം ചോദിച്ചാൽ നീ കരുണ ചെയ്യും, ആ പേർ കൊണ്ട് ദുഃഖത്തെ അകറ്റാൻ ആവശ്യപ്പെട്ടാൽ നീ അകറ്റും". ആഇശ(റ) തുടരുന്നു: ഒരിക്കൽ റസൂൽ(സ) പറഞ്ഞു: "ആഇശാ, ഒരു നാമം അല്ലാഹു എനിക്ക് അറിയിച്ചു തന്നത് നീ അറിഞ്ഞുവോ? അത് കൊണ്ട് പ്രാർത്ഥിച്ചാൽ ഉത്തരം നൽകപ്പെടുക തന്നെചെയ്യും" അവർ പറഞ്ഞു: എന്റെ ഉമ്മയും ഉപ്പയും നിങ്ങൾക്കാണ് റസൂലേ, ആ നാമം എനിക്ക് പഠിപ്പിച്ച് തന്നാലും. നബി(സ) പറഞ്ഞു: "ആഇശാ, അത് നിനക്ക് ആവശ്യമില്ല." അവർ പറയുന്നു: അപ്പോൾ കുറച്ചു സമയം ഞാൻ ഒറ്റക്കിരുന്നു. പിന്നെ എഴുന്നേറ്റു. നബി(സ)യുടെ ശിരസ്സിൽ ചുംബിച്ചു. എന്നിട്ട് ചോദിച്ചു. റസൂലേ, എനിക്കത് പഠിപ്പിച്ച് തന്നാലും. റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ നിനക്ക് പഠിപ്പിച്ച് തന്നാൽ ശരിയാവുകയില്ല. കാരണം നിനക്ക് ആ നാമം കൊണ്ട് ദുനിയാവിലെ കാര്യങ്ങളൊന്നും ചോദിക്കാൻ പറ്റില്ല." ആഇശ(റ) തുടരുന്നു: അപ്പോൾ ഞാൻ എഴുന്നേറ്റു. അംഗശുദ്ധി വരുത്തി. രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. അതിന് ശേഷം ഞാൻ പ്രാർത്ഥിച്ചു: അല്ലാഹുവേ, ഞാൻ നിന്നോട് ദുആ ഇരക്കുന്നു. കരുണാ വാരിധിയേ, നിന്നോട് ഞാൻ ദുആ ഇരക്കുന്നു. കാരുണ്യവാനേ,. ഗുണം ചെയ്യുന്നവനേ, നിന്നോട് ഞാൻ ദുആ ഇരക്കുന്നു. എനിക്ക് അറിയുന്നതും അറിയാത്തതുമായ നിന്റെ പരിശുദ്ധ നാമങ്ങളെ കൊണ്ട് ഞാൻ നിന്നോട് പ്രാർത്ഥിക്കുന്നു. എനിക്ക് പൊറുത്ത് തരികയും എന്നോട് കരുണ കാണിക്കുകയും ചെയ്യേണമേ, ആഇശ(റ) പറയുന്നു: അപ്പോൾ റസൂൽ(സ) ചിരിച്ചു. എന്നിട്ട് പറഞ്ഞു: "അത് നീ ഇപ്പോൾ പ്രാർത്ഥിച്ച നാമങ്ങളിലുണ്ട്." (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 909, 909, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَجُلًا يَقُولُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّكَ أَنْتَ اللهُ الْأَحَدُ الصَّمَدُ، الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ، وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَقَدْ سَأَلَ اللَّهَ بِاسْمِهِ الْأَعْظَمِ، الَّذِي إِذَا سُئِلَ بِهِ أَعْطَى، وَإِذَا دُعِيَ بِهِ أَجَابَ". (د,ت,جه)', 'ബുറൈദ(റ): ഒരാൾ പറയുന്നതായി നബി(സ) കേട്ടു: അല്ലാഹുവേ, നീ ഏകനാണ്, നീ എല്ലാവരും ആശ്രയിക്കുന്നവനും, ആരുടെയും ആശ്രയം ആവശ്യമില്ലാത്തവനുമാണ്, നീ പ്രസവിച്ചിട്ടില്ല, പ്രസവിക്കപ്പെട്ടവനുമല്ല, നിനക്ക് ഒരു തുല്യനുമില്ല. ഇക്കാര്യങ്ങൾ കൊണ്ട് നിന്നോട് ഞാൻ ചോദിക്കുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അദ്ദേഹം അല്ലാഹുവിനോട് തന്റെ മഹത്തായ ഇസ്മ്(പേർ) കൊണ്ട് ചോദിച്ചിരിക്കുന്നു. അത് കൊണ്ടാരെങ്കിലും ചോദിച്ചാൽ നൽകപ്പെടുകയും, പ്രാർത്ഥിച്ചാൽ ഉത്തരം നൽകപ്പെടുകയും ചെയ്യും." (ദ,തു,ജ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 909, 910, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اسْمُ اللَّهِ الْأَعْظَمُ، الَّذِي إِذَا دُعِيَ بِهِ أَجَابَ، فِي سُوَرٍ ثَلَاثٍ: الْبَقَرَةِ، وَآلِ عِمْرَانَ، وَطَهَ". (جه)', 'അബൂ ഉമാമത്(റ): നബി(സ) പറഞ്ഞു: "ദുആ ചെയ്യപ്പെട്ടാൽ അല്ലാഹു ഉത്തരം നൽകുന്ന അവന്റെ ഇസ്മുൽ അഅ്ളം (ശ്രേഷ്ഠമായ പേർ), അൽബഖറഃ, ആലുഇംറാൻ, ത്വാഹാ എന്നീ മൂന്ന് അധ്യായങ്ങളിലുമുണ്ട്." (ജ)', 'أَبِي أُمَامَةَ', 'അബൂ ഉമാമത്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 910, 910, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا مَرَرْتُمْ بِرِيَاضِ الْجَنَّةِ فَارْتَعُوا". قَالُوا: وَمَا رِيَاضُ الْجَنَّةِ؟ قَالَ: "حِلَقُ الذِّكْرِ". (ت)', 'അനസുബ്നു മാലിക്(റ): അല്ലാഹുവിന്റെ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ സ്വർഗ്ഗത്തോപ്പുകളിലൂടെ നടന്നുപോയാൽ നിങ്ങൾ അവയിൽ ആനന്ദത്തോടെ മേഞ്ഞുനടക്കുക." അവർ ചോദിച്ചു: എന്താണ് സ്വർഗ്ഗപ്പൂന്തോപ്പുകൾ? തിരുമേനി(സ) പറഞ്ഞു: "അല്ലാഹുവിനെ സ്മരിക്കുന്ന സദസ്സുകളാണത്." (തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 910, 910, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ عِنْدَ وَفَاتِهِ: "اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي، وَأَلْحِقْنِي بِالرَّفِيقِ الْأَعْلَى". حَسَنٌ صَحِيحٌ. (ق,ت)', 'ആഇശ(റ): റസൂൽ(സ) അവിടുത്തെ വഫാത്തിന്റെ സമയത്ത് പറയുന്നതായി ഞാൻ കേട്ടു: "അല്ലാഹുവേ, നീ എനിക്ക് പൊറുത്ത് തരേണമേ, എന്നോട് കരുണ ചെയ്യേണമേ, അർറഫീഖുൽ അഅ്‌ലാ (ഉന്നതനായ കൂട്ടുകാരനോട്) യുമായി എന്നെ നീ ചേർക്കേണമേ." (ബു,മു,തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 910, 910, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "سَلُوا اللَّهَ عِلْمًا نَافِعًا، وَتَعَوَّذُوا بِاللَّهِ مِنْ عِلْمٍ لَا يَنْفَعُ". (جه)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിനോട് നിങ്ങൾ ഉപകാരപ്രദമായ വിജ്ഞാനം ചോദിക്കുകയും ഉപകരിക്കാത്ത വിജ്ഞാനത്തിൽ നിന്ന് കാവൽ ചോദിക്കുകയും ചെയ്യുക. (ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 910, 910, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "اللَّهُمَّ فَأَيُّمَا مُؤْمِنٍ سَبَبْتُهُ، فَاجْعَلْ ذَلِكَ لَهُ قُرْبَةً إِلَيْكَ يَوْمَ الْقِيَامَةِ". (خ)', 'അബൂഹുറൈറ(റ): അദ്ദേഹം നബി(സ) പറയുന്നതായി കേട്ടു: "അല്ലാഹുവേ, വല്ല സത്യവിശ്വാസിയെയും ഞാൻ ശകാരിച്ചിട്ടുണ്ടെങ്കിൽ അത് അവന് പുനരുദ്ധാന ദിവസത്തിൽ നിന്നെ സമീപിക്കാനുള്ള ഒരു സുകൃതമാക്കേണമേ." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 910, 910, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُعَلِّمُنَا هَذَا الدُّعَاءَ، كَمَا يُعَلِّمُنَا السُّورَةَ مِنَ الْقُرْآنِ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ". (م,د,ت,ن,جه)', 'ഇബ്‌നു അബ്ബാസ്(റ): റസൂൽ(സ) ഖുർആനിലെ അധ്യായം പഠിപ്പിക്കുന്നത് പോലെ ഈ പ്രാർത്ഥന ഞങ്ങൾക്ക് പഠിപ്പിച്ച് തന്നിരുന്നു: "അല്ലാഹുവേ, നിന്നോട് ഞാൻ നരകശിക്ഷയിൽ നിന്ന് കാവൽ ചോദിക്കുന്നു. ഖബ്‌റിലെ ശിക്ഷയിൽ നിന്നും ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു. സർവ്വ സഞ്ചാരിയായ ദജ്ജാലിന്റെ വഴികേടിൽ നിന്നും ഞാൻ നിന്നോട് കാവലിനെ ചോദിക്കുന്നു. ജീവിതത്തിന്റെയും മരണത്തിന്റെയും കഷ്ടതകളിൽ നിന്നും ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു." (മു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്‌നു അബ്ബാസ്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 911, 911, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ كَانَ يُعَلِّمُ بَنِيهِ هَؤُلَاءِ الْكَلِمَاتِ كَمَا يُعَلِّمُ الْمُكَتِّبُ الْغِلْمَانَ، وَيَقُولُ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَتَعَوَّذُ بِهِنَّ دُبُرَ الصَّلَاةِ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْجُبْنِ، وَأَعُوذُ بِكَ مِنَ الْبُخْلِ، وَأَعُوذُ بِكَ مِنْ أَرْذَلِ الْعُمُرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا وَعَذَابِ الْقَبْرِ". حَسَنٌ صَحِيحٌ. (خ,ت,ن)', 'സഅദ്ബിൻ അബീ വഖാസ്(റ): ഒരു അധ്യാപകൻ തന്റെ ശിഷ്യന്മാരെ പഠിപ്പിക്കുന്നത് പോലെ, അദ്ദേഹം ഈ വചനങ്ങൾ തന്റെ മക്കൾക്ക് പഠിപ്പിക്കുമായിരുന്നു. അദ്ദേഹം പറയും: റസൂൽ(സ) നിസ്കാരത്തിന്റെ പിറകെ ഈ പ്രാർത്ഥന കൊണ്ട് കാവൽചോദിക്കുമായിരുന്നു: "അല്ലാഹുവേ, ഭീരുത്വത്തിൽ നിന്ന് നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു. പിശുക്കിൽ നിന്നും അമിത വാർദ്ധക്യത്തിൽ നിന്നും ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു. ദുനിയാവിന്റെ പരീക്ഷണത്തിൽ നിന്നും ഖബ്‌ർ ശിക്ഷയിൽ നിന്നും നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു." (ബു,തു,ന)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅദ്ബിൻ അബീ വഖാസ്(റ)', null, null, array['خ','ت','ن']::text[], array['ബു','തു','ന']::text[], null, null, 911, 911, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ دَخَلَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى امْرَأَةٍ وَبَيْنَ يَدَيْهَا نَوَاةٌ - أَوْ: حَصَاةٌ - تُسَبِّحُ بِهَا، فَقَالَ: "أَلَا أُخْبِرُكِ بِمَا هُوَ أَيْسَرُ عَلَيْكِ مِنْ هَذَا أَوْ أَفْضَلُ؟ سُبْحَانَ اللَّهِ عَدَدَ مَا خَلَقَ فِي السَّمَاءِ، وَسُبْحَانَ اللَّهِ عَدَدَ مَا خَلَقَ فِي الْأَرْضِ، وَسُبْحَانَ اللَّهِ عَدَدَ مَا بَيْنَ ذَلِكَ، وَسُبْحَانَ اللَّهِ عَدَدَ مَا هُوَ خَالِقٌ، وَاللَّهُ أَكْبَرُ مِثْلَ ذَلِكَ، وَالْحَمْدُ لِلَّهِ مِثْلَ ذَلِكَ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ مِثْلَ ذَلِكَ". (د,ت)', 'സഅ്ദുബ്‌നു അബീ വഖാസ്(റ): അദ്ദേഹം റസൂൽ(സ)യുടെ കൂടെ ഒരു സ്ത്രീയുടെ അടുത്ത് വന്നു. അവരുടെ മുന്നിൽ താൻ തസ്ബീഹ് ചൊല്ലുന്ന ഈത്തപ്പഴക്കുരു - അതോ, കല്ല് എന്നോ, (നിവേദകൻ സംശയിക്കുന്നു) - വുമുണ്ടായിരുന്നു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "ഇതിനേക്കാൾ വളരെ എളുപ്പമുള്ളത് അല്ലെങ്കിൽ ഏറ്റവും ശ്രേഷ്ഠമായ ഒന്ന് നിങ്ങൾക്ക് ഞാൻ അറിയിച്ച് തരട്ടെയോ: "ആകാശത്ത് സൃഷ്ടിച്ചവയുടെ എണ്ണമത്രയും അല്ലാഹുവിന്റെ പരിശുദ്ധിയെ ഞാൻ വാഴ്ത്തുന്നു, ഭൂമിയിൽ താൻ പടച്ചവയുടെ എണ്ണമത്രയും അല്ലാഹുവിന്റെ പരിശുദ്ധിയെ ഞാൻ വാഴ്ത്തുന്നു, സൃഷ്ടിക്കാൻ പോകുന്നതിന്റെ എണ്ണമത്രയും അല്ലാഹുവിനെ ഞാൻ വാഴ്ത്തുന്നു. അത്ര പ്രാവശ്യം ഞാൻ ''അല്ലാഹു അക്ബർ'' (അല്ലാഹുവാണ് ഉന്നതൻ) എന്ന് ചൊല്ലുന്നു. അത്ര പ്രാവശ്യം ''അൽഹംദുലില്ലാഹ്''(അല്ലാഹുവിനാണ് സർവ്വ സ്തുതിയും) എന്നും പറയുന്നു. അത്ര പ്രാവശ്യം ''ലാഹൗല വലാഖുവ്വത ഇല്ലാബില്ലാഹ്'' (അവനെക്കൊണ്ടല്ലാതെ ഒരു ശക്തിയും കഴിവുമില്ല) എന്നും പറയുന്നു." (ദ,തു)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദുബ്‌നു അബീ വഖാസ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, 'നിവേദകൻ സംശയിക്കുന്നു', 911, 911, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنِ الزُّبَيْرِ بْنِ الْعَوَّامِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ صَبَاحٍ يُصْبِحُ الْعَبْدُ فِيهِ إِلَّا وَمُنَادٍ يُنَادِي: سُبْحَانَ الْمَلِكِ الْقُدُّوسِ". (ت)', 'സുബൈറുബ്‌നുൽ അവ്വാം(റ): നബി(സ) പറഞ്ഞു: "പരിശുദ്ധനും രാജാധികാരിയുമായവൻ എത്ര പരിശുദ്ധനാണ് എന്ന് വിളിച്ച് പറയുന്നവൻ പറഞ്ഞിട്ടല്ലാതെ ഒരു അടിമയും നേരം പുലരുന്നില്ല." (തു)', 'الزُّبَيْرِ بْنِ الْعَوَّامِ', 'സുബൈറുബ്‌നുൽ അവ്വാം(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 911, 911, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَتَمَنَّيَنَّ أَحَدُكُمُ الْمَوْتَ لِضُرٍّ نَزَلَ بِهِ، فَإِنْ كَانَ لَا بُدَّ مُتَمَنِّيًا فَلْيَقُلِ: اللَّهُمَّ أَحْيِنِي مَا كَانَتِ الْحَيَاةُ خَيْرًا لِي، وَتَوَفَّنِي إِذَا كَانَتِ الْوَفَاةُ خَيْرًا لِي". (م)', 'അനസ്(റ): റസൂൽ(സ) പറയുന്നു: "നിങ്ങളിലൊരാൾക്ക് വന്നുപെട്ട ബുദ്ധിമുട്ട് കാരണം അവൻ ഒരിക്കലും മരണത്തെ ആഗ്രഹിക്കരുത്, ഇനി ആഗ്രഹിച്ചേ പറ്റുവെങ്കിൽ അവൻ ഇങ്ങനെ പറയട്ടെ: അല്ലാഹുവേ, ജീവിതം എനിക്ക് നന്മയാകുന്ന കാലത്തോളം എന്നെ നീ ജീവിപ്പിക്കുകയും, മരണമാണ് നന്മയെങ്കിൽ മരിപ്പിക്കുകയും ചെയ്യേണമേ." (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 912, 912, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَتَمَنَّى أَحَدُكُمُ الْمَوْتَ، وَلَا يَدْعُ بِهِ مِنْ قَبْلِ أَنْ يَأْتِيَهُ، إِنَّهُ إِذَا مَاتَ أَحَدُكُمُ انْقَطَعَ عَمَلُهُ، وَإِنَّهُ لَا يَزِيدُ الْمُؤْمِنَ عُمْرُهُ إِلَّا خَيْرًا". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലാരും മരണത്തെ ആഗ്രഹിക്കരുത്. മരിക്കുന്നതിന് മുമ്പ് അതിന് വേണ്ടി പ്രാർത്ഥിക്കുകയും ചെയ്യരുത്. കാരണം ഒരാൾ മരിച്ചാൽ അവന്റെ പ്രവർത്തനം മുറിഞ്ഞുപോകും. ഒരു സത്യവിശ്വാസിക്ക് തന്റെ ആയുസ്സ് നന്മ മാത്രമേ വർധിപ്പിക്കൂ." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 912, 912, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ أَكْثَرُ دُعَاءِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اللَّهُمَّ رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً، وَفِي الْآخِرَةِ حَسَنَةً، وَقِنَا عَذَابَ النَّارِ". (خ)', 'അനസ്(റ): റസൂൽ(സ)യുടെ അധിക ദുആയും ഇപ്രകാരമായിരുന്നു: "ഞങ്ങളുടെ രക്ഷിതാവായ അല്ലാഹുവേ, ദുനിയാവിൽ ഞങ്ങൾക്ക് നന്മ നൽകേണമേ, പരലോകത്തും നന്മ നൽകേണമേ, നരകശിക്ഷയിൽ നിന്ന് ഞങ്ങളെ രക്ഷിക്കുകയും ചെയ്യേണമേ." (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 912, 912, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ كَانَ يَدْعُو: "اللَّهُمَّ اغْفِرْ لِي خَطِيئَتِي وَجَهْلِي، وَإِسْرَافِي فِي أَمْرِي، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي. اللَّهُمَّ اغْفِرْ لِي هَزْلِي وَجِدِّي وَخَطَايَايَ وَعَمْدِي، وَكُلُّ ذَلِكَ عِنْدِي". (خ)', 'അബൂമൂസൽ അശ്അരി(റ): നബി(സ) ഇങ്ങനെ ദുആ ചെയ്യാറുണ്ടായിരുന്നു. "അല്ലാഹുവേ, എന്റെ തെറ്റുകളും അറിവില്ലായ്മയും നീ എനിക്ക് പൊറുത്ത് തരേണമേ, എന്റെ കാര്യത്തിലെ അമിതവ്യയത്തെയും, നീ എന്നേക്കുറിച്ച് അറിയുന്നകാര്യങ്ങളും (എനിക്ക് പൊറുത്ത് തരേണമേ). അല്ലാഹുവേ, ഞാൻ മനഃപൂർവ്വമോ, അറിയാതെയോ ചെയ്തതിനെയും, കാര്യത്തിലോ തമാശയിലോ ചെയ്തതിനെയും, എന്നിൽ നിന്ന് വന്നുപോയ സർവ്വത്തെയും എനിക്ക് നീ പൊറുത്ത് നൽകേണമേ." (ബു)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമൂസൽ അശ്അരി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 912, 912, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ عُمَرَ بْنِ أَبِي سَلَمَةَ، عَنْ أُمِّهِ أُمِّ سَلَمَةَ، عَنْ أَبِي سَلَمَةَ رَضِيَ اللَّهُ عَنْهُمْ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أَصَابَ أَحَدَكُمْ مُصِيبَةٌ فَلْيَقُلْ: إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، اللَّهُمَّ عِنْدَكَ احْتَسَبْتُ مُصِيبَتِي، فَأْجُرْنِي فِيهَا وَأَبْدِلْنِي مِنْهَا خَيْرًا". فَلَمَّا احْتُضِرَ أَبُو سَلَمَةَ قَالَ: اللَّهُمَّ اخْلُفْ فِي أَهْلِي خَيْرًا مِنِّي. فَلَمَّا قُبِضَ قَالَتْ أُمُّ سَلَمَةَ: إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، عِنْدَ اللَّهِ احْتَسَبْتُ مُصِيبَتِي، فَأْجُرْنِي فِيهَا. حَسَنٌ. (ت,جه)', 'ഉമറുബ്നുഅബീസലമ(റ) തന്റെ ഉമ്മയായ ഉമ്മുസലമ(റ)യിൽ നിന്നും, മഹതി അബൂസലമ(റ)യിൽ നിന്നും നിവേദനം ചെയ്യുന്നു: റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിൽ ആർക്കെങ്കിലും വല്ല ബുദ്ധിമുട്ടും വന്നാൽ അവന്‍ പറയട്ടെ: തീര്‍ച്ചയായും ഞങ്ങള്‍ അല്ലാഹുവിനാകുന്നു. അവനിലേക്ക് തന്നെ മടങ്ങുന്നവരുമാകുന്നു. അല്ലാഹുവേ, എനിക്ക് വന്ന വിപത്തിന് നിന്റെയടുക്കല്‍ ഞാന്‍ തൃപ്തിയണഞ്ഞു. അത് കൊണ്ട് നീ അതില്‍ എനിക്ക് പ്രതിഫലം നല്‍കുകയും അതിനേക്കാള്‍ ഉത്തമമായത് പകരം നല്‍കുകയും ചെയ്യേണമേ.” അങ്ങനെ അബൂസലമ(റ)ക്ക് മരണമാസന്നമായാപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവേ, എന്റെ കുടുംബത്തില്‍ എന്നേക്കാള്‍ നല്ലവനെ നീ പകരക്കാരനാക്കണേ. അങ്ങനെ അബൂസലമ(റ) മരണപ്പെട്ടപ്പോള്‍ ഉമ്മു സലമ(റ) പറഞ്ഞു: നിശ്ചയം ഞങ്ങള്‍ അല്ലാഹുവിനാകുന്നു. അവനിലേക്ക് തന്നെ മടങ്ങുന്നവരുമാകുന്നു. അല്ലാഹുവേ, എനിക്ക് വന്ന വിപത്തിന് ഞാന്‍ നിന്റെയടുക്കല്‍ തൃപ്തിയണഞ്ഞു. അത് കൊണ്ട് നീ അതില്‍ എനിക്ക് പ്രതിഫലം നല്‍കേണമേ. (തു,ജ)', 'عُمَرَ بْنِ أَبِي سَلَمَةَ، عَنْ أُمِّهِ أُمِّ سَلَمَةَ، عَنْ أَبِي سَلَمَةَ', 'ഉമറുബ്നുഅബീസലമ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 912, 913, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنِ ابْنِ عُمَرَ عَنْ أَبِيهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ”مَنْ دَخَلَ السُّوقَ فَقَالَ - وفي رواية: مَنْ قَالَ فِي السُّوقِ -: لَا إِلَهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، يُحْيِي وَيُمِيتُ وَهُوَ حَيٌّ لَا يَمُوتُ، بِيَدِهِ الْخَيْرُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. كَتَبَ اللهُ لَهُ أَلْفَ أَلْفِ حَسَنَةٍ، وَمَحَى عَنْهُ أَلْفَ أَلْفِ سَيِّئَةٍ، وَرَفَعَ لَهُ أَلْفَ أَلْفِ دَرَجَةٍ“ وفي رواية: ”وَبَنَى لَهُ بَيْتًا فِي الجَنَّةِ“. (ت،جه)', 'ഇബ്നു ഉമര്‍(റ) തന്റെ പിതാവില്‍ നിന്ന് നിവേദനം ചെയ്യുന്നു: റസൂല്‍(സ) പറഞ്ഞു: “ആരെങ്കിലും അങ്ങാടിയില്‍ പോകുകയും ഇങ്ങനെ പറയുകയും ചെയ്താല്‍ - മറ്റൊരു നിവേദനത്തില്‍: ആരെങ്കിലും അങ്ങാടിയില്‍ വെച്ച് ഇപ്രകാരം പറഞ്ഞാല്‍ - അവന് പത്ത് ലക്ഷം നന്മയെ അല്ലാഹു എഴുതി വെക്കുകയുംപത്ത് ലക്ഷം തിന്മയെ മായ്ച്ച് കളയുകയും, പത്ത് ലക്ഷം സ്ഥാനത്തെ ഉയര്‍ത്തിക്കൊടുക്കുകയും ചെയ്യും. മറ്റൊരു നിവേദനത്തില്‍: അവന് സ്വര്‍ഗ്ഗത്തില്‍ ഒരു വീട് പണികഴിപ്പിക്കപ്പെടുകയും ചെയ്യും: ''അല്ലാഹുവല്ലാതെ ഒരാരാധ്യനുമില്ല. അവന്‍ ഏകനാണ്. അവന് ഒരു പങ്കാളിയുമില്ല. അവനാണ് സര്‍വ്വധികാരം, സര്‍വ്വസ്തുതിയും അവന് തന്നെ. അവന്‍ ജീവിപ്പിക്കുകയും മരിപ്പിക്കുകയും ചെയ്യുന്നു. അവന്‍ ജീവിക്കുന്നവനാണ്, അവന് മരണമില്ല. അവന്റെ കയ്യിലാകുന്നു സര്‍വ്വ നന്മയും. അവന്‍ സര്‍വ്വ വസ്തുക്കളിലും കഴിവുള്ളവനാകുന്നു.” മറ്റൊരു നിവേദനത്തില്‍: “അവന് സ്വര്‍ഗ്ഗത്തില്‍ ഒരു വീട് പണികഴിപ്പിക്കപ്പെടുകയും ചെയ്യും.” (തു,ജ)', 'ابْنِ عُمَرَ عَنْ أَبِيهِ', 'ഇബ്നു ഉമര്‍(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 913, 913, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=86), 1, 'وَفِي رِوَايَةٍ: مَنْ قَالَ فِي السُّوقِ -: لَا إِلَهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، يُحْيِي وَيُمِيتُ وَهُوَ حَيٌّ لَا يَمُوتُ، بِيَدِهِ الْخَيْرُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. كَتَبَ اللهُ لَهُ أَلْفَ أَلْفِ حَسَنَةٍ، وَمَحَى عَنْهُ أَلْفَ أَلْفِ سَيِّئَةٍ، وَرَفَعَ لَهُ أَلْفَ أَلْفِ دَرَجَةٍ“', 'മറ്റൊരു നിവേദനത്തില്‍: ആരെങ്കിലും അങ്ങാടിയില്‍ വെച്ച് ഇപ്രകാരം പറഞ്ഞാല്‍ - അവന് പത്ത് ലക്ഷം നന്മയെ അല്ലാഹു എഴുതി വെക്കുകയുംപത്ത് ലക്ഷം തിന്മയെ മായ്ച്ച് കളയുകയും, പത്ത് ലക്ഷം സ്ഥാനത്തെ ഉയര്‍ത്തിക്കൊടുക്കുകയും ചെയ്യും.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=86), 2, 'وَفِي رِوَايَةٍ: ”وَبَنَى لَهُ بَيْتًا فِي الجَنَّةِ“. (ت،جه)', 'മറ്റൊരു നിവേദനത്തില്‍: അവന് സ്വര്‍ഗ്ഗത്തില്‍ ഒരു വീട് പണികഴിപ്പിക്കപ്പെടുകയും ചെയ്യും: ''അല്ലാഹുവല്ലാതെ ഒരാരാധ്യനുമില്ല. അവന്‍ ഏകനാണ്. അവന് ഒരു പങ്കാളിയുമില്ല. അവനാണ് സര്‍വ്വധികാരം, സര്‍വ്വസ്തുതിയും അവന് തന്നെ. അവന്‍ ജീവിപ്പിക്കുകയും മരിപ്പിക്കുകയും ചെയ്യുന്നു. അവന്‍ ജീവിക്കുന്നവനാണ്, അവന് മരണമില്ല. അവന്റെ കയ്യിലാകുന്നു സര്‍വ്വ നന്മയും. അവന്‍ സര്‍വ്വ വസ്തുക്കളിലും കഴിവുള്ളവനാകുന്നു.”');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=86), 3, null, 'മറ്റൊരു നിവേദനത്തില്‍: “അവന് സ്വര്‍ഗ്ഗത്തില്‍ ഒരു വീട് പണികഴിപ്പിക്കപ്പെടുകയും ചെയ്യും.” (തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: ”إِذَا دَخَلَ الرَّجُلُ بَيْتَهُ، فَذَكَرَ اللهَ عِنْدَ دُخُولِهِ وَعِنْدَ طَعَامِهِ، قَالَ الشَّيْطَانُ: لَا مَبِيتَ لَكُمْ وَلَا عَشَاءَ. وَإِذَا دَخَلَ وَلَمْ يَذْكُرِ اللهَ عِنْدَ دُخُولِهِ، قَالَ الشَّيْطَانُ: أَدْرَكْتُمُ الْمَبِيتَ. فَإِذَا لَمْ يَذْكُرِ اللهَ عِنْدَ طَعَامِهِ قَالَ: أَدْرَكْتُمُ الْمَبِيتَ وَالْعَشَاءَ“. (م،د،جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂല്‍(സ) പറയുന്നത് അദ്ദേഹം കേട്ടു: “ഒരാള്‍ തന്റെ വീട്ടില്‍ പ്രവേശിക്കുകയും വീട്ടില്‍ കടക്കുമ്പോഴും ഭക്ഷണം കഴിക്കുമ്പോഴും അല്ലാഹുവിനെ സ്മരിക്കുകയും ചെയ്താല്‍ ശൈത്വാന്‍ (തന്റെ അനുയായികളോട്) പറയും. ഇന്ന് നിങ്ങള്‍ക്ക് അത്താഴവും താമസിക്കാന്‍ ഇടവുമില്ല. മറിച്ച് വീട്ടില്‍ പ്രവേശിച്ചപ്പോള്‍ അല്ലാഹുവിനെ സ്മരിക്കാതിരുന്നാല്‍ ശൈത്വാന്‍ പറയും: ഇന്ന് നിങ്ങള്‍ക്ക് പാര്‍പ്പിടമുണ്ട്. അതുപോലെ ഭക്ഷണ സമയത്ത് അല്ലാഹുവിനെ സ്മരിച്ചില്ലെങ്കില്‍ ശൈത്വാന്‍ പറയും: നിങ്ങള്‍ക്ക് ഇന്ന് പാര്‍പ്പിടവും അത്താഴവുമുണ്ട്.” (മു,ദ,ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 913, 913, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَالَ يَعْنِي إِذَا خَرَجَ مِنْ بَيْتِهِ: بِسْمِ اللهِ، تَوَكَّلْتُ عَلَى اللهِ، لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللهِ، يُقَالُ لَهُ: كُفِيتَ وَوُقِيتَ، وَتَنَحَّى عَنْهُ الشَّيْطَانُ". حَسَنٌ صَحِيحٌ. (د,ت)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും വീട്ടിൽ നിന്ന് പുറത്തിറങ്ങുമ്പോൾ: ''അല്ലാഹുവിന്റെ നാമത്തിൽ(ഞാൻ പുറപ്പെടുന്നു), ഞാൻ അല്ലാഹുവിന്റെ മേൽ ഭരമേൽപ്പിക്കുന്നു, കഴിവും ശക്തിയും, അവന് മാത്രമാണ്.'' എന്ന് പറഞ്ഞാൽ അവനോട് പറയപ്പെടും: നിനക്ക് (അല്ലാഹു) മതിയായവനായിരിക്കുന്നു. നിനക്ക് സംരക്ഷണം നൽകപ്പെട്ടു. മാത്രമല്ല നിന്നെതൊട്ട് ചെകുത്താൻ അകന്നു നിൽക്കുകയും ചെയ്യും." (ദ,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 914, 914, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا خَرَجَ مِنْ بَيْتِهِ قَالَ: "بِسْمِ اللهِ، تَوَكَّلْتُ عَلَى اللهِ، اللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ أَنْ نَزِلَّ، أَوْ نَضِلَّ، أَوْ نَظْلِمَ أَوْ نُظْلَمَ، أَوْ نَجْهَلَ أَوْ يُجْهَلَ عَلَيْنَا". حَسَنٌ صَحِيحٌ. (د,ت,ن,جه)', 'ഉമ്മു സലമ(റ): നബി(സ) വീട്ടിൽ നിന്ന് പുറത്ത് കടക്കുമ്പോൾ പറയുമായിരുന്നു: "അല്ലാഹുവിന്റെ നാമത്തിൽ ഞാൻ പുറപ്പെടുന്നു. അവന്റെ മേൽ ഞാൻ ഭരമേൽപ്പിക്കുന്നു. അല്ലാഹുവേ, വഴുതി വീഴുന്നതിൽ നിന്നും പിഴച്ചു പോകുന്നതിൽ നിന്നും അക്രമം പ്രവർത്തിക്കുന്നതിൽ നിന്നും അക്രമിക്കപ്പെടുന്നതിൽ നിന്നും അജ്ഞനാവുന്നതിൽ നിന്നും അജ്ഞനാക്കപ്പെടുന്നതിൽ നിന്നും ഞങ്ങൾ നിന്നോട് കാവൽ ചോദിക്കുന്നു." (ദ,തു,ന,ജ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മു സലമ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 914, 914, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ خَوْلَةَ بِنْتِ حَكِيمٍ السُّلَمِيَّةِ رَضِيَ اللهُ عَنْهَا، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ نَزَلَ مَنْزِلًا ثُمَّ قَالَ: أَعُوذُ بِكَلِمَاتِ اللهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ. لَمْ يَضُرَّهُ شَيْءٌ حَتَّى يَرْتَحِلَ مِنْ مَنْزِلِهِ ذَلِكَ". حَسَنٌ صَحِيحٌ. (م,ت,جه)', 'ഖൗലത് ബിൻതു ഹകീമിനിസ്സുലമിയ്യ(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ ഒരു വീട്ടിൽ പ്രവേശിക്കുകയും, ''പരിപൂർണ്ണമായ അല്ലാഹുവിന്റെ വചനങ്ങൾ കൊണ്ട് അവന്റെ സൃഷ്ടികളുടെ നാശത്തിൽ നിന്ന് ഞാൻ കാവൽ ചോദിക്കുന്നു'' എന്ന് പറയുകയും ചെയ്താൽ അവൻ ആ സ്ഥലത്ത് നിന്ന് യാത്ര ചെയ്യുന്നത് വരെ അവനെ ഒരു വസതുവും ബുദ്ധിമുട്ടിക്കുകയില്ല." (മു,തു,ജ)', 'خَوْلَةَ بِنْتِ حَكِيمٍ السُّلَمِيَّةِ', 'ഖൗലത് ബിൻതു ഹകീമിനിസ്സുലമിയ്യ(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 914, 914, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ عَبْدِ اللهِ بْنِ سَرْجِسَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ - وَفِي رواية: يَتَعَوَّذُ - إِذَا سَافَرَ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ، وَكَآبَةِ الْمُنْقَلَبِ، وَالْحَوْرِ بَعْدَ الْكَوْرِ، وَدَعْوَةِ الْمَظْلُومِ، وَسُوءِ الْمَنْظَرِ فِي الْأَهْلِ وَالْمَالِ". فَإِذَا رَجَعَ، قَالَ مِثْلَهَا. (م,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു സർജിസ്(റ): തിരുനബി(സ) യാത്ര ചെയ്യുമ്പോൾ പറയുമായിരുന്നു. - ഒരു നിവേദനത്തിൽ: കാവൽ ചോദിക്കുമായിരുന്നു. - "അല്ലാഹുവേ, യാത്രയുടെ ബുദ്ധിമുട്ടികളിൽ നിന്നും മടക്ക സമയത്തുണ്ടാകുന്ന മോശമായ അവസ്ഥയിൽ നിന്നും ഐശ്വര്യത്തിന് ശേഷമുള്ള ക്ഷാമത്തിൽ നിന്നും അക്രമിക്കപ്പെട്ടവന്റെ പ്രാർത്ഥനയിൽ നിന്നും സ്വത്തിലും കുടുംബത്തിലും മോശമായത് കാണുന്നതിൽ നിന്നും ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു." യാത്രയിൽ നിന്ന് മടങ്ങി വന്നാലും റസൂൽ(സ) ഇതു പോലെ പറയുമായിരുന്നു. (മു,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ سَرْجِسَ', 'അബ്ദുല്ലാഹിബ്നു സർജിസ്(റ)', null, null, array['م','ت','ن','جه']::text[], array['മു','തു','ന','ജ']::text[], null, null, 914, 915, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=91), 1, 'وَفِي رِوَايَةٍ: يَتَعَوَّذُ - إِذَا سَافَرَ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ، وَكَآبَةِ الْمُنْقَلَبِ، وَالْحَوْرِ بَعْدَ الْكَوْرِ، وَدَعْوَةِ الْمَظْلُومِ، وَسُوءِ الْمَنْظَرِ فِي الْأَهْلِ وَالْمَالِ". فَإِذَا رَجَعَ، قَالَ مِثْلَهَا. (م,ت,ن,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا سَافَرَ فَرَكِبَ رَاحِلَتَهُ قَالَ بِإِصْبَعِهِ: "اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ، وَالْخَلِيفَةُ فِي الْأَهْلِ، اللَّهُمَّ اصْحَبْنَا بِنُصْحِكَ، وَاقْلِبْنَا بِذِمَّتِكَ. اللَّهُمَّ ازْوِ لَنَا الْأَرْضَ. وَهَوِّنْ عَلَيْنَا السَّفَرَ. اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ، وَكَآبَةِ الْمُنْقَلَبِ". حَسَنٌ. (م,د,ت,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) യാത്രക്ക് തയ്യാറായി വാഹനത്തിന് മുകളിൽ കയറിയാൽ കൈവിരൽ കൊണ്ട് (അംഗ്യം കാണിച്ച്) ഇപ്രകാരം പറയുമായിരുന്നു: "അല്ലാഹുവേ, നീയാണ് യാത്രയിലെ കൂട്ടുകാരൻ, വീട്ടിൽ ഞങ്ങളുടെ പ്രതിനിധിയും നീയാണ്, സദുപദേശം നൽകി നീ ഞങ്ങളുടെ കൂടെയാവണമേ. നിന്റെ ഉത്തരവാദിത്വത്തിൽ ഞങ്ങളെ മടക്കേണമേ. അല്ലാഹുവേ, ഭൂമിയെ ഞങ്ങൾക്ക് നീ ചുരുക്കേണമേ. യാത്ര ഞങ്ങൾക്ക് എളുപ്പമാക്കിത്തരേണമേ. അല്ലാഹുവേ, യാത്രയുടെ ബുദ്ധിമുട്ടുകളിൽ നിന്നും മടങ്ങിവന്നാലുള്ള വിഷമത്തിൽ നിന്നും ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു." (മു,ദ,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 915, 915, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ عَبْدِ اللَّهِ بْنِ سَرْجِسَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا سَافَرَ يَقُولُ: "اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ، وَالْخَلِيفَةُ فِي الْأَهْلِ. اللَّهُمَّ اصْحَبْنَا فِي سَفَرِنَا، وَاخْلُفْنَا فِي أَهْلِنَا. اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ، وَكَآبَةِ الْمُنْقَلَبِ، وَمِنَ الْحَوْرِ بَعْدَ الْكَوْرِ، وَمِنْ دَعْوَةِ الْمَظْلُومِ، وَمِنْ سُوءِ الْمَنْظَرِ فِي الْأَهْلِ وَالْمَالِ". حَسَنٌ صَحِيحٌ. (م,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു സർജിസ്(റ): യാത്ര ചെയ്യുമ്പോൾ നബി(സ) പറയാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ, നീയാണ് യാത്രയിലെ കൂട്ടുകാരൻ, വീട്ടിലെ പ്രതിനിധിയും. യാത്രയിൽ നീ ഞങ്ങളുടെ കൂടെയാവണമേ. ഞങ്ങളുടെ വീട്ടിൽ ഞങ്ങൾക്ക് നീ പ്രതിനിധിയാവേണമേ. അല്ലാഹുവേ, യാത്രയുടെ ബുദ്ധിമുട്ടുകളിൽ നിന്നും, മടങ്ങിയെത്തിയാലുള്ള ദുഃഖത്തിൽ നിന്നും, ഐശ്വര്യത്തിന് ശേഷമുള്ള ക്ഷാമത്തിൽ നിന്നും അക്രമിക്കപ്പെട്ടവന്റെ പ്രാർത്ഥനയിൽ നിന്നും, കുടുംബത്തിലും സമ്പത്തിലും മോശമായതിനെ കാണുന്നതിൽ നിന്നും ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു." (മു,തു,ന,ജ)', 'عَبْدِ اللَّهِ بْنِ سَرْجِسَ', 'അബ്ദുല്ലാഹിബ്നു സർജിസ്(റ)', null, null, array['م','ت','ن','جه']::text[], array['മു','തു','ന','ജ']::text[], null, null, 915, 915, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا قَدِمَ مِنْ سَفَرٍ قَالَ: "آيِبُونَ تَائِبُونَ عَابِدُونَ، لِرَبِّنَا حَامِدُونَ". حَسَنٌ صَحِيحٌ. (ت)', 'ബർറാഉബ്നു ആസിബ്(റ): റസൂൽ(സ) യാത്ര കഴിഞ്ഞുവന്നാൽ: "ഞങ്ങൾ ഖേദിച്ചു മടങ്ങുന്നു. തൗബ ചെയ്യുന്നു. ആരാധന നടത്തുന്നു. ഞങ്ങളുടെ രക്ഷിതാവിനെ ഞങ്ങൾ പുകഴ്ത്തുന്നു." എന്ന് പറയാറുണ്ടായിരുന്നു. (തു)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബർറാഉബ്നു ആസിബ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 915, 915, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا قَدِمَ مِنْ سَفَرٍ فَنَظَرَ إِلَى جُدْرَانِ الْمَدِينَةِ أَوْضَعَ رَاحِلَتَهُ، وَإِنْ كَانَ عَلَى دَابَّةٍ حَرَّكَهَا، مِنْ حُبِّهَا. (خ,ت)', 'അനസ്(റ): നബി(സ) യാത്ര കഴിഞ്ഞ് തിരിച്ച് വരുമ്പോൾ മദീനയിലെ ചുമരുകൾ കണ്ടാൽ മദീനയോടുള്ള സ്നേഹത്താൽ തന്റെ വാഹനത്തെ വേഗത്തിലാക്കുമായിരുന്നു. മറ്റു വല്ല മൃഗത്തിനും മുകളിലാണെങ്കിൽ അതിനെ വേഗത്തിൽ ചലിപ്പിക്കുമായിരുന്നു. (ബു,തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ','ت']::text[], array['ബു','തു']::text[], null, null, 915, 916, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا وَدَّعَ رَجُلًا أَخَذَ بِيَدِهِ، فَلَا يَدَعُهَا حَتَّى يَكُونَ الرَّجُلُ هُوَ يَدَعُ يَدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَيَقُولُ: "أَسْتَوْدِعُ اللهَ دِينَكَ وَأَمَانَتَكَ وَآخِرَ عَمَلِكَ". (ن,جه)', 'ഇബ്നു ഉമർ(റ): റസൂൽ(സ) ഒരാളോട് യാത്ര ചോദിക്കുമ്പോൾ അയാളുടെ കൈ പിടിക്കും. അയാൾ നബി(സ)യുടെ കൈവിടുന്നത് വരെ നബി(സ) അയാളുടെ കൈവിടുകയില്ല. എന്നിട്ട് റസൂൽ(സ) പറയും: "നിന്റെ ദീനിനെയും അമാനത്തിനെയും (സൂക്ഷിപ്പു സ്വത്തിനെയും) അന്ത്യകർമ്മത്തെയും ഞാൻ അല്ലാഹുവിൽ ഏൽപ്പിക്കുന്നു." (ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 916, 916, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ كَانَ يَقُولُ لِلرَّجُلِ إِذَا أَرَادَ سَفَرًا: ادْنُ مِنِّي أُوَدِّعْكَ، كَمَا كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُوَدِّعُنَا، فَيَقُولُ: "أَسْتَوْدِعُ اللهَ دِينَكَ وَأَمَانَتَكَ وَخَوَاتِيمَ عَمَلِكَ". حَسَنٌ صَحِيحٌ. (ت,ن,جه)', 'ഇബ്നു ഉമർ(റ): അവർ യാത്ര പുറപ്പെടുമ്പോൾ മറ്റുള്ളവരോട് പറയുമായിരുന്നു. അടുത്തു നിൽക്കൂ. ഞാൻ നിന്നോട് യാത്ര ചോദിക്കട്ടെ, റസൂൽ(സ) ഞങ്ങളോട് യാത്ര ചോദിക്കാറുണ്ടായിരുന്നത് പോലെ. നബി(സ) പറയുമായിരുന്നു: "നിന്റെ ദീനും അമാനത്തും കർമ്മത്തിന്റെ അവസാനവും ഞാൻ അല്ലാഹുവിൽ ഏൽപ്പിക്കുന്നു." (തു,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 916, 916, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللهِ، إِنِّي أُرِيدُ سَفَرًا، فَزَوِّدْنِي. قَالَ: "زَوَّدَكَ اللهُ التَّقْوَى". قَالَ: زِدْنِي، قَالَ: "وَغَفَرَ ذَنْبَكَ". قَالَ: زِدْنِي بِأَبِي أَنْتَ وَأُمِّي، قَالَ: "وَيَسَّرَ لَكَ الْخَيْرَ حَيْثُمَا كُنْتَ". حَسَنٌ. (ت)', 'അനസ്(റ): ഒരാൾ റസൂൽ(സ)യുടെ അടുക്കൽ വന്നുപറഞ്ഞു: തിരുദൂതരേ, ഞാൻ യാത്രക്കുദ്ദേശിക്കുന്നു. അങ്ങ് എനിക്ക് യാത്രക്കുള്ള പാഥേയമൊരുക്കിത്തന്നാലും. റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു ഭക്തിയെ നിനക്ക് പാഥേയമാക്കിത്തരട്ടെ." അദ്ദേഹം പറഞ്ഞു: ഇനിയും (റസൂലേ), നബി(സ) പറഞ്ഞു: "നിന്റെ പാപം പൊറുത്ത് തരികയും ചെയ്യട്ടെ." അദ്ദേഹം പറഞ്ഞു: എന്റെ ഉമ്മയും ഉപ്പയും അങ്ങേക്ക് സമർപ്പണമാണ് റസൂലേ, എനിക്ക് (ഇനിയും) അധികം നൽകേണേ. റസൂൽ(സ) പറഞ്ഞു: "നന്മയെ നിനക്ക് എളുപ്പമാക്കിത്തരട്ടെ, നീ എവിടെയായിരുന്നാലും." (തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 916, 916, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا قَالَ: يَا رَسُولَ اللَّهِ، إِنِّي أُرِيدُ أَنْ أُسَافِرَ، فَأَوْصِنِي. قَالَ: "عَلَيْكَ بِتَقْوَى اللَّهِ، وَالتَّكْبِيرِ عَلَى كُلِّ شَرَفٍ". فَلَمَّا أَنْ وَلَّى الرَّجُلُ قَالَ: "اللَّهُمَّ اطْوِ لَهُ الأَرْضَ، وَهَوِّنْ عَلَيْهِ السَّفَرَ". حَسَنٌ. (ت,جه)', 'അബൂഹുറൈറ(റ): ഒരാൾ പറഞ്ഞു: തിരുദൂതരേ, ഞാൻ യാത്ര ഉദ്ദേശിക്കുന്നു. എന്നെ ഉപദേശിച്ചാലും. അവിടുന്ന് പറഞ്ഞു: "അല്ലാഹുവിനോടുള്ള ഭയഭക്തി നീ മുറുകെ പിടിക്കുക. ഉന്നതമായ എല്ലാ സ്ഥലത്ത് വെച്ചും നീ തക്ബീർ ചൊല്ലുക." ആ വ്യക്തി പിരിഞ്ഞ് പോയപ്പോൾ നബി(സ) പറഞ്ഞു: "അല്ലാഹുവേ, അവന് ഭൂമിയെ ചുരുക്കിക്കൊടുക്കേണമേ, യാത്ര എളുപ്പമാക്കുകയും ചെയ്യേണമേ." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 917, 917, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنْ عَلِيِّ بْنِ رَبِيعَةَ قَالَ: شَهِدْتُ عَلِيًّا أُتِيَ بِدَابَّةٍ لِيَرْكَبَهَا، فَلَمَّا وَضَعَ رِجْلَهُ فِي الرِّكَابِ قَالَ: بِسْمِ اللَّهِ، ثَلَاثًا، فَلَمَّا اسْتَوَى عَلَى ظَهْرِهَا قَالَ: اَلْحَمْدُ لِلَّهِ. ثُمَّ قَالَ: {سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ. وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ} [الزخرف: ١٣]. ثُمَّ قَالَ: اَلْحَمْدُ لِلَّهِ، ثَلَاثًا، وَاللَّهُ أَكْبَرُ ثَلَاثًا، سُبْحَانَكَ إِنِّي قَدْ ظَلَمْتُ نَفْسِي فَاغْفِرْ لِي، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ. ثُمَّ ضَحِكَ. قُلْتُ: مِنْ أَيِّ شَيْءٍ ضَحِكْتَ يَا أَمِيرَ الْمُؤْمِنِينَ؟ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَنَعَ كَمَا صَنَعْتُ ثُمَّ ضَحِكَ، فَقُلْتُ: مِنْ أَيِّ شَيْءٍ ضَحِكْتَ يَا رَسُولَ اللَّهِ؟ قَالَ: "إِنَّ رَبَّكَ لَيَعْجَبُ مِنْ عَبْدِهِ إِذَا قَالَ: رَبِّ اغْفِرْ لِي ذُنُوبِي، إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ غَيْرُكَ". حَسَنٌ صَحِيحٌ. (د,ت,ن)', 'അലിയ്യുബ്നു റബീഅ(റ): ഒരു യാത്രാമൃഗം അലി(റ)വിന് നൽകപ്പെട്ടത് ഞാൻ കണ്ടു. അതിന്റെ ജീനിച്ചവിട്ടിൽ അലി(റ) കാൽവെച്ചപ്പോൾ: ''അല്ലാഹുവിന്റെ നാമത്തിൽ'' എന്ന് മൂന്ന് തവണ പറഞ്ഞു; അതിന്റെ പുറത്തിരുന്നപ്പോൾ അദ്ദേഹം: ''സർവ്വ സ്തുതിയും അല്ലാഹുവിനാകുന്നു.'' എന്ന് പറഞ്ഞു. പിന്നെയദ്ദേഹം ചൊല്ലി: ''ഇത് (മൃഗം) ഞങ്ങൾക്ക് വിധേയമാക്കിത്തന്നവൻ എത്ര പരിശുദ്ധൻ. (അവനുദ്ദേശിച്ചില്ലെങ്കിൽ) ഞങ്ങൾക്ക് ഇത് ലഭിക്കുമായിരുന്നില്ല. തീർച്ചയായും ഞങ്ങൾ ഞങ്ങളുടെ രക്ഷിതാവിലേക്ക് തിരിച്ചെത്തുന്നവർ തന്നെയാകുന്നു.'' (സുഖ്റുഫ്: 13) പിന്നെ അദ്ദേഹം മൂന്ന് തവണ ''സർവ്വ സ്തുതിയും അല്ലാഹുവിനാകുന്നു'' എന്നും മൂന്ന് തവണ ''അല്ലാഹു വലിയവനാകുന്നു'' എന്നും, നിന്നെ ഞാൻ വാഴ്ത്തുന്നു, ഞാൻ എന്റെ ശരീരത്തോട് അക്രമം പ്രവർത്തിച്ചിരിക്കുന്നു. അത് കൊണ്ട് എനിക്ക് നീ പൊറുത്ത് തരിക. കാരണം തീർച്ചയായും നീയല്ലാതെ ആരും പാപത്തെ പൊറുക്കുകയില്ല എന്നും പറഞ്ഞു: പിന്നീട് അദ്ദേഹം ചിരിച്ചു. അപ്പോൾ ഞാൻ ചോദിച്ചു: മുഅ്മിനീങ്ങളുടെ നേതാവേ, നിങ്ങൾ എന്തിനാണ് ചിരിച്ചത്. അലി(റ) പറഞ്ഞു: ഞാൻ ചെയ്തതു പോലെ തിരുമേനി(സ) ചെയ്തത് ഞാൻ കണ്ടു. പിന്നെ നബി(സ) ചിരിക്കുകയും ചെയ്തു. അപ്പോൾ ഞാൻ ചോദിച്ചു. തിരുദൂതരെ, നിങ്ങളെന്തിനാണ് ചിരിക്കുന്നത്? റസൂൽ(സ) പറഞ്ഞു: "അടിമ ഇപ്രകാരം പറഞ്ഞാൽ തന്റെ രക്ഷിതാവ് സന്തോഷിക്കുക തന്നെ ചെയ്യും: എന്റെ രക്ഷിതാവെ, എനിക്ക് എന്റെ ദോഷങ്ങൾ പൊറുത്ത് തരണേ. നീയല്ലാതെ പാപം പൊറുക്കുകയില്ല." (ദ,തു,ന)', 'عَلِيِّ بْنِ رَبِيعَةَ قَالَ', 'അലിയ്യുബ്നു റബീഅ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], 'الزخرف: ١٣', null, 917, 917, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا سَافَرَ فَرَكِبَ رَاحِلَتَهُ كَبَّرَ ثَلَاثًا، وَيَقُولُ {سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ. وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ} [الزخرف: ١٣]. ثُمَّ يَقُولُ: "اللَّهُمَّ إِنِّي أَسْأَلُكَ فِي سَفَرِي هَذَا مِنَ الْبِرِّ وَالتَّقْوَى وَمِنَ الْعَمَلِ مَا تَرْضَى، اللَّهُمَّ هَوِّنْ عَلَيْنَا الْمَسِيرَ وَاطْوِ عَنَّا بُعْدَ الْأَرْضِ، اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ وَالْخَلِيفَةُ فِي الْأَهْلِ، اللَّهُمَّ اصْحَبْنَا فِي سَفَرِنَا وَاخْلُفْنَا فِي أَهْلِنَا". وَكَانَ يَقُولُ إِذَا رَجَعَ إِلَى أَهْلِهِ: "آيِبُونَ إِنْ شَاءَ اللَّهُ، تَائِبُونَ عَابِدُونَ، لِرَبِّنَا حَامِدُونَ". (م,د,ت,ن)', 'ഇബ്നു ഉമർ(റ): റസൂൽ(സ) യാത്രക്കൊരുങ്ങി വാഹനത്തിൽ കയറിയാൽ മൂന്ന്തവണ തക്ബീർ മുഴക്കും. തിരുമേനി(സ) പറയുകയും ചെയ്യും: "ഞങ്ങൾക്കിതിനെ വിധേയമാക്കിത്തന്നവൻ എത്ര പരിശുദ്ധൻ. അത് ഞങ്ങളതിന് ശേഷിയുള്ളവരായിരുന്നില്ല. തീർച്ചയായും ഞങ്ങൾ ഞങ്ങളുടെ രക്ഷിതാവിങ്കലേക്ക് തിരിച്ച് ചെല്ലുന്നവരാകുന്നു." പിന്നെ റസൂൽ(സ) പറയും: "അല്ലാഹുവേ, ഗുണവും ഭക്തിയും നീ ഇഷ്ടപ്പെടുന്ന കർമ്മവും എന്റെ ഈ യാത്രയിൽ ഞാൻ നിന്നോട് ചോദിക്കുന്നു. അല്ലാഹുവേ, യാത്ര ഞങ്ങൾക്ക് എളുപ്പമാക്കിത്തരണമേ. ഭൂമിയുടെ ദൂരങ്ങൾ ഞങ്ങൾക്ക് ചുരുക്കിത്തരേണമേ. അല്ലാഹുവേ, നീയാണ് യാത്രയിലെ കൂട്ടുകാരനും വീട്ടിലെ പ്രതിനിധിയുമാവുക. അല്ലാഹുവേ, ഞങ്ങളുടെ യാത്രയിൽ ഞങ്ങളോടൊപ്പം ഉണ്ടാവണേ. ഞങ്ങളുടെ കുടുംബത്തിൽ പ്രതിനിധിയാവണമേ." കുടുംബത്തിലേക്ക് മടങ്ങിയാൽ റസൂൽ(സ) പറയുമായിരുന്നു: "അല്ലാഹു ഉദ്ദേശിക്കുന്ന പക്ഷം ഞങ്ങൾ മടങ്ങുന്നു, ഞങ്ങൾ തൗബ ചെയ്യുകയും ആരാധന നടത്തുകയും ചെയ്യുന്നു. ഞങ്ങളുടെ രക്ഷിതാവിനെ ഞങ്ങൾ സ്തുതിക്കുന്നു." (മു,ദ,തു,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], 'الزخرف: ١٣', null, 917, 918, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ثَلَاثُ دَعَوَاتٍ مُسْتَجَابَاتٌ -وَفِي رِوَايَةٍ: لَا شَكَّ فِيهِنَّ - : دَعْوَةُ الْمَظْلُومِ، وَدَعْوَةُ الْمُسَافِرِ، وَدَعْوَةُ الْوَالِدِ عَلَى وَلَدِهِ". حَسَنٌ. (د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഉത്തരം നൽകപ്പെടുന്ന മൂന്ന് പ്രാർത്ഥനകൾ ഉണ്ട് - ഒരു നിവേദന പ്രകാരം: അതിൽ സംശയമില്ല - അക്രമിക്കപ്പെട്ടവന്റെ പ്രാർത്ഥന, യാത്രക്കാരന്റെ പ്രാർത്ഥന, മക്കൾക്കെതിരായ പിതാവിന്റെ പ്രാർത്ഥന." (ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 918, 918, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=102), 1, 'وَفِي رِوَايَةٍ: لَا شَكَّ فِيهِنَّ - : دَعْوَةُ الْمَظْلُومِ، وَدَعْوَةُ الْمُسَافِرِ، وَدَعْوَةُ الْوَالِدِ عَلَى وَلَدِهِ". حَسَنٌ. (د,ت)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنْ أَبَانَ بْنِ عُثْمَانَ قَالَ: سَمِعْتُ عُثْمَانَ بْنَ عَفَّانَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ عَبْدٍ يَقُولُ فِي صَبَاحِ كُلِّ يَوْمٍ وَمَسَاءِ كُلِّ لَيْلَةٍ: بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ، ثَلَاثَ مَرَّاتٍ، يَضُرُّهُ شَيْءٌ". وَكَانَ أَبَانُ قَدْ أَصَابَهُ طَرَفُ فَالِجٍ، فَجَعَلَ الرَّجُلُ يَنْظُرُ إِلَيْهِ، فَقَالَ لَهُ أَبَانُ: مَا تَنْظُرُ؟ أَمَا إِنَّ الْحَدِيثَ كَمَا حَدَّثْتُكَ، وَلَكِنِّي لَمْ أَقُلْهُ يَوْمَئِذٍ لِيَمْضِيَ اللَّهُ عَلَيَّ قَدَرَهُ. حَسَنٌ صَحِيحٌ. (د,ت,جه)', 'അബാനുബ്നു ഉസ്മാൻ(റ): ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ) പറയുന്നത് ഞാൻ കേട്ടു: റസൂൽ(സ) പറഞ്ഞു: "ഈ ദുആ രാവിലെയും വൈകുന്നേരവും ആര് ചൊല്ലിയാലും അവനെ യാതൊരു വസ്തുവും ബുദ്ധിമുട്ടിക്കുകയില്ല: ''അല്ലാഹുവിന്റെ നാമത്തിൽ ഞാൻ തുടങ്ങുന്നു, ആ നാമമുണ്ടെങ്കിൽ ഭൂമിയിലും ആകാശത്തിലുമുള്ള ഒരു വസ്തുവും ബുദ്ധിമുട്ടിക്കുകയില്ല. അവൻ എല്ലാം കേൾക്കുന്നവനും അറിയുന്നവനുമാണ്, എന്ന് മൂന്ന് തവണ പ്രഭാതത്തിലും പ്രദോഷത്തിലും പറയുന്ന ഒരടിമക്കും ഒരു വസ്തുവിന്റെ ബുദ്ധിമുട്ടുണ്ടാവുകയില്ല." അബാൻ(റ)വിന് ഭാഗിക പക്ഷാഘാതം പിടിപെട്ടു. അപ്പോൾ ഒരാൾ അദ്ദേഹത്തെ നോക്കിക്കൊണ്ടിരുന്നു. അപ്പോൾ അദ്ദേഹം ചോദിച്ചു: നീ എന്തിനാണ് നോക്കുന്നത്? അറിയുക! നിങ്ങളോട് പറഞ്ഞതുപോലെ തന്നെയാണ് സംഗതി. എങ്കിലും ഞാനപ്പോൾ അത് ചൊല്ലിയിട്ടില്ല, അല്ലാഹു അവന്റെ വിധി എന്നിൽ നടപ്പിലാക്കാൻ വേണ്ടി. (ദ,തു,ജ)', 'أَبَانَ بْنِ عُثْمَانَ قَالَ', 'അബാനുബ്നു ഉസ്മാൻ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 918, 919, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ ثَوْبَانَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَالَ حِينَ يُمْسِي: رَضِيتُ بِاللَّهِ رَبًّا وَبِالْإِسْلَامِ دِينًا وَبِمُحَمَّدٍ نَبِيًّا، كَانَ حَقًّا عَلَى اللَّهِ أَنْ يُرْضِيَهُ". حَسَنٌ. (ت)', 'സൗബാൻ(റ): റസൂൽ(സ) പറഞ്ഞു: "മുഹമ്മദ്(സ)യെ പ്രവാചകനായും, ഇസ്‌ലാമിനെ മതമായും അല്ലാഹുവിനെ രക്ഷിതാവായും ഞാൻ തൃപ്തിപ്പെട്ടു. എന്ന് പ്രദോഷമാകുമ്പോൾ ആരെങ്കിലും പറഞ്ഞാൽ അവനെ തൃപ്തിപ്പെടുത്തൽ അല്ലാഹുവിന്റെ മേൽ ബാധ്യതയാണ്." (തു)', 'ثَوْبَانَ', 'സൗബാൻ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 919, 919, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَمْسَى قَالَ: "أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، أَرَاهُ قَالَ فِيهَا لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. أَسْأَلُكَ خَيْرَ مَا فِي هَذِهِ اللَّيْلَةِ وَخَيْرَ مَا بَعْدَهَا، وَأَعُوذُ بِكَ مِنْ شَرِّ هَذِهِ اللَّيْلَةِ وَشَرِّ مَا بَعْدَهَا، وَأَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ، وَأَعُوذُ بِكَ مِنْ عَذَابِ النَّارِ وَعَذَابِ الْقَبْرِ". وَإِذَا أَصْبَحَ قَالَ ذَلِكَ أَيْضًا: "أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ....". قَالَ تُرْمُذِي هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ. (م،د،ت)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): വൈകുന്നേരമായാൽ റസൂൽ(സ) പറയുമായിരുന്നു: "ഞങ്ങൾ പ്രദോഷത്തിലായി, പ്രദോഷത്തിൽ അധികാരം അല്ലാഹുവിന് തന്നെ. സർവ്വ സ്തുതിയും അല്ലാഹുവിന്നാകുന്നു. അല്ലാഹുവല്ലാതെ ഇലാഹില്ല, അവൻ ഏകനാണ്, അവന് പങ്കുകാരില്ല. അവിടുന്ന് (ഇങ്ങനെയും) പറഞ്ഞതായി എനിക്ക് തോന്നുന്നു അവനാണ് അധികാരം. അവനാണ് സ്തുതി. അവൻ എല്ലാത്തിനും കഴിവുള്ളവനാകുന്നു. ഈ രാത്രിയിലുള്ളവയുടെ നന്മയും അതിനു ശേഷമുള്ളതിന്റെ നന്മയും ഞാൻ ചോദിക്കുന്നു. ഈ രാത്രിയിലുള്ളതിന്റെ തിന്മയിൽ നിന്നും അതിന്റെ ശേഷമുള്ളതിന്റെ തിന്മയിൽ നിന്നും ഞാൻ കാവൽ ചോദിക്കുന്നു. മോശമായ അഹങ്കാരത്തിൽ നിന്നും മടിയിൽ നിന്നും ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു. ഖബറിലേയും നരകത്തിലേയും ശിക്ഷയിൽ നിന്ന് ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു." പ്രഭാതത്തിലും തിരുമേനി(സ) അപ്രകാരം പറയും: "ഞങ്ങൾ പ്രഭാതത്തിലായിരിക്കുന്നു. അധികാരം അല്ലാഹുവിനായിരിക്കുന്നു, അല്ലാഹുവിനാണ് സർവ്വ സ്തുതിയും." (മു,ദ,തു)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 919, 919, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُعَلِّمُ أَصْحَابَهُ يَقُولُ: "إِذَا أَصْبَحَ أَحَدُكُمْ فَلْيَقُلِ: اللَّهُمَّ بِكَ أَصْبَحْنَا وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا وَبِكَ نَمُوتُ، وَإِلَيْكَ الْمَصِيرُ. وَإِذَا أَمْسَى فَلْيَقُلِ: اللَّهُمَّ بِكَ أَمْسَيْنَا وَبِكَ أَصْبَحْنَا، وَبِكَ نَحْيَا وَبِكَ نَمُوتُ، وَإِلَيْكَ النُّشُورُ". حَسَنٌ. (د،ت،جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(റ) തന്റെ അനുയായികളെ പഠിപ്പിക്കുന്നതിനിടയിൽ പറഞ്ഞു: "നിങ്ങൾ ആരെങ്കിലും പ്രഭാതത്തിലായാൽ അവൻ പറയട്ടെ: അല്ലാഹുവേ, നിന്നെക്കൊണ്ടാണ് ഞങ്ങൾ പ്രഭാതത്തിലായത്, നിന്നെക്കൊണ്ട് തന്നെ ഞങ്ങൾ പ്രദോഷത്തിലുമായി. നിന്നെ കൊണ്ടാണ് ഞങ്ങൾ ജീവിക്കുന്നതും മരിക്കുന്നതും. നിന്നിലേക്ക് തന്നെയാണ് മടങ്ങലും. വൈകുന്നേരമായാൽ അവൻ പറയട്ടെ. അല്ലാഹുവേ, നിന്നെ കൊണ്ടാണ് ഞങ്ങൾ പ്രദോഷത്തിലായത്, നിന്നെക്കൊണ്ട് തന്നെ ഞങ്ങൾ പ്രഭാതത്തിലുമായി. നിന്നെ കൊണ്ടാണ് ഞങ്ങൾ ജീവിക്കുന്നതും മരിക്കുന്നതും. നിന്നിലേക്കാണ് മടക്കവും." (ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 919, 919, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ: يَا رَسُولَ اللَّهِ، مُرْنِي بِشَيْءٍ أَقُولُهُ إِذَا أَصْبَحْتُ وَإِذَا أَمْسَيْتُ. قَالَ: "قُلِ: اللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ. قَالَ: قُلْهُ إِذَا أَصْبَحْتَ وَإِذَا أَمْسَيْتَ وَإِذَا أَخَذْتَ مَضْجَعَكَ". حَسَنٌ صَحِيحٌ. (د،ت)', 'അബൂഹുറൈറ(റ): അബൂബക്കർ(റ) പറഞ്ഞു: തിരുദൂതരേ, പ്രഭാതത്തിലും പ്രദോഷത്തിലും ചൊല്ലാൻ എനിക്ക് വല്ലതും തരിക. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ പറയുക. അല്ലാഹുവേ, ദൃശ്യാദൃശ്യ ലോകത്തെക്കുറിച്ച് അറിയുന്നവനെ, ആകാശഭൂമികളെ ഇല്ലായ്മയിൽ നിന്ന് പടച്ചവനെ, എല്ലാവസ്തുവിന്റെയും രക്ഷിതാവും ഉടമസ്ഥനുമായവനെ, നീയല്ലാതെ ഒരു ദൈവമില്ലെന്ന് ഞാൻ സാക്ഷ്യംവഹിക്കുന്നു. പിശാചിന്റെ ശല്യത്തിൽ നിന്നും, അവന്റെ പങ്കുചേർക്കലിൽ നിന്നും എന്റെ ശരീരത്തിന്റെ ശല്യത്തിൽ നിന്നും ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു." റസൂൽ(സ) പറഞ്ഞു: "പ്രഭാതത്തിലും പ്രദോഷത്തിലും ഉറങ്ങാൻ കിടക്കുമ്പോഴും നിങ്ങളിത് പറയുക." (ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 919, 920, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ أَبِي سَلَّامٍ رَضِيَ اللهُ عَنْهُ، خَادِمِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا مِنْ مُسْلِمٍ - أَوْ إِنْسَانٍ، أَوْ عَبْدٍ - يَقُولُ حِينَ يُمْسِي وَحِينَ يُصْبِحُ: رَضِيتُ بِاللَّهِ رَبًّا، وَبِالْإِسْلَامِ دِينًا، وَبِمُحَمَّدٍ نَبِيًّا. إِلَّا كَانَ حَقًّا عَلَى اللَّهِ أَنْ يُرْضِيَهُ يَوْمَ الْقِيَامَةِ". (جه)', 'പ്രവാചകരുടെ സേവകനായ അബൂസലാം(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിനെ രക്ഷിതാവായും ഇസ്‌ലാമിനെ ദീനായും മുഹമ്മദ്(സ)യെ പ്രവാചകനായും ഞാൻ തൃപ്തിപ്പെട്ടു, എന്ന് രാവിലെയും വൈകുന്നേരവും പറയുന്ന അടിമയോ മനുഷ്യനോ മുസ്‌ലിമോ ഇല്ല, അന്ത്യനാളിൽ അവനെ തൃപ്തിപ്പെടുത്തൽ അല്ലാഹുവിന്റെ ബാധ്യതയായിട്ടില്ലാതെ." (ജ)', 'أَبِي سَلَّامٍ', 'പ്രവാചകരുടെ സേവകനായ അബൂസലാം(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 920, 920, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: لَمْ يَكُنْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَعُ هَؤُلَاءِ الدَّعَوَاتِ، حِينَ يُمْسِي وَحِينَ يُصْبِحُ: "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ. اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ، وَأَهْلِي وَمَالِي. اللَّهُمَّ اسْتُرْ عَوْرَاتِي، وَآمِنْ رَوْعَاتِي وَاحْفَظْنِي مِنْ بَيْنِ يَدَيَّ، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي". (د,ن,جه)', 'ഇബ്നു ഉമർ(റ): പ്രഭാതമാകുമ്പോഴും പ്രദോഷമാകുമ്പോഴും ഈ പ്രാർത്ഥനകളെ റസൂൽ(സ) ഒഴിവാക്കാറില്ല: "അല്ലാഹുവേ, ഇഹത്തിലും പരത്തിലും ആരോഗ്യവും മാപ്പും ഞാൻ നിന്നോട് ചോദിക്കുന്നു. എന്റെ ദീനിലും ദുനിയാവിലും എന്റെ കുടുംബത്തിലും സമ്പത്തിലും ആരോഗ്യവും മാപ്പും ഞാൻ നിന്നോട് ചോദിക്കുന്നു. അല്ലാഹുവേ, എന്റെ മറക്കേണ്ട ഭാഗങ്ങളെ നീ മറക്കേണമേ, എന്റെ ഭയങ്ങളെ ഇല്ലാതാക്കേണമേ. എന്റെ മുകളിൽ നിന്നും വലത് ഇടത് ഭാഗങ്ങളിൽ നിന്നും മുൻഭാഗത്ത്നിന്നും, പിൻഭാഗത്തു നിന്നും എന്നെ നീ കാക്കേണമേ. എന്റെ താഴ്ഭാഗത്ത്നിന്ന് വഞ്ചിക്കപ്പെടലിൽ നിന്നും ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു." (ദ,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 920, 920, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ بُرَيْدَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اللَّهُمَّ، أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ بِنِعْمَتِكَ وَأَبُوءُ بِذَنْبِي، فَاغْفِرْ لِي، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ". قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَالَهَا فِي يَوْمِهِ وَلَيْلَتِهِ، فَمَاتَ فِي ذَلِكَ الْيَوْمِ، أَوْ تِلْكَ اللَّيْلَةِ، دَخَلَ الْجَنَّةَ إِنْ شَاءَ اللَّهُ تَعَالَى". (د,جه)', 'ബുറൈദ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവേ, നീയാണെന്റെ രക്ഷിതാവ്, നീ അല്ലാതെ ദൈവമില്ല. നീ എന്നെ സൃഷ്ടിച്ചു. ഞാൻ നിന്റെ അടിമയുമാണ്. ഞാൻ എന്റെ കഴിവനുസരിച്ച് നിന്റെ കരാറിലും, വാഗ്ദാനത്തിലുമാണ്. ഞാൻ പ്രവർത്തിച്ച കാര്യങ്ങളുടെ ശല്യത്തിൽ നിന്ന് ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു. നിന്റെ അനുഗ്രഹം കൊണ്ട് ഞാൻ മടങ്ങുന്നു. എന്റെ ദോഷം കൊണ്ട് ഞാൻ മടങ്ങുന്നു. എനിക്ക് നീ പൊറുത്ത് തരണേ. കാരണം, നീയല്ലാതെ പാപങ്ങളെ (ആരും) പൊറുക്കുകയില്ല." ബുറൈദ(റ) പറയുന്നു: റസൂൽ(സ) പറഞ്ഞു: "ഇത് രാത്രിയും പകലും ആരെങ്കിലും പറയുകയും ആ രാത്രിയോ ആ പകലോ അവൻ മരിക്കുകയും ചെയ്താൽ അല്ലാഹു ഉദ്ദേശിക്കുന്ന പക്ഷം അവൻ സ്വർഗത്തിൽ പ്രവേശിക്കും." (ദ,ജ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 920, 920, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَنْزِلُ رَبُّنَا كُلَّ لَيْلَةٍ إِلَى السَّمَاءِ الدُّنْيَا حِينَ يَبْقَى ثُلُثُ اللَّيْلِ الْآخِرُ، فَيَقُولُ: مَنْ يَدْعُونِي فَأَسْتَجِيبَ لَهُ، وَمَنْ يَسْأَلُنِي فَأُعْطِيَهُ، وَمَنْ يَسْتَغْفِرُنِي فَأَغْفِرَ لَهُ". حَسَنٌ صَحِيحٌ. (ق, د, ت, جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "രാത്രിയുടെ അവസാന മൂന്നിലൊന്നിൽ എല്ലാ രാത്രിയിലും നമ്മുടെ രക്ഷിതാവ് ദുനിയാവിന്റെ ആകാശത്തിലേക്കിറങ്ങും. അവൻ പറയുകയും ചെയ്യും: എന്നോട് പ്രാർത്ഥിച്ചവന് ഞാനുത്തരം നൽകും. എന്നോട് ചോദിച്ചവന് ഞാൻ നൽകും. എന്നോട് പൊറുക്കലിനെ തേടുന്നവന് ഞാൻ പൊറുത്തു കൊടുക്കുകയും ചെയ്യും." (ബു,മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 921, 921, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قِيلَ: يَا رَسُولَ اللَّهِ، أَيُّ الدُّعَاءِ أَسْمَعُ؟ قَالَ: "جَوْفَ اللَّيْلِ الْآخِرِ، وَدُبُرَ الصَّلَوَاتِ الْمَكْتُوبَاتِ". حَسَنٌ. (ت)', 'അബൂഉമാമ(റ): റസൂൽ(സ) ചോദിക്കപ്പെട്ടു: ഏത് പ്രാർത്ഥനയാണ് ഏറ്റവും കേൾക്കപ്പെടുക? റസൂൽ(സ) പറഞ്ഞു: "രാത്രിയുടെ അവസാനത്തിലുള്ള പ്രാർത്ഥനയും നിർബന്ധമാക്കപ്പെട്ട നിസ്കാരങ്ങൾക്ക് ശേഷമുള്ള പ്രാർത്ഥനയും." (തു)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 921, 921, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قَالَ حِينَ يُصْبِحُ: اللَّهُمَّ أَصْبَحْنَا نُشْهِدُكَ وَنُشْهِدُ حَمَلَةَ عَرْشِكَ وَمَلَائِكَتَكَ وَجَمِيعَ خَلْقِكَ، بِأَنَّكَ اللَّهُ لَا إِلَهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ، وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ. إِلَّا غَفَرَ اللَّهُ لَهُ مَا أَصَابَ فِي يَوْمِهِ ذَلِكَ، وَإِنْ قَالَهَا حِينَ يُمْسِي غَفَرَ اللَّهُ لَهُ مَا أَصَابَ فِي تِلْكَ اللَّيْلَةِ مِنْ ذَنْبٍ". (د, ت)', 'അനസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവേ, ഞങ്ങൾ പ്രഭാതത്തിലായിരിക്കുന്നു. നിന്നെയും നിന്റെ സിംഹാസനവാഹകരെയും മാലാഖമാരെയും സർവ്വ സൃഷ്ടികളെയും സാക്ഷികളാക്കി ഞങ്ങൾ പറയുന്നു: അല്ലാഹുവേ, നീ അല്ലാഹുവാണ്, നീയല്ലാതെ ഒരു ആരാധ്യനില്ല, നീ ഏകനാണ്, മുഹമ്മദ്(സ) നിന്റെ ദൂതനും അടിമയുമാണ് എന്ന് ആരെങ്കിലും പ്രഭാതത്തിൽ ചൊല്ലിയാൽ അവനിൽ നിന്ന് ആ പകലിൽ വല്ലതും സംഭവിച്ചാൽ അല്ലാഹു പൊറുത്തു കൊടുക്കും. ഇനി അതിനെ വൈകുന്നേരം പറഞ്ഞാൽ ആ രാത്രിയിൽ അവനിൽ നിന്നുണ്ടാകുന്ന ദോഷങ്ങളെ അല്ലാഹു പൊറുത്ത് കൊടുക്കും." (ദ,തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 921, 921, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنْ أَبِي رَاشِدٍ الْحُبْرَانِيِّ قَالَ: أَتَيْتُ عَبْدَ اللَّهِ بْنَ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا فَقُلْتُ لَهُ: حَدِّثْنَا مِمَّا سَمِعْتَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَأَلْقَى إِلَيَّ صَحِيفَةً فَقَالَ: هَذَا مَا كَتَبَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ: فَنَظَرْتُ فَإِذَا فِيهَا: أَنَّ أَبَا بَكْرٍ الصِّدِّيقَ رَضِيَ اللَّهُ عَنْهُ قَالَ: يَا رَسُولَ اللَّهِ، عَلِّمْنِي مَا أَقُولُ إِذَا أَصْبَحْتُ وَإِذَا أَمْسَيْتُ، فَقَالَ: "يَا أَبَا بَكْرٍ، قُلِ: اللَّهُمَّ فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ، عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، لَا إِلَهَ إِلَّا أَنْتَ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوءًا أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ". حَسَنٌ. (ت)', 'അബൂറാശിദുൽ ഹുബ്റാനി(റ): ഞാൻ അബ്ദുല്ലാഹിബ്നു അംറ്(റ)വിന്റെ അടുത്ത് ചെന്നു പറഞ്ഞു: റസൂൽ(സ)യിൽ നിന്ന് കേട്ട വല്ലതും ഞങ്ങൾക്ക് പറഞ്ഞു തരിക. അപ്പോൾ അദ്ദേഹം എനിക്കൊരു ഏട് എടുത്ത് തന്നു. എന്നിട്ട് പറഞ്ഞു: ഇത് എനിക്ക് റസൂൽ(സ) തന്നതാണ്. നിവേദകൻ പറയുന്നു: ഞാൻ അതിൽ നോക്കി. അതിലുണ്ടായിരുന്നു: നിശ്ചയം അബൂബക്കർ സിദ്ദീഖ് (റ) പറഞ്ഞു: തിരുദൂതരെ, ഞാൻ പ്രഭാതത്തിലാകുമ്പോഴും പ്രദോഷത്തിലാകുമ്പോഴും എന്താണ് പറയേണ്ടതെന്ന് എനിക്ക് പഠിപ്പിച്ച് തന്നാലും. അവിടുന്ന് പറഞ്ഞു: "ഓ അബൂബക്കറെ, നിങ്ങൾ പറയുക. അല്ലാഹുവേ, ആകാശ ഭൂമികളെ പടച്ചവനേ. ദൃശ്യവും അദൃശ്യവും അറിയുന്നവനേ. നീ മാത്രമാണ് ആരാധ്യൻ. എല്ലാ വസ്തുക്കളുടെയും രക്ഷിതാവാണ് നീ, അതിന്റെ യജമാനനും. എന്റെ ശരീരത്തിന്റെ തിന്മയിൽ നിന്നും പിശാചിന്റെ തിന്മയിൽ നിന്നും അവന്റെ ശിർക്കിൽ നിന്നും, ഞാൻ എന്റെ ശരീരത്തിനോട് വല്ല തെറ്റും ചെയ്യുന്നതിൽ നിന്നും മറ്റൊരു മുസ്‌ലിമിലേക്ക് അതിനെ എത്തിക്കുന്നതിൽ നിന്നും നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു.” (തു)', 'أَبِي رَاشِدٍ الْحُبْرَانِيِّ قَالَ', 'അബൂറാശിദുൽ ഹുബ്റാനി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 921, 922, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ فُتِحَ لَهُ مِنْكُمْ بَابُ الدُّعَاءِ فُتِحَتْ لَهُ أَبْوَابُ الرَّحْمَةِ، وَمَا سُئِلَ اللَّهُ شَيْئًا- يَعْنِي - أَحَبَّ إِلَيْهِ مِنْ أَنْ يُسْأَلَ الْعَافِيَةَ". وَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ الدُّعَاءَ يَنْفَعُ مِمَّا نَزَلَ وَمِمَّا لَمْ يَنْزِلْ، فَعَلَيْكُمْ عِبَادَ اللَّهِ بِالدُّعَاءِ". (ت)', 'ഇബ്‌നു ഉമർ(റ): റസൂൽ(സ) പറയുന്നു: "ദുആയുടെ കവാടങ്ങൾ നിങ്ങളിലാർക്കെങ്കിലും തുറക്കപ്പെട്ടാൽ അവന് കരുണയുടെ കവാടം തുറക്കപ്പെടും. ആരോഗ്യം ചോദിക്കുന്നതിനേക്കാൾ ഇഷ്ടപ്പെട്ടതായി അല്ലാഹു ഒന്നും ചോദിക്കപ്പെട്ടിട്ടില്ല." തിരദൂതർ(സ) പറയുന്നു: "ഇറങ്ങിയതിനും ഇറങ്ങാനിരിക്കുന്നതിനും പ്രാർത്ഥന ഉപകരിക്കുന്നതാണ്. അത് കൊണ്ട് തന്നെ അല്ലാഹുവിന്റെ അടിമകളേ, ദുആ നിങ്ങൾ മുറുകെപ്പിടിക്കുക" (തു)', 'ابْنِ عُمَرَ', 'ഇബ്‌നു ഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 922, 922, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنْ بِلَالٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "عَلَيْكُمْ بِقِيَامِ اللَّيْلِ، فَإِنَّهُ دَأْبُ الصَّالِحِينَ قَبْلَكُمْ، وَإِنَّ قِيَامَ اللَّيْلِ قُرْبَةٌ إِلَى اللَّهِ، وَمَنْهَاةٌ عَنِ الْإِثْمِ، وَتَكْفِيرٌ لِلسَّيِّئَاتِ، وَمَطْرَدَةٌ لِلدَّاءِ عَنِ الْجَسَدِ". (ت)', 'ബിലാൽ(റ): റസൂൽ(സ) പറയുന്നു: "രാത്രി നിസ്കാരം നിങ്ങൾ മുറുകെ പിടിക്കുക. കാരണം അത് മുൻ കഴിഞ്ഞ സദ്‌വൃത്തരുടെ പതിവാകുന്നു. തീർച്ചയായും, രാത്രിയിലുള്ള നിസ്കാരം അല്ലാഹുവിലേക്കുള്ള അടുപ്പമാകുന്നു, ദോഷങ്ങളെ പ്രതിരോധിക്കുന്നതും, പാപങ്ങളെ കരിച്ച് കളയുന്നതും, ശരീരത്തിന്റെ രോഗത്തെ തട്ടിക്കളയുന്നതുമാണ്.” (തു)', 'بِلَالٍ', 'ബിലാൽ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 922, 922, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا، وَقَدْ سُئِلَتْ: بِأَيِّ شَيْءٍ كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَفْتَتِحُ صَلَاتَهُ إِذَا قَامَ مِنَ اللَّيْلِ؟ قَالَتْ: كَانَ إِذَا قَامَ مِنَ اللَّيْلِ افْتَتَحَ صَلَاتَهُ فَقَالَ: "اللَّهُمَّ رَبَّ جِبْرِيلَ وَمِيكَائِيلَ وَإِسْرَافِيلَ، فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ، عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ. اهْدِنِي لِمَا اخْتُلِفَ فِيهِ مِنَ الْحَقِّ بِإِذْنِكَ، إِنَّكَ تَهْدِي مَنْ تَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيمٍ". حَسَنٌ. (ق,د,ت,ن,جه)', 'ആഇശ(റ): എന്തു കൊണ്ടാണ് റസൂൽ(സ) രാത്രിയിലെ നിസ്കാരം തുടങ്ങാറുള്ളത് എന്ന് മഹതിയോട് ചോദിക്കപ്പെട്ടു. അവർ പറഞ്ഞു: റസൂൽ(സ) രാത്രിയിലെ നിസ്കാരം തുടങ്ങുമ്പോൾ പറയുമായിരുന്നു: "ജിബ്‌രീലിന്റെയും മീകാഇൗലിന്റെയും ഇസ്റാഫീലിന്റെയും രക്ഷിതാവായ അല്ലാഹുവേ, ആകാശങ്ങളും ഭൂമിയും ഇല്ലായ്മയിൽ നിന്ന് ഉണ്ടാക്കിയവനേ, ദൃശ്യവും അദൃശ്യവും അറിയുന്നവനേ, നിന്റെ അടിമകൾക്കിടയിൽ അവർ ഭിന്നിക്കുന്ന വിഷയത്തിൽ നീ വിധിക്കുന്നു. സത്യത്തിൽ നിന്ന് ഭിന്നിച്ചതിൽ നിന്റെ സമ്മതത്തോടെ നീ എന്നെ സന്മാർഗത്തിലാക്കേണമേ. നിശ്ചയം നീ ഉദ്ദേശിച്ചവനെ നേരായ മാർഗത്തിലേക്ക് നീ നയിക്കുന്നു.” (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 922, 922, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ طَارِقِ بْنِ أَشِيمَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَقَدْ أَتَاهُ رَجُلٌ فَقَالَ: يَا رَسُولَ اللهِ، كَيْفَ أَقُولُ حِينَ أَسْأَلُ رَبِّي؟ قَالَ: "قُلِ: اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَعَافِنِي وَارْزُقْنِي". وَجَمَعَ أَصَابِعَهُ الْأَرْبَعَ إِلَّا الْإِبْهَامَ "فَإِنَّ هَؤُلَاءِ يَجْمَعْنَ لَكَ دِينَكَ وَدُنْيَاكَ". (م,جه)', 'ത്വാരിഖുബ്നു അശീം(റ): റസൂൽ(സ)യുടെ അടുത്തേക്ക് ഒരാൾ വന്നു ചോദിക്കുന്നത് അവർ കേട്ടു: തിരുദൂതരേ, എന്റെ രക്ഷിതാവിനോട് ചോദിക്കുമ്പോൾ ഞാൻ എങ്ങനെയാണ് പറയേണ്ടത്. റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ പറയുക: അല്ലാഹുവേ, എനിക്ക് പൊറുത്തു തരേണമേ, എന്നോട് കരുണ കാണിക്കേണമേ, എനിക്ക് ആരോഗ്യം പ്രദാനം ചെയ്യേണമേ, എനിക്ക് എല്ലാം നൽകേണമേ." നബി(സ) തന്റെ തള്ളവിരൽ അല്ലാത്തതൊക്കെ മടക്കിക്കൊണ്ട്(എണ്ണിക്കൊണ്ട്)പറഞ്ഞു: "ഇവകൾ നിനക്ക് നിന്റെ ഇഹവും പരവും ഒരുമിച്ചു കൂട്ടിത്തരും." (മു,ജ)', 'طَارِقِ بْنِ أَشِيمَ', 'ത്വാരിഖുബ്നു അശീം(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 923, 923, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَّمَهَا هَذَا الدُّعَاءَ: "اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنَ الْخَيْرِ كُلِّهِ، عَاجِلِهِ وَآجِلِهِ، مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ. وَأَعُوذُ بِكَ مِنَ الشَّرِّ كُلِّهِ، عَاجِلِهِ وَآجِلِهِ، مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ. اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ خَيْرِ مَا سَأَلَكَ عَبْدُكَ وَنَبِيُّكَ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا عَاذَ بِهِ عَبْدُكَ وَنَبِيُّكَ اللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ، وَأَعُوذُ بِكَ مِنَ النَّارِ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ. وَأَسْأَلُكَ أَنْ تَجْعَلَ كُلَّ قَضَاءٍ قَضَيْتَهُ لِي خَيْرًا". (جه)', 'ആഇശ(റ): റസൂൽ(സ) അവരെ ഈ പ്രാർത്ഥന പഠിപ്പിച്ചു: "അല്ലാഹുവേ, എനിക്കറിയുന്നതും, അറിയാത്തതുമായ ഇഹത്തിലും പരത്തിലുമുള്ള എല്ലാ നന്മയെയും നിന്നോട് ഞാൻ ചോദിക്കുന്നു. എനിക്കറിയുന്നതും അറിയാത്തതുമായ ഇഹത്തിലും പരത്തിലുമുള്ള സർവ്വ നാശങ്ങളിൽ നിന്നും നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു. അല്ലാഹുവേ, നിന്റെ പ്രവാചകനും ദാസനും ചോദിച്ച നന്മകളെ നിന്നോട് ഞാൻ ചോദിക്കുന്നു. നിന്റെ പ്രവാചകനും ദാസനും കാവൽ ചോദിച്ച നാശങ്ങളിൽ നിന്ന് ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു. അല്ലാഹുവേ, സ്വർഗ്ഗത്തെയും അതിലേക്കടുപ്പിക്കുന്ന വാക്കുകളെയും കർമ്മങ്ങളെയും നിന്നോട് ഞാൻ ചോദിക്കുന്നു. നരകത്തിൽ നിന്നും അതിനോടടുപ്പിക്കുന്ന വാക്കുകളിൽ നിന്നും കർമ്മങ്ങളിൽ നിന്നും ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു. എനിക്ക് നീ വിധിച്ച എല്ലാ വിധികളെയും നന്മയാക്കാൻ നിന്നോട് ഞാൻ അപേക്ഷിക്കുന്നു." (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 923, 923, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِرَجُلٍ: "مَا تَقُولُ فِي الصَّلَاةِ". قَالَ: أَتَشَهَّدُ، ثُمَّ أَسْأَلُ اللهَ الْجَنَّةَ، وَأَعُوذُ بِهِ مِنَ النَّارِ. أَمَا وَاللهِ مَا أُحْسِنُ دَنْدَنَتَكَ، وَلَا دَنْدَنَةَ مُعَاذٍ. قَالَ: "حَوْلَهَا نُدَنْدِنُ". (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) ഒരാളോട് ചോദിച്ചു: "നിങ്ങളെന്താണ് നിസ്കാരത്തിൽ പറയാറുള്ളത്?" അയാൾ പറഞ്ഞു: ഞാൻ തശഹ്ഹുദ് ഓതും. പിന്നെ അല്ലാഹുവിനോട് സ്വർഗ്ഗത്തെ ചോദിക്കും. നരകത്തിൽ നിന്ന് കാവൽ ചോദിക്കും. അല്ലാഹുവാണ്, അങ്ങ് (നിസ്കാരത്തിൽ) മെല്ലെപ്പറയുന്നതും മുആദ് മെല്ലെപ്പറയുന്നതും എനിക്ക് മനസ്സിലാവാറില്ല. റസൂൽ(സ) പറഞ്ഞു: "അവയെക്കുറിച്ച് (സ്വർഗ്ഗനരകങ്ങളെക്കുറിച്ച്) തന്നെയാണ് ഞങ്ങളും പറയുന്നത്." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 923, 923, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنْ بُرَيْدَةَ الْأَسْلَمِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَجُلًا يَدْعُو وَهُوَ يَقُولُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنِّي أَشْهَدُ أَنَّكَ أَنْتَ اللهُ لَا إِلَهَ إِلَّا أَنْتَ، الْأَحَدُ الصَّمَدُ، الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ. قَالَ: فَقَالَ: فَقَالَ: ”وَالَّذِي نَفْسِي بِيَدِهِ، لَقَدْ سَأَلَ اللَّهَ بِاسْمِهِ الْأَعْظَمِ، الَّذِي إِذَا دُعِيَ بِهِ أَجَابَ، وَإِذَا سُئِلَ بِهِ أَعْطَى“. حَسَنٌ. (د،ت،جه)', 'ബുറൈദതുൽ അസ്‌ലമി(റ): റസൂലുല്ലാഹി(സ) ഒരാൾ ഇങ്ങനെ ദുആ ചെയ്യുന്നതായി കേട്ടു: അല്ലാഹുവേ, നീ അല്ലാഹുവാണെന്നും നീയല്ലാത്ത ഒരു ആരാധ്യനുമില്ലെന്നും ഞാൻ സാക്ഷ്യം വഹിച്ചത് കൊണ്ട് ഞാൻ ചോദിക്കുന്നു. നീ ഏകനും സർവ്വരാലും ആശ്രയിക്കപ്പെടുന്ന നിരാശ്രയനുമാകുന്നു, ജനിക്കാത്തവനും ജനിച്ചിട്ടില്ലാത്തവനും ജനിപ്പിക്കപ്പെടാത്തവനുമാണ്. തന്നോട് ഒരു സാമ്യനുമില്ലാത്തവനാകുന്നു. നിവേദകർ പറഞ്ഞു: അപ്പോൾ നബി(സ) പറഞ്ഞു: “എന്റെ ആത്മാവ് ആരുടെ കയ്യിലാണോ അവൻ തന്നെയാണ് സത്യം. തീർച്ചയായും അയാൾ അല്ലാഹുവിന്റെ ഇസ്മുൽ അഅ്ളം (ശ്രേഷ്ഠമായ നാമം)കൊണ്ട് ചോദിച്ചിരിക്കുന്നു. ഇങ്ങനെ ഒരാൾ കൊണ്ടാരെങ്കിലും ദുആ ചെയ്താൽ അല്ലാഹു ഉത്തരം ചെയ്യും. ചോദിച്ചാൽ നൽകുകയും ചെയ്യും.” (ദ,തു,ജ)', 'بُرَيْدَةَ الْأَسْلَمِيِّ', 'ബുറൈദതുൽ അസ്‌ലമി(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 923, 924, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنْ أَسْمَاءَ بِنْتِ يَزِيدَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ”اسْمُ اللَّهِ الْأَعْظَمُ فِي هَاتَيْنِ الْآيَتَيْنِ: {وَإِلَهُكُمْ إِلَهٌ وَاحِدٌ لَا إِلَهَ إِلَّا هُوَ الرَّحْمَنُ الرَّحِيمُ} البقرة: ١٦٣]. وَفَاتِحَةِ آلِ عِمْرَانَ: {الم. اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ}“. حَسَنٌ صَحِيحٌ. (د،ت،جه)', 'അസ്മാഅ് ബിൻത് യസീദ്(റ): നബി(സ) പറയുന്നു: അല്ലാഹുവിന്റെ ഏറ്റവും ശ്രേഷ്ഠമായ നാമം (ഇസ്മുൽ അഅ്ളം) ഈ രണ്ട് ആയത്തുകളിലാകുന്നു: ''വഇലാഹുകും ഇലാഹുൻ വാഹിദുൻ ലാഇലാഹ ഇല്ലാഹുവറഹ്മാനുർറഹീം.'' (അൽബഖറ: 163) എന്ന ആയത്തും ആലു ഇംറാൻ സൂറത്തിന്റെ തുടക്കത്തിലുള്ള ''അലിഫ് ലാം മീം അല്ലാഹു ലാഇലാഹ ഇല്ലാ ഹുവൽ ഹയ്യുൽ ഖയ്യൂം'' എന്ന ആയത്തും.” (ദ,തു,ജ)', 'أَسْمَاءَ بِنْتِ يَزِيدَ', 'അസ്മാഅ് ബിൻത് യസീദ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 924, 924, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنْ شَدَّادِ بْنِ أَوْسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُعَلِّمُنَا أَنْ نَقُولَ: ”اللَّهُمَّ إِنِّي أَسْأَلُكَ الثَّبَاتَ فِي الْأَمْرِ، وَأَسْأَلُكَ عَزِيمَةَ الرُّشْدِ، وَأَسْأَلُكَ شُكْرَ نِعْمَتِكَ وَحُسْنَ عِبَادَتِكَ، وَأَسْأَلُكَ لِسَانًا صَادِقًا وَقَلْبًا سَلِيمًا. وَأَعُوذُ بِكَ مِنْ شَرِّ مَا تَعْلَمُ، وَأَسْأَلُكَ مِنْ خَيْرِ مَا تَعْلَمُ، وَأَسْتَغْفِرُكَ مِمَّا تَعْلَمُ، إِنَّكَ أَنْتَ عَلَّامُ الْغُيُوبِ“. قَالَ: وَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: ”مَا مِنْ مُسْلِمٍ يَأْخُذُ مَضْجَعَهُ، يَقْرَأُ سُورَةً مِنْ كِتَابِ اللَّهِ، إِلَّا وَكَّلَ اللَّهُ بِهِ مَلَكًا، فَلَا يَقْرَبُهُ شَيْءٌ يُؤْذِيهِ حَتَّى يَهُبَّ“. (ت)', 'ശദ്ദാദു ബിൻ ഔസ്(റ): റസൂൽ(സ) ഞങ്ങളെ പറയാൻ പഠിപ്പിക്കുമായിരുന്നു: “അല്ലാഹുവേ, നിന്നോട് ഞാൻ കാര്യങ്ങളിൽ ദൃഢത ചോദിക്കുന്നു. സൻമാർഗ്ഗത്തിൽ സ്ഥൈര്യവും നിന്നോട് ഞാൻ ചോദിക്കുന്നു. നിന്റെ അനുഗ്രഹത്തിനുള്ള നന്ദിയെയും, നല്ല നിലയിലുള്ള ആരാധനയെയും ഞാൻ ചോദിക്കുന്നു. സത്യം പറയുന്ന ഒരു നാവിനെയും രക്ഷപ്പെട്ട ഒരു ഹൃദയത്തെയും ഞാൻ നിന്നോട് ചോദിക്കുന്നു. നീ അറിയുന്നവയുടെ നാശത്തിൽ നിന്ന് നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു. നീ അറിയുന്നവയുടെ നന്മയെ നിന്നോട് ഞാൻ ചോദിക്കുന്നു. നീ അറിയുന്നവയിൽ നിന്ന് നിന്നോട് ഞാൻ പൊറുക്കലിനെ ചോദിക്കുന്നു. നിശ്ചയം നീ ഗൈബുകളെ(മറഞ്ഞ് കിടക്കുന്നവയെ) നന്നായി അറിയുന്നവനാകുന്നു.”
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَمِعْتُ نَبِيَّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ لَيْلَةً حِينَ فَرَغَ مِنْ صَلَاتِهِ: ”اللَّهُمَّ إِنِّي أَسْأَلُكَ رَحْمَةً مِنْ عِنْدِكَ تَهْدِي بِهَا قَلْبِي، وَتَجْمَعُ بِهَا أَمْرِي، وَتَلُمُّ بِهَا شَعَثِي، وَتُصْلِحُ بِهَا غَائِبِي، وَتَرْفَعُ بِهَا شَاهِدِي، وَتُزَكِّي بِهَا عَمَلِي، وَتُلْهِمُنِي بِهَا رُشْدِي، وَتَرُدُّ بِهَا أُلْفَتِي، وَتَعْصِمُنِي بِهَا مِنْ كُلِّ سُوءٍ. اللَّهُمَّ أَعْطِنِي إِيمَانًا وَيَقِينًا لَيْسَ بَعْدَهُ كُفْرٌ، وَرَحْمَةً أَنَالُ بِهَا شَرَفَ كَرَامَتِكَ فِي الدُّنْيَا وَالْآخِرَةِ اللَّهُمَّ إِنِّي أَسْأَلُكَ الْفَوْزَ فِي الْعَطَاءِ، وَنُزُلَ الشُّهَدَاءِ، وَعَيْشَ السُّعَدَاءِ، وَالنَّصْرَ عَلَى الْأَعْدَاءِ. اللَّهُمَّ إِنِّي أُنْزِلُ بِكَ حَاجَتِي، وَإِنْ قَصُرَ رَأْيِي وَضَعُفَ عَمَلِي افْتَقَرْتُ إِلَى رَحْمَتِكَ، فَأَسْأَلُكَ يَا قَاضِيَ الْأُمُورِ وَيَا شَافِيَ الصُّدُورِ، كَمَا تُجِيرُ بَيْنَ الْبُحُورِ، أَنْ تُجِيرَنِي مِنْ عَذَابِ السَّعِيرِ، وَمِنْ دَعْوَةِ الثُّبُورِ وَمِنْ فِتْنَةِ الْقُبُورِ. اللَّهُمَّ مَا قَصُرَ عَنْهُ رَأْيِي - وَلَمْ تَبْلُغْهُ نِيَّتِي وَلَمْ تَبْلُغْهُ مَسْأَلَتِي - مِنْ خَيْرٍ وَعَدْتَهُ أَحَدًا مِنْ خَلْقِكَ، أَوْ خَيْرٍ أَنْتَ مُعْطِيهِ أَحَدًا مِنْ عِبَادِكَ، فَإِنِّي أَرْغَبُ إِلَيْكَ فِيهِ، وَأَسْأَلُكَهُ بِرَحْمَتِكَ رَبَّ الْعَالَمِينَ. اللَّهُمَّ ذَا الْحَبْلِ الشَّدِيدِ وَالْأَمْرِ الرَّشِيدِ، أَسْأَلُكَ الْأَمْنَ يَوْمَ الْوَعِيدِ، وَالْجَنَّةَ يَوْمَ الْخُلُودِ، مَعَ الْمُقَرَّبِينَ الشُّهُودِ الرُّكَّعِ السُّجُودِ الْمُوفِينَ بِالْعُهُودِ، إِنَّكَ رَحِيمٌ وَدُودٌ، وَإِنَّكَ تَفْعَلُ مَا تُرِيدُ. اللَّهُمَّ اجْعَلْنَا هَادِينَ مُهْتَدِينَ، غَيْرَ ضَالِّينَ وَلَا مُضِلِّينَ، سِلْمًا لِأَوْلِيَائِكَ، وَعَدُوًّا لِأَعْدَائِكَ، نُحِبُّ بِحُبِّكَ مَنْ أَحَبَّكَ، وَنُعَادِي بِعَدَاوَتِكَ مَنْ خَالَفَكَ. اللَّهُمَّ هَذَا الدُّعَاءُ وَعَلَيْكَ الْإِجَابَةُ، وَهَذَا الْجُهْدُ وَعَلَيْكَ التُّكْلَانُ. اللَّهُمَّ اجْعَلْ لِي نُورًا فِي قَلْبِي، وَنُورًا فِي قَبْرِي، وَنُورًا مِنْ بَيْنِ يَدَيَّ، وَنُورًا مِنْ خَلْفِي، وَنُورًا عَنْ يَمِينِي، وَنُورًا عَنْ شِمَالِي، وَنُورًا مِنْ فَوْقِي، وَنُورًا مِنْ تَحْتِي، وَنُورًا فِي سَمْعِي، وَنُورًا فِي بَصَرِي، وَنُورًا فِي شَعْرِي، وَنُورًا فِي بَشَرِي، وَنُورًا فِي لَحْمِي، وَنُورًا فِي دَمِي، وَنُورًا فِي عِظَامِي. اللَّهُمَّ أَعْظِمْ لِي نُورًا، وَأَعْطِنِي نُورًا، وَاجْعَلْ لِي نُورًا. سُبْحَانَ الَّذِي تَعَطَّفَ الْعِزَّ وَقَالَ بِهِ، سُبْحَانَ الَّذِي لَبِسَ الْمَجْدَ وَتَكَرَّمَ بِهِ، سُبْحَانَ الَّذِي لَا يَنْبَغِي التَّسْبِيحُ إِلَّا لَهُ، سُبْحَانَ ذِي الْفَضْلِ وَالنِّعَمِ، سُبْحَانَ ذِي الْمَجْدِ وَالْكَرَمِ، سُبْحَانَ ذِي الْجَلَالِ وَالْإِكْرَامِ». (ت)', 'ഇബ്‌നുഅബ്ബാസ്(റ): റസൂൽ(സ) ഒരു രാത്രിയിൽ തന്റെ നിസ്കാരത്തിൽ നിന്ന് വിരമിച്ച ശേഷം ഇങ്ങനെ പറയുന്നതായി ഞാൻ കേട്ടു: "അല്ലാഹുവേ, എന്റെ ഹൃദയത്തെ വഴികാട്ടുന്ന, എന്റെ കാര്യം ഏകോപിപ്പിക്കുന്ന, എന്റെ ഭിന്നിപ്പുകളെ ഒരുമിപ്പിക്കുന്ന, എന്നിൽ നിന്ന് അസാധ്യമായതിനെ നന്നാക്കുന്ന, എന്നിൽ പ്രകടമായതിനെ ഉയർത്തുന്ന, എന്റെ കർമ്മത്തെ സംസ്കരിക്കുന്ന, എന്റെ നേർവഴിയെ എനിക്ക് ബോധനം തരുന്ന, സൽകാര്യങ്ങളോടുള്ള എന്റെ ഇണക്കത്തെ തിരിച്ച് തരുന്ന, സർവ്വ ദുഷ്ടതയിൽ നിന്നും എന്നെ രക്ഷിക്കുകയും ചെയ്യുന്ന നിന്റെയടുക്കൽ നിന്നുള്ള കാരുണ്യം തീർച്ചയായും ഞാൻ നിന്നോട് ചോദിക്കുന്നു. അല്ലാഹുവേ, ശേഷം (സത്യ)നിഷേധം വരാത്ത വിശ്വാസവും ദൃഢതയും, ഇഹത്തിലും പരത്തിലും നിന്റെ മാന്യതയുടെ ഉന്നതി എനിക്ക് ലഭിക്കാൻ കാരണമാകുന്ന കാരുണ്യവും നീ എനിക്ക് നൽകേണമേ. അല്ലാഹുവേ, (നിന്റെ) ദാനത്തിൽ ലാഭവും (സത്യവഴിയിലെ) രക്തസാക്ഷികളുടെ ആതിഥ്യ ഭക്ഷണവും (യഥാർത്ഥ) വിജയികളുടെ ജീവിതവും, (നിന്റെ ദീനിന്റെ) ശത്രുക്കൾക്കു മേൽ സഹായവും നിന്നോട് ഞാൻ ചോദിക്കുന്നു. അല്ലാഹുവേ, നിശ്ചയം ഞാൻ എന്റെ ആവശ്യം നിന്നിലേക്ക് ഇറക്കിവെക്കുന്നു. എന്റെ സാമർത്ഥ്യം എത്ര കുറവാണെങ്കിലും എന്റെ കർമ്മം എത്ര ക്ഷയിച്ചതാണെങ്കിലും ഞാൻ നിന്റെ കാരുണ്യത്തിലേക്ക് ആവശ്യക്കാരനാകുന്നു. ഹൃദയങ്ങളെ ശമിപ്പിക്കുന്നവനും കാര്യങ്ങളെ വീട്ടിക്കൊടുക്കുന്നവനുമായവനേ, സമുദ്രങ്ങൾക്കിടയിൽ നീ സംരക്ഷിക്കുന്നത് പോലെ നരക ശിക്ഷയിൽ നിന്നും അന്ത്യനാളിൽ ''എന്റെ നാശമേ'' എന്ന വിളിയിൽ നിന്നും ഖബ്‌റിലെ പരീക്ഷണങ്ങളിൽ നിന്നും എന്നെ മോചിപ്പിക്കാൻ നിന്നോട് ഞാൻ കേഴുന്നു. അല്ലാഹുവേ, നിന്റെ സൃഷ്ടികളിൽ നിന്നാർക്കെങ്കിലും നീ വാഗ്ദത്തം ചെയ്ത വല്ല നന്മയിലേക്കും എന്റെ ആഗ്രഹവും അപേക്ഷയും എത്തിയിട്ടില്ലെങ്കിൽ അതിനെക്കുറിച്ചുള്ള എന്റെ കാഴ്ചപ്പാട് ചെറുതാണെങ്കിൽ (അല്ലാഹുവേ,) നിശ്ചയം ഞാൻ ആ നന്മയെ നിന്നിൽ നിന്നും ആഗ്രഹിക്കുന്നു. ലോക രക്ഷിതാവേ, നിന്റെ അനുഗ്രഹം കൊണ്ട് ഞാനതിനെ നിന്നോട് ചോദിക്കുകയും ചെയ്യുന്നു. ദൃഢമായ പാശവും സത്യയുക്തമായ കാര്യവുമുടയവനായ അല്ലാഹുവേ, ഭയപ്പെടുത്തപ്പെട്ട ആ ദിനത്തിൽ നിർഭയത്വത്തെയും, ശാശ്വത ദിനത്തിൽ ഉടമ്പടികൾ പാലിക്കുന്ന, സാജിദീങ്ങളും റാകിഇൗങ്ങളുമായ, (സാഷ്ടാംഗം നമിക്കുന്നവരും താഴ്മയോടെ തലകുനിക്കുന്നവരുമായ) സാക്ഷികളായ, നിന്റെ സമീപസ്ഥരോട് കൂടെ, സ്വർഗ്ഗത്തെയും നിന്നോട് ഞാൻ ചോദിക്കുന്നു. നിശ്ചയം നീ കരുണാമയനും കൂടുതൽ സ്നേഹിക്കുന്നവനുമാണ്. നിശ്ചയം നീ ഉദ്ദേശിക്കുന്നത് നീ ചെയ്യുന്നു.
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا قَالَ: يَا رَسُولَ اللهِ، سَمِعْتُ دُعَاءَكَ اللَّيْلَةَ، فَكَانَ الَّذِي وَصَلَ إِلَيَّ مِنْهُ أَنَّكَ تَقُولُ: "اللَّهُمَّ اغْفِرْ لِي ذَنْبِي، وَوَسِّعْ لِي فِي رِزْقِي، وَبَارِكْ لِي فِيمَا رَزَقْتَنِي". قَالَ: "فَهَلْ تَرَاهُنَّ تَرَكْنَ شَيْئًا". (ت)', 'അബൂഹുറൈറ(റ): ഒരാൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ തിരുദൂതരേ, രാത്രിയിലുള്ള അവിടുത്തെ പ്രാർത്ഥനയിൽ ഇങ്ങനെ പറയുന്നതായി ഞാൻ കേട്ടു: "അല്ലാഹുവേ, എന്റെ പാപങ്ങളെ നീ പൊറുത്തു തരേണമേ, എന്റെ വിഭവങ്ങളിൽ എനിക്ക് വിശാലത നൽകേണമേ, നീ നൽകിയതിൽ എനിക്ക് നീ ബറകത്ത് ചെയ്യേണമേ." റസൂൽ(സ) ചോദിച്ചു: "വല്ലതും ഒഴിവാക്കിയതായി അതിൽ നീ കണ്ടോ?" (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 926, 926, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنْ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُ قَالَ: قَلَّمَا كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُومُ مِنْ مَجْلِسٍ حَتَّى يَدْعُوَ بِهَؤُلَاءِ الْكَلِمَاتِ لِأَصْحَابِهِ: "اللَّهُمَّ اقْسِمْ لَنَا مِنْ خَشْيَتِكَ مَا يَحُولُ بَيْنَنَا وَبَيْنَ مَعَاصِيكَ، وَمِنْ طَاعَتِكَ مَا تُبَلِّغُنَا بِهِ جَنَّتَكَ، وَمِنَ الْيَقِينِ مَا تُهَوِّنُ بِهِ عَلَيْنَا مُصِيبَاتِ الدُّنْيَا، وَمَتِّعْنَا بِأَسْمَاعِنَا وَأَبْصَارِنَا وَقُوَّتِنَا مَا أَحْيَيْتَنَا، وَاجْعَلْهُ الْوَارِثَ مِنَّا، وَاجْعَلْ ثَأْرَنَا عَلَى مَنْ ظَلَمَنَا، وَانْصُرْنَا عَلَى مَنْ عَادَانَا. وَلَا تَجْعَلْ مُصِيبَتَنَا فِي دِينِنَا، وَلَا تَجْعَلِ الدُّنْيَا أَكْبَرَ هَمِّنَا وَلَا مَبْلَغَ عِلْمِنَا، وَلَا تُسَلِّطْ عَلَيْنَا مَنْ لَا يَرْحَمُنَا". حَسَنٌ. (ت)', 'ഇബ്‌നു ഉമർ(റ): തന്റെ അനുചരന്മാർക്കായി ഈ വചനങ്ങളാൽ പ്രാർത്ഥിക്കുന്നത് വരെ റസൂൽ(സ) ഒരു മജ്‌ലിസിൽ നിന്ന് എഴുന്നേൽക്കൽ വളരെ വിരളമായിരുന്നു: "അല്ലാഹുവേ, ഞങ്ങളുടെയും പാപങ്ങളുടെയും ഇടയിൽ മറതീർക്കുന്ന നിന്നോടുള്ള ഭീതിയെയും നിന്റെ സ്വർഗ്ഗത്തെ പ്രാപിക്കുന്ന തരത്തിലുള്ള നിന്നോടുള്ള വഴിപ്പെടലിനെയും ദുനിയാവിന്റെ ആപത്തുകളെ നിസ്സാരമാക്കുന്ന ദൃഢതയെയും നീ ഞങ്ങൾക്ക് പ്രദാനം ചെയ്യേണമേ, നീ ഞങ്ങൾക്ക് ജീവൻ നൽകുന്ന കാലമത്രയും ഞങ്ങളുടെ കേൾവി കൊണ്ടും കാഴ്ച കൊണ്ടും ശക്തി കൊണ്ടും ഞങ്ങള്‍ക്ക് സുഖം നല്‍കണമേ, അതിനെ അവസാനം വരെ അവശേഷിപ്പിക്കുകയും ചെയ്യേണമേ, ഞങ്ങളെ അക്രമിച്ചവര്‍ക്ക് ഞങ്ങളുടെ പ്രതികാരം എത്തിക്കുകയും ചെയ്യേണമേ, ഞങ്ങളോട് ശത്രുത വെച്ചവരുടെ മേല്‍ വിജയം നല്‍കേണമേ, ഞങ്ങളുടെ ദീനില്‍ നീ വിപത്ത് വരുത്തല്ലേ, ഈ ദുന്‍യാവിനെ ഞങ്ങളുടെ പ്രധാനചിന്തയോ അറിവിന്റെ ലക്ഷ്യസ്ഥാനമോ നീ ആക്കരുതേ, ഞങ്ങളോട് കരുണ കാണിക്കാത്തവരെ ഞങ്ങളുടെ അധികാരിയാക്കരുതേ." (തു)', 'ابْنِ عُمَرَ', 'ഇബ്‌നു ഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 926, 927, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنْ مُسْلِمِ بْنِ أَبِي بَكْرَةَ قَالَ: سَمِعَنِي أَبِي وَأَنَا أَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْكَسَلِ، وَعَذَابِ الْقَبْرِ". قَالَ: يَا بُنَيَّ، مِمَّنْ سَمِعْتَ هَذَا؟ قُلْتُ: سَمِعْتُكَ تَقُولُهُنَّ. قَالَ: الْزَمْهُنَّ، فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُهُنَّ. حَسَنٌ صَحِيحٌ. (ت,ن)', 'മുസ്‌ലിം ബിന്‍ അബീബക്റ(റ): ഞാന്‍ ഇങ്ങനെ പറയുന്നതായി എന്റെ പിതാവ് കേട്ടു: "അല്ലാഹുവേ, ദുഃഖത്തില്‍ നിന്നും മടിയില്‍ നിന്നും ഖബര്‍ ശിക്ഷയില്‍ നിന്നും നിന്നോട് ഞാന്‍ കാവല്‍ ചോദിക്കുന്നു." പിതാവ് ചോദിച്ചു: എന്റെ മോനെ, ആരില്‍ നിന്നാണ് നീ ഇത് കേട്ടത്? ഞാന്‍ പറഞ്ഞു: നിങ്ങള്‍ പറയുന്നതായി ഞാന്‍ കേട്ടിട്ടുണ്ട്. പിതാവ് പറഞ്ഞു: നീ അത് പതിവാക്കുക. കാരണം റസൂല്‍(സ) അത് ചൊല്ലുന്നതായി ഞാന്‍ കേട്ടിട്ടുണ്ട്. (തു,ന)', 'مُسْلِمِ بْنِ أَبِي بَكْرَةَ قَالَ', 'മുസ്‌ലിം ബിന്‍ അബീബക്റ(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 927, 927, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَلَا أُعَلِّمُكَ كَلِمَاتٍ إِذَا قُلْتَهُنَّ غَفَرَ اللَّهُ لَكَ، وَإِنْ كُنْتَ مَغْفُورًا لَكَ". قَالَ: "قُلْ: لَا إِلَهَ إِلَّا اللَّهُ الْعَلِيُّ الْعَظِيمُ، لَا إِلَهَ إِلَّا اللَّهُ الْحَلِيمُ الْكَرِيمُ، لَا إِلَهَ إِلَّا اللَّهُ، سُبْحَانَ اللَّهِ رَبِّ الْعَرْشِ الْعَظِيمِ" وَفِي رِوَايَةٍ: قَالَ فِي آخِرِهَا: "اَلْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ". (ت)', 'അലി(റ): അല്ലാഹുവിന്റെ റസൂല്‍(സ) എന്നോട് പറഞ്ഞു: "ഞാന്‍ താങ്കള്‍ക്ക് ചില വചനങ്ങളെ പഠിപ്പിച്ച് തരട്ടെയോ, അത് പറഞ്ഞാല്‍ നിങ്ങള്‍ക്ക് അല്ലാഹു പൊറുത്ത് തരും, താങ്കള്‍ പൊറുക്കപ്പെട്ടവനാണെങ്കിലും"- (എന്നിട്ട്) നബി(സ) പറഞ്ഞു: "പറയുക: ഉന്നതനും ശ്രേഷ്ഠനുമായ അല്ലാഹുവല്ലാതെ ഒരു ആരാധ്യനുമില്ല. അത്യുദാരനും സഹനശീലനുമായ അല്ലാഹുവല്ലാതെ ഒരു ആരാധ്യനുമില്ല. ആരാധ്യന്‍ അല്ലാഹു മാത്രമാകുന്നു. ശ്രേഷ്ഠമായ സിംഹാസനത്തിന്റെ രക്ഷിതാവായ അല്ലാഹു എത്ര പരിശുദ്ധനാകുന്നു."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=128), 1, 'وَفِي رِوَايَةٍ: قَالَ فِي آخِرِهَا: "اَلْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ". (ت)', 'മറ്റൊരു നിവേദനത്തില്‍: അതിന്റെ അവസാനത്തില്‍ നബി(സ) പറഞ്ഞിട്ടുണ്ട്: "ലോകങ്ങളുടെ നാഥനായ അല്ലാഹുവിനാണ് സര്‍വ്വസ്തുതിയും." (തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "التَّسْبِيحُ نِصْفُ الْمِيزَانِ، وَالْحَمْدُ لِلَّهِ يَمْلَؤُهُ، وَلَا إِلَهَ إِلَّا اللَّهُ لَيْسَ لَهَا دُونَ اللَّهِ حِجَابٌ حَتَّى تَخْلُصَ إِلَيْهِ". (ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂല്‍(സ) പറഞ്ഞു: "തസ്ബീഹ് മീസാനി(തുലാസ്)ന്റെ പകുതിയാണെങ്കില്‍ അല്ലാഹുവിനെ സ്തുതിക്കല്‍ അതിനെ നിറക്കുന്നതുമാകുന്നു, ലാ ഇലാഹ ഇല്ലല്ലാഹു (അല്ലാഹുവല്ലാതെ ഒരാരാധ്യനുമില്ല) എന്നത് അല്ലാഹുവിലേക്ക് എത്തുന്നത് വരെ അതിനും അല്ലാഹുവിനുമിടയില്‍ യാതൊരു മറയുമില്ലാത്തതാണ്." (തു)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 927, 927, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنْ جُرَيٍّ النَّهْدِيِّ، عَنْ رَجُلٍ مِنْ بَنِي سُلَيْمٍ قَالَ: عَدَّهُنَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي يَدِي، أَوْ فِي يَدِهِ: "التَّسْبِيحُ نِصْفُ الْمِيزَانِ، وَالْحَمْدُ لِلَّهِ يَمْلَؤُهُ، وَالتَّكْبِيرُ يَمْلَأُ مَا بَيْنَ السَّمَاءِ وَالْأَرْضِ، وَالصَّوْمُ نِصْفُ الصَّبْرِ، وَالطُّهُورُ نِصْفُ الْإِيمَانِ". حَسَنٌ. (ت)', 'ജുറയ്യുന്നഹ്ദി(റ): ബനൂസുലൈമില്‍പ്പെട്ട ഒരു വ്യക്തി പറയുന്നു. റസൂല്‍(സ) എന്റെ കയ്യിലായി അല്ലെങ്കിൽ അവിടുത്തെ തിരു കയ്യിലായി ഇവയെ എണ്ണിപ്പറഞ്ഞു: "തസ്ബീഹ് മീസാനി(തുലാസ്)ന്റെ പകുതിയാകുന്നു. അല്ലാഹുവിനെ സ്തുതിക്കൽ അതിനെ നിറക്കുന്നതും തക്ബീർ ആകാശഭൂമികൾക്കിടയിലുള്ളതിനെ മുഴുവൻ നിറക്കുന്നതുമാണ്. നോമ്പ് ക്ഷമയുടെ പകുതിയാണ്. ശുദ്ധി വിശ്വാസത്തിന്റെ പകുതിയും." (തു)', 'جُرَيٍّ النَّهْدِيِّ، عَنْ رَجُلٍ مِنْ بَنِي سُلَيْمٍ قَالَ', 'ജുറയ്യുന്നഹ്ദി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 927, 928, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: شَكَتْ إِلَيَّ فَاطِمَةُ مَجْلَ يَدَيْهَا مِنَ الطَّحِينِ، فَقُلْتُ: لَوْ أَتَيْتِ أَبَاكِ فَسَأَلْتِهِ خَادِمًا؟ فَقَالَ: "أَلَا أَدُلُّكُمَا عَلَى مَا هُوَ خَيْرٌ لَكُمَا مِنَ الْخَادِمِ؟ إِذَا أَخَذْتُمَا مَضْجَعَكُمَا تَقُولَانِ ثَلَاثًا وَثَلَاثِينَ وَثَلَاثًا وَثَلَاثِينَ وَأَرْبَعًا وَثَلَاثِينَ، مِنْ تَحْمِيدٍ وَتَسْبِيحٍ وَتَكْبِيرٍ" حَسَنٌ. (ق,د,ت)', 'അലി(റ): മാവ് കുഴച്ച് കയ്യിൽ തഴമ്പ് ഉണ്ടായതിനെക്കുറിച്ച് ഫാത്വിമ(റ) എന്നോട് പരാതി പറഞ്ഞു. അപ്പോൾ ഞാൻ പറഞ്ഞു: നിന്റെ ഉപ്പയുടെ സന്നിധിയിൽചെന്ന് ഒരു പരിചാരകനെ ആവശ്യപ്പെടുക. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ആ പരിചാരകനേക്കാൾ ഉത്തമമായ കാര്യം നിങ്ങൾക്ക് ഞാൻ അറിയിക്കട്ടെയോ? നിങ്ങൾ ഉറങ്ങാൻ കിടക്കുകയാണെങ്കിൽ മുപ്പത്തിമൂന്ന് പ്രാവശ്യം തഹ്മീദും മുപ്പത്തിമൂന്ന് പ്രാവശ്യം തസ്ബീഹും മുപ്പത്തിനാല് പ്രാവശ്യം തക്ബീറും ചൊല്ലുക." (ബു,മു,ദ,തു)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 928, 928, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قَالَ: سُبْحَانَ اللَّهِ الْعَظِيمِ وَبِحَمْدِهِ، غُرِسَتْ لَهُ نَخْلَةٌ فِي الْجَنَّةِ". حَسَنٌ. (ت)', 'ജാബിർ(റ): നബി(സ) പറയുന്നു: "അത്യുന്നതനായ അല്ലാഹു എത്ര പരിശുദ്ധനാകുന്നു, അവനാണ് എല്ലാ സ്തുതികളും എന്ന് ആരെങ്കിലും പറഞ്ഞാൽ സ്വർഗത്തിൽ അവന് വേണ്ടി ഒരു ഈത്തപ്പന നടപ്പെടും." (തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 928, 928, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قَالَ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، مِائَةَ مَرَّةٍ، غُفِرَتْ لَهُ ذُنُوبُهُ - وفي رواية: حُطَّتْ عَنْهُ خَطَايَاهُ - وَإِنْ كَانَتْ أَكْثَرَ مِثْلَ زَبَدِ - وفي رواية: أَكْثَرَ مِنْ زَبَدِ الْبَحْرِ". حَسَنٌ صَحِيحٌ. (ت)', 'അബൂഹുറൈറ(റ): റസൂലുല്ലാഹി(സ) പറയുന്നു: "അത്യുന്നതനായ അല്ലാഹു എത്ര പരിശുദ്ധനാണ്, അവനാണ് എല്ലാ സ്തുതികളും എന്ന് ആരെങ്കിലും നൂറ് പ്രാവശ്യം പറഞ്ഞാൽ, അവന്റെ ദോഷങ്ങൾ പൊറുക്കപ്പെടും. മറ്റൊരു നിവേദനത്തിൽ: അവന്റെ പാപങ്ങൾ മായ്ക്കപ്പെടും, അത് നുരയെപ്പോലെയാണെങ്കിലും. മറ്റൊരു നിവേദനത്തിൽ: കടലിലെ നുരയേക്കാൾ കൂടുതലാണെങ്കിലും." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 928, 928, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=133), 1, 'وَفِي رِوَايَةٍ: حُطَّتْ عَنْهُ خَطَايَاهُ - وَإِنْ كَانَتْ أَكْثَرَ مِثْلَ زَبَدِ -', 'മറ്റൊരു നിവേദനത്തിൽ: അവന്റെ പാപങ്ങൾ മായ്ക്കപ്പെടും, അത് നുരയെപ്പോലെയാണെങ്കിലും.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=133), 2, 'وَفِي رِوَايَةٍ: أَكْثَرَ مِنْ زَبَدِ الْبَحْرِ". حَسَنٌ صَحِيحٌ. (ت)', 'മറ്റൊരു നിവേദനത്തിൽ: കടലിലെ നുരയേക്കാൾ കൂടുതലാണെങ്കിലും." (തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "كَلِمَتَانِ خَفِيفَتَانِ عَلَى اللِّسَانِ، ثَقِيلَتَانِ فِي الْمِيزَانِ، حَبِيبَتَانِ إِلَى الرَّحْمَنِ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ الْعَظِيمِ". حَسَنٌ صَحِيحٌ. (ق,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "നാവിന് വളരെ (എളുപ്പമായതും) ലഘുവായതും, തുലാസിൽ ഭാരം തൂങ്ങുന്നതും, റഹ്മാനിലേക്ക് ഇഷ്ടപ്പെട്ടതുമായ രണ്ട് വചനങ്ങളാണ്: അല്ലാഹു എത്ര പരിശുദ്ധൻ, അവനാണ് സർവ്വ സ്തുതിയും അത്യുന്നതനായ അല്ലാഹു പരിശുദ്ധൻ, എന്നിവ." (ബു,മു,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 928, 928, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قَالَ حِينَ يُصْبِحُ وَحِينَ يُمْسِي: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، مِائَةَ مَرَّةٍ، لَمْ يَأْتِ أَحَدٌ يَوْمَ الْقِيَامَةِ بِأَفْضَلَ مِمَّا جَاءَ بِهِ، إِلَّا أَحَدٌ قَالَ مِثْلَ مَا قَالَ أَوْ زَادَ عَلَيْهِ“. حَسَنٌ صَحِيحٌ. (م،د،ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: “ആരെങ്കിലും പ്രഭാതത്തിലും പ്രദോഷത്തിലും നൂറ് പ്രാവശ്യം: അല്ലാഹുവിനെ സ്തുതിക്കുന്നതോടൊപ്പം അവനെ ഞാൻ വാഴ്ത്തുന്നു എന്ന് പറഞ്ഞാൽ, അന്ത്യനാളിൽ അവൻ കൊണ്ടു വരുന്നതിനേക്കാൾ ശ്രേഷ്ഠമായത് ആരും കൊണ്ടു വരികയില്ല, അവൻ പറഞ്ഞതു പോലെയോ അതിലധികമോ പറഞ്ഞവനല്ലാതെ.” (മു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 928, 929, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ لِأَصْحَابِهِ: ”قُولُوا: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، مِائَةَ مَرَّةٍ، مَنْ قَالَهَا مَرَّةً كُتِبَتْ لَهُ عَشْرًا، وَمَنْ قَالَهَا عَشْرًا كُتِبَتْ لَهُ مِائَةٌ، وَمَنْ قَالَهَا مِائَةً كُتِبَتْ لَهُ أَلْفًا، وَمَنْ زَادَ زَادَهُ اللَّهُ، وَمَنِ اسْتَغْفَرَ اللَّهَ غَفَرَ لَهُ“. حَسَنٌ. (ت)', 'ഇബ്‌നു ഉമർ(റ): റസൂൽ(സ) ഒരിക്കൽ തന്റെ അനുയായികളോട് പറഞ്ഞു: “അല്ലാഹുവിനെ സ്തുതിക്കുന്ന തോടൊപ്പം ഞാൻ വാഴ്ത്തുന്നു, എന്ന് നിങ്ങൾ നൂറ്പ്രാവശ്യം ചൊല്ലുക. ഇത് ആരെങ്കിലും ഒരു തവണ പറഞ്ഞാൽ പത്തെണ്ണമായി എഴുതപ്പെടും. പത്തെണ്ണം ചൊല്ലിയാൽ നൂറ് എണ്ണമായി എഴുതപ്പെടും. നൂറെണ്ണം ചൊല്ലിയാൽ ആയിരമായി എഴുതപ്പെടും. അതിലും അധികമാക്കിയാൽ അല്ലാഹു അവന് കൂടുതൽ നൽകും, ആരെങ്കിലും അല്ലാഹുവിനോട് പൊറുക്കലിനെ ചോദിച്ചാൽ അവന് പൊറുത്ത് കൊടുക്കും.” (തു)', 'ابْنِ عُمَرَ', 'ഇബ്‌നു ഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 929, 929, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِجُلَسَائِهِ: ”أَيَعْجِزُ أَحَدُكُمْ أَنْ يَكْسِبَ أَلْفَ حَسَنَةٍ“. فَسَأَلَهُ سَائِلٌ مِنْ جُلَسَائِهِ: كَيْفَ يَكْسِبُ أَحَدُنَا أَلْفَ حَسَنَةٍ؟ قَالَ: ”يُسَبِّحُ أَحَدُكُمْ مِائَةَ تَسْبِيحَةٍ، تُكْتَبُ لَهُ أَلْفُ حَسَنَةٍ، وَتُحَطُّ عَنْهُ أَلْفُ سَيِّئَةٍ“. حَسَنٌ صَحِيحٌ. (م،ت)', 'സഅ്ദുബ്‌നു അബീ വഖ്ഖാസ്(റ): റസൂൽ(സ) തന്റെ സദസ്യരോട് പറഞ്ഞു: “ആയിരം നന്മകൾ കരസ്ഥമാക്കാൻ നിങ്ങൾക്ക് ബുദ്ധിമുട്ടുണ്ടോ?” അപ്പോൾ സദസ്യരിൽ നിന്നൊരാൾ ചോദിച്ചു: ഞങ്ങളെങ്ങനെയാണ് ആയിരം നന്മകൾ കരസ്ഥമാക്കുക? റസൂൽ(സ) പറഞ്ഞു: “നിങ്ങളിൽ ഒരാൾ നൂറ് തസ്ബീഹ് ചൊല്ലിയാൽ ആയിരം നന്മകൾ എഴുതപ്പെടും. ആയിരം തിന്മകൾ മായ്ക്കപ്പെടുകയും ചെയ്യും.” (മു,തു)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദുബ്‌നു അബീ വഖ്ഖാസ്(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 929, 929, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ”لَقِيتُ إِبْرَاهِيمَ لَيْلَةَ أُسْرِيَ بِي، فَقَالَ: يَا مُحَمَّدُ، أَقْرِئْ أُمَّتَكَ مِنِّي السَّلَامَ، وَأَخْبِرْهُمْ: أَنَّ الْجَنَّةَ طَيِّبَةُ التُّرْبَةِ عَذْبَةُ الْمَاءِ، وَأَنَّهَا قِيعَانٌ، وَأَنَّ غِرَاسَهَا: سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ“. حَسَنٌ. (م،ت،ن،جه)', 'ഇബ്‌നുമസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: “രാപ്രയാണ രാത്രിയിൽ (മിഅ്റാജിന്റെ രാവിൽ) ഇബ്‌റാഹീം(അ)നെ ഞാൻ കണ്ടുമുട്ടി. അപ്പോൾ ഇബ്‌റാഹീം(അ) പറഞ്ഞു: അങ്ങയുടെ ഉമ്മത്തിന് എന്റെ സലാം പറയുക, അവരെ അറിയിക്കുകയും ചെയ്യുക: സ്വർഗ്ഗം, തെളിഞ്ഞ വെള്ളവും നല്ല മണ്ണുമുള്ള ഒഴിഞ്ഞ വിശാല സ്ഥലമാണ്. അവിടെ നടാനുള്ളത്: അല്ലാഹുവിനെ വാഴ്ത്തുന്നു, സർവ്വ സ്തുതിയും അല്ലാഹുവിനാകുന്നു. അല്ലാഹുവല്ലാതെ ഇലാഹില്ല. അല്ലാഹു വലിയവനാകുന്നു, എന്നതാണ്.” (മു,തു,ന,ജ)', 'ابْنِ مَسْعُودٍ', 'ഇബ്‌നുമസ്ഊദ്(റ)', null, null, array['م','ت','ن','جه']::text[], array['മു','തു','ന','ജ']::text[], null, null, 929, 929, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا: قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ”مَنْ سَبَّحَ اللَّهَ مِائَةً بِالْغَدَاةِ وَمِائَةً بِالْعَشِيِّ كَانَ كَمَنْ حَجَّ مِائَةَ مَرَّةٍ، وَمَنْ حَمِدَ اللَّهَ مِائَةً بِالْغَدَاةِ وَمِائَةً بِالْعَشِيِّ كَانَ كَمَنْ حَمَلَ عَلَى مِائَةِ فَرَسٍ فِي سَبِيلِ اللَّهِ“. أَوْ قَالَ: غَزَا مِائَةَ غَزْوَةٍ، ”وَمَنْ هَلَّلَ اللَّهَ مِائَةً بِالْغَدَاةِ وَمِائَةً بِالْعَشِيِّ كَانَ كَمَنْ أَعْتَقَ مِائَةَ رَقَبَةٍ مِنْ وَلَدِ إِسْمَعِيلَ، وَمَنْ كَبَّرَ اللَّهَ مِائَةً بِالْغَدَاةِ وَمِائَةً بِالْعَشِيِّ لَمْ يَأْتِ فِي ذَلِكَ الْيَوْمِ أَحَدٌ بِأَكْثَرَ مِمَّا أَتَى بِهِ، إِلَّا مَنْ قَالَ مِثْلَ مَا قَالَ أَوْ زَادَ عَلَى مَا قَالَ“. حَدِيثٌ حَسَنٌ (ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "പ്രഭാതത്തിലും പ്രദോഷത്തിലും നൂറു വീതം തസ്ബീഹ് ചൊല്ലുന്നവൻ നൂറ് ഹജ്ജ് ചെയ്തവനെപ്പോലെയാണ്. പ്രഭാതത്തിലും പ്രദോഷത്തിലും നൂറു തവണ അല്ലാഹുവിനെ സ്തുതിക്കുന്നവൻ നൂറു കുതിരകളുമായി അല്ലാഹുവിന്റെ മാർഗത്തിൽ യുദ്ധം ചെയ്തവനെപ്പോലെയാണ്. അല്ലെങ്കിൽ റസൂൽ(സ): "നൂറ് യുദ്ധം ചെയ്തവനെപ്പോലെയാണ്" എന്നാണ് പറഞ്ഞത്. "പ്രഭാതത്തിലും പ്രദോഷത്തിലും നൂറു വീതം തഹ്‌ലീൽ ചൊല്ലുന്നവൻ ഇസ്മാഈൽ സന്തതികളിലെ നൂറ് അടിമകളെ മോചിപ്പിച്ചവനെപ്പോലെയാണ്. പ്രഭാതത്തിലും പ്രദോഷത്തിലും നൂറ് വീതം തക്ബീർ ചൊല്ലിയവർ, അന്നാളിൽ അവൻ കൊണ്ടുവരുന്നതിനേക്കാൾ വലിയതുമായി ആരും വരികയില്ല; അവൻ പറഞ്ഞതുപോലെ പറഞ്ഞവനും അതിലധികം പറഞ്ഞവനുമൊഴിച്ച്." (തു)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 929, 930, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنِ الزُّهْرِيِّ قَالَ: تَسْبِيحَةٌ فِي رَمَضَانَ أَفْضَلُ مِنْ أَلْفِ تَسْبِيحَةٍ فِي غَيْرِهِ. (ت)', 'സുഹ്‌രി(റ): റമളാൻ മാസത്തിലുള്ള ഒരു തസ്ബീഹ് ഇതര മാസത്തിലുള്ള ആയിരം തസ്ബീഹിനേക്കാൾ ശ്രേഷ്ഠമാണ്. (തു)', 'الزُّهْرِيِّ قَالَ', 'സുഹ്‌രി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 930, 930, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزَاةٍ، فَلَمَّا قَفَلْنَا أَشْرَفْنَا عَلَى الْمَدِينَةِ فَكَبَّرَ النَّاسُ تَكْبِيرَةً وَرَفَعُوا بِهَا أَصْوَاتَهُمْ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ رَبَّكُمْ لَيْسَ بِأَصَمَّ وَلَا غَائِبٍ، هُوَ بَيْنَكُمْ وَبَيْنَ رُءُوسِ رِحَالِكُمْ". ثُمَّ قَالَ: "يَا عَبْدَ اللَّهِ بْنَ قَيْسٍ، أَلَا أُعَلِّمُكَ كَنْزًا مِنْ كُنُوزِ الْجَنَّةِ: لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ". حَسَنٌ صَحِيحٌ. (ق,د,ت,جه)', 'അബൂമൂസൽ അശ്അരി(റ): ഞങ്ങൾ ഒരു യുദ്ധത്തിൽ തിരുദൂതർ(സ)യുടെ കൂടെയായിരുന്നു. ഞങ്ങൾ മടങ്ങി മദീനയിൽ എത്താറായപ്പോൾ ഉറക്കെ തക്ബീർ മുഴക്കി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളുടെ നാഥൻ ബധിരനോ അസാന്നിധ്യനോ അല്ല. അവൻ നിങ്ങൾക്കും നിങ്ങളുടെ ഒട്ടകങ്ങളുടെ തലകൾക്കുമിടയിലുമുണ്ട്." പിന്നീട് റസൂൽ(സ) പറഞ്ഞു: "അബ്ദുല്ലാഹിബ്നു ഖൈസേ, സ്വർഗത്തിൽ പെട്ട ഒരു നിധിയെക്കുറിച്ച് ഞാൻ നിനക്ക് പറഞ്ഞു തരട്ടെ: അല്ലാഹുവിനെക്കൊണ്ടല്ലാതെ ശക്തിയും കഴിവുമില്ല എന്നതാണത്." (ബു,മു,ദ,തു,ജ)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമൂസൽ അശ്അരി(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 930, 930, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا عَلَى الْأَرْضِ أَحَدٌ يَقُولُ: لَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، إِلَّا كُفِّرَتْ عَنْهُ خَطَايَاهُ وَلَوْ كَانَتْ مِثْلَ زَبَدِ الْبَحْرِ". حَسَنٌ. (ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവല്ലാതെ ഇലാഹില്ല, അല്ലാഹുവാണ് ഏറ്റവും വലിയവൻ, അല്ലാഹുവിനെക്കൊണ്ടല്ലാതെ ഒരു കഴിവും ശക്തിയുമില്ല. എന്ന് പറയുന്ന ഒരടിമയുമില്ല, അവന്റെ പാപങ്ങൾ പൊറുക്കപ്പെട്ടിട്ടല്ലാതെ, അത് സമുദ്രത്തിലെ നുരയോളമുണ്ടായാലും." (തു)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 930, 930, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قَالَ: لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. فِي يَوْمٍ مِائَةَ مَرَّةٍ، كَانَتْ لَهُ عَدْلَ عَشْرِ رِقَابٍ، وَكُتِبَ لَهُ مِائَةُ حَسَنَةٍ، وَمُحِيَتْ عَنْهُ مِائَةُ سَيِّئَةٍ، وَكَانَتْ لَهُ حِرْزًا مِنَ الشَّيْطَانِ يَوْمَهُ ذَلِكَ حَتَّى يُمْسِيَ، وَلَمْ يَأْتِ أَحَدٌ بِأَفْضَلَ مِمَّا جَاءَ إِلَّا رَجُلٌ عَمِلَ أَكْثَرَ مِنْهُ". (خ)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവല്ലാതെ ഇലാഹില്ല. അവൻ ഏകനും പങ്കുകാരില്ലാത്തവനുമാണ്, അവനാണ് സർവ്വ സ്തുതിയും അധികാരവും, അവൻ എല്ലാറ്റിനും കഴിവുള്ളവനാണ്, എന്ന് ദിവസം നൂറ് തവണ പറയുന്നവന് പത്ത് അടിമകളെ മോചിപ്പിച്ചതിന്റെ പ്രതിഫലമുണ്ട്. അവന് നൂറ് നന്മകൾ എഴുതപ്പെടുകയും അവനിൽ നിന്ന് നൂറ് തിന്മകൾ നീക്കപ്പെടുകയും ചെയ്യും. അന്ന് വൈകുന്നേരം വരെ പിശാചിൽ നിന്ന് അവന് സംരക്ഷണം നൽകപ്പെടുകയും ചെയ്യും. അവൻ കൊണ്ടുവരുന്നതിനേക്കാൾ ശ്രേഷ്ഠമായത് ആരും കൊണ്ടു വരികയില്ല, അവനേക്കാൾ അധികം അത് പറഞ്ഞവനൊഴികെ." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 930, 930, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنْ أَبِي أَيُّوبَ الْأَنْصَارِيِّ، وَابْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُمَا قَالَا فِي هَذَا الْحَدِيثِ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قَالَ عَشْرًا كَانَ كَمَنْ أَعْتَقَ رَقَبَةً مِنْ وَلَدِ إِسْمَاعِيلَ". (خ)', 'അബൂ അയ്യൂബിൽ അൻസാരി(റ), ഇബ്നു മസ്ഊദ്(റ) എന്നിവർ ഈ ഹദീസിൽ ഇങ്ങനെ പറയുന്നു: റസൂൽ(സ) പറഞ്ഞു: "ഇത് (മുൻകഴിഞ്ഞ ഹദീസിൽ പറഞ്ഞ ദിക്ർ) പത്ത് തവണ പറഞ്ഞവൻ ഇസ്മാഈൽ (അ) സന്തതിയായ ഒരു അടിമയെ മോചിപ്പിച്ചവനെപ്പോലെയാണ്." (ബു)', 'أَبِي أَيُّوبَ الْأَنْصَارِيِّ، وَابْنِ مَسْعُودٍ', 'അബൂ അയ്യൂബിൽ അൻസാരി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 931, 931, true from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَثَلُ الَّذِي يَذْكُرُ رَبَّهُ وَالَّذِي لَا يَذْكُرُ رَبَّهُ مَثَلُ الْحَيِّ وَالْمَيِّتِ". (خ)', 'അബൂമൂസ(റ): റസൂൽ(സ) പറഞ്ഞു: "തന്റെ രക്ഷിതാവിനെ സ്മരിക്കുന്നവന്റെയും സ്മരിക്കാത്തവന്റെയും അവസ്ഥ ജീവനുള്ളതിന്റെയും ജീവനില്ലാത്തതിന്റെയും അവസ്ഥ പോലെയാണ്." (ബു)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 931, 931, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَذْكُرُ اللهَ عَلَى كُلِّ أَحْيَانِهِ. حَسَنٌ. (م,د,ت,جه)', 'ആഇശ(റ): റസൂൽ(സ) എല്ലാ സമയങ്ങളിലും അല്ലാഹുവിനെ സ്മരിക്കാറുണ്ടായിരുന്നു. (മു,ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 931, 931, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ لِلَّهِ مَلَائِكَةً يَطُوفُونَ فِي الطُّرُقِ يَلْتَمِسُونَ أَهْلَ الذِّكْرِ، فَإِذَا وَجَدُوا قَوْمًا يَذْكُرُونَ اللَّهَ تَنَادَوْا هَلُمُّوا إِلَى حَاجَتِكُمْ". قَالَ: "فَيَحُفُّونَهُمْ بِأَجْنِحَتِهِمْ إِلَى السَّمَاءِ الدُّنْيَا". قَالَ: "فَيَسْأَلُهُمْ رَبُّهُمْ، وَهُوَ أَعْلَمُ مِنْهُمْ، مَا يَقُولُ عِبَادِي؟". قَالَ: "تَقُولُ: يُسَبِّحُونَكَ وَيُكَبِّرُونَكَ وَيَحْمَدُونَكَ وَيُمَجِّدُونَكَ". قَالَ: "فَيَقُولُ: هَلْ رَأَوْنِي؟". قَالَ: "فَيَقُولُونَ: لَا وَاللَّهِ مَا رَأَوْكَ". قَالَ: "فَيَقُولُ: وَكَيْفَ لَوْ رَأَوْنِي؟". قَالَ: "يَقُولُونَ: لَوْ رَأَوْكَ كَانُوا أَشَدَّ لَكَ عِبَادَةً، وَأَشَدَّ لَكَ تَمْجِيدًا وَأَكْثَرَ لَكَ تَسْبِيحًا". قَالَ: "يَقُولُ: فَمَا يَسْأَلُونَنِي؟". قَالَ: "يَسْأَلُونَكَ الْجَنَّةَ". قَالَ: "يَقُولُ: وَهَلْ رَأَوْهَا؟". قَالَ: "يَقُولُونَ: لَا وَاللَّهِ يَا رَبِّ مَا رَأَوْهَا". قَالَ: "يَقُولُ: فَكَيْفَ لَوْ أَنَّهُمْ رَأَوْهَا؟". قَالَ: "يَقُولُونَ: لَوْ أَنَّهُمْ رَأَوْهَا كَانُوا أَشَدَّ عَلَيْهَا حِرْصًا، وَأَشَدَّ لَهَا طَلَبًا، وَأَعْظَمَ فِيهَا رَغْبَةً". قَالَ: "فَمِمَّ يَتَعَوَّذُونَ؟". قَالَ: "يَقُولُونَ: مِنَ النَّارِ". قَالَ: "يَقُولُ: وَهَلْ رَأَوْهَا؟". قَالَ: "يَقُولُونَ: لَا وَاللَّهِ يَا رَبِّ مَا رَأَوْهَا". قَالَ: "يَقُولُ: فَكَيْفَ لَوْ رَأَوْهَا؟". قَالَ: "يَقُولُونَ: لَوْ رَأَوْهَا كَانُوا أَشَدَّ مِنْهَا فِرَارًا، وَأَشَدَّ لَهَا مَخَافَةً". قَالَ: "فَيَقُولُ: فَأُشْهِدُكُمْ أَنِّي قَدْ غَفَرْتُ لَهُمْ". قَالَ: "يَقُولُ مَلَكٌ مِنَ الْمَلَائِكَةِ: فِيهِمْ فُلَانٌ لَيْسَ مِنْهُمْ، إِنَّمَا جَاءَ لِحَاجَةٍ قَالَ: هُمُ الْجُلَسَاءُ لَا يَشْقَى بِهِمْ جَلِيسُهُمْ". (ق,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന് ഒരു കൂട്ടം മലക്കുകളുണ്ട്, അല്ലാഹുവിന് ദിക്ർ ചൊല്ലുന്നവരെ അന്വേഷിച്ച് അവർ വഴികളിൽ ചുറ്റിക്കൊണ്ടിരിക്കും. ദിക്റിന്റെ ആളുകളെ കണ്ടുമുട്ടിയാൽ നിങ്ങളുടെ ലക്ഷ്യത്തിലേക്ക് വരികയെന്ന് അവർ വിളിച്ച് പറയും." റസൂൽ(സ) തുടരുന്നു: "ഈ മലക്കുകൾ ഒന്നാം ആകാശം വരെ തങ്ങളുടെ ചിറകുകൾ കൊണ്ട് അവരെ പൊതിയും." റസൂൽ(സ) പറയുന്നു: "അപ്പോൾ അവരുടെ നാഥൻ അവരോട് ചോദിക്കും, അവൻ അവരെക്കാൾ കൂടുതൽ അറിയുന്നവനാണ്: എന്റെ ദാസന്മാർ എന്താണ് പറഞ്ഞുകൊണ്ടിരിക്കുന്നത്? മാലാഖമാർ പറയും: അവർ നിന്റെ പരിശുദ്ധതയെയും മഹത്വത്തെയും പ്രകീർത്തിക്കുകയും നിന്നെ സ്തുതിക്കുകയും ചെയ്യുന്നു. അല്ലാഹു ചോദിക്കും: അവരെന്നെ കണ്ടിട്ടുണ്ടോ? അവർ പറയും: അല്ലാഹുവാണ് സത്യം, അവർ നിന്നെ കണ്ടിട്ടില്ല. അല്ലാഹു ചോദിക്കും: അവരെന്നെ കണ്ടിരുന്നെങ്കിൽ എങ്ങനെയാണുണ്ടാവുക? അവർ പറയും: അവർ നിന്നെ കണ്ടിരുന്നെങ്കിൽ നിനക്ക് കൂടുതൽ ആരാധനകൾ ചെയ്യും, കൂടുതലായി നിന്റെ പരിശുദ്ധതയെ വാഴ്ത്തും. കൂടുതലായി നിന്നെ സ്തുതിക്കും. അപ്പോൾ അല്ലാഹു ചോദിക്കും: അവരെന്താണ് എന്നോട് ചോദിക്കുന്നത്? അവർ പറയും: സ്വർഗമാണവർ നിന്നോട് ചോദിക്കുന്നത്. അല്ലാഹു ചോദിക്കും: അവരത് കണ്ടിട്ടുണ്ടോ? മലക്കുകൾ പറയും: അല്ലാഹുവാണ് സത്യം, അവരത് കണ്ടിട്ടില്ല. അല്ലാഹു ചോദിക്കും: അവരത് കണ്ടിരുന്നെങ്കിൽ എങ്ങനെയായിരിക്കും? അവർ പറയും: അവരത് കണ്ടിരുന്നെങ്കിൽ അവർക്കതിന് കൂടുതൽ ആഗ്രഹവും ആർത്തിയുമുണ്ടാവും. അതിന് വേണ്ടി ശക്തമായി പരിശ്രമിക്കുകയും ചെയ്യും. അല്ലാഹു ചോദിക്കും: അവർ എന്തിൽ നിന്നാണ് കാവൽ ചോദിക്കുന്നത്? അവർ പറയും: നരകത്തിൽ നിന്ന്. അല്ലാഹു ചോദിക്കും: അവരത് കണ്ടിട്ടുണ്ടോ? അവർ പറയും: ഇല്ല, അല്ലാഹുവാണ് സത്യം, അവരത് കണ്ടിട്ടില്ല. അല്ലാഹു ചോദിക്കും: അവരത് കണ്ടിരുന്നെങ്കിൽ എങ്ങനെയായിരിക്കും ഉണ്ടാവുക. അവർ പറയും: അത് കണ്ടാൽ അവർക്ക് കൂടുതൽ ഭയമുണ്ടാകും. അവരതിൽ നിന്ന് ഓടി രക്ഷപ്പെടാൻ ശ്രമിക്കും. അപ്പോൾ അല്ലാഹു പറയും: ഞാനവർക്ക് പൊറുത്ത് കൊടുത്തിരിക്കുന്നു. അതിന് നിങ്ങൾ സാക്ഷിയാവുക. അന്നേരം ഒരു മലക്ക് പറയും: അവരുടെ കൂട്ടത്തിൽ ഒരാൾ കൂടിയുണ്ട്, യഥാർത്ഥത്തിൽ അവൻ അക്കൂട്ടത്തിൽ പെട്ടവനല്ല. എന്തോ ആവശ്യത്തിന് അവിടെ വന്ന് പെട്ടവനാണ്. അപ്പോൾ അല്ലാഹു പറയും: അവരെല്ലാം ഒരു സദസ്സിൽ കൂടിയിരുന്നവരാണ്. കൂട്ടത്തിൽ ചേർന്നിരിക്കുന്ന ഒരാളും പരാജയപ്പെട്ടുപോകാൻ പാടുള്ളതല്ല." (ബു,മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 931, 932, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنْ يُسَيْرَةَ بِنْتِ يَاسِرٍ رَضِيَ اللهُ عَنْهَا- وَكَانَتْ مِنَ الْمُهَاجِرَاتِ - قَالَتْ: قَالَ لَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "عَلَيْكُنَّ بِالتَّسْبِيحِ وَالتَّهْلِيلِ وَالتَّقْدِيسِ، وَاعْقِدْنَ بِالْأَنَامِلِ، فَإِنَّهُنَّ مَسْئُولَاتٌ مُسْتَنْطَقَاتٌ، وَلَا تَغْفُلْنَ فَتَنْسَيْنَ الرَّحْمَةَ". (د،ت)', 'യുസൈറ ബിൻത് യാസിർ(റ): - മഹതി മുഹാജിറുകളിൽ പെട്ടവരാണ്. - ഞങ്ങളോട് റസൂൽ(സ) പറഞ്ഞു: "തസ്ബീഹും തഹ്‌ലീലും തഖ്ദീസും (അല്ലാഹുവിനെ വാഴ്ത്തൽ) നിങ്ങൾ നിർബന്ധമാക്കുകയും കൈവിരലുകൾ കൊണ്ട് എണ്ണം പിടിക്കുകയും ചെയ്യുക, കാരണം കൈവിരലുകൾ ചോദിക്കപ്പെടുന്നവയും, സംസാരിക്കാൻ ആവശ്യപ്പെടുന്നവയുമാണ്. നിങ്ങൾ അശ്രദ്ധരാകരുത്, അശ്രദ്ധരായാൽ അല്ലാഹുവിന്റെ അനുഗ്രഹത്തെ നിങ്ങൾ മറന്നു കളയും." (ദ,തു)', 'يُسَيْرَةَ بِنْتِ يَاسِرٍ', 'യുസൈറ ബിൻത് യാസിർ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 932, 932, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَعْقِدُ التَّسْبِيحَ بِيَدِهِ. حَسَنٌ. (د،ت،ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): തിരുനബി(സ) തസ്ബീഹ് ചൊല്ലുമ്പോൾ കൈകൊണ്ട് എണ്ണം പിടിക്കുന്നത് ഞാൻ കണ്ടു. (ദ,തു,ന)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 932, 932, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: عَلَّمَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "قُولِي: اللَّهُمَّ هَذَا اسْتِقْبَالُ لَيْلِكَ، وَإِدْبَارُ نَهَارِكَ، وَأَصْوَاتُ دُعَاتِكَ، وَحُضُورُ صَلَوَاتِكَ، أَسْأَلُكَ أَنْ تَغْفِرَ لِي". (د،ت)', 'ഉമ്മുസലമ(റ): റസൂൽ(സ) എന്നെ പഠിപ്പിച്ചു: "നീ പറയുക: അല്ലാഹുവേ, ഇത് നിന്റെ രാത്രിയുടെ ആഗമനമാണ്. നിന്റെ പകലിന്റെ പിന്മാറ്റവും, ഇത് നിന്നോട് പ്രാർത്ഥിക്കുന്നവരുടെ ശബ്ദങ്ങളുയരുന്ന സമയമാണ്, നിനക്ക് വേണ്ടിയുള്ള നമസ്കാരങ്ങൾ ആസന്നമായ സമയമാണ്. അതുകൊണ്ട് എനിക്ക് പൊറുത്ത് തരാൻ ഞാൻ നിന്നോട് ചോദിക്കുന്നു." (ദ,തു)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 932, 933, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا قَالَ عَبْدٌ: لَا إِلَهَ إِلَّا اللهُ، قَطُّ مُخْلِصًا، إِلَّا فُتِحَتْ لَهُ أَبْوَابُ السَّمَاءِ، حَتَّى تُفْضِيَ إِلَى الْعَرْشِ، مَا اجْتَنَبَ الْكَبَائِرَ". حَسَنٌ. (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ലാഇലാഹ ഇല്ലല്ലാഹു (അല്ലാഹുവല്ലാതെ ഇലാഹില്ല) എന്ന് നിഷ്കളങ്കമായി പറയുന്ന ഏതൊരു അടിമയുടെയും മുമ്പിൽ ആകാശ കവാടങ്ങൾ മലർക്കെ തുറക്കപ്പെടും. അതിലൂടെ അവൻ അല്ലാഹുവിന്റെ സിംഹാസനത്തിലേക്ക് എത്തിക്കപ്പെടും. അവൻ വൻകുറ്റങ്ങൾ ചെയ്യാത്ത കാലത്തോളം." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 933, 933, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنْ قُطْبَةَ بْنِ مَالِكٍ التَّغْلَبِي رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ مُنْكَرَاتِ الْأَخْلَاقِ وَالْأَعْمَالِ وَالْأَهْوَاءِ". حَسَنٌ. (ت)', 'ഖുത്ബത്തുബ്നു മാലികുത്തഗ്‌ലബി(റ): റസൂൽ(സ) പ്രാർത്ഥിക്കാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ, വെറുക്കപ്പെടുന്ന ഇച്ഛകളിൽ നിന്നും കർമ്മങ്ങളിൽ നിന്നും സ്വഭാവങ്ങളിൽ നിന്നും തിന്മകളിൽ നിന്നും നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു." (തു)', 'قُطْبَةَ بْنِ مَالِكٍ التَّغْلَبِي', 'ഖുത്ബത്തുബ്നു മാലികുത്തഗ്‌ലബി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 933, 933, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: بَيْنَمَا نَحْنُ نُصَلِّي مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ قَالَ رَجُلٌ مِنَ الْقَوْمِ: "اللَّهُ أَكْبَرُ كَبِيرًا، وَالْحَمْدُ لِلَّهِ كَثِيرًا، وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلًا". فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنِ الْقَائِلُ كَذَا وَكَذَا؟". فَقَالَ رَجُلٌ مِنَ الْقَوْمِ: أَنَا يَا رَسُولَ اللَّهِ. قَالَ: "عَجِبْتُ لَهَا، فُتِحَتْ لَهَا أَبْوَابُ السَّمَاءِ". قَالَ ابْنُ عُمَرَ: مَا تَرَكْتُهُنَّ مُنْذُ سَمِعْتُهُنَّ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. حَسَنٌ صَحِيحٌ. (م,ت,ن)', 'ഇബ്നു ഉമർ(റ): ഞങ്ങൾ തിരുദൂതരുടെ(സ) കൂടെ നിസ്കരിച്ചുകൊണ്ടിരിക്കുമ്പോൾ കൂട്ടത്തിൽ ഒരാൾ പറഞ്ഞു: അല്ലാഹുവാണ് ഏറ്റവും വലിയവൻ, സർവ്വത്ര സ്തോത്രങ്ങളും അല്ലാഹുവിനാണ്. പ്രഭാതത്തിലും പ്രദോഷത്തിലും ഞാൻ അല്ലാഹുവിനെ വാഴ്ത്തുന്നു. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "ആരാണ് ഇപ്രകാരം പറഞ്ഞത്?." അപ്പോൾ കൂട്ടത്തിൽ നിന്നൊരാൾ പറഞ്ഞു: ഞാനാണ്, അല്ലാഹുവിന്റെ റസൂലേ. റസൂൽ(സ) പറഞ്ഞു: "അത് കേട്ടു ഞാൻ അത്ഭുതപ്പെട്ടു. അതിനു വേണ്ടി ആകാശത്തിന്റെ കവാടങ്ങൾ തുറക്കപ്പെട്ടിരുന്നു." ഇബ്നു ഉമർ(റ) പറയുന്നു: റസൂൽ(സ)യിൽ നിന്ന് ഇത് കേട്ട ശേഷം ഞാനതിനെ ഒഴിവാക്കിയിട്ടില്ല. (മു,തു,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['م','ت','ن']::text[], array['മു','തു','ന']::text[], null, null, 933, 933, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّ بِشَجَرَةٍ يَابِسَةِ الْوَرَقِ، فَضَرَبَهَا بِعَصَاهُ، فَتَنَاثَرَ الْوَرَقُ، فَقَالَ: "إِنَّ الْحَمْدَ لِلَّهِ وَسُبْحَانَ اللَّهِ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ لَتَسَاقِطُ مِنْ ذُنُوبِ الْعَبْدِ كَمَا تَسَاقَطَ وَرَقُ هَذِهِ الشَّجَرَةِ هَذِهِ". (ت)', 'അനസുബ്നു മാലിക്(റ): ഇല ഉണങ്ങിയ ഒരു മരത്തിന്റെ അടുത്ത്കൂടെ റസൂൽ(സ) നടന്നുപോയി. റസൂൽ(സ) തന്റെ വടികൊണ്ട് അതിനെ അടിച്ചു. അപ്പോൾ അതിന്റെ ഇലകൾ പൊഴിഞ്ഞു വീണു. അന്നേരം റസൂൽ(സ) പറഞ്ഞു: "സർവ്വ സ്തുതിയും അല്ലാഹുവിനാകുന്നു. ഞാൻ അല്ലാഹുവിനെ വാഴ്ത്തുന്നു. അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ല. അല്ലാഹു ഏറ്റവും വലിയവനാകുന്നു. എന്നത്, ഈ മരത്തിൽ നിന്ന് ഇലകൾ കൊഴിഞ്ഞത് പോലെ അടിമയുടെ ദോഷങ്ങൾ കൊഴിച്ച് കളയും." (തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 933, 933, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 155, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "سَبَقَ الْمُفَرِّدُونَ". قَالُوا: يَا رَسُولَ اللَّهِ، وَمَا الْمُفَرِّدُونَ؟ قَالَ: "الْمُسْتَهْتَرُونَ فِي ذِكْرِ اللَّهِ، يَضَعُ الذِّكْرُ عَنْهُمْ أَثْقَالَهُمْ، فَيَأْتُونَ يَوْمَ الْقِيَامَةِ خِفَافًا". حَسَنٌ. (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "മുഫർരിദീങ്ങൾ മുൻകടന്നിരിക്കുന്നു." അവർ ചോദിച്ചു. തിരുദൂതരെ, ആരാണ് മുഫർരിദീങ്ങൾ? അവിടുന്ന് പറഞ്ഞു: "അല്ലാഹുവിന്റെ സ്മരണയിൽ മുഴുകിയവരാണവർ. അവരുടെ ഭാരങ്ങളെ ആ സ്മരണ വിദൂരത്താക്കും. അന്ത്യനാളിൽ (പാപ) ഭാരമില്ലാത്തവരായിട്ടായിരിക്കും അവർ വരിക." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 934, 934, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 156, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَأَنْ أَقُولَ: سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ. أَحَبُّ إِلَيَّ مِمَّا طَلَعَتْ عَلَيْهِ الشَّمْسُ". حَسَنٌ صَحِيحٌ. (ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ പരിശുദ്ധിയെ ഞാൻ വാഴ്ത്തുന്നു. സർവ്വസ്തുതിയും അല്ലാഹുവിനാകുന്നു, അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ല. ആല്ലാഹു വലിയവനാകുന്നു. എന്ന ദിക്റ് ഞാൻ ചൊല്ലൽ സൂര്യനുദിക്കപ്പെട്ട എല്ലാ വസ്തുക്കളെക്കാളും (ദുനിയാവിലെ സർവ വസ്തുക്കളെക്കാളും) എനിക്ക് പ്രിയപ്പെട്ടതാണ്." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 934, 934, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 157, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ثَلَاثَةٌ لَا تُرَدُّ دَعْوَتُهُمْ: الصَّائِمُ حَتَّى يُفْطِرَ، وَالْإِمَامُ الْعَادِلُ، وَدَعْوَةُ الْمَظْلُومِ، يَرْفَعُهَا اللَّهُ فَوْقَ الْغَمَامِ وَيَفْتَحُ لَهَا أَبْوَابَ السَّمَاءِ، وَيَقُولُ الرَّبُّ وَعِزَّتِي لَأَنْصُرَنَّكِ وَلَوْ بَعْدَ حِينٍ". حَسَنٌ. (ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "മൂന്ന് കൂട്ടരുണ്ട്, അവരുടെ പ്രാർത്ഥന തട്ടപ്പെടുകയില്ല: നോമ്പുകാരൻ അവന്റെ നോമ്പ് തുറക്കുന്നത് വരെ, നീതിമാനായ ഭരണാധികാരി, അക്രമിക്കപ്പെട്ടവന്റെ പ്രാർത്ഥന, ആ പ്രാർത്ഥനകളെ അല്ലാഹു മേഘത്തിനു മുകളിൽ ഉയർത്തുകയും അതിന് വേണ്ടി ആകാശത്തിലെ കവാടങ്ങൾ തുറന്നു കൊടുക്കുകയും ചെയ്യും. നാഥൻ പറയും, എന്റെ അന്തസ് തന്നെ സത്യം! എത്ര കാലത്തിന് ശേഷമായാലും ഞാൻ നിന്നെ സഹായിക്കുക തന്നെ ചെയ്യും." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 934, 934, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 158, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اللَّهُمَّ انْفَعْنِي بِمَا عَلَّمْتَنِي، وَعَلِّمْنِي مَا يَنْفَعُنِي، وَزِدْنِي عِلْمًا، الْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ، وَأَعُوذُ بِاللَّهِ مِنْ حَالِ أَهْلِ النَّارِ". (ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവേ, നീ എനിക്ക് പഠിപ്പിച്ച വിജ്ഞാനം ഉപകാരപ്രദമാക്കണേ, എനിക്ക് ഉപകാരമുള്ളത് നീ പഠിപ്പിച്ച് തരികയും ചെയ്യേണമേ, എനിക്ക് അറിവ് വർദ്ധിപ്പിച്ച് തരേണമേ, എല്ലാ അവസ്ഥയിലും സർവ്വ സ്തുതിയും അല്ലാഹുവിനാകുന്നു, നരകക്കാരുടെ അവസ്ഥയിൽ നിന്ന് ഞാൻ അല്ലാഹുവിനോട് കാവൽ ചോദിക്കുന്നു." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 934, 934, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 159, 'عَنْ صَفْوَانَ بْنِ سُلَيْمٍ قَالَ: مَا نَهَضَ مَلَكٌ مِنَ الْأَرْضِ حَتَّى قَالَ: لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ. (ت)', 'സ്വഫ്‌വാനുബ്നു സുലൈം(റ): അല്ലാഹുവിനെക്കൊണ്ടല്ലാതെ ഒരു ശക്തിയും കഴിവുമില്ല എന്ന് പറയാതെ ഒരു മലകും ഭൂമിയിൽ നിന്ന് ഉയരുകയില്ല. (തു)', 'صَفْوَانَ بْنِ سُلَيْمٍ قَالَ', 'സ്വഫ്‌വാനുബ്നു സുലൈം(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 934, 934, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 160, 'عَنِ الْبَرَاءِ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أَخَذْتَ مَضْجَعَكَ فَتَوَضَّأْ وُضُوءَكَ لِلصَّلَاةِ، ثُمَّ اضْطَجِعْ عَلَى شِقِّكَ الْأَيْمَنِ، ثُمَّ قُلِ: اللَّهُمَّ أَسْلَمْتُ وَجْهِيَ إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لَا مَلْجَأَ وَلَا مَنْجَا مِنْكَ إِلَّا إِلَيْكَ، آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَنَبِيِّكَ الَّذِي أَرْسَلْتَ. فَإِنْ مُتَّ فِي لَيْلَتِكَ مُتَّ عَلَى الْفِطْرَةِ". قَالَ: فَرَدَّدْتُهُنَّ لِأَسْتَذْكِرَهُ فَقُلْتُ: آمَنْتُ بِرَسُولِكَ الَّذِي أَرْسَلْتَ. فَقَالَ: "قُلْ آمَنْتُ بِنَبِيِّكَ الَّذِي أَرْسَلْتَ". حَسَنٌ صَحِيحٌ. (ق,د,ت)', 'ബറാഅ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നീ ഉറങ്ങുന്ന സ്ഥലത്ത് ചെന്നാൽ നിസ്കരിക്കാൻ വേണ്ടിയെന്നപോലെ അംഗശുദ്ധി വരുത്തുക, എന്നിട്ട് വലതു ഭാഗത്തേക്ക് ചെരിഞ്ഞു കിടക്കുക, എന്നിട്ട് നീ പറയുക. അല്ലാഹുവേ, നിനക്ക് ഞാൻ എന്റെ മുഖത്തെ കീഴ്പ്പെടുത്തിയിരിക്കുന്നു, എന്റെ കാര്യങ്ങളെല്ലാം നിന്നിലേൽപ്പിച്ചിരിക്കുന്നു. എന്റെ മുതുക് നിന്നിലേക്ക് അഭയം പ്രാപിക്കുന്നു, ഭക്തിയോടും ആശയോടും കൂടി. നീയല്ലാതെ മറ്റൊരു അഭയകേന്ദ്രമോ രക്ഷാസങ്കേതമോ ഇല്ല. അല്ലാഹുവേ നീ ഇറക്കിയ ഗ്രന്ഥത്തിലും നീ അയച്ച നബിയിലും ഞാനിതാ വിശ്വസിച്ചിരിക്കുന്നു. (ബറാഅ്(റ)വിനോട് റസൂൽ(സ) പറയുന്നു) ആ രാത്രിയിലാണ് നീ മരണപ്പെടുന്നതെങ്കിൽ പരിശുദ്ധ പ്രകൃതിയിലാണ് നീ മരണപ്പെടുന്നത്." ബറാഅ്(റ) പറയുന്നു: ഞാൻ ഈ പ്രാർത്ഥനകൾ തിരുദൂതർ(സ)യുടെ മുമ്പിൽ വെച്ചു ആവർത്തിച്ചു. അങ്ങനെ ഞാൻ പറഞ്ഞു: നീ അയച്ച റസൂലിൽ ഞാൻ വിശ്വസിക്കുന്നു (നീ അയച്ച നബി എന്നതിന് പകരം). അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നീ പറയുക, നീ അയച്ച നബിയിൽ ഞാൻ വിശ്വസിക്കുന്നു." (ബു,മു,ദ,തു)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 935, 935, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 161, 'عَنْ عَبْدِ اللَّهِ بْنِ خُبَيْبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَرَجْنَا فِي لَيْلَةٍ مَطِيرَةٍ وَظُلْمَةٍ شَدِيدَةٍ، نَطْلُبُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي لَنَا، قَالَ: فَأَدْرَكْتُهُ، فَقَالَ: "قُلْ". فَلَمْ أَقُلْ شَيْئًا. ثُمَّ قَالَ: "قُلْ". فَلَمْ أَقُلْ شَيْئًا. قَالَ: "قُلْ". فَقُلْتُ: مَا أَقُولُ؟ قَالَ: "قُلْ: {قُلْ هُوَ اللَّهُ أَحَدٌ} وَالْمُعَوِّذَتَيْنِ حِينَ تُمْسِي وَتُصْبِحُ، ثَلَاثَ مَرَّاتٍ، تَكْفِيكَ مِنْ كُلِّ شَيْءٍ". حَسَنٌ صَحِيحٌ. (د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു ഖുബൈബ്(റ): റസൂൽ(സ)യെ, ഞങ്ങൾക്ക് നിസ്കരിക്കാൻ വേണ്ടി അന്വേഷിച്ച് ശക്തമായ ഇരുട്ടും കോരിച്ചൊരിയുന്ന മഴയും ഉള്ള ഒരു രാത്രിയിൽ ഞങ്ങൾ പുറപ്പെട്ടു. അങ്ങനെ റസൂൽ(സ)യുടെ അടുത്ത് ഞാൻ പോയി. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നീ പറയുക". ഞാനൊന്നും പറഞ്ഞില്ല. നബി(സ) പിന്നെയും പറഞ്ഞു: "നീ പറയുക". ഞാനൊന്നും പറഞ്ഞില്ല, അവിടന്ന് വീണ്ടും പറഞ്ഞു: "നീ പറയുക." അപ്പോൾ ഞാൻ ചോദിച്ചു: ഞാനെന്താണ് പറയേണ്ടത്? റസൂൽ(സ) പറഞ്ഞു: "രാവിലെയും വൈകുന്നേരവും മൂന്ന് തവണ നീ സൂറതുൽ ഇഖ്‌ലാസും മുഅവ്വിദതൈനിയും (സൂറതുൽ ഫലഖ്, നാസ്) ഓതുക. എന്നാൽ എല്ലാ വസ്തുക്കളിൽ നിന്നും നിനക്കത് മതിയാവും." (ദ,തു,ന)', 'عَبْدِ اللَّهِ بْنِ خُبَيْبٍ', 'അബ്ദുല്ലാഹിബ്നു ഖുബൈബ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 935, 935, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 162, 'عَنْ عَبْدِ اللَّهِ بْنِ بُسْرٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا قَالَ: يَا رَسُولَ اللَّهِ، إِنَّ شَرَائِعَ الْإِسْلَامِ قَدْ كَثُرَتْ عَلَيَّ، فَأَخْبِرْنِي بِشَيْءٍ أَتَشَبَّثُ بِهِ؟ قَالَ: "لَا يَزَالُ لِسَانُكَ رَطْبًا مِنْ ذِكْرِ اللَّهِ". حَسَنٌ. (ت,جه)', 'അബ്ദുല്ലാഹിബ്നു ബുർസ്(റ): ഒരാൾ വന്നു പറഞ്ഞു: തിരുദൂതരെ, ഇസ്‌ലാമിന്റെ വിധി വിലക്കുകൾ എനിക്കധികമായി തോന്നുന്നു. അതു കൊണ്ട് എനിക്ക് എപ്പോഴും ചെയ്യാൻ പറ്റിയത് പറഞ്ഞു തരിക. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ നാവ് എപ്പോഴും അല്ലാഹുവിന്റെ ദിക്‌റ് കൊണ്ട് നനവുള്ളതായിരിക്കട്ടെ." (തു,ജ)', 'عَبْدِ اللَّهِ بْنِ بُسْرٍ', 'അബ്ദുല്ലാഹിബ്നു ബുർസ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 935, 936, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 163, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُئِلَ: أَيُّ الْعِبَادِ أَفْضَلُ دَرَجَةً عِنْدَ اللَّهِ يَوْمَ الْقِيَامَةِ؟ قَالَ: "الذَّاكِرُونَ اللَّهَ كَثِيرًا وَالذَّاكِرَاتُ". قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، وَمِنَ الْغَازِي فِي سَبِيلِ اللَّهِ؟ قَالَ: "لَوْ ضَرَبَ بِسَيْفِهِ فِي الْكُفَّارِ وَالْمُشْرِكِينَ حَتَّى يَنْكَسِرَ وَيَخْتَضِبَ دَمًا لَكَانَ الذَّاكِرُونَ اللَّهَ أَفْضَلَ مِنْهُ دَرَجَةً". (ت)', 'അബൂസഇൗദിൽ ഖുദ്‌രി(റ): റസൂൽ(സ) ചോദിക്കപ്പെട്ടു: അന്ത്യനാളിൽ അല്ലാഹുവിന്റെ അടുക്കൽ ഏറ്റവും ശ്രേഷ്ഠമായ ഉയർന്ന പദവിയുള്ള ദാസന്മാർ ആരാണ്? റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന് അധികമായി ദിക്‌റ് ചെയ്യുന്ന ആണുങ്ങളും പെണ്ണുങ്ങളും." നിവേദകൻ പറയുന്നു: ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അല്ലാഹുവിന്റെ മാർഗത്തിൽ യുദ്ധം ചെയ്യുന്നവരേക്കാൾ ശ്രേഷ്ഠരാണോ ഇവർ? റസൂൽ(സ) പറഞ്ഞു: "അവൻ തന്റെ വാള് പൊട്ടുവോളവും താൻ രക്തത്തിൽ കുളിക്കുവോളവും തന്റെ വാള് കൊണ്ട് നിഷേധികളെയും ബഹുദൈവാരാധകരെയും വെട്ടിയാലും, അല്ലാഹുവിന് അധികമായി ദിക്‌റ് ചൊല്ലുന്നവരാണ് അവനേക്കാൾ ശ്രേഷ്ഠൻ." (തു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഇൗദിൽ ഖുദ്‌രി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 936, 936, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 164, 'عَنْ تَمِيمٍ الدَّارِيِّ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قَالَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، إِلَهًا وَاحِدًا أَحَدًا صَمَدًا، لَمْ يَتَّخِذْ صَاحِبَةً وَلَا وَلَدًا، وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ. عَشْرَ مَرَّاتٍ كَتَبَ اللَّهُ لَهُ أَرْبَعِينَ أَلْفَ أَلْفِ حَسَنَةٍ". (ت)', 'തമീമുദ്ദാരി(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്ന് ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു, അവൻ ഏകനും പങ്കുകാരില്ലാത്തവനുമാകുന്നു, അവൻ ഏകനായ ആരാധ്യനാകുന്നു, ഏകനും ആരെയും ആശ്രയിക്കാത്തവനുമാകുന്നു, ഒരു സന്താനമോ കൂട്ടുകാരനോ ഇല്ലാത്തവനാകുന്നു, അവന് തുല്യമായവൻ ആരുമില്ല." എന്ന് പത്ത് തവണ ആരെങ്കിലും പറഞ്ഞാൽ അല്ലാഹു അവന് നാല് കോടി നന്മകൾ എഴുതി വെക്കും. (തു)', 'تَمِيمٍ الدَّارِيِّ', 'തമീമുദ്ദാരി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 936, 936, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 165, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قَالَ فِي دُبُرِ صَلَاةِ الْفَجْرِ، وَهُوَ ثَانٍ رِجْلَيْهِ قَبْلَ أَنْ يَتَكَلَّمَ: لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، يُحْيِي وَيُمِيتُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. عَشْرَ مَرَّاتٍ، كُتِبَتْ لَهُ عَشْرُ حَسَنَاتٍ، وَمُحِيَتْ عَنْهُ عَشْرُ سَيِّئَاتٍ، وَرُفِعَ لَهُ عَشْرُ دَرَجَاتٍ، وَكَانَ يَوْمَهُ ذَلِكَ كُلَّهُ فِي حِرْزٍ مِنْ كُلِّ مَكْرُوهٍ، وَحُرِسَ مِنَ الشَّيْطَانِ، وَلَمْ يَنْبَغِ لِذَنْبٍ أَنْ يُدْرِكَهُ فِي ذَلِكَ الْيَوْمِ إِلَّا الشِّرْكَ بِاللَّهِ". حَسَنٌ صَحِيحٌ. (ت)', 'അബൂദർറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവല്ലാതെ ഒരു ആരാധ്യനില്ല, അവൻ ഏകനും പങ്കുകാരില്ലാത്തവനുമാണ്, അവനാണ് സർവ്വ സ്തുതിയും, സർവ്വ അധികാരവും. അവൻ ജീവിപ്പിക്കുകയും മരിപ്പിക്കുകയും ചെയ്യുന്നു. അവൻ എല്ലാറ്റിനും കഴിവുള്ളവാകുന്നു എന്ന് സുബ്‌ഹി നിസ്കാരത്തിന്റെ ഉടനെ മറ്റൊരു സംസാരം സംസാരിക്കുന്നതിന് മുമ്പ് കാൽ മടക്കി വെച്ചവനായ നിലയിൽ വല്ലവനും പത്ത് തവണ പറഞ്ഞാൽ അവന് പത്ത് നന്മകൾ എഴുതപ്പെടും. പത്ത് പാപങ്ങൾ മായ്ക്കപ്പെടും. പത്ത് സ്ഥാനങ്ങൾ ഉയർത്തപ്പെടും. ആ ദിവസം മുഴുവൻ വെറുക്കപ്പെട്ട കാര്യങ്ങളിൽ നിന്നും അവൻ സംരക്ഷിതനായിരിക്കും, പിശാചിൽ നിന്ന് കാവലിലുമായിരിക്കും, അല്ലാഹുവിന് പങ്കുചേർക്കലല്ലാത്ത മറ്റൊരു പാപവും ആ ദിവസം അവന് വന്നുചേരുകയില്ല." (തു)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 936, 937, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 166, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَنْزِلُ رَبُّنَا تَبَارَكَ وَتَعَالَى كُلَّ لَيْلَةٍ إِلَى السَّمَاءِ الدُّنْيَا، حِينَ يَبْقَى ثُلُثُ اللَّيْلِ الْآخِرُ، فَيَقُولُ: مَنْ يَدْعُونِي فَأَسْتَجِيبَ لَهُ؟ وَمَنْ يَسْأَلُنِي فَأُعْطِيَهُ؟ وَمَنْ يَسْتَغْفِرُنِي فَأَغْفِرَ لَهُ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "എല്ലാ രാത്രിയും അവസാന മൂന്നിലൊന്ന് എത്തുമ്പോൾ അല്ലാഹു ഭൂമിക്കടുത്ത ആകാശത്തിലേക്ക് ഇറങ്ങി വരും. എന്നിട്ട് അവൻ പറയും: വല്ലവനും എന്നോട് പ്രാർത്ഥിച്ചാൽ ഞാൻ അവന് ഉത്തരം ചെയ്യും. വല്ലവനും എന്നോട് ചോദിച്ചാൽ ഞാനവന് നൽകും. വല്ലവനും പൊറുക്കലിനെ ചോദിച്ചാൽ അവന് ഞാൻ പൊറുത്ത് കൊടുക്കും." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 937, 937, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 167, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ بَعْثًا قِبَلَ نَجْدٍ، فَغَنِمُوا غَنَائِمَ كَثِيرَةً، وَأَسْرَعُوا الرَّجْعَةَ، فَقَالَ رَجُلٌ مِمَّنْ لَمْ يَخْرُجْ: مَا رَأَيْنَا بَعْثًا أَسْرَعَ رَجْعَةً وَلَا أَفْضَلَ غَنِيمَةً مِنْ هَذَا الْبَعْثِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَلَا أَدُلُّكُمْ عَلَى قَوْمٍ أَفْضَلَ غَنِيمَةً وَأَسْرَعَ رَجْعَةً؟ قَوْمٌ شَهِدُوا صَلَاةَ الصُّبْحِ، ثُمَّ جَلَسُوا يَذْكُرُونَ اللَّهَ حَتَّى طَلَعَتْ عَلَيْهِمُ الشَّمْسُ، فَأُولَئِكَ أَسْرَعُ رَجْعَةً وَأَفْضَلُ غَنِيمَةً". (ت)', 'ഉമർ(റ): റസൂൽ(സ) നജ്ദിന്റെ ഭാഗത്തേക്ക് ഒരു സംഘത്തെ യുദ്ധത്തിനയച്ചു. അവർക്കൊരുപാട് യുദ്ധമുതൽ ലഭിച്ചു. അവർ പെട്ടെന്ന് മടങ്ങിവരികയും ചെയ്തു. അത് കണ്ട് സംഘത്തിൽ ഇല്ലാത്ത ഒരാൾ പറഞ്ഞു: ഇത്ര പെട്ടെന്ന് മടങ്ങിവരികയും ഇത്രയധികം യുദ്ധമുതൽ കിട്ടുകയും ചെയ്ത ഒരു സംഘത്തെയും മുമ്പ് നാം കണ്ടിട്ടില്ല. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഇതിനേക്കാൾ പെട്ടെന്ന് മടങ്ങി വരികയും ഇതിനേക്കാൾ ശ്രേഷ്ഠമായ യുദ്ധമുതൽ ലഭിക്കുകയും ചെയ്യുന്ന ഒരു കൂട്ടരെക്കുറിച്ച് ഞാൻ നിങ്ങൾക്ക് അറിയിച്ചു തരട്ടെയോ? സുബ്‌ഹി നിസ്കരിച്ച് സൂര്യനുദിക്കുന്നത് വരെ അല്ലാഹുവിന് ദിക്‌റ് ചൊല്ലുന്നവരാണ് അക്കൂട്ടർ. അവരാണ് വേഗത്തിൽ മടക്കമുണ്ടാകുന്നവരും ശ്രേഷ്ഠമായ യുദ്ധമുതൽ വാരിക്കൂട്ടുന്നവരും." (തു)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 937, 937, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 168, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا قَامَ إِلَى الصَّلَاةِ قَالَ: "وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَوَاتِ وَالأَرْضَ حَنِيفًا وَمَا أَنَا مِنَ الْمُشْرِكِينَ، إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ، لَا شَرِيكَ لَهُ، وَبِذَلِكَ أُمِرْتُ وَأَنَا مِنَ الْمُسْلِمِينَ. اللَّهُمَّ أَنْتَ الْمَلِكُ لَا إِلَهَ إِلَّا أَنْتَ، أَنْتَ رَبِّي وَأَنَا عَبْدُكَ، ظَلَمْتُ نَفْسِي وَاعْتَرَفْتُ بِذَنْبِي فَاغْفِرْ لِي ذُنُوبِي جَمِيعًا، إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، وَاهْدِنِي لِأَحْسَنِ الْأَخْلَاقِ لَا يَهْدِي لِأَحْسَنِهَا إِلَّا أَنْتَ، وَاصْرِفْ عَنِّي سَيِّئَهَا إِنَّهُ لَا يَصْرِفُ عَنِّي سَيِّئَهَا إِلَّا أَنْتَ. آمَنْتُ بِكَ، تَبَارَكْتَ وَتَعَالَيْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ". فَإِذَا رَكَعَ قَالَ: "اللَّهُمَّ لَكَ رَكَعْتُ، وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، خَشَعَ لَكَ سَمْعِي وَبَصَرِي وَمُخِّي وَعِظَامِي وَعَصَبِي". فَإِذَا رَفَعَ رَأْسَهُ قَالَ: "اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ، مِلْءَ السَّمَوَاتِ وَالأَرْضِينَ وَمِلْءَ مَا بَيْنَهُمَا، وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ". فَإِذَا سَجَدَ قَالَ: "اللَّهُمَّ لَكَ سَجَدْتُ، وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، سَجَدَ وَجْهِي لِلَّذِي خَلَقَهُ فَصَوَّرَهُ وَشَقَّ سَمْعَهُ وَبَصَرَهُ، فَتَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ". ثُمَّ يَكُونُ آخِرَ مَا يَقُولُ بَيْنَ التَّشَهُّدِ وَالسَّلَامِ: "اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ، لَا إِلَهَ إِلَّا أَنْتَ". (م, د, ت, ن, جه)
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=168), 1, 'وَفِي رِوَايَةٍ: أَنَّهُ كَانَ إِذَا قَامَ إِلَى الصَّلَاةِ الْمَكْتُوبَةِ رَفَعَ يَدَيْهِ حَذْوَ مَنْكِبَيْهِ، وَيَصْنَعُ ذَلِكَ أَيْضًا إِذَا قَضَى قِرَاءَتَهُ وَأَرَادَ أَنْ يَرْكَعَ، وَيَصْنَعُهَا إِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ، وَلَا يَرْفَعُ يَدَيْهِ فِي شَيْءٍ مِنْ صَلَاتِهِ وَهُوَ قَاعِدٌ، فَإِذَا قَامَ مِنْ سَجْدَتَيْنِ رَفَعَ يَدَيْهِ كَذَلِكَ فَكَبَّرَ. (ت)', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) നിർബന്ധമായ നിസ്കാരത്തിന് നിന്നാൽ ചുമലിനു നേരെ ഇരുകരങ്ങളുയർത്തും. ഓതിക്കഴിഞ്ഞ് റുകൂഇലേക്ക് പോകുമ്പോഴും റുകൂഇൽ നിന്നുയരുമ്പോഴും റസൂൽ കൈ ഉയർത്തും. നിസ്കാരത്തിൽ ഇരിക്കുമ്പോൾ വേറെ ഒരിടത്തും കൈ ഉയർത്താറില്ല. രണ്ട് സുജൂദും കഴിഞ്ഞ് എഴുന്നേൽക്കുമ്പോൾ നബി(സ) ഇതു പോലെ കൈ ഉയർത്തും, എന്നിട്ട് തക്ബീർ ചൊല്ലും. (തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 169, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "خَلَّتَانِ لَا يُحْصِيهِمَا رَجُلٌ مُسْلِمٌ إِلَّا دَخَلَ الْجَنَّةَ، أَلَا وَهُمَا يَسِيرٌ، وَمَنْ يَعْمَلُ بِهِمَا قَلِيلٌ يُسَبِّحُ اللَّهَ فِي دُبُرِ كُلِّ صَلَاةٍ عَشْرًا، وَيَحْمَدُهُ عَشْرًا، وَيُكَبِّرُهُ عَشْرًا". قَالَ: فَأَنَا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَعْقِدُهَا بِيَدِهِ. قَالَ: "فَتِلْكَ خَمْسُونَ وَمِائَةٌ بِاللِّسَانِ، وَأَلْفٌ وَخَمْسُ مِائَةٍ فِي الْمِيزَانِ. وَإِذَا أَخَذْتَ مَضْجَعَكَ تُسَبِّحُهُ وَتُكَبِّرُهُ وَتَحْمَدُهُ مِائَةً، فَتِلْكَ مِائَةٌ بِاللِّسَانِ، وَأَلْفٌ فِي الْمِيزَانِ. فَأَيُّكُمْ يَعْمَلُ فِي الْيَوْمِ وَاللَّيْلَةِ أَلْفَيْنِ وَخَمْسَ مِائَةِ سَيِّئَةٍ". قَالُوا: فَكَيْفَ لَا يُحْصِيهَا؟ قَالَ: "يَأْتِي أَحَدَكُمُ الشَّيْطَانُ وَهُوَ فِي صَلَاتِهِ فَيَقُولُ: اذْكُرْ كَذَا، اذْكُرْ كَذَا، حَتَّى يَنْفَتِلَ، فَلَعَلَّهُ لَا يَفْعَلُ، وَيَأْتِيهِ وَهُوَ فِي مَضْجَعِهِ، فَلَا يَزَالُ يُنَوِّمُهُ حَتَّى يَنَامَ". حَسَنٌ صَحِيحٌ. (د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "രണ്ട് കാര്യങ്ങൾ, അവയെ പതിവാക്കിയ ഏതൊരു മുസ്ലിമും സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുന്നതായിരിക്കും, അറിയുക, അവ വളരെ ലളിതമാണ്. അവ കൊണ്ട് പ്രവർത്തിക്കുന്നവർ നന്നേ കുറവാണ്. ഓരോ നിസ്കാരത്തിന് ശേഷവും പത്ത് വീതം തസ്ബീഹും, ഹംദും, തക്ബീറും, ചൊല്ലലാണത്." നിവേദകൻ പറയുന്നു: നബി(സ) ഇവയെ കൈകൊണ്ട് എണ്ണം പിടിക്കുന്നതായി ഞാൻ കണ്ടിട്ടുണ്ട്. നബി(സ) തുടരുന്നു: "അത് നാക്ക് കൊണ്ട് നൂറ്റമ്പത് ആണെങ്കിലും മീസാനിൽ ആയിരത്തിഅഞ്ഞൂറാണ്. ഇനി നീ കിടപ്പറയിൽ ചെന്ന് നൂറ് വട്ടം അല്ലാഹുവിനെ തസ്ബീഹും ഹംദും തക്ബീറും ചൊല്ലിയാൽ, നാക്ക് കൊണ്ടത് നൂറാണെങ്കിലും മീസാനിൽ അത് ആയിരമാണ്. നിങ്ങളിലാരാണ് ഒരു ദിനരാത്രിയിൽ രണ്ടായിരത്തഞ്ഞൂറ് തെറ്റുകൾ ചെയ്യുക." അവർ ചോദിച്ചു: എങ്ങനെയാണതിനെ പതിവാക്കാതിരിക്കുന്ന അവസ്ഥയുണ്ടാകുക? നബി(സ) പറഞ്ഞു: "നിസ്കാരത്തിലായിരിക്കെ അടുത്തേക്ക് ശൈത്താൻ വന്ന്, നിസ്കാരം കഴിയുന്നത് വരെ, പറഞ്ഞ് കൊണ്ടിരിക്കും, നീ ഇന്നതോർക്ക്, നീ ഇന്നതോർക്ക് എന്ന്, അങ്ങനെ അവൻ (നിസ്കരിക്കുന്നവൻ) ഇത് ചെയ്യാതിരുന്നേക്കാം. ഇനി അവന്റെ കിടപ്പറയിലും ശൈത്താൻ വരും. അവൻ ഉറങ്ങുന്നത് വരെ ശൈത്താൻ അവനെ ഉറക്കിക്കൊണ്ടിരിക്കും." (ദ,തു,ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 939, 939, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 170, 'عَنْ كَعْبِ بْنِ عُجْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مُعَقِّبَاتٌ لَا يَخِيبُ قَائِلُهُنَّ: يُسَبِّحُ اللهَ فِي دُبُرِ كُلِّ صَلَاةٍ ثَلَاثًا وَثَلَاثِينَ، وَيَحْمَدُهُ ثَلَاثًا وَثَلَاثِينَ وَيُكَبِّرُهُ أَرْبَعًا وَثَلَاثِينَ". حَسَنٌ. (م,ت,ن)', 'കഅ്ബുബ്നു ഉജ്റ(റ): നബി(സ) പറഞ്ഞു: "നിസ്കാരത്തിന് ശേഷം ചില വചനങ്ങളുണ്ട്. അത് പറയുന്നവർ നിരാശരാവില്ല. നിസ്കാരത്തിന് ശേഷം മുപ്പത്തിമൂന്ന് തവണ വീതം തസ്ബീഹും ഹംദും, മുപ്പത്തിനാല് തക്ബീറും ചൊല്ലലാണത്." (മു,തു,ന)', 'كَعْبِ بْنِ عُجْرَةَ', 'കഅ്ബുബ്നു ഉജ്റ(റ)', null, null, array['م','ت','ن']::text[], array['മു','തു','ന']::text[], null, null, 940, 940, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 171, 'عَنْ زَيْدِ بْنِ ثَابِتٍ رَضِيَ اللهُ عَنْهُ قَالَ: أُمِرْنَا أَنْ نُسَبِّحَ دُبُرَ كُلِّ صَلَاةٍ: ثَلَاثًا، وَثَلَاثِينَ، وَنَحْمَدَهُ ثَلَاثًا وَثَلَاثِينَ، وَنُكَبِّرَهُ أَرْبَعًا وَثَلَاثِينَ. قَالَ: فَرَأَى رَجُلٌ مِنَ الْأَنْصَارِ فِي الْمَنَامِ، فَقَالَ: أَمَرَكُمْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ تُسَبِّحُوا فِي دُبُرِ كُلِّ صَلَاةٍ ثَلَاثًا وَثَلَاثِينَ، وَتَحْمَدُوا اللهَ ثَلَاثًا وَثَلَاثِينَ، وَتُكَبِّرُوا أَرْبَعًا وَثَلَاثِينَ. قَالَ: نَعَمْ. قَالَ: فَاجْعَلُوا خَمْسًا وَعِشْرِينَ، وَاجْعَلُوا التَّهْلِيلَ مَعَهُنَّ، فَغَدَا عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَحَدَّثَهُ، فَقَالَ: "افْعَلُوا". حَسَنٌ صَحِيحٌ. (ت,ن)', 'സൈദുബ്നു സാബിത്(റ): ഓരോ നിസ്കാരത്തിന് പിറകെയും മുപ്പത്തിമൂന്ന് വീതം തസ്ബീഹും ഹംദും മുപ്പത്തിനാല് തക്ബീറും ചൊല്ലാൻ ഞങ്ങൾ കൽപ്പിക്കപ്പെട്ടു; നിവേദകൻ പറയുന്നു: അൻസാറുകളിൽ പെട്ടൊരാൾ സ്വപ്നം കണ്ടു. അയാൾ ചോദിച്ചു: ഓരോ നിസ്കാരശേഷവും മുപ്പത്തിമൂന്ന് വീതം തസ്ബീഹും ഹംദും മുപ്പത്തിനാല് തക്ബീറും ചൊല്ലാൻ റസൂൽ(സ) നിങ്ങളോട് കൽപ്പിച്ചിട്ടില്ലേ. അദ്ദേഹം പറഞ്ഞു: അതെ, അയാൾ പറഞ്ഞു: എന്നാൽ നിങ്ങളത് ഇരുപത്തഞ്ചാക്കുകയും അവയോട് കൂടെ തഹ്ലീൽ ചേർക്കുകയും ചെയ്യുക, അങ്ങനെ അയാൾ പിറ്റേ ദിവസം രാവിലെ റസൂൽ(സ)യോട് വിവരം പറഞ്ഞു: അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളപ്രകാരം ചെയ്യുക." (തു,ന)', 'زَيْدِ بْنِ ثَابِتٍ', 'സൈദുബ്നു സാബിത്(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 940, 940, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 172, 'عَنْ عَبْدِ اللهِ بْنِ مُغَفَّلٍ رَضِيَ اللهُ عَنْهُ: سَمِعَ ابْنَهُ يَقُولُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ الْقَصْرَ الْأَبْيَضَ عَنْ يَمِينِ الْجَنَّةِ، إِذَا دَخَلْتُهَا. فَقَالَ: أَيْ بُنَيَّ، سَلِ اللهَ الْجَنَّةَ وَعُذْ بِهِ مِنَ النَّارِ، فَإِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "سَيَكُونُ قَوْمٌ يَعْتَدُونَ فِي الدُّعَاءِ". (د,جه)', 'അബ്ദുല്ലാഹിബ്നു മുഅഫ്ഫൽ(റ): തന്റെ മകൻ ഇപ്രകാരം ദുആചെയ്യുന്നത് അദ്ദേഹം കേട്ടു: അല്ലാഹുവേ, ഞാൻ സ്വർഗത്തിൽ പ്രവേശിക്കുകയാണെങ്കിൽ സ്വർഗ്ഗത്തിന്റെ വലതു ഭാഗത്ത് ഒരു വെളുത്ത കൊട്ടാരം ഞാൻ നിന്നോട് ചോദിക്കുന്നു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: പൊന്നുമോനേ, നീ അല്ലാഹുവിനോട് സ്വർഗ്ഗം ചോദിക്കുക. നരകത്തിൽ നിന്ന് കാവലും ചോദിക്കുക: കാരണം റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "അതിരുവിട്ട് പ്രാർത്ഥിക്കുന്ന ഒരു കൂട്ടർ ശേഷം വരും." (ദ,ജ)', 'عَبْدِ اللهِ بْنِ مُغَفَّلٍ', 'അബ്ദുല്ലാഹിബ്നു മുഅഫ്ഫൽ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 940, 940, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 173, 'عَنْ سَلْمَانَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ رَبَّكُمْ حَيٌّ كَرِيمٌ، يَسْتَحْيِي مِنْ عَبْدِهِ أَنْ يَرْفَعَ إِلَيْهِ يَدَيْهِ فَيَرُدَّهُمَا صِفْرًا". أَوْ قَالَ: "خَائِبَتَيْنِ". (د,ت,جه)', 'സൽമാൻ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ നാഥൻ ജീവസ്സുറ്റവനും മാന്യനുമാകുന്നു. തന്നിലേക്ക് തന്റെ ദാസനുയർത്തിയ കരങ്ങൾ വെറുതെ മടക്കാൻ അല്ലെങ്കിൽ നിരാശപ്പെട്ടവയായി മടക്കാൻ അവൻ ലജ്ജിക്കുന്നു." (ദ,തു,ജ)', 'سَلْمَانَ', 'സൽമാൻ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 940, 941, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 174, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا دَعَوْتَ اللَّهَ فَادْعُ بِبُطُونِ كَفَّيْكَ، وَلَا تَدْعُ بِظُهُورِهِمَا. فَإِذَا فَرَغْتَ فَامْسَحْ بِهِمَا وَجْهَكَ". (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ അല്ലാഹുവിനോട് പ്രാർത്ഥിക്കുമ്പോൾ ഉള്ളൻ കൈകൊണ്ട് പ്രാർത്ഥിക്കുക. കൈപുറം കൊണ്ട് പ്രാർത്ഥിക്കരുത്. പ്രാർത്ഥനയിൽ നിന്ന് വിരമിച്ചാൽ ഇരു കരങ്ങൾകൊണ്ടും മുഖം തടവുക." (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 941, 941, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 175, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا رَفَعَ يَدَيْهِ فِي الدُّعَاءِ لَمْ يَحُطَّهُمَا - يَرُدَّهُمَا - حَتَّى يَمْسَحَ بِهِمَا وَجْهَهُ. (ت)', 'ഉമർ(റ): റസൂൽ(സ) പ്രാർത്ഥനക്ക് കരമുയർത്തിയാൽ മുഖം തടവാതെ അത് താഴ്ത്താറില്ല. (തു)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 941, 941, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 176, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا، عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا ذَكَرَ أَحَدًا فَدَعَا لَهُ بَدَأَ بِنَفْسِهِ. حَسَنٌ صَحِيحٌ. (د,ت)', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)വിൽ നിന്ന് ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) ഒരാൾക്ക് വേണ്ടി പ്രാർത്ഥിക്കുമ്പോൾ സ്വന്തത്തിൽ നിന്ന് തുടങ്ങുമായിരുന്നു. (ദ,തു)', 'ابْنِ عَبَّاسٍ', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 941, 941, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 177, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ثَلَاثُ دَعَوَاتٍ يُسْتَجَابُ لَهُنَّ، لَا شَكَّ فِيهِنَّ: دَعْوَةُ الْمَظْلُومِ، وَدَعْوَةُ الْمُسَافِرِ، وَدَعْوَةُ الْوَالِدِ لِوَلَدِهِ". (د,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിസ്സംശയം ഉത്തരം നൽകപ്പെടുന്ന മൂന്ന് പ്രാർത്ഥനകളുണ്ട്: അക്രമിക്കപ്പെട്ടവന്റെ പ്രാർത്ഥന, യാത്രക്കാരന്റെ പ്രാർത്ഥന, മകന് വേണ്ടിയുള്ള പിതാവിന്റെ പാർത്ഥന." (ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 941, 941, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 178, 'عَنْ أُمِّ حَكِيمٍ بِنْتِ وَدَاعٍ الْخُزَاعِيَّةِ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "دُعَاءُ الْوَالِدِ يُفْضِي إِلَى الْحِجَابِ". (جه)', 'വദാഉൽ ഖുസാഇയ്യയുടെ മകൾ ഉമ്മുഹകീം(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "പിതാവിന്റെ പ്രാർത്ഥന ആ മറയിലേക്ക് - അല്ലാഹുവിലേക്ക് - എത്തും." (ജ)', 'أُمِّ حَكِيمٍ بِنْتِ وَدَاعٍ الْخُزَاعِيَّةِ', 'വദാഉൽ ഖുസാഇയ്യയുടെ മകൾ ഉമ്മുഹകീം(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 941, 941, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 179, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدْعُو فَيَقُولُ: "اللَّهُمَّ مَتِّعْنِي بِسَمْعِي وَبَصَرِي، وَاجْعَلْهُمَا الْوَارِثَ مِنِّي، وَانْصُرْنِي عَلَى مَنْ يَظْلِمُنِي، وَخُذْ مِنْهُ بِثَأْرِي". (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പ്രാർത്ഥിക്കാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ, എന്റെ കാഴ്ചയിലും കേൾവിയിലും സുഖം പ്രദാനം ചെയ്യേണമേ. അവയെ എന്റെ അനന്തരമാക്കേണമേ. അക്രമിക്കെതിരെ എന്നെ സഹായിക്കേണമേ, ഞങ്ങൾക്ക് വേണ്ടി അവനോട് പ്രതികാരം ചെയ്യേണമേ." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 941, 942, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 180, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا رَأَى سَحَابًا مُقْبِلًا مِنْ أُفُقٍ مِنَ الْآفَاقِ تَرَكَ مَا هُوَ فِيهِ – وَإِنْ كَانَ فِي صَلَاتِهِ – حَتَّى يَسْتَقْبِلَهُ، فَيَقُولُ: "اللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ شَرِّ مَا أُرْسِلَ بِهِ". فَإِنْ أَمْطَرَ قَالَ: "اللَّهُمَّ صَيِّبًا نَافِعًا" مَرَّتَيْنِ أَوْ ثَلَاثَةً. وَإِنْ كَشَفَهُ اللهُ عَزَّ وَجَلَّ وَلَمْ يُمْطِرْ حَمِدَ اللهَ عَلَى ذَلِكَ. (د, ن, جه)', 'ആഇശ(റ): നബി(സ) ചക്രവാളങ്ങളിലെവിടെയെങ്കിലും മേഘം കണ്ടാൽ അവിടന്ന് എന്ത് പ്രവർത്തിയിലായിരുന്നോ, അത് നിസ്കാരമാണെങ്കിലും, അതുപേക്ഷിച്ച് മേഘത്തിനു നേരെ മുന്നിട്ട് പറയും: "അല്ലാഹുവേ, അയക്കപ്പെട്ടതിന്റെ നാശത്തിൽ നിന്ന് നിന്നോട് ഞങ്ങൾ കാവൽ ചോദിക്കുന്നു." ഇനി മഴ പെയ്താൽ റസൂൽ(സ) രണ്ടോ മൂന്നോ പ്രാവശ്യം പറയും: "ഉപകാരപ്രദമായി നീ വർഷിപ്പിക്കേണമേ." ഇനി മേഘം തെളിഞ്ഞ് മഴ പെയ്യാതിരുന്നാൽ റസൂൽ(സ) അതിന് അല്ലാഹുവിനെ സ്തുതിക്കുകയും ചെയ്യും. (ദ, ന, ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 942, 942, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 181, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا رَأَى الْمَطَرَ قَالَ: "اللَّهُمَّ اجْعَلْهُ صَيِّبًا هَنِيئًا". (خ, جه)', 'ആഇശ(റ): റസൂൽ(സ) മഴ കണ്ടാൽ പറയുമായിരുന്നു: "അല്ലാഹുവേ, ആ മഴയെ ഒലിച്ചിറങ്ങുന്നതും ഉപകാര പ്രദവുമാക്കി വർഷിപ്പിക്കേണമേ." (ബു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 942, 942, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 182, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا رَأَى مَخِيلَةً تَلَوَّنَ وَجْهُهُ وَتَغَيَّرَ، وَدَخَلَ وَخَرَجَ، وَأَقْبَلَ وَأَدْبَرَ، فَإِذَا أَمْطَرَتْ سُرِّيَ عَنْهُ. قَالَ: فَذَكَرَتْ لَهُ عَائِشَةُ بَعْضَ مَا رَأَتْ مِنْهُ، فَقَالَ: "وَمَا يُدْرِيكِ؟ لَعَلَّهُ كَمَا قَالَ قَوْمُ هُودٍ: {فَلَمَّا رَأَوْهُ عَارِضًا مُسْتَقْبِلَ أَوْدِيَتِهِمْ قَالُوا هَذَا عَارِضٌ مُمْطِرُنَا بَلْ هُوَ مَا اسْتَعْجَلْتُمْ بِهِ}" الْآيَةَ [الأحقاف: ٢٤]. (م, ت, جه)', 'ആഇശ(റ): റസൂൽ(സ) മഴയും ഇടിയുമുണ്ടാകാൻ സാധ്യതയുള്ള മേഘം കണ്ടാൽ, അവിടത്തെ മുഖം വിവർണ്ണമാകും, വീടിനുള്ളിൽ നിന്ന് പുറത്ത് പോവുകയും അകത്ത് കടക്കുകയും, മുന്നിടുകയും പിന്നിടുകയും ചെയ്യും. മേഘം മഴ പെയ്യിപ്പിച്ചാൽ നബി(സ)യിൽ നിന്നും വിഷമം അകന്ന് പോകും. നിവേദകൻ പറയുന്നു: അവിടത്തെ പക്കൽ നിന്നും ചില (അസാധാരണ) പെരുമാറ്റം കണ്ടത് ആഇശ(റ) അവിടത്തോട് ഓർമ്മിപ്പിച്ചു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "അതെന്താണെന്ന് നിനക്കറിയുമോ? ഒരു പക്ഷേ, അത് ഹൂദ് നബി(അ)ന്റെ സമുദായം പറഞ്ഞത് പോലെയായിരിക്കും: (ശിക്ഷയെ തങ്ങളുടെ താഴ്‌വരകൾക്കഭിമുഖമായി വെളിപ്പെട്ട മേഘമായി കണ്ടപ്പോൾ അവർ പറഞ്ഞു: ഇതാ, നമുക്ക് മഴനൽകുന്ന മേഘം, അല്ല, നിങ്ങൾ എന്തൊന്നിന് ധൃതി കൂട്ടിയോ അതു തന്നെയാണിത്)." (അഹ്ഖാഫ്: 24) (മു,തു,ജ,)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], 'الأحقاف: ٢٤', null, 942, 942, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 183, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا رَأَى الرِّيحَ قَالَ: "اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ خَيْرِهَا وَخَيْرِ مَا فِيهَا وَخَيْرِ مَا أُرْسِلَتْ بِهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا وَشَرِّ مَا فِيهَا وَشَرِّ مَا أُرْسِلَتْ بِهِ". حَسَنٌ. (ق,ت)', 'ആഇശ(റ): നബി(സ)തങ്ങൾ കാറ്റ് കണ്ടാൽ പറയുമായിരുന്നു: "അല്ലാഹുവേ, അതിന്റെ നന്മയും അതിലുള്ളതിന്റെ നന്മയും അത് അയക്കപ്പെട്ടതിന്റെ നന്മയും നിന്നോട് ഞാൻ ചോദിക്കുന്നു. അതിന്റെ നാശത്തിൽ നിന്നും അതിലുള്ളതിന്റെ നാശത്തിൽ നിന്നും അത് അയക്കപ്പെട്ടതിന്റെ നാശത്തിൽ നിന്നും. നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു. (ബു,മു,തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 942, 943, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 184, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا سَمِعَ صَوْتَ الرَّعْدِ وَالصَّوَاعِقِ قَالَ: "اللَّهُمَّ لَا تَقْتُلْنَا بِغَضَبِكَ، وَلَا تُهْلِكْنَا بِعَذَابِكَ، وَعَافِنَا قَبْلَ ذَلِكَ". (ت)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): തിരുദൂതർ(സ) ഇടിയുടെ ശബ്ദം കേട്ടാൽ പറയുമായിരുന്നു: "അല്ലാഹുവേ, നിന്റെ ദേഷ്യം കൊണ്ട് ഞങ്ങളെ വധിച്ച് കളയരുതേ, നിന്റെ ശിക്ഷ കൊണ്ട് ഞങ്ങളെ നശിപ്പിക്കരുതേ, അതിന് മുമ്പ് തന്നെ ഞങ്ങളെ നീ സംരക്ഷിക്കേണമേ." (തു)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 943, 943, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 185, 'عَنْ عَبْدِ الْعَزِيزِ - وَهُوَ ابْنُ صُهَيْبٍ - قَالَ: سَأَلَ قَتَادَةُ أَنَسًا رَضِيَ اللَّهُ عَنْهُ: أَيُّ دَعْوَةٍ كَانَ يَدْعُو بِهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَكْثَرَ؟ قَالَ: كَانَ أَكْثَرُ دَعْوَةٍ يَدْعُو بِهَا يَقُولُ: "اللَّهُمَّ آتِنَا فِي الدُّنْيَا حَسَنَةً، وَفِي الْآخِرَةِ حَسَنَةً، وَقِنَا عَذَابَ النَّارِ". قَالَ: وَكَانَ أَنَسٌ إِذَا أَرَادَ أَنْ يَدْعُوَ بِدَعْوَةٍ دَعَا بِهَا، فَإِذَا أَرَادَ أَنْ يَدْعُوَ بِدُعَاءٍ دَعَا بِهَا فِيهِ. (م)', 'അബ്ദുൽ അസീസുബ്നു സ്വുഹൈബ്(റ): ഖതാദ(റ) അനസ്(റ)വിനോട് ചോദിച്ചു: ഏത് ദുആയായിരുന്നു നബി(സ) കൂടുതലായി ചെയ്തിരുന്നത്? അവർ പറഞ്ഞു: അവിടന്ന് ഏറ്റവും കൂടുതലായി പ്രാർത്ഥിക്കാറുള്ള പ്രാർത്ഥന ഇങ്ങനെയായിരുന്നു: "അല്ലാഹുവേ, ഞങ്ങൾക്ക് ഈ ലോകത്ത് നന്മയെ നൽകേണമേ, പരലോകത്തും ഞങ്ങൾക്ക് നന്മയെ നൽകേണമേ. നരക ശിക്ഷയിൽ നിന്നും ഞങ്ങളെ സംരക്ഷിക്കേണമേ." നിവേദകൻ പറയുന്നു: അനസ്(റ) ഒരു ദുആ ചെയ്യാൻ ഉദ്ദേശിച്ചാൽ ഇത് കൊണ്ട് മാത്രമായിരുന്നു പ്രാർത്ഥിച്ചിരുന്നത്. ഇനി ദുആ ഉദ്ദേശിക്കുകയാണെങ്കിൽ ആ ദുആയിൽ ഈ വചനങ്ങളെ കൊണ്ട് പ്രാർത്ഥിക്കുമായിരുന്നു. (മു)', 'عَبْدِ الْعَزِيزِ - وَهُوَ ابْنُ صُهَيْبٍ - قَالَ', 'അബ്ദുൽ അസീസുബ്നു സ്വുഹൈബ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 943, 943, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 186, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "قُلْ: اللَّهُمَّ اهْدِنِي، وَسَدِّدْنِي. وَاذْكُرْ بِالْهُدَى هِدَايَتَكَ الطَّرِيقَ، وَالسَّدَادِ سَدَادَ السَّهْمِ". (م)', 'അലിയ്യ്(റ): റസൂൽ(സ) എന്നോട് പറഞ്ഞു: "നീ പറയുക:. അല്ലാഹുവേ, എന്നെ നീ സന്മാർഗ്ഗത്തിലേക്ക് വഴിനടത്തേണമേ, എന്നെ ശരിപ്പെടുത്തുകയും ചെയ്യേണമേ, ഹുദാ(സൻമാർഗം) കൊണ്ട് നിന്റെ സന്മാർഗ മാകുന്ന വഴിയെയും, സിദാദ് (ശരിപ്പെടുത്തൽ) കൊണ്ട് യാഥാർത്ഥ്യത്തിന്മേലുള്ള സ്ഥിതിയെയുമാണ് നീ ഓർക്കേണ്ടത്." (മു)', 'عَلِيٍّ', 'അലിയ്യ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 943, 944, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 187, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "بَيْنَمَا ثَلَاثَةُ نَفَرٍ يَتَمَشَّوْنَ أَخَذَهُمُ الْمَطَرُ، فَأَوَوْا إِلَى غَارٍ فِي جَبَلٍ، فَانْحَطَّتْ عَلَى فَمِ غَارِهِمْ صَخْرَةٌ مِنَ الْجَبَلِ، فَانْطَبَقَتْ عَلَيْهِمْ، فَقَالَ بَعْضُهُمْ لِبَعْضٍ: انْظُرُوا أَعْمَالًا عَمِلْتُمُوهَا صَالِحَةً لِلَّهِ، فَادْعُوا اللَّهَ تَعَالَى بِهَا لَعَلَّ اللَّهَ يَفْرُجُهَا عَنْكُمْ، فَقَالَ أَحَدُهُمُ: اللَّهُمَّ إِنَّهُ كَانَ لِي وَالِدَانِ شَيْخَانِ كَبِيرَانِ وَامْرَأَتِي، وَلِي صِبْيَةٌ صِغَارٌ، أَرْعَى عَلَيْهِمْ، فَإِذَا أَرَحْتُ عَلَيْهِمْ، حَلَبْتُ فَبَدَأْتُ بِوَالِدَيَّ فَسَقَيْتُهُمَا قَبْلَ بَنِيَّ، وَإِنِّي نَأَى بِي ذَاتَ يَوْمٍ الشَّجَرُ، فَلَمْ آتِ حَتَّى أَمْسَيْتُ، فَوَجَدْتُهُمَا قَدْ نَامَا، فَحَلَبْتُ كَمَا كُنْتُ أَحْلُبُ، فَجِئْتُ بِالْحِلَابِ فَقُمْتُ عِنْدَ رُءُوسِهِمَا، أَكْرَهُ أَنْ أُوقِظَهُمَا مِنْ نَوْمِهِمَا، وَأَكْرَهُ أَنْ أَسْقِيَ الصِّبْيَةَ قَبْلَهُمَا، وَالصِّبْيَةُ يَتَضَاغَوْنَ عِنْدَ قَدَمَيَّ، فَلَمْ يَزَلْ ذَلِكَ دَأْبِي وَدَأْبَهُمْ حَتَّى طَلَعَ الْفَجْرُ، فَإِنْ كُنْتَ تَعْلَمُ أَنِّي فَعَلْتُ ذَلِكَ ابْتِغَاءَ وَجْهِكَ فَافْرُجْ لَنَا مِنْهَا فُرْجَةً نَرَى مِنْهَا السَّمَاءَ. فَفَرَجَ اللَّهُ مِنْهَا فُرْجَةً فَرَأَوْا مِنْهَا السَّمَاءَ. وَقَالَ الْآخَرُ: اللَّهُمَّ إِنَّهُ كَانَتْ لِي ابْنَةُ عَمٍّ أَحْبَبْتُهَا كَأَشَدِّ مَا يُحِبُّ الرِّجَالُ النِّسَاءَ، وَطَلَبْتُ إِلَيْهَا نَفْسَهَا، فَأَبَتْ حَتَّى آتِيَهَا بِمِائَةِ دِينَارٍ، فَتَعِبْتُ حَتَّى جَمَعْتُ مِائَةَ دِينَارٍ، فَجِئْتُهَا بِهَا، فَلَمَّا وَقَعْتُ بَيْنَ رِجْلَيْهَا قَالَتْ: يَا عَبْدَ اللَّهِ، اتَّقِ اللَّهَ وَلَا تَفْتَحِ الْخَاتَمَ إِلَّا بِحَقِّهِ. فَقُمْتُ عَنْهَا، فَإِنْ كُنْتَ تَعْلَمُ أَنِّي فَعَلْتُ ذَلِكَ ابْتِغَاءَ وَجْهِكَ. فَافْرُجْ لَنَا مِنْهَا فُرْجَةً. فَفَرَجَ لَهُمْ وَقَالَ الْآخَرُ: اللَّهُمَّ إِنِّي كُنْتُ اسْتَأْجَرْتُ أَجِيرًا بِفَرَقِ أَرُزٍّ، فَلَمَّا قَضَى عَمَلَهُ قَالَ: أَعْطِنِي حَقِّي. فَعَرَضْتُ عَلَيْهِ فَرَقَهُ فَرَغِبَ عَنْهُ، فَلَمْ أَزَلْ أَزْرَعُهُ حَتَّى جَمَعْتُ مِنْهُ بَقَرًا وَرِعَاءَهَا، فَجَاءَنِي فَقَالَ: اتَّقِ اللَّهَ وَلَا تَظْلِمْنِي حَقِّي. قُلْتُ: اذْهَبْ إِلَى تِلْكَ الْبَقَرِ وَرِعَائِهَا، فَخُذْهَا، فَقَالَ: اتَّقِ اللَّهَ وَلَا تَسْتَهْزِئْ بِي، فَقُلْتُ: إِنِّي لَا أَسْتَهْزِئُ بِكَ، خُذْ ذَلِكَ الْبَقَرَ وَرِعَاءَهَا. فَأَخَذَهُ فَذَهَبَ بِهِ، فَإِنْ كُنْتَ تَعْلَمُ أَنِّي فَعَلْتُ ذَلِكَ ابْتِغَاءَ وَجْهِكَ، فَافْرُجْ [لَنَا] مَا بَقِيَ. فَفَرَجَ اللَّهُ مَا بَقِيَ". (م)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) പറയുന്നു: "ഒരിക്കൽ മൂന്ന്പേരടങ്ങുന്ന ഒരു സംഘം നടന്നു പോകവേ മഴ പെയ്തു. അവർ മലയിലെ ഒരു ഗുഹയിൽ കയറിയിരുന്നു, അപ്പോൾ മലയിൽ നിന്ന് ഒരു പാറക്കല്ല് ഗുഹാമുഖത്ത് വന്നടഞ്ഞു, അത് അവരുടെമേൽ അടഞ്ഞുകിടന്നു. അവർ പരസ്പരം പറഞ്ഞു: നിങ്ങൾ ചെയ്ത സൽക്കർമ്മങ്ങൾ നോക്കുകയും അത് കൊണ്ട് പ്രാർത്ഥിക്കുകയും ചെയ്യുക, അല്ലാഹു പാറക്കല്ലിനെ മാറ്റിയേക്കാം. അപ്പോൾ അവരിൽ നിന്നൊരാൾ പറഞ്ഞു: അല്ലാഹുവേ, എനിക്ക് വൃദ്ധരായ മാതാപിതാക്കളും, ഒരു ഭാര്യയും ചെറിയ കുട്ടികളുമുണ്ടായിരുന്നു. അവർക്ക് വേണ്ടി ഞാൻ ആടിനെ മേച്ചിരുന്നു. വൈകുന്നേരം തിരിച്ചു വന്നാൽ ഞാൻ പാൽ കറക്കുകയും കുട്ടികൾക്ക് കൊടുക്കുന്നതിന് മുമ്പ് എന്റെ മാതാപിതാക്കൾക്ക് നൽകുകയും ചെയ്തിരുന്നു. അങ്ങനെ ഒരു ദിവസം മേച്ചിൽ സ്ഥലം വളരെ വിദൂരത്തായിരുന്നു. അതിനാൽ വൈകുന്നേരമാണ് ഞാൻ മടങ്ങിവന്നത്. അപ്പോഴേക്കും എന്റെ മാതാപിതാക്കൾ ഉറങ്ങിയിരുന്നു. ഞാൻ പാൽ കറന്നു. കറവു പാത്രവുമായി അവരുടെ അടുക്കൽ ചെന്ന് തലയുടെ ഭാഗത്ത് നിന്നു. അവരെ ഉണർത്താൻ മടിച്ച ഞാൻ അവരുടെ മുമ്പായി എന്റെയടുത്ത് കരഞ്ഞ് കൊണ്ടിരിക്കുന്ന കുട്ടികൾക്ക് കൊടുക്കാൻ ഇഷ്ടപ്പെട്ടില്ല. പുലർച്ച വരെ ഇത് തുടർന്ന് കൊണ്ടിരുന്നു. അല്ലാഹുവേ, നിന്റെ പ്രീതി ഉദ്ദേശിച്ചാണ് ഞാനത് ചെയ്തതെന്ന് നീ അറിയുമെങ്കിൽ ഞങ്ങൾക്ക് ആകാശം കാണും വിധം ഈ പാറക്കല്ലിനെ ഒന്ന് മാറ്റിത്തരേണമേ. അപ്പോൾ അല്ലാഹു അതിനെ കുറച്ച് മാറ്റുകയും അവർ അതിലൂടെ ആകാശം കാണുകയും ചെയ്തു. അപ്പോൾ മറ്റൊരാൾ പറഞ്ഞു: അല്ലാഹുവേ, എനിക്കൊരു എളാപ്പയുടെ മകളുണ്ടായിരുന്നു. ഞാൻ അവളെ പുരുഷൻമാർ സ്ത്രീകളെ അതിയായി സ്നേഹിക്കുന്നത് പോലെ കൂടുതൽ സ്നേഹിച്ചിരുന്നു. അവളുടെ ശരീരം, ഞാൻ അവളോട് ആവശ്യപ്പെട്ടു. ഞാൻ നൂറ്ദീനാറുമായി വരുന്നത് വരെ അവൾ സമ്മതിക്കുകയില്ലെന്നായിരുന്നു. അങ്ങനെ ഞാൻ അധ്വാനിച്ച് നൂറ് ദീനാർ ഒപ്പിക്കുകയും അവളുടെയടുക്കൽ പോകുകയും ചെയ്തു. ഞാൻ അവളുടെ രണ്ട് കാലുകൾക്കിടയിൽ കിടന്നപ്പോൾ അവൾ പറഞ്ഞു: ഓ, അല്ലാഹുവിന്റെ അടിമയേ, നീ അല്ലാഹുവിനെ സൂക്ഷിക്കുക. സീൽ പൊട്ടിക്കാൻ അവകാശമില്ലാതെ പൊട്ടിക്കരുത്. അപ്പോൾ ഞാൻ അവളിൽ നിന്നെണീറ്റു പോന്നു. (അല്ലാഹുവേ) ഞാൻ അങ്ങനെ ചെയ്തത് നിന്റെ വജ്ഹ് (മുഖം) ഉദ്ദേശിച്ചാണെന്ന് നിനക്ക് അറിയാമെങ്കിൽ ഈ പാറയെ കുറച്ച് മാറ്റിത്തരേണമേ. അപ്പോൾ അല്ലാഹു അത് കുറച്ച് നീക്കിക്കൊടുത്തു. മറ്റൊരാൾ പറഞ്ഞു: അല്ലാഹുവേ, ഒരു ഫറഖ് (ഏഴര കിലോ) അരിക്ക് പകരം ഒരാളെ ഞാൻ കൂലിക്ക് വിളിച്ചു. പണിപൂർത്തിയായപ്പോൾ അയാൾ എന്നോട് പറഞ്ഞു: എന്റെ അവകാശം എനിക്ക് നൽകുക. ഞാൻ അദ്ദേഹത്തിന് തന്റെ അവകാശം കൊടുത്തപ്പോൾ അദ്ദേഹം അത് തൃപ്തിപ്പെട്ടില്ല. അങ്ങനെ ഞാൻ അത് കൃഷിയിലിറക്കി ഒരു പശുക്കൂട്ടത്തെയും അതിന്റെ ഇടയരെയും സമ്പാദിച്ചു. അങ്ങനെയിരിക്കെ അദ്ദേഹം എന്റെയടുത്ത് വന്ന് പറഞ്ഞു: നീ അല്ലാഹുവിനെ സൂക്ഷിക്കുക, എന്റെ അവകാശത്തിൽ എന്നോട് അക്രമം ചെയ്യരുത്. ഞാൻ പറഞ്ഞു: ആ പശുക്കൂട്ടത്തെയും ഇടയരെയും നീ എടുത്ത് കൊള്ളുക. അദ്ദേഹം പറഞ്ഞു: നീ അല്ലാഹുവിനെ സൂക്ഷിക്കുക, എന്നെ പരിഹസിക്കരുത്. ഞാൻ പറഞ്ഞു: ഞാൻ നിന്നെ പരിഹസിക്കുകയല്ല, നീ അത് എടുക്കുക. അപ്പോൾ അദ്ദേഹം അത് എടുത്ത് കൊണ്ട് പോയി. അല്ലാഹുവേ, ഞാൻ അങ്ങനെ ചെയ്തത് നിന്റെ വജ്ഹ് (മുഖം) ഉദ്ദേശിച്ചാണെന്ന് നിനക്ക് അറിയാമെങ്കിൽ ബാക്കിയുള്ള പാറക്കല്ല് കൂടി നീ നീക്കിത്തരേണമേ. അപ്പോൾ ബാക്കിയുള്ളതും അല്ലാഹു നീക്കിക്കൊടുത്തു." (മു)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], 'لَنَا', null, 944, 945, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 188, 'عَنْ قَيْسِ بْنِ سَعْدِ بْنِ عُبَادَةَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ أَبَاهُ دَفَعَهُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْدُمُهُ، قَالَ: فَمَرَّ بِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَدْ صَلَّيْتُ، فَضَرَبَنِي بِرِجْلِهِ وَقَالَ: "أَلَا أَدُلُّكَ عَلَى بَابٍ مِنْ أَبْوَابِ الْجَنَّةِ". قُلْتُ: بَلَى، قَالَ: "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ". حَسَنٌ صَحِيحٌ. (ت)', 'ഖൈസുബ്‌നു സഅ്ദുബ്‌നു ഉബാദ(റ): അദ്ദേഹത്തെ തന്റെ പിതാവ് റസൂൽ(സ)ക്ക് സേവകനായി നൽകിയതായിരുന്നു. അദ്ദേഹം പറയുന്നു: ഞാൻ നിസ്കരിച്ചിരിക്കെ നബി(സ) എന്റെ അടുത്ത് കൂടി നടന്നു പോയി. അപ്പോൾ എന്നെ കാൽ കൊണ്ട് അടിച്ച് ചോദിച്ചു: സ്വർഗ്ഗകവാടങ്ങളിലെ ഒരു കവാടത്തെ കുറിച്ച് നിനക്ക് ഞാൻ അറിയിച്ച് തരട്ടെയോ? ഞാൻ പറഞ്ഞു: അതെ. റസൂൽ(സ) പറഞ്ഞു: "ലാ ഹൗല വലാ ഖുവ്വത ഇല്ലാ ബില്ലാഹ് (അല്ലാഹുവിനെക്കൊണ്ടല്ലാതെ ഒരു ശക്തിയും കഴിവും ഇല്ലതന്നെ.) (തു)', 'قَيْسِ بْنِ سَعْدِ بْنِ عُبَادَةَ', 'ഖൈസുബ്‌നു സഅ്ദുബ്‌നു ഉബാദ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 945, 945, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 189, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَكْثِرْ مِنْ قَوْلِ: لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، فَإِنَّهَا كَنْزٌ مِنْ كُنُوزِ الْجَنَّةِ". قَالَ مَكْحُولٌ: فَمَنْ قَالَ: لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، وَلَا مَنْجَا مِنَ اللَّهِ إِلَّا إِلَيْهِ. كَشَفَ عَنْهُ سَبْعِينَ بَابًا مِنَ الضُّرِّ، أَدْنَاهُنَّ الْفَقْرُ. (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) എന്നോട് പറഞ്ഞു: "നീ ഈ വാക്യം അധികമായി പറയുക. അല്ലാഹുവിനെക്കൊണ്ടല്ലാതെ ഒരു ശക്തിയും കഴിവും ഇല്ല തന്നെ." കാരണം അത് സ്വർഗ്ഗ നിധികളിലെ ഒരു നിധിയാകുന്നു." മക്ഹൂൽ(റ) പറയുന്നു: അല്ലാഹുവിനെ കൊണ്ടല്ലാതെ ഒരു ശക്തിയോ കഴിവോ ഇല്ല. അല്ലാഹുവിൽ നിന്ന് അവനല്ലാതെ ഒരു അഭയ കേന്ദ്രവുമില്ല. എന്ന് ആരെങ്കിലും പറഞ്ഞാൽ അവന്റെ ബുദ്ധിമുട്ടുകളുടെ എഴുപത് വാതിൽ അവന്റെ മുമ്പിൽ അടക്കപ്പെടും. ദാരിദ്ര്യം അതിൽ ഏറ്റവും ചെറുതാകുന്നു. (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 945, 946, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 190, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا خَرَجَ مِنْ بَيْتِهِ قَالَ: "بِسْمِ اللَّهِ، لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، التُّكْلَانُ عَلَى اللَّهِ". [ز: في سنده ضعيف] (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) അവിടത്തെ വീട്ടിൽ നിന്ന് പുറത്തിറങ്ങിയാൽ പറയാറുണ്ടായിരുന്നു: "അല്ലാഹുവിന്റെ നാമം കൊണ്ട് ഞാൻ തുടങ്ങുന്നു, ഒരു ശക്തിയും കഴിവും അല്ലാഹുവിനെക്കൊണ്ടല്ലാതെ ഇല്ല. അവലംബം അല്ലാഹുവിലാകുന്നു." (സനദിൽ ഒരു ബലഹീനൻ ഉണ്ട്). (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', null, 946, 946, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 191, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا خَرَجَ الرَّجُلُ مِنْ بَابِ بَيْتِهِ - أَوْ: مِنْ بَابِ دَارِهِ - كَانَ مَعَهُ مَلَكَانِ مُوَكَّلَانِ بِهِ، فَإِذَا قَالَ: بِسْمِ اللَّهِ، قَالَا: هُدِيتَ. وَإِذَا قَالَ: لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، قَالَا: وُقِيتَ. وَإِذَا قَالَ: تَوَكَّلْتُ عَلَى اللَّهِ، قَالَا: كُفِيتَ. قَالَ: فَيَلْقَاهُ قَرِينَاهُ فَيَقُولَانِ: مَاذَا تُرِيدَانِ مِنْ رَجُلٍ قَدْ هُدِيَ وَكُفِيَ وَوُقِيَ". [ز: في سنده ضعيف] (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "ഒരാൾ തന്റെ വീടിന്റെ വാതിലിൽ നിന്ന് പുറത്തിറങ്ങിയാൽ അവനെയേൽപ്പിക്കപ്പെട്ട രണ്ട് മലക്കുകൾ അവന്റെ കൂടെയുണ്ടാകും. അങ്ങനെ, ബിസ്മില്ലാഹി (അല്ലാഹുവിന്റെ നാമം കൊണ്ട്) എന്നവൻ പറഞ്ഞാൽ മലക്കുകൾ പറയും: നീ സൻമാർഗത്തിലാക്കപ്പെട്ടു. ഇനിയവൻ ലാഹൗല വലാഖുവ്വത ഇല്ലാബില്ലാഹി(ഒരു ശക്തിയോ, കഴിവോ അല്ലാഹുവിനെക്കൊണ്ടല്ലാതെ ഇല്ല) എന്ന് പറഞ്ഞാൽ അവർ പറയും. നീ സംരക്ഷിക്കപ്പെട്ടു. ഇനിയവൻ തവക്കൽതു അലല്ലാഹ് (ഞാൻ അല്ലാഹുവിന്റെ മേൽ ഭരമേൽപ്പിച്ചു) എന്ന് പറഞ്ഞാൽ അവർ പറയും: നിനക്കത് മതി. നിവേദകൻ പറയുന്നു: അങ്ങനെ അവന്റെ കാര്യം ഏൽപിക്കപ്പെട്ട രണ്ട് പിശാചുക്കൾ അവനെ കണ്ടുമുട്ടും. അപ്പോൾ മലക്കുകൾ അവരോട് ഇപ്രകാരം ചോദിക്കും: സംരക്ഷിക്കപ്പെടുകയും നേർവഴിയിലാക്കപ്പെടുകയും മതിയാക്കപ്പെടുകയും ചെയ്ത ഒരു വ്യക്തിയിൽനിന്ന് എന്താണ് നിങ്ങൾ ഉദ്ദേശിക്കുന്നത്?." (പരമ്പരയിൽ ബലഹീനതയുണ്ട്.) (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', null, 946, 946, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 192, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَادَهُ، أَوْ أَنَّ أَبَا ذَرٍّ عَادَ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: بِأَبِي أَنْتَ وَأُمِّي يَا رَسُولَ اللَّهِ، أَيُّ الْكَلَامِ أَحَبُّ إِلَى اللَّهِ؟ فَقَالَ: "مَا اصْطَفَاهُ اللَّهُ لِمَلَائِكَتِهِ: سُبْحَانَ رَبِّي وَبِحَمْدِهِ، سُبْحَانَ رَبِّي وَبِحَمْدِهِ". حَسَنٌ صَحِيحٌ. (م,ت)', 'അബൂദർറ്(റ): റസൂൽ(സ) അദ്ദേഹത്തെ സന്ദർശിച്ചു. അല്ലെങ്കിൽ അബൂദർറ് റസൂൽ(സ)യെ സന്ദർശിച്ചു. എന്നിട്ട് ചോദിച്ചു: അല്ലാഹുവിന്റെ തിരുദൂതരെ, എന്റെ ഉപ്പയും ഉമ്മയും അങ്ങേക്ക് ദണ്ണമാണ്. അല്ലാഹുവിന് ഏറ്റവും ഇഷ്ടപ്പെട്ട വചനം ഏതാണ്? റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു തന്റെ മലക്കുകൾക്ക് വേണ്ടി തെരഞ്ഞെടുത്ത ''സുബ്ഹാന റബ്ബീ വബിഹംദിഹി, സുബ്ഹാന റബ്ബീ വബിഹംദിഹി'' (എന്റെ രക്ഷിതാവ് എത്ര പരിശുദ്ധനാകുന്നു. അവനാണ് സർവ്വ സ്തുതിയും. എന്റെ രക്ഷിതാവ് എത്ര പരിശുദ്ധനാകുന്നു. അവനാണ് സർവ്വ സ്തുതിയും.) എന്നതാണത്." (മു,തു)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 946, 947, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 193, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَلَا أُنَبِّئُكُمْ بِخَيْرِ أَعْمَالِكُمْ، وَأَزْكَاهَا عِنْدَ مَلِيكِكُمْ، وَأَرْفَعِهَا فِي دَرَجَاتِكُمْ، وَخَيْرٍ لَكُمْ مِنْ إِنْفَاقِ الذَّهَبِ وَالْوَرِقِ، وَخَيْرٍ لَكُمْ مِنْ أَنْ تَلْقَوْا عَدُوَّكُمْ فَتَضْرِبُوا أَعْنَاقَهُمْ وَيَضْرِبُوا أَعْنَاقَكُمْ". قَالُوا: بَلَى، قَالَ: "ذِكْرُ اللهِ". (ت,جه)', 'അബൂദ്ദർദാഅ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ പ്രവർത്തനങ്ങളിൽ നിന്ന് ഏറ്റവും ശ്രേഷ്ഠവും, നിങ്ങളുടെ യജമാനന്റെയടുക്കൽ ഏറ്റവും പരിശുദ്ധവും, നിങ്ങളുടെ സ്ഥാനങ്ങളിൽ ഏറ്റവും ഉയർന്നതും സ്വർണ്ണവും വെള്ളിയും നൽകുന്നതിനേക്കാൾ നിങ്ങൾക്ക് ഏറ്റവും ഉത്തമവും, നിങ്ങളുടെ ശത്രുവുമായി പരസ്പരം യുദ്ധം ചെയ്യുന്നതിനേക്കാൾ നിങ്ങൾക്ക് ശ്രേഷ്ഠവുമായതിനെക്കുറിച്ച് നിങ്ങളെ ഞാൻ അറിയിക്കട്ടെയോ?" അവർ പറഞ്ഞു: അതെ. തിരുമേനി(സ) പറഞ്ഞു: "അല്ലാഹുവിനെ സ്മരിക്കലാകുന്നു." (തു,ജ)', 'أَبِي الدَّرْدَاءِ', 'അബൂദ്ദർദാഅ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 947, 947, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 194, 'عَنْ أَبِي هُرَيْرَةَ وَأَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُمَا شَهِدَا عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "مَا مِنْ قَوْمٍ يَذْكُرُونَ اللهَ إِلَّا حَفَّتْ بِهِمُ الْمَلَائِكَةُ، وَغَشِيَتْهُمُ الرَّحْمَةُ، وَنَزَلَتْ عَلَيْهِمُ السَّكِينَةُ، وَذَكَرَهُمُ اللهُ فِيمَنْ عِنْدَهُ". حَسَنٌ صَحِيحٌ. (م,ت,جه)', 'അബൂഹുറൈറ, അബൂസഈദുൽ ഖുദ്‌രിയ്യ്(റ): ഇവർ രണ്ട് പേരും നബി(സ) തങ്ങൾ ഇങ്ങനെ പറയുന്നതായി സാക്ഷ്യം വഹിച്ചു: "അല്ലാഹുവിനെ സ്മരിക്കുന്ന ഒരു കൂട്ടം ആളുകൾ ഉണ്ടാകുകയില്ല; അവർക്കു ചുറ്റും മലക്കുകൾ കൂടുകയും അവരെ അല്ലാഹുവിന്റെ കാരുണ്യം പൊതിയുകയും, അവർക്ക് ശാന്തി ഇറങ്ങുകയും അല്ലാഹു അവന്റെയടുത്തുള്ളവരുടെ കൂടെ അവരെ സ്മരിക്കുകയും ചെയ്തിട്ടല്ലാതെ." (മു,തു,ജ)', 'أَبِي هُرَيْرَةَ وَأَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂഹുറൈറ, അബൂസഈദുൽ ഖുദ്‌രിയ്യ്(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 947, 947, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 195, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجَ مُعَاوِيَةُ رَضِيَ اللهُ عَنْهُ إِلَى الْمَسْجِدِ، فَقَالَ: مَا يُجْلِسُكُمْ؟ قَالُوا: جَلَسْنَا نَذْكُرُ اللهَ، قَالَ: آللهِ مَا أَجْلَسَكُمْ إِلَّا ذَاكَ؟ قَالُوا: وَاللهِ مَا أَجْلَسَنَا إِلَّا ذَاكَ. قَالَ: أَمَا إِنِّي لَمْ أَسْتَحْلِفْكُمْ تُهْمَةً لَكُمْ، وَمَا كَانَ أَحَدٌ بِمَنْزِلَتِي مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَقَلَّ حَدِيثًا عَنْهُ مِنِّي، إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَرَجَ عَلَى حَلْقَةٍ مِنْ أَصْحَابِهِ، فَقَالَ: "مَا يُجْلِسُكُمْ". قَالُوا: جَلَسْنَا نَذْكُرُ اللهَ وَنَحْمَدُهُ لِمَا هَدَانَا لِلْإِسْلَامِ، وَمَنَّ عَلَيْنَا بِهِ. فَقَالَ: "آللهِ مَا أَجْلَسَكُمْ إِلَّا ذَاكَ". قَالُوا: آللهِ مَا أَجْلَسَنَا إِلَّا ذَاكَ. قَالَ: "أَمَا إِنِّي لَمْ أَسْتَحْلِفْكُمْ لِتُهْمَةٍ لَكُمْ، إِنَّهُ أَتَانِي جِبْرِيلُ فَأَخْبَرَنِي أَنَّ اللهَ يُبَاهِي بِكُمُ الْمَلَائِكَةَ". حَسَنٌ. (م,ت,ن)', 'അബൂസഈദുൽ ഖുദ്‌രിയ്യ്(റ): മുആവിയ(റ) പള്ളിയിലേക്ക് പുറപ്പെട്ടു. അപ്പോൾ അദ്ദേഹം ചോദിച്ചു: ഇവിടെയിരിക്കാൻ നിങ്ങളെ പ്രേരിപ്പിച്ച ഘടകമെന്താണ്?. അവർ പറഞ്ഞു: അല്ലാഹുവിനെ സ്മരിക്കാനാണ് ഞങ്ങൾ ഇരുന്നത്. അദ്ദേഹം ചോദിച്ചു: സത്യമായും നിങ്ങൾ അതിന് വേണ്ടി തന്നെയാണോ ഇരുന്നത്? അവർ പറഞ്ഞു: അല്ലാഹു തന്നെ സത്യം, ഞങ്ങൾ അതിന് വേണ്ടി തന്നെയാണ് ഇരുന്നത്. അദ്ദേഹം പറഞ്ഞു: ഞാൻ നിങ്ങളെ സത്യം ചെയ്യിക്കുന്നത്, നിങ്ങളെ തെറ്റിദ്ധരിച്ചത് കൊണ്ടല്ല.. നബി(സ)യുടെ അടുക്കൽ ഇത്ര സ്ഥാനം ഉണ്ടായിട്ടും എന്നേക്കാൾ കുറവായി ഹദീസ് പറഞ്ഞവരായി ആരുമുണ്ടായില്ല. തീർച്ചയായും റസൂൽ(സ) അവിടുത്തെ അനുചരൻമാരുടെ കൂട്ടത്തിലേക്ക് പോയപ്പോൾ അവരോട് ചോദിച്ചു: ഇവിടെയിരിക്കാൻ നിങ്ങളെ പ്രേരിപ്പിച്ച ഘടകമെന്താണ്?. അവർ പറഞ്ഞു: ഞങ്ങളെ ഇസ്‌ലാമിലേക്ക് മാർഗദർശനം ചെയ്യുകയും അത് കൊണ്ട് ഞങ്ങളെ അനുഗ്രഹിക്കുകയും ചെയ്ത അല്ലാഹുവിനെ സ്മരിക്കാനും സ്തുതിക്കാനും വേണ്ടിയാണ്. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "സത്യമായും അത് തന്നെയാണോ നിങ്ങളെ ഇരുത്തിയത്." അവർ പറഞ്ഞു: അല്ലാഹുവിനെ തന്നെയാണ് സത്യം, അതിന് വേണ്ടിതന്നെയാണ് ഞങ്ങൾ ഇരുന്നിട്ടുള്ളത്. നബി(സ) പറഞ്ഞു: "ഞാൻ നിങ്ങളെ സത്യം ചെയ്യിക്കുന്നത്, നിങ്ങളെ തെറ്റിദ്ധരിച്ചത് കൊണ്ടല്ല. എന്റെയടുക്കൽ ജിബ്‌രീൽ(അ) വന്നുപറഞ്ഞു: നിശ്ചയം അല്ലാഹു നിങ്ങളെക്കൊണ്ട് മലക്കുകളോട് പ്രൗഢി നടിക്കുന്നു." (മു,തു,ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്‌രിയ്യ്(റ)', null, null, array['م','ت','ن']::text[], array['മു','തു','ന']::text[], null, null, 947, 948, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 196, 'عَنْ أَبِي هُرَيْرَةَ وَابْنِ سَعِيدٍ رَضِيَ اللهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا جَلَسَ قَوْمٌ مَجْلِسًا لَمْ يَذْكُرُوا اللَّهَ فِيهِ، وَلَمْ يُصَلُّوا عَلَى نَبِيِّهِمْ، إِلَّا كَانَ عَلَيْهِمْ تِرَةً، فَإِنْ شَاءَ عَذَّبَهُمْ وَإِنْ شَاءَ غَفَرَ لَهُمْ". حَسَنٌ صَحِيحٌ. (د,ت)', 'അബൂഹുറൈറ, ഇബ്നു സഈദ്(റ): നബി(സ) പറഞ്ഞു: അല്ലാഹുവിനെ സ്മരിക്കാതെയും തങ്ങളുടെ നബിയുടെ പേരിൽ സ്വലാത്ത് ചൊല്ലാതെയും സമ്മേളിച്ച ഏതൊരു കൂട്ടത്തിനും ഖേദവും ദുഃഖവും ഉണ്ടാവാതിരിക്കില്ല. അല്ലാഹു ഉദ്ദേശിക്കുകയാണെങ്കിൽ അവരെ ശിക്ഷിക്കും, അവൻ ഉദ്ദേശിക്കുകയാണെങ്കിൽ അവർക്ക് പൊറുത്ത് കൊടുക്കുകയും ചെയ്യും." (ദ,തു)', 'أَبِي هُرَيْرَةَ وَابْنِ سَعِيدٍ', 'അബൂഹുറൈറ, ഇബ്നു സഈദ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 948, 948, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 197, 'عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا قَامَ إِلَى الصَّلَاةِ مِنْ جَوْفِ اللَّيْلِ يَقُولُ: "اللَّهُمَّ لَكَ الحَمْدُ أَنْتَ نُورُ السَّمَوَاتِ وَالأَرْضِ، وَلَكَ الْحَمْدُ أَنْتَ قَيَّامُ السَّمَوَاتِ وَالْأَرْضِ، وَلَكَ الْحَمْدُ أَنْتَ رَبُّ السَّمَوَاتِ وَالأَرْضِ وَمَنْ فِيهِنَّ. أَنْتَ الحَقُّ، وَوَعْدُكَ الحَقُّ، وَلِقَاؤُكَ حَقٌّ، وَالجَنَّةُ حَقٌّ، وَالنَّارُ حَقٌّ، وَالسَّاعَةُ حَقٌّ. اللَّهُمَّ لَكَ أَسْلَمْتُ، وَبِكَ آمَنْتُ، وَعَلَيْكَ تَوَكَّلْتُ، وَإِلَيْكَ أَنَبْتُ، وَبِكَ خَاصَمْتُ، وَإِلَيْكَ حَاكَمْتُ. فَاغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ. أَنْتَ إِلَهِي، لَا إِلَهَ إِلَّا أَنْتَ". حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): റസൂൽ(സ) അർദ്ധരാത്രിയിൽ നിസ്കരിക്കാൻ എണീറ്റാൽ പറയുമായിരുന്നു: "അല്ലാഹുവേ, നിനക്കാണ് സർവ്വ സ്തുതിയും, നീ ആകാശഭൂമികളുടെ പ്രകാശമാകുന്നു, നിനക്കാണ് സ്തുതി. നീ ആകാശ ഭൂമികളെ നിയന്ത്രിക്കുന്നവനാണ്, നിനക്കാണ് സർവ്വസ്തുതികളും. നീ ആകാശ ഭൂമികളുടെയും അതിലുള്ളവരുടെയും രക്ഷിതാവാകുന്നു. നീയാണ് സത്യം, നിന്റെ വാഗ്ദാനവും സത്യമാണ്. നിന്റെ തിരുമുൾക്കാഴ്ചയും സത്യമാണ്. സ്വർഗ്ഗവും സത്യമാണ്. നരകവും സത്യമാണ്. അന്ത്യദിനവും സത്യമാണ്. അല്ലാഹുവേ നിനക്ക് ഞാൻ കീഴ്പെട്ടു. നിന്നിൽ ഞാൻ വിശ്വസിച്ചു. നിന്നിൽ ഞാൻ ഭരമേൽപ്പിച്ചു. നിന്നിലേക്ക് ഞാൻ ഖേദിച്ചു മടങ്ങി. നിന്റെ കാര്യത്തിൽ ഞാൻ തർക്കിച്ചു. നിന്നിലേക്ക് ഞാൻ വിധിയെ ഏൽപ്പിച്ചു. അത് കൊണ്ട് റബ്ബേ, ഞാൻ മുമ്പ് ചെയ്തതും ശേഷം ചെയ്യുന്നതും, ഞാൻ രഹസ്യമാക്കിയതും പരസ്യമാക്കിയതും എനിക്ക് പൊറുത്ത് തരേണമേ. നീ എന്റെ ആരാധ്യനാകുന്നു. നീയല്ലാതെ ഒരാരാധ്യനുമില്ല." (ബു,മു,ദ,തു,ന,ജ)', 'عَبْدِ اللَّهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 948, 949, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 198, 'عَنْ أَبِي سَعِيدٍ وَأَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُمَا شَهِدَا عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "مَنْ قَالَ: لَا إِلَهَ إِلَّا اللهُ وَاللهُ أَكْبَرُ، صَدَّقَهُ رَبُّهُ فَقَالَ: لَا إِلَهَ إِلَّا أَنَا وَأَنَا أَكْبَرُ. وَإِذَا قَالَ: لَا إِلَهَ إِلَّا اللهُ وَحْدَهُ، قَالَ: يَقُولُ اللهُ: لَا إِلَهَ إِلَّا أَنَا وَحْدِي. وَإِذَا قَالَ: لَا إِلَهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ، قَالَ اللهُ: لَا إِلَهَ إِلَّا أَنَا وَحْدِي لَا شَرِيكَ لِي. وَإِذَا قَالَ: لَا إِلَهَ إِلَّا اللهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، قَالَ اللهُ: لَا إِلَهَ إِلَّا أَنَا لِيَ الْمُلْكُ وَلِيَ الْحَمْدُ. وَإِذَا قَالَ: لَا إِلَهَ إِلَّا اللهُ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، قَالَ: لَا إِلَهَ إِلَّا أَنَا وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِي". وَكَانَ يَقُولُ: "مَنْ قَالَهَا فِي مَرَضِهِ ثُمَّ مَاتَ لَمْ تَطْعَمْهُ النَّارُ". حَسَنٌ. (ت,جه)', 'അബൂസഈദ്, അബൂഹുറൈറ(റ): നബി(സ) ഇങ്ങനെ പറയുന്നതായി ഇവർ രണ്ടു പേരും സാക്ഷികളായിട്ടുണ്ട്: "ആരാധ്യൻ അല്ലാഹു മാത്രമാണ്, അല്ലാഹു വലിയവനാകുന്നു, എന്ന് ആരെങ്കിലും പറഞ്ഞാൽ അല്ലാഹു അവനെ വാസ്തവമാക്കി പറയും: ''ഞാൻ മാത്രമാണ് ആരാധ്യൻ, ഞാൻ വലിയവനാകുന്നു.'' ഇനി അവൻ: ''അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ല, അവൻ ഏകനാണ്'' എന്ന് പറഞ്ഞാൽ അവൻ (അല്ലാഹു) പറയും: ഞാൻ മാത്രമാണ് ആരാധ്യൻ, ഞാൻ ഏകനാണ്. അവൻ: ''അരാധ്യൻ അല്ലാഹു മാത്രമാണ്, അവൻ ഒരുവനാണ്, അവന് ഒരു പങ്കാളിയുമില്ല'' എന്ന് പറഞ്ഞാൽ അല്ലാഹു പറയും: ഞാൻ മാത്രമാണ് ആരാധ്യൻ, ഞാൻ ഏകനാണ്, എനിക്ക് ഒരു പങ്കാളിയുമില്ല. ഇനിയവൻ: ''അല്ലാഹു മാത്രമാണ് ആരാധ്യൻ, അവന്നാണ് സർവ്വ അധികാരങ്ങളു സർവ്വ സ്തുതിയും'' എന്ന് പറഞ്ഞാൽ അല്ലാഹു പറയും: ഞാനല്ലാതെ ആരാധ്യനില്ല, സർവ്വാധികാരവും സർവ്വ സ്തുതിയും എനിക്ക് മാത്രമുള്ളതാണ്. ഇനി അവൻ: ''അല്ലാഹു മാത്രമാണ് ആരാധ്യൻ, അല്ലാഹുവിനെ കൊണ്ടല്ലാതെ ഒരു ശക്തിയോ കഴിവോ ഇല്ല തന്നെ'' എന്ന് പറഞ്ഞാൽ അവൻ പറയും: ഞാൻ അല്ലാത്ത ഒരു ആരാധ്യനുമില്ല. എന്നെ കൊണ്ടല്ലാതെ ഒരു ശക്തിയോ ഒരു കഴിവോ ഇല്ല.'' അവിടുന്ന് പറയാറുണ്ടായിരുന്നു: "ആരെങ്കിലും തന്റെ രോഗ സമയത്ത് ഇത് പറയുകയും, പിന്നെ മരിക്കുകയും ചെയ്താൽ അവനെ നരകം രുചിക്കുകയില്ല." (തു,ജ)', 'أَبِي سَعِيدٍ وَأَبِي هُرَيْرَةَ', 'അബൂസഈദ്, അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 949, 949, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 199, 'عَنْ ابْنِ عُمَرَ، عن عمر رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ رَأَى صَاحِبَ بَلَاءٍ فَقَالَ: الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي مِمَّا ابْتَلَاكَ بِهِ، وَفَضَّلَنِي عَلَى كَثِيرٍ مِمَّنْ خَلَقَ تَفْضِيلًا. إِلَّا عُوفِيَ مِنْ ذَلِكَ الْبَلَاءِ، كَائِنًا مَا كَانَ مَا عَاشَ". (ت,جه)', 'ഉമർ(റ)വിൽനിന്ന് ഇബ്നു ഉമർ(റ): റസൂൽ(സ) പറയുന്നു: "ആരെങ്കിലും ബുദ്ധിമുട്ടുള്ളവനെ കാണുകയും നിങ്ങളുടെ ഈ പരീക്ഷണത്തിൽനിന്ന് എന്നെ സംരക്ഷിക്കുകയും സൃഷ്ടികളിൽ അധിക പേരെക്കാളും എന്നെ ശ്രേഷ്ഠനാക്കുകയും ചെയ്ത അല്ലാഹുവിനാകുന്നു സർവ്വ സ്തുതിയും എന്ന് പറയുകയും ചെയ്താൽ ജീവിക്കുന്ന കാലമത്രയും അവനെ അല്ലാഹു ആ പരീക്ഷണത്തിൽനിന്ന് സംരക്ഷിക്കും". (തു, ജ)', 'ابْنِ عُمَرَ، عن عمر', 'ഉമർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 949, 950, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 200, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ رَأَى مُبْتَلًى فَقَالَ: الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي مِمَّا ابْتَلَاكَ بِهِ، وَفَضَّلَنِي عَلَى كَثِيرٍ مِمَّنْ خَلَقَ تَفْضِيلًا، لَمْ يُصِبْهُ ذَلِكَ الْبَلَاءُ". حَسَنٌ. (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "ആരെങ്കിലും പരീക്ഷണ വിധേയനെ കാണുമ്പോൾ നീ പരീക്ഷിക്കപ്പെടുന്ന ഈ പരീക്ഷണത്തിൽ നിന്ന് എന്നെ സംരക്ഷിക്കുകയും, സൃഷ്ടി അധിക പേരേക്കാളും എന്നെ ശ്രേഷ്ഠനാക്കുകയും ചെയ്ത അല്ലാഹുവിനാണ് സർവ്വസ്തുതിയും എന്ന് പറഞ്ഞാൽ അവന് ആ പരീക്ഷണം ബാധിക്കുകയില്ല". (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 950, 950, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 201, 'عَنْ طَلْحَةَ بْنِ عُبَيْدِ اللهِ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا رَأَى الْهِلَالَ قَالَ: "اللَّهُمَّ أَهْلِلْهُ عَلَيْنَا بِالْيُمْنِ وَالْإِيمَانِ وَالسَّلَامَةِ وَالْإِسْلَامِ، رَبِّي وَرَبُّكَ اللهُ". حَسَنٌ. (ت)', 'ത്വൽഹതുബ്നു ഉബൈദില്ല(റ): റസൂൽ(സ) ചന്ദ്രക്കല കണ്ടാൽ പറയുമായിരുന്നു: "അല്ലാഹുവേ, വിജയം കൊണ്ടും വിശ്വാസം കൊണ്ടും രക്ഷ കൊണ്ടും, ഇസ്‌ലാം കൊണ്ടും അതിനെ നീ ഞങ്ങളുടെ മേൽ ഉദിപ്പിക്കേണമേ. നിന്റെയും എന്റെയും രക്ഷിതാവ് അല്ലാഹുവാകുന്നു". (തു)', 'طَلْحَةَ بْنِ عُبَيْدِ اللهِ', 'ത്വൽഹതുബ്നു ഉബൈദില്ല(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 950, 950, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 202, 'عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللهُ عَنْهُ قَالَ: اسْتَبَّ رَجُلَانِ عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَتَّى عُرِفَ الْغَضَبُ فِي وَجْهِ أَحَدِهِمَا، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي لَأَعْلَمُ كَلِمَةً لَوْ قَالَهَا لَذَهَبَ غَضَبُهُ: أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ". (د,ت,ن)', 'മുആദുബ്നു ജബൽ(റ): റസൂൽ(സ)യുടെ തിരുസന്നിധിയിൽ രണ്ടു പേർ വഴക്ക് കൂടി. അങ്ങനെ ഒരാളുടെ മുഖത്ത് ദേഷ്യം പ്രകടമായി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിശ്ചയം, എനിക്ക് ഒരു വചനം അറിയാം. അയാൾ അത് പറഞ്ഞാൽ അയാളുടെ ദേഷ്യം പോകും: അഊദു ബില്ലാഹി മിനശ്ശൈത്വാനിർറജീം (ആട്ടിയോടിക്കപ്പെട്ട പിശാചിൽ നിന്നും അല്ലാഹുവോട് ഞാൻ കാവൽ ചോദിക്കുന്നു)". (ദ,തു,ന)', 'مُعَاذِ بْنِ جَبَلٍ', 'മുആദുബ്നു ജബൽ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 950, 950, true from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 203, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِذَا رَأَى أَحَدُكُمُ الرُّؤْيَا يُحِبُّهَا فَإِنَّمَا هِيَ مِنَ اللهِ، فَلْيَحْمَدِ اللهَ عَلَيْهَا وَلْيُحَدِّثْ بِمَا رَأَى. وَإِذَا رَأَى غَيْرَ ذَلِكَ مِمَّا يَكْرَهُهُ فَإِنَّمَا هِيَ مِنَ الشَّيْطَانِ، فَلْيَسْتَعِذْ بِاللَّهِ مِنْ شَرِّهَا، وَلَا يَذْكُرْهَا لِأَحَدٍ، فَإِنَّهَا لَا تَضُرُّهُ". حَسَنٌ صَحِيحٌ. (خ,ت,جه)', 'അബൂസഈദിൽ ഖുദ്‌രീ(റ): അദ്ദേഹം റസൂൽ(സ) പറയുന്നത് കേട്ടു: "നിങ്ങളാരെങ്കിലും താൻ ഇഷ്ടപ്പെട്ട സ്വപ്നം കാണുകയാണെങ്കിൽ നിശ്ചയം അത് അല്ലാഹുവിൽ നിന്നാകുന്നു. അതിന് അവൻ അല്ലാഹുവിനെ സ്തുതിക്കുകയും, കണ്ടത് പറയുകയും ചെയ്യട്ടെ. അവൻ വെറുക്കുന്ന വല്ലതും കണ്ടാൽ നിശ്ചയം അത് പിശാചിൽ നിന്നാകുന്നു. അതിന്റെ നാശത്തിൽനിന്ന് അല്ലാഹുവോടവൻ കാവൽ ചോദിക്കട്ടെ. അതിനെക്കുറിച്ച് ആരോടും പറയുകയുമരുത്. എങ്കിലത് അവനെ ബുദ്ധിമുട്ടിക്കുകയില്ല." (ബു,തു,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്‌രീ(റ)', null, null, array['خ','ت','جه']::text[], array['ബു','തു','ജ']::text[], null, null, 950, 951, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 204, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّاسُ إِذَا رَأَوْا أَوَّلَ الثَّمَرِ جَاءُوا بِهِ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَإِذَا أَخَذَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اللَّهُمَّ بَارِكْ لَنَا فِي ثِمَارِنَا، وَبَارِكْ لَنَا فِي مَدِينَتِنَا، وَبَارِكْ لَنَا فِي صَاعِنَا وَمُدِّنَا. اللَّهُمَّ إِنَّ إِبْرَاهِيمَ عَبْدُكَ وَخَلِيلُكَ وَنَبِيُّكَ، وَإِنِّي عَبْدُكَ وَنَبِيُّكَ، وَإِنَّهُ دَعَاكَ لِمَكَّةَ وَأَنَا أَدْعُوكَ لِلْمَدِينَةِ بِمِثْلِ مَا دَعَاكَ بِهِ لِمَكَّةَ، وَمِثْلِهِ مَعَهُ". قَالَ: ثُمَّ يَدْعُو أَصْغَرَ وَلِيدٍ يَرَاهُ فَيُعْطِيهِ ذَلِكَ الثَّمَرَ. قَالَ تِرْمُذِي هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ. (م،ت،جه)', 'അബൂഹുറൈറ(റ): ജനങ്ങൾ ആദ്യത്തെ ഫലം കായ്ക്കുന്നത് കണ്ടാൽ അതുമായി റസൂൽ(സ)യുടെ സന്നിധിയിലേക്ക് വരുമായിരുന്നു. അങ്ങനെ തിരുമേനി(സ) അത് സ്വീകരിച്ചാൽ ഇപ്രകാരം പറയുമായിരുന്നു: "അല്ലാഹുവേ, ഞങ്ങളുടെ ഫലങ്ങളിൽ ഞങ്ങൾക്ക് നീ ബറകത് നൽകേണമേ. ഞങ്ങളുടെ മുദ്ദിലും സ്വാഇലും (അളവുകൾ) ഞങ്ങൾക്ക് ബറകത് നൽകേണമേ. ഞങ്ങളുടെ മദീനയിൽ നീ ഞങ്ങൾക്ക് ബറകത് നൽകേണമേ. അല്ലാഹുവേ, നിശ്ചയം ഇബ്രാഹീം(അ) നിന്റെ അടിമയും നിന്റെ സുഹൃത്തും നിന്റെ പ്രവാചകനുമാണ്. ഞാൻ നിന്റെ അടിമയും പ്രവാചകനുമാണ്. ഇബ്‌റാഹീം(അ) മക്കക്ക് വേണ്ടി നിന്നോട് പ്രാർത്ഥിച്ചു. ഞാൻ മദീനക്ക് വേണ്ടിയും (അവർ മക്കക്ക് വേണ്ടി ദുആ ചെയ്ത പോലെ) പ്രാർത്ഥിക്കുന്നു. ഇബ്‌റാഹീം നബി(അ) മക്കഃക്ക് വേണ്ടി പ്രാർത്ഥിച്ചത് പോലോത്തത് കൊണ്ട് മദീനക്ക് വേണ്ടി അതിന്റെ ഇരട്ടി നിന്നോട് ഞാൻ ചോദിക്കുന്നു." നിവേദകൻ പറയുന്നു. പിന്നെ തിരുമേനി(സ) ഒരു ചെറിയ കുട്ടിയെ വിളിക്കുകയും ആ പഴം അവന് നൽകുകയും ചെയ്തിരുന്നു. (മു,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 951, 951, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 205, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: دَخَلْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَا وَخَالِدُ بْنُ الْوَلِيدِ عَلَى مَيْمُونَةَ، فَجَاءَتْنَا بِإِنَاءٍ فِيهِ لَبَنٌ، فَشَرِبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَنَا عَلَى يَمِينِهِ وَخَالِدٌ عَلَى شِمَالِهِ، فَقَالَ لِي: "الشَّرْبَةُ لَكَ، فَإِنْ شِئْتَ آثَرْتَ بِهَا خَالِدًا". فَقُلْتُ: مَا كُنْتُ أُوثِرُ عَلَى سُؤْرِكَ أَحَدًا. ثُمَّ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَطْعَمَهُ اللهُ الطَّعَامَ فَلْيَقُلِ: اللَّهُمَّ بَارِكْ لَنَا فِيهِ، وَأَطْعِمْنَا خَيْرًا مِنْهُ. وَمَنْ سَقَاهُ اللَّهُ لَبَنًا فَلْيَقُلِ: اللَّهُمَّ بَارِكْ لَنَا فِيهِ وَزِدْنَا مِنْهُ". وَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَيْسَ شَيْءٌ يُجْزِئُ مَكَانَ الطَّعَامِ وَالشَّرَابِ غَيْرُ اللَّبَنِ". حَسَنٌ. (د،ت،جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഞാനും ഖാലിദുബ്നു വലീദ്(റ)വും റസൂൽ(സ)യുടെ കൂടെ മൈമൂന(റ)യുടെ അടുത്ത് പോയി. അപ്പോൾ മഹതി ഒരു പാത്രം പാൽ കൊണ്ടുവന്നു. അങ്ങനെ റസൂൽ(സ) കുടിച്ചു. ഞാൻ അവിടുത്തെ വലതുഭാഗത്തും ഖാലിദ്(റ) അവിടുത്തെ ഇടത് ഭാഗത്തുമായിരുന്നു. അപ്പോൾ നബി(സ) എന്നോട് പറഞ്ഞു: "കുടി നിനക്കുള്ളതാണ്. നീ ഉദ്ദേശിക്കുകയാണെങ്കിൽ ഖാലിദിനെ തെരെഞ്ഞെടുക്കാം." ഞാൻ പറഞ്ഞു: അവിടുന്ന് കുടിച്ച വെള്ളത്തിന്റെ ശേഷിപ്പിന് വേണ്ടി ഞാൻ വേറെ ആരെയും തെരെഞ്ഞെടുക്കാറില്ല. പിന്നെ റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു ആരെയെങ്കിലും ഭക്ഷിപ്പിച്ചാൽ അവൻ ഇപ്രകാരം പറയട്ടെ: അല്ലാഹുവേ, ഞങ്ങൾക്കതിൽ നീ ബറകത് ചെയ്യേണമേ, അതിനേക്കാൾ നല്ലത് ഞങ്ങളെ നീ ഭക്ഷിപ്പിക്കുകയും ചെയ്യേണമേ. ഇനി ആരെയെങ്കിലും അല്ലാഹു പാൽ കുടിപ്പിച്ചാൽ അവൻ പറയട്ടെ: അല്ലാഹുവേ ഞങ്ങൾക്ക് അതിൽ നീ ബറകത് ചെയ്യേണമേ. അതിനേക്കാൾ അധികരിപ്പിക്കുകയും ചെയ്യേണമേ." റസൂൽ(സ) പറഞ്ഞു: "ഭക്ഷണത്തിന്റെയും വെള്ളത്തിന്റെയും പകരമായി മതിയാകുന്നത് പാൽ മാത്രമാണ്." (ദ,തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 951, 952, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 206, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا رُفِعَتِ الْمَائِدَةُ مِنْ بَيْنِ يَدَيْهِ يَقُولُ: "الْحَمْدُ لِلَّهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ، غَيْرَ مُوَدَّعٍ وَلَا مُسْتَغْنًى عَنْهُ رَبَّنَا". حَسَنٌ صَحِيحٌ. (خ,د,ت,ن,جه)', 'അബൂ ഉമാമ(റ): തന്റെ മുന്നിൽനിന്ന് സുപ്ര എടുക്കപ്പെട്ടാൽ റസൂൽ(സ) പറയുമായിരുന്നു: "നമ്മുടെ രക്ഷിതാവിന് ആവശ്യമുള്ളതും അവൻ തിരസ്കരിക്കാത്തതുമായ പവിത്രമാക്കപ്പെട്ട ധാരാളം നല്ല സ്തുതികളാൽ ഞാൻ അല്ലാഹുവിനെ സ്തുതിക്കുന്നു." (ബു,ദ,തു,ന,ജ)', 'أَبِي أُمَامَةَ', 'അബൂ ഉമാമ(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 952, 952, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 207, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا أَكَلَ أَوْ شَرِبَ قَالَ: "الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا وَجَعَلَنَا مُسْلِمِينَ". (د,ت)', 'അബൂസഈദ്(റ): നബി(സ) കുടിക്കുകയോ കഴിക്കുകയോ ചെയ്താൽ പറയുമായിരുന്നു: " അൽഹംദു ലില്ലാഹില്ലദീ അഥ്അമനാ വസഖാനാ വജഅലനാ മുസ്ലിമീൻ (ഞങ്ങളെ ഭക്ഷിപ്പിക്കുകയും കുടിപ്പിക്കുകയും മുസ്ലിംകളാക്കുകയും ചെയ്ത അല്ലാഹുവിനാകുന്നു സർവ്വ സ്തുതിയും)." (ദ,തു)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 952, 952, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 208, 'عَنْ مُعَاذِ بْنِ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَكَلَ طَعَامًا فَقَالَ: الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ، غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ". حَسَنٌ. (د,ت)', 'മുആദ് ബിൻ അനസ്(റ): റസൂൽ(സ) പറയുന്നു: "ആരെങ്കിലും ഭക്ഷണം കഴിച്ച് കഴിഞ്ഞാൽ ''അൽഹംദു ലില്ലാഹില്ലദീ അഥ്അമനീ ഹാദാ വരസഖനീഹി മിൻഗൈരി ഹൗലിൻ മിന്നീ വലാഖുവ്വ'' (എന്റെ കഴിവോ ശക്തിയോ ഇല്ലാതെ, എനിക്കിത് നൽകുകയും ഭക്ഷിപ്പിക്കുകയും ചെയ്ത അല്ലാഹുവിനാണ് സർവ്വ സ്തുതിയും) എന്ന് പറഞ്ഞാൽ അവന്റെ മുൻകഴിഞ്ഞ ദോഷങ്ങൾ പൊറുക്കപ്പെടും." (ദ,തു)', 'مُعَاذِ بْنِ أَنَسٍ', 'മുആദ് ബിൻ അനസ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 952, 952, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 209, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا سَمِعْتُمْ صِيَاحَ الدِّيَكَةِ فَاسْأَلُوا اللهَ مِنْ فَضْلِهِ، فَإِنَّهَا رَأَتْ مَلَكًا. وَإِذَا سَمِعْتُمْ نَهِيقَ الْحِمَارِ فَتَعَوَّذُوا بِاللَّهِ مِنَ الشَّيْطَانِ، فَإِنَّهُ رَأَى شَيْطَانًا". حَسَنٌ صَحِيحٌ. (ق,د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "നിങ്ങൾ കോഴി കൂവുന്നത് കേട്ടാൽ അല്ലാഹുവിനോട് അവന്റെ ഔദാര്യത്തെ ചോദിക്കുക. കാരണം കോഴി (കൂവുന്നത്) ഒരു മലക്കിനെ കണ്ടത് കൊണ്ടാണ്. ഇനി നിങ്ങൾ കഴുതയുടെ ശബ്ദം കേൾക്കുകയാണെങ്കിൽ നിങ്ങൾ അല്ലാഹുവിനോട് പിശാചിൽ നിന്നും കാവൽ ചോദിക്കുക, കാരണം അത് പിശാചിനെ കണ്ടിട്ടുണ്ട്." (ബു,മു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 952, 952, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 210, 'عَنْ عَبْدِ اللَّهِ بن مسعود رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَدْعُو: "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى". حَسَنٌ صَحِيحٌ. (م،ت،جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) ദുആ ചെയ്യാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ, നേർമാർഗവും ഭയഭക്തിയും സദാചാരവും ഐശ്വര്യവും നിന്നോട് ഞാൻ ചോദിക്കുന്നു." (മു,തു,ജ)', 'عَبْدِ اللَّهِ بن مسعود', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 953, 953, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 211, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "كَانَ مِنْ دُعَاءِ دَاوُدَ يَقُولُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ حُبَّكَ، وَحُبَّ مَنْ يُحِبُّكَ، وَالْعَمَلَ الَّذِي يُبَلِّغُنِي حُبَّكَ. اللَّهُمَّ اجْعَلْ حُبَّكَ أَحَبَّ إِلَيَّ مِنْ نَفْسِي وَأَهْلِي، وَمِنَ الْمَاءِ الْبَارِدِ". قَالَ: وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا ذَكَرَ دَاوُدَ يُحَدِّثُ عَنْهُ قَالَ: "كَانَ أَعْبَدَ الْبَشَرِ". حَسَنٌ . (ت)', 'അബുദ്ദർദാഅ്(റ): റസൂൽ(സ) പറയുന്നു: "ദാവൂദ്(അ)ന്റെ ദുആയിൽ അവർ പറയാറുണ്ടായിരുന്നു: അല്ലാഹുവേ, നിന്നോടുള്ള സ്നേഹവും നിന്നെ സ്നേഹിക്കുന്നവരോടുള്ള സ്നേഹവും നിന്റെ സ്നേഹത്തിലേക്ക് എന്നെയെത്തിക്കുന്ന പ്രവർത്തനങ്ങളോടുള്ള സ്നേഹവും ചോദിക്കുന്നു. അല്ലാഹുവേ നിന്നോടുള്ള സ്നേഹത്തെ എന്റെ ശരീരത്തേക്കാളും എന്റെ കുടുംബത്തേക്കാളും തണുത്ത വെള്ളത്തേക്കാളും എനിക്ക് ഏറ്റവും ഇഷ്ടപ്പെട്ടതാക്കേണമേ. ദാവൂദ്(അ)നെ സ്മരിക്കുമ്പോൾ അവിടുന്ന് പറയുമായിരുന്നു. അവർ മനുഷ്യരിൽ വെച്ചേറ്റവും ഇബാദത്ത് ചെയ്യുന്നവർ (ഏറ്റവും നല്ല അടിമ) ആയിരുന്നു. (തു)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഅ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 953, 953, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 212, 'عَنْ سَعْدِ بن أبي وقاص رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "دَعْوَةُ ذِي النُّونِ إِذْ دَعَا وَهُوَ فِي بَطْنِ الْحُوتِ: {لَّا إِلَهَ إِلَّا أَنتَ سُبْحَانَكَ إِنِّي كُنتُ مِنَ الظَّالِمِينَ} [الأنبياء: ٨٧] فَإِنَّهُ لَمْ يَدْعُ بِهَا رَجُلٌ مُسْلِمٌ فِي شَيْءٍ قَطُّ إِلَّا اسْتَجَابَ اللَّهُ لَهُ". (ت)', 'സഅ്ദുബ്നു അബീ വഖാസ്(റ): റസൂൽ(സ) പറയുന്നു: "മത്സ്യത്തിന്റെ വയറ്റിലായിരുന്നപ്പോൾ യൂനുസ് നബി(അ) പ്രാർത്ഥിച്ച ദുആ: ''നീ മാത്രമാണ് ആരാധ്യൻ, നീ എത്ര പരിശുദ്ധനാകുന്നു. തീർച്ചയായും ഞാൻ അക്രമികളിൽ പെട്ടവനാകുന്നു.'' (അമ്പിയാഅ്: 87). ഈ ദുആ കൊണ്ട് എന്തൊരാവശ്യത്തിന്വേണ്ടി പ്രാർത്ഥിക്കുന്ന ഏതൊരാൾക്കും അല്ലാഹു ഉത്തരം ചെയ്യാതിരിക്കില്ല. " (തു)', 'سَعْدِ بن أبي وقاص', 'സഅ്ദുബ്നു അബീ വഖാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], 'الأنبياء: ٨٧', null, 953, 953, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 213, 'عَنْ عَائِشَةَ و عَنْ أَبِي بَكْرِ الصِّدِّيقِ رَضِيَ اللَّهُ عَنْهُمَا، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا أَرَادَ أَمْرًا قَالَ: "اللَّهُمَّ خِرْ لِي". (ت)', 'അബൂബക്കർ സിദ്ദീഖ്(റ), ആഇശ(റ): റസൂൽ (സ) ഒരു കാര്യം ഉദ്ദേശിച്ചാൽ പറയുമായിരുന്നു: "അല്ലാഹുവേ, എനിക്ക് നീ ഗുണം നൽകേണമേ." (തു)', 'عَائِشَةَ و عَنْ أَبِي بَكْرِ الصِّدِّيقِ', 'അബൂബക്കർ സിദ്ദീഖ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 953, 953, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 214, 'عَنْ أَبِي مَالِكِ الْأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْوُضُوءُ شَطْرُ الْإِيمَانِ، وَالْحَمْدُ لِلَّهِ تَمْلَأُ الْمِيزَانَ، وَسُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ تَمْلَآنِ - أَوْ: تَمْلَأُ - مَا بَيْنَ السَّمَوَاتِ وَالْأَرْضِ، وَالصَّلَاةُ نُورٌ، وَالصَّدَقَةُ بُرْهَانٌ، وَالصَّبْرُ ضِيَاءٌ، وَالْقُرْآنُ حُجَّةٌ لَكَ أَوْ عَلَيْكَ. كُلُّ النَّاسِ يَغْدُو، فَبَائِعٌ نَفْسَهُ: فَمُعْتِقُهَا أَوْ مُوبِقُهَا". حَسَنٌ صَحِيحٌ. (م،ت،ن،جه)', 'അബൂമാലികിൽ അശ്അരിയ്യ്(റ): റസൂൽ(സ) പറയുന്നു: "വുളൂഅ് വിശ്വാസത്തിന്റെ പകുതിയാകുന്നു. അൽഹംദുലില്ലാഹി (സർവ്വസ്തുതിയും അല്ലാഹുവിനാകുന്നു) തുലാസിനെ നിറക്കുന്നതാണ്. സർവ്വ സ്തുതിയും അല്ലാഹുവിനാകുന്നു, അല്ലാഹു എത്ര പരിശുദ്ധനാകുന്നു, എന്നത് ആകാശ ഭൂമികൾക്കിടയിലുള്ളതിനെ നിറക്കുന്നതാണ്. നിസ്കാരം പ്രകാശമാണ്. ദാനം തെളിവാകുന്നു. ക്ഷമ വെളിച്ചമാകുന്നു. ഖുർആൻ നിനക്കനുകൂലമായോ പ്രതികൂലമായോ ആയ തെളിവാകുന്നു, എല്ലാ ജനങ്ങളും രാവിലെ പുറപ്പെട്ട് തങ്ങളുടെ ശരീരത്തെ വിൽക്കുന്നു, ഒന്നുകിൽ അതിനെ മോചിപ്പിക്കാൻ (അല്ലാഹുവിന് വിൽക്കുന്നു) അല്ലെങ്കിൽ അതിനെ നശിപ്പിക്കാൻ (പിശാചിന് വിൽക്കുന്നു)." (മു,തു,ന,ജ)', 'أَبِي مَالِكِ الْأَشْعَرِيِّ', 'അബൂമാലികിൽ അശ്അരിയ്യ്(റ)', null, null, array['م','ت','ن','جه']::text[], array['മു','തു','ന','ജ']::text[], null, null, 954, 954, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 215, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "خَيْرُ الدُّعَاءِ دُعَاءُ يَوْمِ عَرَفَةَ، وَخَيْرُ مَا قُلْتُ أَنَا وَالنَّبِيُّونَ مِنْ قَبْلِي: لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ". حَسَنٌ. (ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "അറഫാ ദിനത്തിലെ പ്രാർത്ഥനയാണ് ഏറ്റവും ഉത്തമമായ പ്രാർത്ഥന, ഞാനും എന്റെ മുമ്പുള്ള പ്രവാചകരും പറഞ്ഞതിൽ ഏറ്റവും ഉത്തമമായത് ഇതാണ്: ''അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ല, അവൻ ഏകനും പങ്കുകാരില്ലാത്തവനുമാകുന്നു. അവനാണ് സർവ്വ സ്തുതികളും അധികാരവും. അവൻ എല്ലാറ്റിനും കഴിവുള്ളവനാണ്." (തു)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 954, 954, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 216, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَكْثَرُ مَا دَعَا بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَشِيَّةَ عَرَفَةَ فِي الْمَوْقِفِ: "اللَّهُمَّ لَكَ الْحَمْدُ كَالَّذِي نَقُولُ وَخَيْرًا مِمَّا نَقُولُ، اللَّهُمَّ لَكَ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي، وَإِلَيْكَ مَآبِي، وَلَكَ - رَبِّ - تُرَاثِي. اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَوَسْوَسَةِ الصَّدْرِ، وَشَتَاتِ الْأَمْرِ. اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا تَجِيءُ بِهِ الرِّيحُ". (ت)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): മൗഖിഫിൽ വെച്ച് അറഫാ രാത്രിയിൽ റസൂൽ(സ) അധികമായി ദുആ ചെയ്തിരുന്നത് ഇതായിരുന്നു: "അല്ലാഹുവേ ഞങ്ങൾ പറയുന്നത് പോലെയും അതിനേക്കാൾ ഉത്തമമായും നിനക്കാണ് സർവ്വ സ്തുതിയും. അല്ലാഹുവേ, എന്റെ നിസ്കാരവും, എന്റെ ആരാധനയും, എന്റെ ജീവിതവും, എന്റെ മരണവും നിനക്കുള്ളതാകുന്നു, നിന്നിലേക്കാണ് എന്റെ മടക്കം. എന്റെ രക്ഷിതാവേ, എന്റെ ശേഷമുള്ളതും നിനക്കുള്ളതാണ്. രക്ഷിതാവേ, ഖബർ ശിക്ഷയിൽ നിന്നും ഹൃദയത്തിന്റെ ദുർബോധനത്തിൽ നിന്നും, കാര്യങ്ങൾ ഛിന്നഭിന്നമാകലിൽനിന്നും നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു. കാറ്റ് കൊണ്ടു വരുന്ന എല്ലാ നാശത്തിൽ നിന്നും നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു. (തു)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 954, 955, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 217, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: دَعَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِدُعَاءٍ كَثِيرٍ لَمْ نَحْفَظْ مِنْهُ شَيْئًا. قُلْنَا: يَا رَسُولَ اللَّهِ، دَعَوْتَ بِدُعَاءٍ كَثِيرٍ لَمْ نَحْفَظْ مِنْهُ شَيْئًا؟ قَالَ: "أَلَا أَدُلُّكُمْ عَلَى مَا يَجْمَعُ ذَلِكَ كُلَّهُ؟ تَقُولُ: اللَّهُمَّ إِنَّا نَسْأَلُكَ مِنْ خَيْرِ مَا سَأَلَكَ مِنْهُ نَبِيُّكَ مُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَنَعُوذُ بِكَ مِنْ شَرِّ مَا اسْتَعَاذَ مِنْهُ نَبِيُّكَ مُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنْتَ الْمُسْتَعَانُ وَعَلَيْكَ الْبَلَاغُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ". حَسَنٌ. (ت)', 'അബൂഉമാമ(റ): ഞങ്ങൾ തീരെ മനഃപാഠമാക്കാത്ത ധാരാളം ദുആകൾ തിരുമേനി ദുആ ചെയ്തിരുന്നു. ഞങ്ങൾ പറഞ്ഞു: തിരുദൂതരെ, ഞങ്ങൾ മനഃപാഠമാക്കാത്ത ധാരാളം ദുആകൾ അങ്ങ് പ്രാർത്ഥിച്ചിട്ടുണ്ട്. നബി(സ) പറഞ്ഞു: "അതെല്ലാം ഉൾക്കൊണ്ട ഒരു ദുആ നിങ്ങൾക്ക് ഞാൻ അറിയിച്ച് തരട്ടെയോ? നിങ്ങൾ പറയുക: അല്ലാഹുവേ, നിന്റെ റസൂലായ മുഹമ്മദ്(സ) നിന്നോട് ചോദിച്ച നന്മയെ ഞങ്ങൾ നിന്നോട് ചോദിക്കുന്നു. നിന്റെ റസൂലായ മുഹമ്മദ്(സ) നിന്നോട് കാവൽ ചോദിച്ച തിന്മയിൽനിന്ന് ഞങ്ങൾ നിന്നോട് കാവൽ ചോദിക്കുന്നു. നീയാണ് സഹായി. നിന്നിലാണ് അഭയം, അല്ലാഹുവിനെക്കൊണ്ടല്ലാതെ ശക്തിയോ, കഴിവോ ഇല്ല തന്നെ." (തു)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 955, 955, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 218, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَلِظُّوا بِيَا ذَا الْجَلَالِ وَالْإِكْرَامِ". (ت)', 'അനസ്(റ): നബി(സ) പറയുന്നു: "യാദൽ ജലാലി വൽ ഇക്റാം (ഔദാര്യവും മഹത്വവുമുള്ളവനേ) എന്ന് നിങ്ങൾ പതിവാക്കുക." (തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 955, 955, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=80 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 219, 'عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلًا يَدْعُو يَقُولُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ تَمَامَ النِّعْمَةِ. فَقَالَ: "أَيُّ شَيْءٍ تَمَامُ النِّعْمَةِ؟". قَالَ: دَعْوَةٌ دَعَوْتُ بِهَا أَرْجُو بِهَا الْخَيْرَ. قَالَ: "فَإِنَّ مِنْ تَمَامِ النِّعْمَةِ دُخُولَ الْجَنَّةِ وَالْفَوْزَ مِنَ النَّارِ". وَسَمِعَ رَجُلًا وَهُوَ يَقُولُ: يَا ذَا الْجَلَالِ وَالْإِكْرَامِ. فَقَالَ: "قَدِ اسْتُجِيبَ لَكَ، فَسَلْ". وَسَمِعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلًا وَهُوَ يَقُولُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ الصَّبْرَ. قَالَ: "سَأَلْتَ اللَّهَ الْبَلَاءَ، فَسَلْهُ الْعَافِيَةَ". (ت)', 'മുആദുബ്നു ജബൽ(റ): അല്ലാഹുവേ പരിപൂർണ്ണമായ അനുഗ്രഹത്തെ നിന്നോട് ഞാൻ ചോദിക്കുന്നു, എന്ന് ദുആ ചെയ്യുന്നതായി ഒരാളെ റസൂൽ(സ) കേട്ടു. തിരുമേനി(സ) ചോദിച്ചു: "പൂർണ്ണമായ അനുഗ്രഹം ഏത് വസ്തുവാണ്?" അദ്ദേഹം പറഞ്ഞു: ഞാൻ നന്മ പ്രതീക്ഷിച്ച് പ്രാർത്ഥിച്ച ദുആയാണത്. നബി(സ) പറഞ്ഞു: "സ്വർഗ്ഗപ്രവേശനവും നരക രക്ഷയും തീർച്ചയായും പൂർണ്ണമായ അനുഗ്രഹത്തിൽ പെട്ടതാകുന്നു." ഔദാര്യവും മഹത്വവുമുള്ളവനേ എന്ന് പറയുന്ന ഒരാളെ റസൂൽ(സ) കേട്ടു. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "നിനക്ക് ഉത്തരം നൽകപ്പെടും. അത് കൊണ്ട് ചോദിക്കുക." അല്ലാഹുവേ, നിന്നോട് ഞാൻ ക്ഷമയെ ചോദിക്കുന്നു എന്ന് പറയുന്നതായി ഒരാളെ റസൂൽ(സ) കേട്ടു. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "നീ അല്ലാഹുവിനോട് പരീക്ഷണത്തെ ചോദിച്ചിരിക്കുന്നു. അത് കൊണ്ട് നീ സുഖത്തെ ചോദിക്കുക." (തു)', 'مُعَاذِ بْنِ جَبَلٍ', 'മുആദുബ്നു ജബൽ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 955, 956, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=80 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 220, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا كَرَبَهُ أَمْرٌ قَالَ: "يَا حَيُّ يَا قَيُّومُ، بِرَحْمَتِكَ أَسْتَغِيثُ". (ت)', 'അനസുബ്നുമാലിക്(റ): നബി(സ)ക്ക് വല്ല വിഷമവുമുണ്ടായാൽ "യാഹയ്യു യാഖയ്യൂം ബിറഹ്മതിക അസ്തഗീസ്" (ശാശ്വതമായി നിലനിൽക്കുന്നവനേ, ജീവിച്ചിരിക്കുന്നവനേ, നിന്റെ അനുഗ്രഹം കൊണ്ട് ഞാൻ സഹായം ചോദിക്കുന്നു) എന്ന് പറയുമായിരുന്നു. (തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 956, 956, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=81 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 221, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَقُولُ اللَّهُ تَعَالَى: أَنَا عِنْدَ ظَنِّ عَبْدِي بِي، وَأَنَا مَعَهُ حِينَ يَذْكُرُنِي، فَإِنْ ذَكَرَنِي فِي نَفْسِهِ ذَكَرْتُهُ فِي نَفْسِي، وَإِنْ ذَكَرَنِي فِي مَلَإٍ، ذَكَرْتُهُ فِي مَلَإٍ خَيْرٍ مِنْهُمْ، وَإِنِ اقْتَرَبَ إِلَيَّ شِبْرًا اقْتَرَبْتُ مِنْهُ ذِرَاعًا، وَإِنِ اقْتَرَبَ إِلَيَّ ذِرَاعًا اقْتَرَبْتُ إِلَيْهِ بَاعًا وَإِنْ أَتَانِي يَمْشِي أَتَيْتُهُ هَرْوَلَةً". حَسَنٌ صَحِيحٌ. (ق,ت,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: അല്ലാഹുതആല പറയുന്നു: എന്റെ അടിമ എന്നെക്കുറിച്ച് ഭാവിക്കുന്നിടത്താണ് ഞാൻ. അവൻ എന്നെ ഓർക്കുമ്പോൾ ഞാൻ അവനോട് കൂടെയായിരിക്കും. അവൻ ഒറ്റക്ക് എന്നെ ഓർത്താൽ ഞാനും അവനെ ഒറ്റക്ക് ഓർക്കും, ഒരു കൂട്ടത്തിൽ വെച്ചാണ് അവൻ എന്നെ ഓർക്കുന്നതെങ്കിൽ അതിനേക്കാൾ ഉത്തമമായ ഒരു കൂട്ടത്തിൽ ഞാൻ അവനെ ഓർക്കും, എന്നിലേക്ക് അവൻ ഒരു ചാൺ അടുത്താൽ ഞാൻ അവനിലേക്ക് ഒരു മുഴം അടുക്കും, അവൻ ഒരു മുഴം അടുത്താൽ രണ്ട് കൈകൾ ഇരുവശത്തേക്കും നീട്ടിയാലുള്ള അളവ് ഞാൻ അവനിലേക്ക് അടുക്കും. എന്നിലേക്ക് നടന്നുവന്നാൽ ഞാൻ അവനിലേക്ക് ഓടിയടുക്കും. (ബു,മു,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 956, 956, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 222, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ حُسْنَ الظَّنِّ بِاللَّهِ مِنْ حُسْنِ عِبَادَةِ اللَّهِ". (د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "തീർച്ചയായും അല്ലാഹുവിനെക്കുറിച്ചുള്ള നല്ല ധാരണ നല്ല ആരാധനയിൽ പെട്ടതാണ്." (ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 956, 956, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 223, 'عَنْ عَبْدِ اللَّهِ بْنِ بُسْرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَزَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى أَبِي، قَالَ: فَقَرَّبْنَا إِلَيْهِ طَعَامًا فَأَكَلَ مِنْهُ، ثُمَّ أُتِيَ بِتَمْرٍ، فَكَانَ يَأْكُلُ وَيُلْقِي النَّوَى بِإِصْبَعَيْهِ، جَمَعَ السَّبَّابَةَ وَالْوُسْطَى، وَأَلْقَى النَّوَى بَيْنَ أُصْبُعَيْنِ، ثُمَّ أُتِيَ بِشَرَابٍ فَشَرِبَهُ، ثُمَّ نَاوَلَهُ الَّذِي عَنْ يَمِينِهِ، قَالَ: فَقَالَ أَبِي، وَأَخَذَ بِلِجَامِ دَابَّتِهِ: ادْعُ لَنَا. فَقَالَ: "اللَّهُمَّ بَارِكْ لَهُمْ فِيمَا رَزَقْتَهُمْ وَاغْفِرْ لَهُمْ وَارْحَمْهُمْ". حَسَنٌ صَحِيحٌ. (م،د،ت)', 'അബ്ദുല്ലാഹിബ്നു ബുസ്ർ(റ): റസൂൽ(സ) എന്റെ ഉപ്പയുടെ അടുക്കൽ അതിഥിയായി വന്നു. നിവേദകൻ പറയുന്നു: ഞങ്ങൾ അവിടുത്തേക്ക് ഭക്ഷണം നൽകി. അവിടുന്ന് ഭക്ഷിച്ചു. പിന്നെ കാരക്ക കൊണ്ട് വന്നു, അപ്പോൾ അവിടന്ന് അത് തിന്നുകയും അതിന്റെ കുരു അവിടുത്തെ വിരലുകൾ കൊണ്ട് എടുത്ത് ചൂണ്ടു വിരലിന്റെയും നടുവിരലിന്റെയും ഇടയിൽ വെക്കുകയും ചെയ്തു. പിന്നെ വെള്ളം കൊണ്ടു വന്നു. അവിടുന്നത് കുടിച്ച് അവിടുത്തെ വലത് ഭാഗത്തുള്ളവർക്ക് കൊടുത്തു. നിവേദകൻ പറയുന്നു: എന്റെ ഉപ്പ തന്റെ മൃഗത്തിന്റെ കടിഞ്ഞാൺ പിടിച്ച് കൊണ്ട് പറഞ്ഞു: ഞങ്ങൾക്ക് വേണ്ടി ദുആ ചെയ്താലും. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "അല്ലാഹുവേ, നീ അവർക്ക് നൽകിയതിൽ ബറകത് ചെയ്യേണമേ. അവർക്ക് നീ പൊറുത്ത് കൊടുക്കുകയും കരുണ നൽകുകയും ചെയ്യേണമേ." (മു,ദ,തു)', 'عَبْدِ اللَّهِ بْنِ بُسْرٍ', 'അബ്ദുല്ലാഹിബ്നു ബുസ്ർ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 956, 957, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 224, 'عَنْ زَيْدِ بْنِ بَوْلَا - مَوْلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - رَضِيَ اللَّهُ عَنْهُ: سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ قَالَ: أَسْتَغْفِرُ اللَّهَ الْعَظِيمَ الَّذِي لَا إِلَهَ إِلَّا هُوَ الْحَيَّ الْقَيُّومَ وَأَتُوبُ إِلَيْهِ، غُفِرَ لَهُ وَإِنْ كَانَ فَرَّ مِنَ الزَّحْفِ". (د،ت)', 'നബി(സ)യുടെ അടിമയായിരുന്ന സൈദുബ്നു ബൗലാ(റ): അദ്ദേഹം റസൂൽ(സ) പറയുന്നതായി കേട്ടു: "അസ്തഗ്ഫിറുല്ലാഹൽഅളീം അല്ലദീ ലാഇലാഹ ഇല്ലാഹുവൽഹയ്യുൽഖയ്യൂം വഅതൂബു ഇലൈഹി"(കൈകാര്യകർത്താവും ജീവസ്സുറ്റവനും അവനല്ലാതെ മറ്റൊരു ആരാധ്യനില്ലാത്തവനുമായ മഹോന്നതനായ അല്ലാഹുവിനോട് ഞാൻ പൊറുക്കൽ ചോദിക്കുന്നു, അവനിലേക്ക് ഞാൻ ഖേദിച്ചു മടങ്ങുകയും ചെയ്യുന്നു) എന്നാരെങ്കിലും പറഞ്ഞാൽ അവൻ യുദ്ധത്തിൽ തിരിഞ്ഞോടിയവനായാലും അല്ലാഹു പൊറുത്ത് കൊടുക്കും." (ദ,തു)', 'زَيْدِ بْنِ بَوْلَا - مَوْلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -', 'നബി(സ)യുടെ അടിമയായിരുന്ന സൈദുബ്നു ബൗലാ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 957, 957, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 225, 'عَنْ عُثْمَانَ بْنِ حُنَيْفٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا ضَرِيرَ الْبَصَرِ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: ادْعُ اللَّهَ أَنْ يُعَافِيَنِي. قَالَ: "إِنْ شِئْتَ دَعَوْتُ، وَإِنْ شِئْتَ صَبَرْتَ فَهُوَ خَيْرٌ لَكَ". قَالَ: فَادْعُهُ. قَالَ: فَأَمَرَهُ أَنْ يَتَوَضَّأَ فَيُحْسِنَ وُضُوءَهُ وَيَدْعُوَ بِهَذَا الدُّعَاءِ: "اللَّهُمَّ إِنِّي أَسْأَلُكَ وَأَتَوَجَّهُ إِلَيْكَ بِنَبِيِّكَ مُحَمَّدٍ نَبِيِّ الرَّحْمَةِ، إِنِّي تَوَجَّهْتُ بِكَ إِلَى رَبِّي فِي حَاجَتِي هَذِهِ لِتُقْضَى لِي، اللَّهُمَّ فَشَفِّعْهُ فِيَّ". حَسَنٌ صَحِيحٌ. (ت،جه)', 'ഉസ്മാനുബ്നു ഹുനൈഫ്(റ): കണ്ണിന് കേട് പറ്റിയ ഒരാൾ റസൂൽ(സ)യുടെ തിരുസന്നിധിയിൽ വന്ന് പറഞ്ഞു: അല്ലാഹു എന്നെ സുഖപ്പെടുത്താൻ അങ്ങ് ദുആ ഇരന്നാലും. അവിടുന്ന് പറഞ്ഞു: "നീ ഉദ്ദേശിക്കുകയാണെങ്കിൽ ഞാൻ ദുആ ചെയ്യാം. അല്ലെങ്കിൽ നീ ക്ഷമിക്കുക, അതാണ് നിനക്കുത്തമം." അദ്ദേഹം പറയുന്നു: എന്നാൽ അങ്ങ് പ്രാർത്ഥിക്കുക. നിവേദകൻ പറയുന്നു: അപ്പോൾ അവിടുന്ന് അദ്ദേഹത്തോട് നല്ല രീതിയിൽ വുളു എടുത്ത് ഇങ്ങനെ ദുആ ചെയ്യാൻ പറഞ്ഞു: "അല്ലാഹുവേ, ഞാൻ നിന്നോട് ചോദിക്കുകയും നിന്റെ പ്രവാചകനായ കാരുണ്യത്തിന്റെ റസൂൽ സയ്യിദുനാ മുഹമ്മദ്(സ)മിനെക്കൊണ്ട് നിന്നിലേക്ക് തിരിയുകയും ചെയ്യുന്നു. എന്റെ ഈ ആവശ്യം സഫലമാവാൻ ഞാൻ എന്റെ റബ്ബിലേക്ക് അങ്ങയെക്കൊണ്ട് തിരിഞ്ഞിരിക്കുന്നു. അല്ലാഹുവേ, അവിടുത്തെ നീ എന്റെ വിഷയത്തിൽ ശുപാർശകാരനാക്കേണമേ. (തു,ജ)', 'عُثْمَانَ بْنِ حُنَيْفٍ', 'ഉസ്മാനുബ്നു ഹുനൈഫ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 957, 957, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 226, 'عَنْ عَمْرِو بْنِ عَبَسَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "أَقْرَبُ مَا يَكُونُ الرَّبُّ مِنَ الْعَبْدِ فِي جَوْفِ اللَّيْلِ الْآخِرِ، فَإِنِ اسْتَطَعْتَ أَنْ تَكُونَ مِمَّنْ يَذْكُرُ اللهَ فِي تِلْكَ السَّاعَةِ فَكُنْ". حَسَنٌ صَحِيحٌ. (د,ت,جه)', 'അംറുബ്നു അബസ(റ): റസൂൽ(സ) പറയുന്നത് അദ്ദേഹം കേട്ടു: "രക്ഷിതാവ് തന്റെ അടിമയിലേക്ക് ഏറ്റവും അടുത്തവനാകുന്നത് രാത്രിയുടെ അവസാനഭാഗത്തിലാണ്, അതിനാൽ ആ സമയത്ത് അല്ലാഹുവിനെ സ്മരിക്കുന്നവരിൽപെടാൻ നിനക്ക് സാധിക്കുമെങ്കിൽ നീ അത് ചെയ്യുക." (ദ,തു,ജ)', 'عَمْرِو بْنِ عَبَسَةَ', 'അംറുബ്നു അബസ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 957, 958, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 227, 'عَنْ عُمَارَةَ بْنِ زَعْكَرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ: إِنَّ عَبْدِي الَّذِي يَذْكُرُنِي وَهُوَ مُلَاقٍ قِرْنَهُ" يَعْنِي عِنْدَ الْقِتَالِ. (د,ت,ن,جه)', 'ഉമാറതുബ്നു സഅ്കറ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "അല്ലാഹു പറയുന്നു: തന്റെ ശത്രുവിനെ കണ്ടുമുട്ടുന്ന സമയത്ത് (യുദ്ധ സമയത്ത്) എന്നെ ഓർക്കുന്ന അടിമയാണ് എന്റെ യഥാർത്ഥ അടിമ." (ദ,തു,ന,ജ)', 'عُمَارَةَ بْنِ زَعْكَرَةَ', 'ഉമാറതുബ്നു സഅ്കറ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 958, 958, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 228, 'عَنْ مُحَمَّدِ بْنِ سَالِمٍ رَضِيَ اللَّهُ عَنْهُ: قَالَ: قَالَ لِي ثَابِتٌ الْبَنَانِيُّ: يَا مُحَمَّدُ، إِذَا اشْتَكَيْتَ فَضَعْ يَدَكَ حَيْثُ تَشْتَكِي، ثُمَّ قُلْ: "بِسْمِ اللَّهِ، أَعُوذُ بِعِزَّةِ اللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ مِنْ وَجَعِي هَذَا. ثُمَّ ارْفَعْ يَدَكَ، ثُمَّ أَعِدْ ذَلِكَ وِتْرًا". فَإِنَّ أَنَسَ بْنَ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ حَدَّثَنِي: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَدَّثَنِي بِذَلِكَ. حَسَنٌ. (ت)', 'മുഹമ്മദുബ്നു സാലിം(റ): എന്നോട് സാബിതുൽ ബനാനി(റ) പറഞ്ഞു: മുഹമ്മദേ, താങ്കൾക്ക് വല്ല വേദനയുമുണ്ടായാൽ താങ്കളുടെ കൈ വേദനയുള്ള ഭാഗത്ത് വെച്ച്: അല്ലാഹുവിന്റെ നാമത്തിൽ, ഞാൻ അനുഭവിക്കുന്ന ഈ വേദനയുടെ നാശത്തിൽ നിന്ന് അല്ലാഹുവിന്റെ പ്രതാപം കൊണ്ടും അവന്റെ ശക്തി കൊണ്ടും ഞാൻ കാവൽ ചോദിക്കുന്നു എന്ന് പറയുക. പിന്നെ നിന്റെ കൈ എടുക്കുക, എന്നിട്ട് അതിനെ ഒറ്റയാക്കി ആവർത്തിച്ച് ചെല്ലുക. കാരണം അനസുബ്നു മാലിക്(റ) എന്നോട് പറഞ്ഞു: നിശ്ചയം റസൂൽ(സ) എന്നോട് അത് പറഞ്ഞിട്ടുണ്ട്. (തു)', 'مُحَمَّدِ بْنِ سَالِمٍ', 'മുഹമ്മദുബ്നു സാലിം(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 958, 958, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=85 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 229, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا غَزَا قَالَ: "اللَّهُمَّ أَنْتَ عَضُدِي، وَأَنْتَ نَصِيرِي، وَبِكَ أُقَاتِلُ". (د,ت)', 'അനസ്(റ): യുദ്ധം ചെയ്യുമ്പോൾ നബി(സ) പറയുമായിരുന്നു: "അല്ലാഹുവേ, നീയാണെന്റെ ശക്തി നീയാണെന്റെ സഹായി, നിന്നെക്കൊണ്ടാണ് ഞാൻ പോരാടുന്നത്." (ദ,തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 958, 958, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 230, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ: عَلَّمَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "قُلْ: اللَّهُمَّ اجْعَلْ سَرِيرَتِي خَيْرًا مِنْ عَلَانِيَتِي وَاجْعَلْ عَلَانِيَتِي صَالِحَةً. اَللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ صَالِحِ مَا تُؤْتِي النَّاسَ مِنَ الْمَالِ وَالْأَهْلِ وَالْوَلَدِ، غَيْرِ الضَّالِّ وَلَا الْمُضِلِّ". (ت)', 'ഉമർ(റ): റസൂൽ(സ) എന്നെ പഠിപ്പിച്ചു: "നീ പറയുക. അല്ലാഹുവേ, എന്റെ രഹസ്യാവസ്ഥയെ പരസ്യാവസ്ഥയേക്കാൾ ഉത്തമമാക്കേണമേ, എന്റെ പരസ്യാവസ്ഥയെ നല്ലതാക്കണേ. അല്ലാഹുവേ, സന്താനത്തിലും സമ്പത്തിലും കുടുംബത്തിലും ജനങ്ങൾക്ക് നൽകപ്പെടുന്ന പിഴച്ചതും പിഴപ്പിക്കുന്നതുമല്ലാത്ത നല്ലതിനെ ഞാൻ ചോദിക്കുന്നു." (തു)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 958, 959, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=87 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 231, 'عَنْ شِهَابِ بْنِ كُلَيْبِ الْجَرْمِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلْتُ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يُصَلِّي وَقَدْ وَضَعَ يَدَهُ الْيُسْرَى عَلَى فَخِذِهِ الْيُسْرَى، وَوَضَعَ يَدَهُ الْيُمْنَى عَلَى فَخِذِهِ الْيُمْنَى، وَقَبَضَ عَلَى أَصَابِعِهِ وَبَسَطَ السَّبَّابَةَ، وَهُوَ يَقُولُ: "يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ". (ت)', 'ശിഹാബുബ്നു കുലൈബിനിൽ ജർമിയ്യ്(റ): നബി(സ) നിസ്കരിച്ചു കൊണ്ടിരിക്കെ ഞാൻ തിരുമേനി(സ)യുടെ അടുത്തേക്ക് പ്രവേശിച്ചു. തിരുമേനി(സ) ഇടതു കൈ അവിടുത്തെ ഇടത്തെ തുടയിലും വലതു കൈ വലത്തെ തുടയിലും വെച്ചു കൊണ്ട് അവിടുത്തെ വിരലുകൾ പിടിക്കുകയും ചൂണ്ടു വിരൽ നിവർത്തുകയും ചെയ്തിരിക്കുന്നു. തിരുമേനി(സ) പറയുന്നുണ്ടായിരുന്നു: "ഹൃദയങ്ങളെ ചാഞ്ചാട്ടുന്നവനേ, എന്റെ ഹൃദയത്തെ നിന്റെ ദീനിൽ ഉറപ്പിച്ച് നിർത്തേണമേ." (തു)', 'شِهَابِ بْنِ كُلَيْبِ الْجَرْمِيِّ', 'ശിഹാബുബ്നു കുലൈബിനിൽ ജർമിയ്യ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 959, 959, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 232, 'عَنْ أُمِّ سَلَمَةَ أُمِّ الْمُؤْمِنِينَ رَضِيَ اللهُ عَنْهَا، وَقَدْ سُئِلَتْ: مَا كَانَ أَكْثَرُ دُعَاءِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا كَانَ عِنْدَكِ؟ قَالَتْ: كَانَ أَكْثَرُ دُعَائِهِ: "يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ". قَالَتْ: فَقُلْتُ: يَا رَسُولَ اللهِ، مَا أَكْثَرَ دُعَاءَكَ: "يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ". قَالَ: "يَا أُمَّ سَلَمَةَ، إِنَّهُ لَيْسَ آدَمِيٌّ إِلَّا وَقَلْبُهُ بَيْنَ أُصْبُعَيْنِ مِنْ أَصَابِعِ اللَّهِ، فَمَنْ شَاءَ أَقَامَ وَمَنْ شَاءَ أَزَاغَ". حَسَنٌ. (ت)', 'ഉമ്മുൽമുഅ്മിനീൻ ഉമ്മുസലമ(റ): മഹതിയതിയോട് ചോദിക്കപ്പെട്ടു: റസൂൽ(സ) നിങ്ങളുടെ അടുത്തായിരിക്കുമ്പോൾ കൂടുതൽ പ്രാർത്ഥിച്ചിരുന്ന പ്രാർത്ഥന എന്താണ്? മഹതി പറഞ്ഞു: അവിടുന്ന് അധികവും പ്രാർത്ഥിച്ചിരുന്നത് ഇതാണ്: "ഹൃദയങ്ങളെ ചാഞ്ചാടിക്കുന്ന അല്ലാഹുവേ, എന്റെ ഹൃദയത്തെ നിന്റെ ദീനിൽ ഉറപ്പിച്ച് നിർത്തേണമേ." ഞാൻ ചോദിച്ചു: അങ്ങ് എന്ത് കൊണ്ടാണ് ഹൃദയങ്ങളെ ചാഞ്ചാട്ടുന്ന അല്ലാഹുവേ, എന്റെ ഹൃദയത്തെ നിന്റെ ദീനിൽ ഉറപ്പിച്ച് നിർത്തേണമേ, എന്ന പ്രാർത്ഥന വർദ്ധിപ്പിക്കുന്നത്? റസൂൽ(സ) മറുപടി പറഞ്ഞു: "ഏ ഉമ്മുസലമ, ഹൃദയം അല്ലാഹുവിന്റെ വിരലുകളിലെ രണ്ട് വിരലുകൾക്കിടയിലല്ലാത്ത ഒരു മനഷ്യനുമില്ല. അവൻ ഉദ്ദേശിച്ചവരെ അവൻ നിലനിർത്തും. അവൻ ഉദ്ദേശിച്ചവരെ വഴിപിഴപ്പിക്കും." (തു)', 'أُمِّ سَلَمَةَ أُمِّ الْمُؤْمِنِينَ', 'ഉമ്മുൽമുഅ്മിനീൻ ഉമ്മുസലമ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 959, 959, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 233, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "سَلُوا اللَّهَ مِنْ فَضْلِهِ، فَإِنَّ اللَّهَ عَزَّ وَجَلَّ يُحِبُّ أَنْ يُسْأَلَ، وَأَفْضَلُ الْعِبَادَةِ انْتِظَارُ الْفَرَجِ". (ت)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിനോട് അവന്റെ ഔദാര്യത്തെ നിങ്ങൾ ചോദിക്കുക. അവനോട് ചോദിക്കൽ അല്ലാഹു ഇഷ്ടപ്പെടുന്നു. ഏറ്റവും ശ്രേഷ്ഠമായ ആരാധന പരിഹാരം പ്രതീക്ഷിച്ചിരിക്കലാണ്." (തു)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 959, 960, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 234, 'عَنْ زَيْدِ بْنِ أَرْقَمَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكَسَلِ وَالْعَجْزِ وَالْبُخْلِ. وَ كَانَ يَتَعَوَّذُ مِنْ الْهَرَمِ وَعَذَابِ الْقَبْرِ. حَسَنٌ صَحِيحٌ. (م,ت,ن)', 'സൈദുബ്നു അർഖം(റ): നബി(സ) പറയാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ, പിശുക്കിൽ നിന്നും അശക്തതയിൽ നിന്നും അലസതയിൽ നിന്നും ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു." വാർദ്ധകൃത്തിൽ നിന്നും ഖബ്‌റിലെ ശിക്ഷയിൽ നിന്നും നബി(സ) കാവൽ ചോദിക്കാറുണ്ടായിരുന്നു. (മു,തു,ന)', 'زَيْدِ بْنِ أَرْقَمَ', 'സൈദുബ്നു അർഖം(റ)', null, null, array['م','ت','ن']::text[], array['മു','തു','ന']::text[], null, null, 960, 960, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 235, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: بَيْنَمَا نَحْنُ عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذْ جَاءَهُ عَلِيُّ بْنُ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ فَقَالَ: بِأَبِي أَنْتَ وَأُمِّي، تَفَلَّتَ هَذَا الْقُرْآنُ مِنْ صَدْرِي، فَمَا أَجِدُنِي أَقْدِرُ عَلَيْهِ. فَقَالَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا أَبَا الْحَسَنِ، أَفَلَا أُعَلِّمُكَ كَلِمَاتٍ يَنْفَعُكَ اللَّهُ بِهِنَّ، وَيَنْفَعُ بِهِنَّ مَنْ عَلَّمْتَهُ، وَيُثَبِّتُ مَا تَعَلَّمْتَ فِي صَدْرِكَ؟". قَالَ: أَجَلْ يَا رَسُولَ اللهِ. فَعَلِّمْنِي. قَالَ: "إِذَا كَانَ لَيْلَةُ الْجُمُعَةِ فَإِنِ اسْتَطَعْتَ أَنْ تَقُومَ فِي ثُلُثِ اللَّيْلِ الْآخِرِ، فَإِنَّهَا سَاعَةٌ مَشْهُودَةٌ، وَالدُّعَاءُ فِيهَا مُسْتَجَابٌ، وَقَدْ قَالَ أَخِي يَعْقُوبُ لِبَنِيهِ: {سَوْفَ أَسْتَغْفِرُ لَكُمْ رَبِّي} [يوسف: ٩٨] يَقُولُ: حَتَّى تَأْتِيَ لَيْلَةُ الْجُمُعَةِ، فَإِنْ لَمْ تَسْتَطِعْ فَقُمْ فِي وَسَطِهَا، فَإِنْ لَمْ تَسْتَطِعْ فَقُمْ فِي أَوَّلِهَا: فَصَلِّ أَرْبَعَ رَكَعَاتٍ، تَقْرَأُ فِي الرَّكْعَةِ الْأُولَى بِفَاتِحَةِ الْكِتَابِ وَسُورَةِ {يس}. وَفِي الرَّكْعَةِ الثَّانِيَةِ بِفَاتِحَةِ الْكِتَابِ وَ{حم} الدُّخَانِ، وَفِي الرَّكْعَةِ الثَّالِثَةِ بِفَاتِحَةِ الْكِتَابِ وَ{الم تَنْزِيلُ..} السَّجْدَةِ، وَفِي الرَّكْعَةِ الرَّابِعَةِ بِفَاتِحَةِ الْكِتَابِ وَ{تَبَارَكَ} الْمُفَصَّلِ. فَإِذَا فَرَغْتَ مِنَ التَّشَهُّدِ فَاحْمَدِ اللهَ. وَأَحْسِنِ الثَّنَاءَ عَلَى اللهِ، وَصَلِّ عَلَيَّ، وَأَحْسِنْ عَلَى سَائِرِ النَّبِيِّينَ. وَاسْتَغْفِرْ لِلْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ. وَلِإِخْوَانِكَ الَّذِينَ سَبَقُوكَ بِالْإِيمَانِ. ثُمَّ قُلْ فِي آخِرِ ذَلِكَ: اللَّهُمَّ ارْحَمْنِي بِتَرْكِ الْمَعَاصِي أَبَدًا مَا أَبْقَيْتَنِي، وَارْحَمْنِي أَنْ أَتَكَلَّفَ مَا لَا يَعْنِينِي، وَارْزُقْنِي حُسْنَ النَّظَرِ فِيمَا يُرْضِيكَ عَنِّي. اللَّهُمَّ بَدِيعَ السَّمَوَاتِ وَالْأَرْضِ، ذَا الْجَلَالِ وَالْإِكْرَامِ وَالْعِزَّةِ الَّتِي لَا تُرَامُ: أَسْأَلُكَ يَا أَللهُ يَا رَحْمَنُ بِجَلَالِكَ وَنُورِ وَجْهِكَ: أَنْ تُلْزِمَ قَلْبِي حِفْظَ كِتَابِكَ كَمَا عَلَّمْتَنِي، وَارْزُقْنِي أَنْ أَتْلُوَهُ عَلَى النَّحْوِ الَّذِي يُرْضِيكَ عَنِّي اللَّهُمَّ بَدِيعَ السَّمَوَاتِ وَالْأَرْضِ ذَا الْجَلَالِ وَالْإِكْرَامِ وَالْعِزَّةِ الَّتِي لَا تُرَامُ: أَسْأَلُكَ يَا أَللهُ يَا رَحْمَنُ بِجَلَالِكَ وَنُورِ وَجْهِكَ: أَنْ تُنَوِّرَ بِكِتَابِكَ بَصَرِي، وَأَنْ تُطْلِقَ بِهِ لِسَانِي، وَأَنْ تُفَرِّجَ بِهِ عَنْ قَلْبِي، وَأَنْ تَشْرَحَ بِهِ صَدْرِي، وَأَنْ تَغْسِلَ بِهِ بَدَنِي، فَإِنَّهُ لَا يُعِينُنِي عَلَى الْحَقِّ غَيْرُكَ، وَلَا يُؤْتِيهِ إِلَّا أَنْتَ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ. يَا أَبَا الْحَسَنِ. تَفْعَلُ ذَلِكَ ثَلَاثَ جُمَعٍ، أَوْ خَمْسًا، أَوْ سَبْعًا، تُجَبْ بِإِذْنِ اللَّهِ، وَالَّذِي بَعَثَنِي بِالْحَقِّ. مَا أَخْطَأَ مُؤْمِنًا قَطُّ". قَالَ ابْنُ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: فَوَاللهِ مَا لَبِثَ عَلِيٌّ إِلَّا خَمْسًا أَوْ سَبْعًا حَتَّى جَاءَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي مِثْلِ ذَلِكَ الْمَجْلِسِ فَقَالَ: يَا رَسُولَ اللهِ، إِنِّي كُنْتُ فِيمَا خَلَا لَا آخُذُ إِلَّا أَرْبَعَ آيَاتٍ أَوْ نَحْوَهُنَّ، وَإِذَا قَرَأْتُهُنَّ عَلَى نَفْسِي تَفَلَّتْنَ، وَأَنَا أَتَعَلَّمُ الْيَوْمَ أَرْبَعِينَ آيَةً أَوْ نَحْوَهَا، وَإِذَا قَرَأْتُهَا عَلَى نَفْسِي فَكَأَنَّمَا كِتَابُ اللَّهِ بَيْنَ عَيْنَيَّ. وَلَقَدْ كُنْتُ أَسْمَعُ الْحَدِيثَ فَإِذَا رَدَّدْتُهُ تَفَلَّتَ، وَأَنَا الْيَوْمَ أَسْمَعُ الْأَحَادِيثَ، فَإِذَا تَحَدَّثْتُ بِهَا لَمْ أَخْرِمْ مِنْهَا حَرْفًا. فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ ذَلِكَ: "مُؤْمِنٌ وَرَبِّ الْكَعْبَةِ، يَا أَبَا الْحَسَنِ". حَسَنٌ. (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): ഞങ്ങൾ തിരുദൂതരുടെ സമീപത്ത് ഇരിക്കുന്നതിനിടയിൽ അലി(റ) കടന്നു വന്നു പറഞ്ഞു: എന്റെ ഉമ്മയും ഉപ്പയും അങ്ങേക്ക് ദണ്ഡമാണ് റസൂലേ, ഖുർആൻ മനഃപാഠമാക്കിയത് ഞാൻ മറന്നു പോകുന്നു, അത് പഠിക്കാൻ എനിക്ക് കഴിയുമെന്ന് തോന്നുന്നില്ല. റസൂൽ(സ) പറഞ്ഞു: "അബുൽഹസനേ, നിങ്ങൾ പഠിച്ചത് നിങ്ങളുടെ മനസ്സിൽ ഉറപ്പിച്ച് നിർത്തുകയും നിങ്ങൾക്കും നിങ്ങൾ പഠിപ്പിക്കുന്നവർക്കും അല്ലാഹു ഉപകാരം ചെയ്യുന്നതുമായ ചില വചനങ്ങൾ നിങ്ങൾക്ക് ഞാൻ പഠിപ്പിച്ച് തരട്ടെയോ?" അലി(റ) പറഞ്ഞു: നബിയേ, അങ്ങെനിക്ക് പഠിപ്പിച്ച് തന്നാലും. റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾക്ക് കഴിയുമെങ്കിൽ വെള്ളിയാഴ്ചരാവിലെ മൂന്ന് ഭാഗങ്ങളിൽ അവസാനത്തെ ഭാഗത്തിൽ എഴുന്നേൽക്കുക, അത് മാലാഖമാർ സന്നിഹിതരാവുകയും പ്രാർത്ഥനകൾക്ക് ഉത്തരം നൽകപ്പെടുകയും ചെയ്യുന്ന സമയമാണ്, നിശ്ചയം, എന്റെ സഹോദരൻ യഅ്ഖൂബ് നബി(അ) തന്റെ സന്തതികളോട് പറയുമായിരുന്നു. ''നിങ്ങൾക്ക് വേണ്ടി എന്റെ നാഥനോട് ഞാൻ പൊറുക്കലിനെ ചോദിക്കാം.'' (യൂസുഫ്: 98). വെള്ളിയാഴ്ച രാവ് എത്തുന്നത് വരെ എന്നാണ് അദ്ദേഹം പറയുന്നത്. നിങ്ങൾക്ക് മൂന്നിൽ അവസാനത്തെ സമയത്ത് കഴിയില്ലെങ്കിൽ മധ്യ സമയത്തും അതും കഴിയില്ലെങ്കിൽ ആദ്യ സമയത്തും എഴുന്നേൽക്കുക, എന്നിട്ട് നാല് റക്അത്ത് നിസ്കരിക്കുക. ഒന്നാം റക്അത്തിൽ ''ഫാതിഹ''യും ''യാസീനു''ം, രണ്ടാമത്തേതിൽ ''ഫാതിഹ''യും ''ദുഖാനു''ം മൂന്നാം റക്അത്തിൽ ''ഫാതിഹ''യും ''സജദഃ''യും, നാലാമത്തേതിൽ ''ഫാതിഹ''യും ''തബാറക(മുൽക്)''യും ഓതുക. അത്തഹിയ്യാത്ത് ഓതിക്കഴിഞ്ഞാൽ നിങ്ങൾ അല്ലാഹുവിനെ സ്തുതിക്കുകയും അവനെ നല്ലവണ്ണം വാഴ്ത്തുകയും എന്റെമേൽ സ്വലാത്ത് ചൊല്ലുകയും മറ്റു മുർസലുകളെക്കുറിച്ച് നല്ലത് പറയുകയും ചെയ്യുക. പിന്നെ വിശ്വാസികളായ എല്ലാ ആണിനും പെണ്ണിനും ഈമാനുകൊണ്ട് നിങ്ങളെ മുൻ കടന്ന നിങ്ങളുടെ സഹോദരന്മാർക്കും പൊറുക്കലിനെ ചോദിക്കുക. ഇതിന്റെയെല്ലാം ശേഷം പറയുക: അല്ലാഹുവേ, എന്നെ നീ ജീവിപ്പിക്കുന്ന കാലത്തോളം തെറ്റുകളിൽ നിന്ന് മുക്തനാക്കിക്കൊണ്ട് എന്നോട് കരുണ കാണിക്കണേ, എനിക്കാവശ്യമില്ലാത്ത കാര്യങ്ങൾക്കായി ഞാൻ സ്വയം കഷ്ടപ്പെടുന്നതിലും എന്നോട് നീ കരുണ കാണിക്കണേ. നിന്നെ എന്നോട് ഇഷ്ടമുള്ളവനാക്കുന്ന കാര്യങ്ങളിൽ എനിക്ക് നീ നല്ല കാഴ്ചയെ നൽകേണമേ. ആകാശ ഭൂമികളെ അത്ഭുതകരമായി മുൻരൂപമില്ലാതെ രൂപപ്പെടുത്തിയ അല്ലാഹുവേ, മറ്റാർക്കും പ്രാപ്യമല്ലാത്ത മഹത്വവും പ്രതാപവും ഔദാര്യവും ഉള്ളവനായ അല്ലാഹുവേ, കാരുണ്യവാനേ, നിന്റെ തിരുമുഖപ്രകാശം കൊണ്ടും നിന്റെ മാഹാത്മ്യം കൊണ്ടും നിന്നോട് ഞാൻ ചോദിക്കുന്നു: നീ പഠിപ്പിച്ച പോലെ നിന്റെ ഗ്രന്ഥം മനഃപാഠമാക്കാൻ എന്റെ ഹൃദയത്തെ പര്യാപ്തമാക്കേണമേ, നീ ഇഷ്ടപ്പെടുന്ന രൂപത്തിൽ അതിനെ പാരായണം ചെയ്യാനുള്ള കഴിവും എനിക്ക് പ്രദാനം ചെയ്യേണമേ. ആകാശ ഭൂമികളെ അത്ഭുതകരമായി മുൻരൂപമില്ലാതെ രൂപപ്പെടുത്തിയവനും മറ്റാർക്കും പ്രാപ്യമല്ലാത്ത മാഹാത്മ്യവും പ്രതാപവും ഔദാര്യവും ഉടയവനുമായ അല്ലാഹുവേ, നിന്റെ തിരുമുഖ പ്രകാശം കൊണ്ടും പ്രഭകൊണ്ടും, കാരുണ്യവാനായ അല്ലാഹുവേ, നിന്നോട് ഞാൻ ചോദിക്കുന്നു: നിന്റെ ഗ്രന്ഥം കൊണ്ട് എന്റെ കണ്ണിനെ പ്രകാശിപ്പിക്കേണമേ, അത് കൊണ്ട് എന്റെ നാവിനെ ഉച്ചരിപ്പിക്കേണമേ, അത് കൊണ്ട് എന്റെ ഹൃദയത്തെ തുറസ്സാക്കണേ, അത് കൊണ്ട് എന്റെ നെഞ്ചിനെ വിശാലമാക്കേണമേ, എന്റെ ശരീരത്തെ കഴുകേണമേ, കാരണം സത്യത്തിന്റെ മേൽ നീയല്ലാതെ മറ്റാരും എന്നെ സഹായിക്കുകയില്ല, സത്യത്തെ നീയല്ലാതെ തരികയുമില്ല, മഹോന്നതനും ഉയർന്നവനുമായ അല്ലാഹുവിൽനിന്നല്ലാതെ കഴിവും ശക്തിയുമില്ല. അബൂഹസനേ, മൂന്നോ അഞ്ചോ ഏഴോ വെള്ളിയാഴ്ചകളിൽ നിങ്ങൾ ഇത് ചെയ്യുക. അല്ലാഹുവിന്റെ അനുമതിയാൽ നിങ്ങൾക്ക് ഉത്തരം നൽകപ്പെടും, എന്നെ സത്യം കൊണ്ട് അയച്ചവനാണ് സത്യം! അല്ലാഹു ഒരു വിശ്വാസിയെയും പിഴപ്പിച്ചിട്ടില്ല."
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 236, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: دُعَاءٌ حَفِظْتُهُ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَا أَدَعُهُ: "اللَّهُمَّ اجْعَلْنِي أُعَظِّمُ شُكْرَكَ، وَأُكْثِرُ ذِكْرَكَ، وَأَتَّبِعُ نَصِيحَتَكَ، وَأَحْفَظُ وَصِيَّتَكَ". (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ)യിൽ നിന്ന് ഞാൻ പഠിച്ച ഒരു പ്രാർത്ഥനയുണ്ട്. ഞാനത് ഒഴിവാക്കാറില്ല. അത് ഇപ്രകാരമാണ്. "അല്ലാഹുവേ, നീയെന്നെ, നിനക്ക് നന്ദി ചെയ്യൽ മഹത്തരമായി കാണുന്നവനും നിന്റെ സ്മരണ വർദ്ധിപ്പിക്കുന്നവനും നിന്റെ ഉപദേശങ്ങൾ പിന്തുടരുന്നവനും നിന്റെ വസിയ്യത് സൂക്ഷിക്കുന്നവനുമാക്കേണമേ." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 962, 962, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 237, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ رَجُلٍ يَدْعُو اللَّهَ بِدُعَاءٍ إِلَّا اسْتُجِيبَ لَهُ: فَإِمَّا أَنْ يُعَجَّلَ لَهُ فِي الدُّنْيَا، وَإِمَّا أَنْ يُدَّخَرَ لَهُ فِي الْآخِرَةِ، وَإِمَّا يُكَفَّرَ عَنْهُ ذُنُوبِهِ بِقَدْرِ مَا دَعَا. مَا لَمْ يَدْعُ بِإِثْمٍ أَوْ قَطِيعَةِ رَحِمٍ أَوْ يَسْتَعْجِلْ". قَالُوا: يَا رَسُولَ اللَّهِ، وَكَيْفَ يَسْتَعْجِلُ؟ قَالَ: "فَيَقُولُ: دَعَوْتُ رَبِّي فَمَا اسْتَجَابَ لِي". (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ധൃതി കൂട്ടാതിരിക്കുകയോ തെറ്റ് കൊണ്ടോ കുടുംബ ബന്ധം മുറിക്കൽ കൊണ്ടോ പ്രാർത്ഥിക്കുകയോ ചെയ്യാത്ത കാലത്തോളം അല്ലാഹുവിനോട് പ്രാർത്ഥിച്ചിട്ട് ഉത്തരം കിട്ടാത്ത ഒരാളുമുണ്ടാവില്ല. അതൊരുപക്ഷെ, ദുനിയാവിൽ വെച്ച്തന്നെ കിട്ടിയേക്കാം, അല്ലെങ്കിൽ പരലോകത്തേക്ക് സൂക്ഷിച്ചിട്ടുണ്ടാവും. അതുമല്ലെങ്കിൽ അവന്റെ പ്രാർത്ഥിക്കലിന് സമാനമായ പാപങ്ങൾ പൊറുക്കപ്പെട്ടിട്ടുണ്ടാവും." അവർ ചോദിച്ചു: റസൂലേ, ധൃതികൂട്ടുക എന്നത് എങ്ങനെയാണ്? റസൂൽ(സ) പറഞ്ഞു: "ഞാനെന്റെ നാഥനോട് പ്രാർത്ഥിച്ചു, പക്ഷെ. അവനെനിക്ക് ഉത്തരം നൽകിയില്ല എന്നവൻ പറയലാണ്." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 962, 962, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=92 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 238, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا عَلَى الْأَرْضِ مُسْلِمٌ يَدْعُو اللهَ بِدَعْوَةٍ إِلَّا آتَاهُ اللهُ إِيَّاهَا، أَوْ صَرَفَ عَنْهُ مِنَ السُّوءِ مِثْلَهَا، مَا لَمْ يَدْعُ بِإِثْمٍ أَوْ قَطِيعَةِ رَحِمٍ". فَقَالَ رَجُلٌ مِنَ الْقَوْمِ: إِذًا نُكْثِرُ. قَالَ: "اللهُ أَكْثَرُ". حَسَنٌ صَحِيحٌ. (ت)', 'ഉബാദതുബ്നു സ്വാമിത്(റ): റസൂൽ(സ) പറഞ്ഞു: തെറ്റു കൊണ്ടും കുടുംബ ബന്ധം മുറിക്കൽ കൊണ്ടും പ്രാർത്ഥിക്കാത്ത കാലത്തോളം താൻ ചോദിക്കുന്നത് അല്ലാഹു നൽകുകയോ അതല്ലെങ്കിൽ സമാനമായ ദോഷം തന്നിൽ നിന്ന് തിരിച്ച് കളയുകയോ ചെയ്യപ്പെടാത്ത ഒരു മുസ്‌ലിമും ഭൂലോകത്തില്ല." അപ്പോൾ കൂട്ടത്തിൽ നിന്നൊരാൾ പറഞ്ഞു: എങ്കിൽ ഞങ്ങൾ ധാരാളം പ്രാർത്ഥിക്കും. റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു ധാരാളം നൽകുന്നവനാണ്." (തു)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദതുബ്നു സ്വാമിത്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 962, 963, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=92 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 239, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ عَبْدٍ يَرْفَعُ يَدَيْهِ حَتَّى يَبْدُوَ إِبْطُهُ، يَسْأَلُ اللهَ مَسْأَلَةً، إِلَّا آتَاهَا إِيَّاهُ، مَا لَمْ يَعْجَلْ". قَالُوا: يَا رَسُولَ اللهِ، وَكَيْفَ عَجَلَتُهُ؟ قَالَ: "يَقُولُ: قَدْ سَأَلْتُ وَسَأَلْتُ، وَلَمْ أُعْطَ شَيْئًا". وفي رواية: "يُسْتَجَابُ لِأَحَدِكُمْ مَا لَمْ يَعْجَلْ، يَقُولُ: دَعَوْتُ فَلَمْ يُسْتَجَبْ لِي". (ق, د, ت, جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ധൃതി കൂട്ടാത്ത കാലത്തോളം, കക്ഷം കാണുന്ന വിധത്തിൽ കൈയുയർത്തി അല്ലാഹുവിനോട് ചോദിക്കുന്ന അടിമക്ക് അവൻ ചോദിക്കുന്നത് നൽകുക തന്നെ ചെയ്യും. അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എങ്ങനെയാണ് ''ധൃതികൂട്ടുക'' എന്നത്. നബി(സ) പറഞ്ഞു: "അവൻ പറയലാണ്. ഞാൻ അല്ലാഹുവിനോട് ചോദിച്ചു: പിന്നെയും ചോദിച്ചു. പക്ഷെ അവനെനിക്ക് ഒന്നും തന്നില്ല."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=239), 1, 'وَفِي رِوَايَةٍ: "يُسْتَجَابُ لِأَحَدِكُمْ مَا لَمْ يَعْجَلْ، يَقُولُ: دَعَوْتُ فَلَمْ يُسْتَجَبْ لِي". (ق, د, ت, جه)', 'മറ്റൊരു നിവേദനം: ''ഞാൻ പ്രാർത്ഥിച്ചു. പക്ഷെ, എനിക്ക് ഉത്തരം കിട്ടിയില്ല'' എന്നുപറഞ്ഞ ധൃതികൂട്ടാത്തിടത്തോളം നിങ്ങളോരോരുത്തർക്കും ഉത്തരം നൽകപ്പെടും." (ബു,മു,ദ,തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 240, 'عَنْ عُمَرَ بْنِ أَبِي سَلَمَةَ عَنْ أَبِيهِ - رَضِيَ اللهُ عَنْهُمَا - قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لِيَنْظُرَنَّ أَحَدُكُمْ مَا الَّذِي يَتَمَنَّى، فَإِنَّهُ لَا يَدْرِي مَا يُكْتَبُ لَهُ مِنْ أُمْنِيَّتِهِ". حَسَنٌ. (ت)', 'ഉമറുബ്നു അബീസലമ(റ) തന്റെ പിതാവിൽനിന്ന്: റസൂൽ(സ) പറഞ്ഞു: "താനെന്താണ് ആഗ്രഹിക്കുന്നതെന്ന് ഓരോരുത്തരും ചിന്തിച്ചു കൊള്ളട്ടെ. കാരണം അവന്റെ ആഗ്രഹത്തിൽനിന്ന് എന്തൊക്കെയാണ് എഴുതപ്പെടുകയെന്ന് അവനറിയില്ല." (തു)', 'عُمَرَ بْنِ أَبِي سَلَمَةَ عَنْ أَبِيهِ -', 'ഉമറുബ്നു അബീസലമ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 963, 963, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=93 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 241, 'عَنْ عُمَرَ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ اسْتَأْذَنَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْعُمْرَةِ، فَقَالَ: "أَيْ أُخَيَّ، أَشْرِكْنَا فِي دُعَائِكَ وَلَا تَنْسَنَا". حَسَنٌ صَحِيحٌ. (د, ت, جه)', 'ഉമർ(റ): ഉംറക്ക് വേണ്ടി അദ്ദേഹം നബി(സ)യോട് സമ്മതം ചോദിച്ചു: അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: ഓ, പൊന്നു സഹോദരാ, താങ്കളുടെ പ്രാർത്ഥനയിൽ ഞങ്ങളെയും ചേർക്കണേ, ഞങ്ങളെ താങ്കൾ മറന്നു പോകരുത്". (ദ,തു,ജ)', 'عُمَرَ', 'ഉമർ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 963, 963, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=94 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 242, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لِيَسْأَلْ أَحَدُكُمْ رَبَّهُ حَاجَتَهُ كُلَّهَا، حَتَّى يَسْأَلَ شِسْعَ نَعْلِهِ إِذَا انْقَطَعَ". وفي رواية: "حَتَّى يَسْأَلَهُ الْمِلْحَ، وَحَتَّى يَسْأَلَهُ شِسْعَ نَعْلِهِ إِذَا انْقَطَعَ". (ت)', 'അനസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലോരോരുത്തരും തന്റെ നാഥനോട് തന്റെ ആവശ്യങ്ങൾ മുഴുവനും ചോദിച്ചുകൊള്ളട്ടെ. തന്റെ ചെരുപ്പിന്റെ വാർ പൊട്ടിയാൽ പോലും അവനോട് ചോദിക്കട്ടെ.”
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=242), 1, 'وَفِي رِوَايَةٍ: "حَتَّى يَسْأَلَهُ الْمِلْحَ، وَحَتَّى يَسْأَلَهُ شِسْعَ نَعْلِهِ إِذَا انْقَطَعَ". (ت)', 'മറ്റൊരു നിവേദനം: “ഉപ്പു വരേ അവനോട് ചോദിക്കട്ടെ, ചെരുപ്പിന്റെ വാറ് പൊട്ടിയാൽ അതും അവനോട് ചോദിക്കട്ടെ.” (തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 243, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ مُكَاتَبًا جَاءَهُ فَقَالَ: إِنِّي قَدْ عَجَزْتُ عَنْ كِتَابَتِي، فَأَعِنِّي. قَالَ: أَلَا أُعَلِّمُكَ كَلِمَاتٍ عَلَّمَنِيهِنَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، لَوْ كَانَ عَلَيْكَ مِثْلُ جَبَلِ صِيرٍ دَيْنًا أَدَّاهُ اللَّهُ عَنْكَ؟ قَالَ: قُلْ: ”اللَّهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ، وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ“. حَسَنٌ. (ت)', 'അലി(റ): മോചന പത്രം എഴുതപ്പെട്ട ഒരടിമ മഹാനവർകളുടെ അടുത്ത് വന്നു പറഞ്ഞു: കരാർ പാലിക്കാൻ ഞാൻ അശക്തനായിരിക്കുന്നു. അതിനാൽ എന്നെ സഹായിക്കണം. അലി(റ) പറഞ്ഞു: റസൂൽ(സ) എനിക്ക് പഠിപ്പിച്ച് തന്ന ചില വാക്കുകൾ നിന്നെ ഞാൻ പഠിപ്പിക്കട്ടെയോ? (അത് ചൊല്ലുന്ന പക്ഷം,) ഒരു പർവ്വതത്തിന്റെ അത്രയും വലിയ കടം നിനക്കുണ്ടെങ്കിലും അല്ലാഹു നിനക്കത് വീട്ടിത്തരും. അവിടുന്ന് പറഞ്ഞു: “നീ പറയുക: അല്ലാഹുവേ, നിന്റെ ഹറാം വേണ്ടാത്തവിധം നിന്റെ ഹലാൽ കൊണ്ട് നീയെന്നെ തൃപ്തിപ്പെടുത്തണേ, മറ്റുള്ളവരെ ആശ്രയിക്കേണ്ടാത്തവിധം നിന്റെ ഔദാര്യം കൊണ്ട് നീയെന്നെ ഐശ്വര്യവാനാക്കണേ.” (തു)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 964, 964, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=96 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 244, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنْتُ شَاكِيًا، فَمَرَّ بِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا أَقُولُ: اللَّهُمَّ إِنْ كَانَ أَجَلِي قَدْ حَضَرَ فَأَرِحْنِي، وَإِنْ كَانَ مُتَأَخِّرًا فَارْفَعْنِي، وَإِنْ كَانَ بَلَاءً فَصَبِّرْنِي. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ”كَيْفَ قُلْتَ؟“. قَالَ: فَأَعَادَ عَلَيْهِ مَا قَالَ، قَالَ: فَضَرَبَهُ بِرِجْلِهِ وَقَالَ: ”اللَّهُمَّ عَافِهِ، أَوْ: اشْفِهِ“. قَالَ: فَمَا اشْتَكَيْتُ وَجَعِي بَعْدُ. حَسَنٌ صَحِيحٌ. (ت)', 'അലി(റ): ഞാൻ രോഗിയായിരുന്നപ്പോൾ റസൂൽ(സ) എന്റെ അടുത്ത് കൂടെ നടന്നു പോയി. ഞാൻ അപ്പോൾ ഇപ്രകാരം പറഞ്ഞു കൊണ്ടിരിക്കുകയായിരുന്നു: അല്ലാഹുവേ, എന്റെ മരണം അടുത്തുവെങ്കിൽ എനിക്ക് സുഖം നൽകേണമേ. എന്റെ മരണം പിന്തിയതാണെങ്കിൽ എന്നെ നീ ഉയർത്തേണമേ. ഇത് വല്ല പരീക്ഷണവുമാണെങ്കിൽ എനിക്ക് ക്ഷമ പ്രദാനം ചെയ്യേണമേ. അപ്പോൾ നബി(സ) ചോദിച്ചു: “നിങ്ങളെന്താണ് പറഞ്ഞത്?.” നിവേദകൻ പറയുന്നു: അലി(റ) താൻ പറഞ്ഞത് ആവർത്തിച്ചു. അപ്പോൾ നബി(സ) കാലുകൊണ്ട് അദ്ദേഹത്തെ അടിച്ചു. എന്നിട്ട് പറഞ്ഞു: “അല്ലാഹുവേ, ഇദ്ദേഹത്തിന് നീ ആരോഗ്യം നൽകേണമേ, അല്ലെങ്കിൽ ശമനം നൽകേണമേ.” അലി(റ) പറയുന്നു: അതിനു ശേഷം ഞാനെന്റെ വേദനയെക്കുറിച്ച് ആവലാതിപ്പെട്ടിട്ടില്ല. (തു)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 964, 964, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=97 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 245, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا عَادَ مَرِيضًا قَالَ: ”أَذْهِبِ الْبَأْسَ رَبَّ النَّاسِ، وَاشْفِ أَنْتَ الشَّافِي، لَا شِفَاءَ إِلَّا شِفَاؤُكَ، شِفَاءً لَا يُغَادِرُ سَقَمًا“. حَسَنٌ. (ت)', 'അലി(റ): നബി(സ) ഒരു രോഗിയെ സന്ദർശിച്ചാൽ ഇപ്രകാരം പറയുമായിരുന്നു: “ജനങ്ങളുടെ നാഥാ, എല്ലാ ബുദ്ധിമുട്ടുകളെയും നീ നീക്കേണമേ, ഒരു രോഗവും ബാക്കി വരാത്ത ശമനം നൽകേണമേ, നീയാണ് ശമനം നൽകുന്നവൻ. നിന്റെ ശമനമല്ലാതെ ഒരു ശമനവുമില്ല.” (തു)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 964, 964, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=97 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 246, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ فِي وِتْرِهِ: "اللَّهُمَّ إِنِّي أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَأَعُوذُ بِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ، وَأَعُوذُ بِكَ مِنْكَ لَا أُحْصِي ثَنَاءً عَلَيْكَ، أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ". حَسَنٌ. (د،ت،جه)', 'അലി(റ): നബി(സ) ''വിത്റ്'' നിസ്കരിക്കുമ്പോൾ പറയുമായിരുന്നു: "അല്ലാഹുവേ, നിന്റെ തൃപ്തികൊണ്ട് നിന്റെ ദേഷ്യത്തിൽ നിന്ന് ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു. നിന്റെ മാപ്പു കൊണ്ട് നിന്റെ ശിക്ഷയിൽ നിന്ന് ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു, നിന്റെ ശിക്ഷയിൽ നിന്ന് നിന്റെ അനുഗ്രഹം കൊണ്ട് ഞാൻ കാവൽ ചോദിക്കുന്നു. നിനക്കനുയോജ്യമാം വിധം നിന്നെ വാഴ്ത്താൻ ഞാനശക്തനാണ്. നീ സ്വയം എപ്രകാരം വാഴ്ത്തിയോ അപ്രകാരമാണ് നീ. (ദ,തു,ജ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലി(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 965, 965, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=98 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 247, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ دَعَا عَلَى مَنْ ظَلَمَهُ فَقَدِ انْتَصَرَ". (ت)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "തന്നെ അക്രമിച്ചവനെതിരെ വല്ലവനും പ്രാർത്ഥിച്ചാൽ അവൻ സഹായമഭ്യർത്ഥിച്ചിരിക്കുന്നു" (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 965, 965, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=99 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 248, 'عَنْ أَبِي أَيُّوبَ الْأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَالَ عَشْرَ مَرَّاتٍ: لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، يُحْيِي وَيُمِيتُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. كَانَتْ لَهُ عِدْلَ أَرْبَعِ رِقَابٍ مِنْ وَلَدِ إِسْمَعِيلَ". (ق،ت)', 'അബൂ അയ്യൂബുൽ അൻസാരി(റ): റസൂൽ(സ) പറഞ്ഞു: "ലാഇലാഹ ഇല്ലല്ലാഹു വഹ്‍ദഹുലാശരീകലഹു ലഹുൽമുല്കു വലഹുൽഹംദു യുഹ്‌യീവയുമീതു വഹുവഅലാകുല്ലിശൈഇൻ ഖദീർ''(അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ല, അവൻ ഏകനും പങ്കുകാരില്ലാത്തവനുമാണ്, അവനാണ് സർവ്വ സ്തുതികളും അധികാരവും, അവൻ ജീവിപ്പിക്കുയും മരിപ്പിക്കുകയും ചെയ്യുന്നു., അവൻ എല്ലാത്തിനും കഴിവുള്ളവനുമാണ്.) എന്ന് വല്ലവനും പത്ത് തവണ പറഞ്ഞാൽ അവൻ ഇസ്മാഈൽ(അ)ന്റെ സന്തതികളായ നാല് അടിമകളെ മോചിപ്പിച്ച പ്രതിഫലമുണ്ട്." (ബു,മു,തു)', 'أَبِي أَيُّوبَ الْأَنْصَارِيِّ', 'അബൂ അയ്യൂബുൽ അൻസാരി(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 965, 965, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=100 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 249, 'عَنْ صَفِيَّةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: دَخَلَ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَبَيْنَ يَدَيَّ أَرْبَعَةُ آلَافِ نَوَاةٍ، أُسَبِّحُ بِهَا. قَالَ: "لَقَدْ سَبَّحْتِ بِهَذِهِ؟ أَلَا أُعَلِّمُكِ بِأَكْثَرَ مِمَّا سَبَّحْتِ بِهِ". فَقُلْتُ: بَلَى، عَلِّمْنِي. فَقَالَ: "قُولِي: سُبْحَانَ اللَّهِ، عَدَدَ خَلْقِهِ". (ت)', 'സ്വഫിയ്യ(റ): ഞാൻ തസ്ബീഹ് ചൊല്ലാനുപയോഗിക്കുന്ന നാലായിരം മുത്തുകൾ എന്റെ മുന്നിലിരിക്കെ തിരുമേനി(സ) എന്റെ അടുത്തേക്ക് കടന്നു വന്നു. തിരുമേനി(സ) പറഞ്ഞു: "നീ ഇതുകൊണ്ട് തസ്ബീഹ് ചൊല്ലുകയായിരുന്നോ? നീ ഈ തസ്ബീഹ് ചൊല്ലിയതിനേക്കാൾ അധികമുള്ള ഒന്നു ഞാൻ നിന്നെ പഠിപ്പിക്കട്ടെയോ?" ഞാൻ പറഞ്ഞു: അതെ, പഠിപ്പിച്ചു തന്നാലും. റസൂൽ(സ) പറഞ്ഞു: "നീ പറയൂ, അല്ലാഹുവിനെ അവന്റെ സൃഷ്ടികളുടെ എണ്ണം കണക്കെ ഞാൻ വാഴ്ത്തുന്നു." (തു)', 'صَفِيَّةَ', 'സ്വഫിയ്യ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 965, 966, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=101 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 250, 'عَنْ جُوَيْرِيَةَ بِنْتِ الْحَارِثِ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّ عَلَيْهَا وَهِيَ فِي مَسْجِدِهَا، ثُمَّ مَرَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِهَا قَرِيبًا مِنْ نِصْفِ النَّهَارِ، فَقَالَ لَهَا: "مَا زِلْتِ عَلَى حَالِكِ". فَقَالَتْ: نَعَمْ، فَقَالَ: "أَلَا أُعَلِّمُكِ كَلِمَاتٍ تَقُولِينَهَا: سُبْحَانَ اللَّهِ عَدَدَ خَلْقِهِ، سُبْحَانَ اللَّهِ عَدَدَ خَلْقِهِ، سُبْحَانَ اللَّهِ عَدَدَ خَلْقِهِ، سُبْحَانَ اللَّهِ رِضَى نَفْسِهِ، سُبْحَانَ اللَّهِ رِضَى نَفْسِهِ، سُبْحَانَ اللَّهِ رِضَا نَفْسِهِ، سُبْحَانَ اللَّهِ زِنَةَ عَرْشِهِ، سُبْحَانَ اللَّهِ زِنَةَ عَرْشِهِ، سُبْحَانَ اللَّهِ زِنَةَ عَرْشِهِ. سُبْحَانَ اللَّهِ مِدَادَ كَلِمَاتِهِ، سُبْحَانَ اللَّهِ مِدَادَ كَلِمَاتِهِ، سُبْحَانَ اللَّهِ مِدَادَ كَلِمَاتِهِ". حَسَنٌ صَحِيحٌ. (م,ت,ن,جه)', 'ജുവൈരിയ്യ ബിൻതു ഹാരിസ്(റ): അവർ അവരുടെ പള്ളിയിലിരിക്കെ അവരുടെ അടുത്തുകൂടെ നബി(സ) നടന്നു പോയി, പിന്നെ ഉച്ചയോടടുത്ത സമയത്തും അവിടുന്ന് അതുവഴി നടന്നു പോയി. അപ്പോൾ നബി(സ) അവരോട് ചോദിച്ചു: "നീ നിന്റെ ഇതേ അവസ്ഥയിൽ തന്നെ ആയിരുന്നോ?." മഹതി പറഞ്ഞു: അതെ. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നിനക്ക് ചൊല്ലാനായി ചില വചനങ്ങൾ ഞാൻ പഠിപ്പിച്ചു തരട്ടെയോ? (നീ പറയുക: അല്ലാഹുവിനെ അവന്റെ സൃഷ്ടികളുടെ എണ്ണംകണക്കേ ഞാൻ വാഴ്ത്തുന്നു, അല്ലാഹുവിനെ അവന്റെ സൃഷ്ടികളുടെ എണ്ണംകണക്കേ ഞാൻ വാഴ്ത്തുന്നു, അല്ലാഹുവിനെ അവന്റെ സൃഷ്ടികളുടെ എണ്ണംകണക്കേ ഞാൻ വാഴ്ത്തുന്നു, അല്ലാഹുവിനെ അവൻ സ്വയം തൃപ്തിപ്പെടുമാറ് ഞാൻ വാഴ്ത്തുന്നു, അല്ലാഹുവിനെ അവൻ സ്വയം തൃപ്തിപ്പെടുമാറ് ഞാൻ വാഴ്ത്തുന്നു, അല്ലാഹുവിനെ അവൻ സ്വയം തൃപ്തിപ്പെടുമാറ് ഞാൻ വാഴ്ത്തുന്നു, അല്ലാഹുവിനെ അവന്റെ അർശിന്റെ തൂക്കത്തിന് അനുസരിച്ച് ഞാൻ പരിശുദ്ധനാക്കുന്നു, അല്ലാഹുവിനെ അവന്റെ അർശിന്റെ തൂക്കത്തിന് അനുസരിച്ച് ഞാൻ പരിശുദ്ധനാക്കുന്നു, അല്ലാഹുവിനെ അവന്റെ അർശിന്റെ തൂക്കത്തിന് അനുസരിച്ച് ഞാൻ പരിശുദ്ധനാക്കുന്നു, അല്ലാഹുവിനെ അവന്റെ വചനങ്ങളുടെ എണ്ണമത്രയും ഞാൻ വാഴ്ത്തുന്നു, അല്ലാഹുവിനെ അവന്റെ വചനങ്ങളുടെ എണ്ണമത്രയും ഞാൻ വാഴ്ത്തുന്നു, അല്ലാഹുവിനെ അവന്റെ വചനങ്ങളുടെ എണ്ണമത്രയും ഞാൻ വാഴ്ത്തുന്നു." (മു,തു,ന,ജ)', 'جُوَيْرِيَةَ بِنْتِ الْحَارِثِ', 'ജുവൈരിയ്യ ബിൻതു ഹാരിസ്(റ)', null, null, array['م','ت','ن','جه']::text[], array['മു','തു','ന','ജ']::text[], null, null, 966, 966, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=101 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 251, 'عَنْ سَلْمَانَ الْفَارِسِيِّ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ اللَّهَ حَيِيٌّ كَرِيمٌ، يَسْتَحْيِي إِذَا رَفَعَ الرَّجُلُ إِلَيْهِ يَدَيْهِ أَنْ يَرُدَّهُمَا صِفْرًا خَائِبَتَيْنِ". حَسَنٌ. (د,ت,جه)', 'സൽമാനുൽ ഫാരിസി(റ): നബി(സ) പറഞ്ഞു: അല്ലാഹു ലജ്ജാശീലനും മാന്യതയുള്ളവനുമാണ്. തന്നിലേക്ക് ഉയർത്തപ്പെട്ട ആളുടെ കൈ വെറുതെ മടക്കാൻ അവൻ ലജ്ജിക്കുന്നു. (ദ,തു,ജ)', 'سَلْمَانَ الْفَارِسِيِّ', 'സൽമാനുൽ ഫാരിസി(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 966, 966, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=102 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 252, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا كَانَ يَدْعُو بِإِصْبَعَيْهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَحِّدْ أَحِّدْ". حَسَنٌ صَحِيحٌ. (ت,ن)', 'അബൂഹുറൈറ(റ): ഒരാൾ തന്റെ രണ്ട് വിരൽ കൊണ്ട് പ്രാർത്ഥിക്കുകയായിരുന്നു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നീ ഒറ്റയാക്ക്, ഒറ്റയാക്ക്" (തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 966, 967, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=102 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 253, 'عَنْ شَدَّادِ ابْنِ أَوْسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهُ: "أَلَا أَدُلُّكَ عَلَى سَيِّدِ الِاسْتِغْفَارِ: اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، وَأَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ وَأَعْتَرِفُ بِذُنُوبِي، فَاغْفِرْ لِي ذُنُوبِي، إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ. لَا يَقُولُهَا أَحَدُكُمْ حِينَ يُمْسِي فَيَأْتِي عَلَيْهِ قَدَرٌ قَبْلَ أَنْ يُصْبِحَ إِلَّا وَجَبَتْ لَهُ الْجَنَّةُ، وَلَا يَقُولُهَا حِينَ يُصْبِحُ فَيَأْتِي عَلَيْهِ قَدَرٌ قَبْلَ أَنْ يُمْسِيَ إِلَّا وَجَبَتْ لَهُ الْجَنَّةُ". حَسَنٌ. (خ,د,ت,ن,جه)', 'ശദ്ദാദുബ്നു ഔസ്(റ): നബി(സ) അദ്ദേഹത്തോട് പറഞ്ഞു: "പാപമോചനങ്ങളുടെ നേതാവിനെക്കുറിച്ച് നിനക്ക് ഞാൻ പറഞ്ഞ് തരട്ടെയോ? ''അല്ലാഹുവേ, നീയാണെന്റെ രക്ഷിതാവ്, നീയല്ലാതെ ആരാധ്യനില്ല, നീ എന്നെ സൃഷ്ടിച്ചു. ഞാൻ നിന്റെ അടിമയാണ്, എന്റെ കഴിവിന്റെ പരമാവധി നിന്നോടുള്ള കരാറും ഉടമ്പടിയും ഞാൻ പാലിച്ചു പോരുന്നു, ഞാൻ ചെയ്ത എല്ലാ പ്രവർത്തനങ്ങളുടെയും തിന്മയിൽ നിന്ന് നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു, നീ എനിക്ക് ചെയ്ത അനുഗ്രഹങ്ങളെ ഞാൻ അംഗീകരിക്കുന്നു, എന്റെ പാപങ്ങളെ ഞാൻ സമ്മതിക്കുന്നു, അത് കൊണ്ട് എന്റെ പാപങ്ങളെ നീ പൊറുത്ത് തരേണമേ, നിശ്ചയം, നീയല്ലാതെ ഒരാളും പാപങ്ങൾ പൊറുക്കുകയില്ല.'' ഇത് ആരെങ്കിലും പ്രദോഷ സമയത്ത് ചൊല്ലുകയും പ്രഭാതത്തിന് മുമ്പ് അവന്റെ വിധിയെത്തുകയും ചെയ്താൽ സ്വർഗ്ഗം അവന് നിർബന്ധമായിരിക്കുന്നു, ആരെങ്കിലും പ്രഭാത സമയത്ത് ചൊല്ലി പ്രദോഷത്തിന് മുമ്പ് അവന്റെ വിധിയെത്തിയാൽ അവന് സ്വർഗ്ഗം നിർബന്ധമായിരിക്കുന്നു. (ബു,ദ,തു,ന,ജ)', 'شَدَّادِ ابْنِ أَوْسٍ', 'ശദ്ദാദുബ്നു ഔസ്(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 967, 967, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=103 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 254, 'عَنْ عَبْدِ اللَّهِ بْنِ يَزِيدَ الْخَطْمِيِّ الْأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ كَانَ يَقُولُ فِي دُعَائِهِ: "اللَّهُمَّ ارْزُقْنِي حُبَّكَ، وَحُبَّ مَنْ يَنْفَعُنِي حُبُّهُ عِنْدَكَ. اللَّهُمَّ مَا رَزَقْتَنِي مِمَّا أُحِبُّ فَاجْعَلْهُ قُوَّةً لِي فِيمَا تُحِبُّ. اللَّهُمَّ وَمَا زَوَيْتَ عَنِّي مِمَّا أُحِبُّ فَاجْعَلْهُ فَرَاغًا لِي فِيمَا تُحِبُّ". حَسَنٌ. (ت)', 'അബ്ദുല്ലാഹിബ്നു യസീദ്(റ): റസൂൽ(സ) തന്റെ ദുആയിൽ ഇപ്രകാരം പറയുമായിരുന്നു: "അല്ലാഹുവേ, എനിക്ക് നീ നിന്നോടുള്ള സ്നേഹം നൽകേണമേ, ആരോടുള്ള സ്നേഹമാണോ നിന്റെ അടുക്കൽ ഉപകാരപ്പെടുന്നത് അവരോടുള്ള സ്നേഹവും എനിക്ക് നൽകേണമേ, അല്ലാഹുവേ ഞാനിഷ്ടപ്പെടുന്നതിൽ നിന്ന് എനിക്ക് നീ നൽകിയത് നിന്റെ ഇഷ്ടപ്രകാരം പ്രവർത്തിക്കുന്നതിന് എനിക്കുള്ള ശക്തിയാക്കേണമേ. അല്ലാഹുവേ, ഞാനിഷ്ടപ്പെടുന്നതിൽ നിന്ന് നീ എനിക്ക് നൽകാത്തതിനെ നീ ഇഷ്ടപ്പെടുന്നതിൽ മുഴുകാനുള്ള കാരണമാക്കേണമേ. (തു)', 'عَبْدِ اللَّهِ بْنِ يَزِيدَ الْخَطْمِيِّ الْأَنْصَارِيِّ', 'അബ്ദുല്ലാഹിബ്നു യസീദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 967, 967, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=103 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 255, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قَالَ حِينَ يُمْسِي ثَلَاثَ مَرَّاتٍ: أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ، لَمْ يَضُرَّهُ حُمَةٌ تِلْكَ اللَّيْلَةَ". قَالَ تُرْمُذِي هَذَا حَدِيثٌ حَسَنٌ. (ت)', 'അബൂഹുറൈറ(റ): നബി(സ) പറയുന്നു: "അല്ലാഹുവിന്റെ പൂർണ്ണമായ വചനങ്ങൾ കൊണ്ട് അവൻ സൃഷ്ടിച്ച എല്ലാ നാശത്തിൽ നിന്നും ഞാൻ കാവൽ ചോദിക്കുന്നു'' എന്ന് ആരെങ്കിലും മൂന്ന്പ്രാവശ്യം പറഞ്ഞാൽ ആ രാത്രി അവനെ യാതൊന്നും ബുദ്ധിമുട്ടിക്കുകയില്ല." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 967, 967, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=103 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 256, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِأَبِي: "يَا حُصَيْنُ، كَمْ تَعْبُدُ الْيَوْمَ إِلَهًا؟". قَالَ أَبِي: سَبْعَةً سِتَّةً فِي الْأَرْضِ وَوَاحِدًا فِي السَّمَاءِ. قَالَ: "فَأَيُّهُمْ تَعُدُّ لِرَغْبَتِكَ وَرَهْبَتِكَ؟". قَالَ: الَّذِي فِي السَّمَاءِ. قَالَ: "يَا حُصَيْنُ، أَمَا إِنَّكَ لَوْ أَسْلَمْتَ عَلَّمْتُكَ كَلِمَتَيْنِ تَنْفَعَانِكَ". قَالَ: فَلَمَّا أَسْلَمَ حُصَيْنٌ قَالَ: يَا رَسُولَ اللَّهِ، عَلِّمْنِي الْكَلِمَتَيْنِ اللَّتَيْنِ وَعَدْتَنِي. فَقَالَ: "قُلْ: اللَّهُمَّ أَلْهِمْنِي رُشْدِي، وَأَعِذْنِي مِنْ شَرِّ نَفْسِي". حَسَنٌ. (ت)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): നബി(സ) എന്റെ പിതാവിനോട് പറഞ്ഞു: "ഹുസൈനേ, ഇപ്പോൾ നീ എത്ര ദൈവങ്ങളെ ആരാധിക്കുന്നുണ്ട്?." എന്റെ പിതാവ് പറഞ്ഞു: ഏഴ്, ആറെണ്ണം ഭൂമിയിലും ഒരെണ്ണം ആകാശത്തുമാണ്. തിരുമേനി(സ) ചോദിച്ചു: "നിങ്ങളുടെ ഇഷ്ടാനിഷ്ടങ്ങൾ അവരിൽനിന്ന് ആര് നടത്തിത്തരുമെന്നാണ് നിങ്ങൾ പ്രതീക്ഷിക്കുന്നത്.?" അദ്ദേഹം പറഞ്ഞു: ആകാശത്തുള്ളവൻ. നബി(സ) പറഞ്ഞു: "ഹുസൈനേ, നീ മുസ്‌ലിമായാൽ നിനക്ക് ഉപകാരപ്പെടുന്ന രണ്ട് വചനങ്ങളെ ഞാൻ പഠിപ്പിച്ച് തരാം." നിവേദകൻ പറയുന്നു: അങ്ങനെ ഹുസൈൻ മുസ്‌ലിമായപ്പോൾ റസൂൽ(സ)യോട് പറഞ്ഞു: അല്ലാഹുവിന്റെ തിരുദൂതരെ, അവിടുന്ന് എനിക്ക് വാഗ്ദാനം ചെയ്ത രണ്ട് വചനങ്ങൾ പഠിപ്പിച്ച് തന്നാലും. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "നീ പറയുക, അല്ലാഹുവേ, എനിക്ക് നീ സന്മാർഗത്തെ തോന്നിപ്പിക്കേണമേ. എന്റെ ശരീരത്തിന്റെ നാശത്തിൽ നിന്നും എനിക്ക് നീ കാവൽ നൽകേണമേ. (തു)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 968, 968, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=104 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 257, 'عَنْ زِرِّ بْنِ حُبَيْشٍ قَالَ: أَتَيْتُ صَفْوَانَ بْنَ عَسَّالٍ الْمُرَادِيَّ - رَضِيَ اللَّهُ عَنْهُ - أَسْأَلُهُ عَنِ الْمَسْحِ عَلَى الْخُفَّيْنِ، فَقَالَ: مَا جَاءَ بِكَ يَا زِرُّ؟ فَقُلْتُ ابْتِغَاءَ الْعِلْمِ. فَقَالَ: "إِنَّ الْمَلَائِكَةَ لَتَضَعُ أَجْنِحَتَهَا لِطَالِبِ الْعِلْمِ رِضًا بِمَا يَطْلُبُ". فَقُلْتُ: إِنَّهُ حَكَّ فِي صَدْرِي الْمَسْحُ عَلَى الْخُفَّيْنِ بَعْدَ الْغَائِطِ وَالْبَوْلِ، وَكُنْتَ امْرَأً مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجِئْتُ أَسْأَلُكَ: هَلْ سَمِعْتَهُ يَذْكُرُ فِي ذَلِكَ شَيْئًا؟ قَالَ: نَعَمْ، كَانَ يَأْمُرُنَا إِذَا كُنَّا سَفْرًا - أَوْ: مُسَافِرِينَ - أَنْ لَا نَنْزِعَ خِفَافَنَا ثَلَاثَةَ أَيَّامٍ وَلَيَالِيهِنَّ إِلَّا مِنْ جَنَابَةٍ، لَكِنْ مِنْ غَائِطٍ وَبَوْلٍ وَنَوْمٍ. قَالَ: فَقُلْتُ: هَلْ سَمِعْتَهُ يَذْكُرُ فِي الْهَوَى شَيْئًا؟ قَالَ: نَعَمْ، كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَبَيْنَا نَحْنُ عِنْدَهُ إِذْ نَادَاهُ أَعْرَابِيٌّ بِصَوْتٍ لَهُ جَهْوَرِيٍّ: يَا مُحَمَّدُ. فَأَجَابَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَحْوًا مِنْ صَوْتِهِ: "هَاؤُمُ". فَقُلْنَا لَهُ: وَيْحَكَ اغْضُضْ مِنْ صَوْتِكَ، فَإِنَّكَ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَقَدْ نُهِيتَ عَنْ هَذَا. فَقَالَ: وَاللَّهِ لَا أَغْضُضُ. قَالَ الْأَعْرَابِيُّ: الْمَرْءُ يُحِبُّ الْقَوْمَ وَلَمَّا يَلْحَقْ بِهِمْ؟ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْمَرْءُ مَعَ مَنْ أَحَبَّ يَوْمَ الْقِيَامَةِ". فَمَا زَالَ يُحَدِّثُنَا حَتَّى ذَكَرَ بَابًا مِنْ قِبَلِ الْمَغْرِبِ مَسِيرَةَ سَبْعِينَ عَامًا - عَرْضُهُ - أَوْ: يَسِيرُ الرَّاكِبُ فِي عَرْضِهِ أَرْبَعِينَ أَوْ سَبْعِينَ عَامًا، قِبَلَ الشَّامِ، خَلَقَهُ اللَّهُ يَوْمَ خَلَقَ السَّمَوَاتِ وَالْأَرْضَ مَفْتُوحًا - يَعْنِي - لِلتَّوْبَةِ، لَا يُغْلَقُ حَتَّى تَطْلُعَ الشَّمْسُ مِنْهُ". حَسَنٌ صَحِيحٌ. (ت,ن,جه)', 'സിർറ്ബിൻ ഹുബൈശ്(റ): ഞാൻ സ്വഫ്വാനുബ്നു അസ്സ്വാലിൽ മുറാദി എന്നവരുടെയടുത്ത് ഖുഫ്ഫയുടെ മേൽ തടവുന്നതിനെക്കുറിച്ച് ചോദിക്കാൻ പോയി. അപ്പോൾ സ്വഫ്വാൻ(റ) ചോദിച്ചു: സിർറേ എന്തിനാണ് നിങ്ങൾ വന്നത്? ഞാൻ പറഞ്ഞു: അറിവ് ചോദിച്ചു വന്നതാണ്. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: "അറിവ് ചോദിക്കുന്നവന്, അവന്റെ തേട്ടത്തെ ഇഷ്ടപ്പെട്ടതുകാരണം മലക്കുകൾ അവരുടെ ചിറകുകളെ നിവർത്തി കൊടുക്കും." ഞാൻ പറഞ്ഞു: മലമൂത്രവിസർജ്ജനത്തിനുശേഷം ഖുഫ്ഫയുടെ മുകളിലൂടെ തടവുന്നതിനെക്കുറിച്ച് എന്റെ ഹൃദയത്തിൽ ഒരു സംശയമുണ്ട്. നിങ്ങൾ നബി(സ)യുടെ അനുചരരിൽ പെട്ടവരല്ലെയോ. അത് കൊണ്ട് അതിനെ കുറിച്ച് വല്ലതും താങ്കൾ കേട്ടിട്ടുണ്ടോ എന്ന് ചോദിക്കാൻ വന്നതാണ് ഞാൻ. അദ്ദേഹം പറഞ്ഞു: അതെ. ഞങ്ങൾ യാത്രയിലായിരുന്നപ്പോൾ അവിടുന്ന് ഇപ്രകാരം കൽപിക്കുമായിരുന്നു: മൂന്ന് ദിവസം നിങ്ങൾ ഖുഫ്ഫ അഴിക്കരുത്, ജനാബത്തുണ്ടായാൽ ഒഴികെ. ഉറക്കമോ ചെറിയ അശുദ്ധിയോ ഉണ്ടായാൽ അഴിക്കുമായിരുന്നില്ല. നിവേദകൻ പറയുന്നു: അപ്പോൾ ഞാൻ ചോദിച്ചു: സ്നേഹത്തെക്കുറിച്ച് അവിടുന്ന് വല്ലതും പറയുന്നതായി താങ്കൾ കേട്ടിട്ടുണ്ടോ? അദ്ദേഹം പറഞ്ഞു: അതെ, ഒരിക്കൽ ഞങ്ങൾ റസൂൽ(സ)യുടെ കൂടെ യാത്രയിലായിരുന്നു, അങ്ങനെ ഞങ്ങൾ തിരുമേനി(സ)യുടെ തൊട്ടടുത്തായിരുന്നപ്പോൾ ഒരു അഅ്റാബി ഉച്ചത്തിൽ വിളിച്ചു: ഓ മുഹമ്മദേ. അപ്പോൾ നബി(സ) അതേ ശബ്ദത്തിൽ പറഞ്ഞു: "ഇവിടെ വരൂ." അപ്പോൾ അദ്ദേഹത്തോട് ഞങ്ങൾ പറഞ്ഞു: നിനക്ക് നാശം, നീ ശബ്ദം കുറക്കുക. കാരണം നീ നബി(സ)യുടെ അടുത്താകുന്നു, ഇത് നിരോധിക്കപ്പെട്ടിരിക്കുന്നു. അദ്ദേഹം പറഞ്ഞു: അല്ലാഹു തന്നെ സത്യം! ഞാൻ കുറക്കുകയില്ല. അഅ്റാബി ചോദിച്ചു: ഒരു സമുദായത്തെ സ്നേഹിക്കുകയും അവരോട് ഇതുവരെ കൂടിയിട്ടുമില്ലാത്ത ഒരു മനുഷ്യന്റെ അവസ്ഥ എന്താണ്? നബി(സ) പറഞ്ഞു: "താൻ ആരെയാണ് സ്നേഹിച്ചത് അവരുടെ കൂടെയായിരിക്കും അന്ത്യനാളിൽ അവൻ." അവിടന്ന് ഞങ്ങളോട് ഹദീസ് പറഞ്ഞ് കൊണ്ടേയിരുന്നു. അങ്ങനെ പടിഞ്ഞാറ് ഭാഗത്തുള്ള ഒരു വാതിലിനെ കുറിച്ച് പറഞ്ഞു, അതിന്റെ വീതി എഴുപത് വർഷത്തെ വഴിദൂരമാണ്. അല്ലെങ്കിൽ വാഹനം കൊണ്ടുള്ള നാൽപ്പതോ എഴുപതോ വർഷമാകുന്നു. അത് ശാമിന്റെ ഭാഗമാകുന്നു. ആകാശഭൂമികളെ പടച്ച ദിവസം അല്ലാഹു അതിനെ ഉണ്ടാക്കുകയും തൗബക്ക് തുറന്നിട്ടിരിക്കുകയും ചെയ്തിരിക്കുന്നു. പടിഞ്ഞാറിൽ നിന്ന് സൂര്യനുദിക്കുന്നത് വരെ അത് അടക്കപ്പെടുകയില്ല. (തു,ന,ജ)', 'زِرِّ بْنِ حُبَيْشٍ قَالَ', 'സിർറ്ബിൻ ഹുബൈശ്(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 968, 969, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 258, 'عَنْ أَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا أَصَرَّ مَنِ اسْتَغْفَرَ، وَلَوْ فَعَلَهُ فِي الْيَوْمِ سَبْعِينَ مَرَّةً". (د,ت)', 'അബൂബക്കർ(റ): റസൂൽ(സ) പറയുന്നു: "പൊറുക്കലിനെ ചോദിച്ചവർ ദിവസവും എഴുപത് പ്രാവശ്യം തെറ്റ്ചെയ്യുകയാണെങ്കിലും തെറ്റിൽ സ്ഥിരമായിട്ടില്ല." (ദ,തു)', 'أَبِي بَكْرٍ', 'അബൂബക്കർ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 969, 969, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=106 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 259, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَبِسَ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ ثَوْبًا جَدِيدًا، فَقَالَ: الْحَمْدُ لِلَّهِ الَّذِي كَسَانِي مَا أُوَارِي بِهِ عَوْرَتِي، وَأَتَجَمَّلُ بِهِ فِي حَيَاتِي. ثُمَّ عَمَدَ إِلَى الثَّوْبِ الَّذِي أَخْلَقَ فَتَصَدَّقَ بِهِ، ثُمَّ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ لَبِسَ ثَوْبًا جَدِيدًا فَقَالَ: الْحَمْدُ لِلَّهِ الَّذِي كَسَانِي مَا أُوَارِي بِهِ عَوْرَتِي، وَأَتَجَمَّلُ بِهِ فِي حَيَاتِي. ثُمَّ عَمَدَ إِلَى الثَّوْبِ الَّذِي أَخْلَقَ فَتَصَدَّقَ بِهِ، كَانَ فِي كَنَفِ اللَّهِ وَفِي حِفْظِ اللَّهِ وَفِي سِتْرِ اللَّهِ، حَيًّا وَمَيِّتًا". (ت,جه)', 'അബൂഉമാമ(റ): ഉമറുബ്നുൽ ഖത്താബ്(റ) ഒരു പുതിയ വസ്ത്രം ധരിച്ചു, അപ്പോഴദ്ദേഹം ഇങ്ങനെ പറഞ്ഞു: ''എന്റെ ഔറത്ത് മറക്കാനും ഈ ജീവിതത്തിൽ എനിക്ക് സുന്ദരനാകാനുമുതകുന്ന (വസ്ത്രത്തെ) എനിക്ക് ധരിപ്പിച്ച് തന്ന അല്ലാഹുവിനാണ് സർവ്വ സ്തുതിയും.'' പിന്നെ പഴയ വസ്ത്രമെടുത്ത് ദാനം ചെയ്തു. എന്നിട്ടദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടിട്ടുണ്ട്: "ആരെങ്കിലും പുതിയ വസ്ത്രം ധരിക്കുകയും എന്നിട്ട് ''എന്റെ ഔറത്ത് മറക്കാനും എന്റെ ജീവിതത്തിൽ എനിക്ക് സുന്ദരനാകാനുമുതകുന്ന വസ്ത്രത്തെ എന്നെ ധരിപ്പിച്ച അല്ലാഹുവിനാണ് സർവ്വ സ്തുതിയും'' എന്ന് പറയുകയും, ശേഷം തന്റെ പഴയ വസ്ത്രം ദാനം ചെയ്യുകയും ചെയ്താൽ മരിച്ച് കഴിഞ്ഞാലും ജീവിച്ചിരിക്കുമ്പോഴും അവൻ അല്ലാഹുവിന്റെ സഹായത്തിലും അല്ലാഹുവിന്റെ സംരക്ഷണത്തിലും അല്ലാഹുവിന്റെ മറയിലുമായിരിക്കും." (തു,ജ)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 969, 970, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=107 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 260, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَتْ فَاطِمَةُ رَضِيَ اللَّهُ عَنْهَا إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَسْأَلُهُ خَادِمًا، فَقَالَ لَهَا: "قُولِي: اللَّهُمَّ رَبَّ السَّمَوَاتِ السَّبْعِ وَرَبَّ الْعَرْشِ الْعَظِيمِ، رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، مُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيلِ وَالْقُرْآنِ، فَالِقَ الْحَبِّ وَالنَّوَى: أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أَنْتَ آخِذٌ بِنَاصِيَتِهِ، أَنْتَ الأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الْآخِرُ فَلَيْسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اقْضِ عَنِّي الدَّيْنَ وَأَغْنِنِي مِنَ الْفَقْرِ. حَسَنٌ. (م,ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) തങ്ങളുടെ തിരുസന്നിധിയിൽ ഫാതിമ(റ) ഒരു പരിചാരകനെ ചോദിച്ചു കൊണ്ടു വന്നു. അപ്പോൾ അവിടുന്ന് അവരോട് പറഞ്ഞു: "നീ പറയുക, ഏഴാകാശങ്ങളുടെയും ശ്രേഷ്ഠമായ സിംഹാസനത്തിന്റെയും രക്ഷിതാവായ അല്ലാഹുവേ, ഞങ്ങളുടെയും മറ്റു സകല വസ്തുക്കളുടെയും രക്ഷിതാവേ, ഇൻജീലും, തൗറാത്തും, ഖുർആനും ഇറക്കിയവനെ, വിത്തുകളെയും ധാന്യത്തെയും പൊളിക്കുന്നവനേ, നീ നിയന്ത്രിച്ച് കൊണ്ടിരിക്കുന്ന എല്ലാ വസ്തുക്കളുടെയും വിപത്തിൽനിന്ന് നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു. നീയാണ് ആദ്യമുള്ളവൻ, നിനക്ക് മുമ്പ് ഒന്നുംതന്നെയില്ല. നീയാണ് അന്ത്യം, നിനക്ക് ശേഷം ഒന്നുമില്ല. നീയാണ് പ്രത്യക്ഷമായവൻ, നിനക്ക് മുകളിലായി ഒന്നുമില്ല. നീയാണ് പരോക്ഷമായവൻ, നിനക്ക് താഴെ ഒന്നുമില്ല. എന്റെ കടം വീട്ടുകയും എന്നെ ദാരിദ്ര്യത്തിൽ നിന്നും ഐശ്വര്യമാക്കുകയും ചെയ്യേണമേ. (മു,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 970, 970, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=108 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 261, 'عَنْ أَبِي بَكْرِ الصِّدِّيقِ - رَضِيَ اللَّهُ عَنْهُ - أَنَّهُ قَالَ: يَا رَسُولَ اللَّهِ، عَلِّمْنِي دُعَاءً أَدْعُو بِهِ فِي صَلَاتِي. قَالَ: "قُلِ اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا، وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ، وَارْحَمْنِي، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ". حَسَنٌ صَحِيحٌ. (ق,ت,ن,جه)', 'അബൂബക്കർ സിദ്ദീഖ്(റ): അബൂബക്കർ(റ) പറഞ്ഞു: തിരുദൂതരെ, എനിക്ക് നിസ്കാരത്തിൽ ദുആ ചെയ്യാൻ ഒരു ദുആ പഠിപ്പിച്ച് തരണം. തിരുമേനി(സ) പറഞ്ഞു: "നിങ്ങൾ ഇപ്രകാരം പറയുക: അല്ലാഹുവേ, ഞാൻ എന്റെ ശരീരത്തോട് വളരെയധികം അക്രമം കാണിച്ചു, പാപങ്ങളെ പൊറുക്കുന്നവൻ നീ മാത്രമാണ്. അത് കൊണ്ട് എനിക്ക് പൊറുത്ത് തരേണമേ, എന്നോട് കരുണ ചെയ്യണേ. നീ തീർച്ചയായും കൂടുതൽ പൊറുക്കുന്നവനും കരുണ കാണിക്കുന്നവനുമാകുന്നു." (ബു,മു,തു,ന,ജ)', 'أَبِي بَكْرِ الصِّدِّيقِ -', 'അബൂബക്കർ സിദ്ദീഖ്(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 970, 971, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 262, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، رَأَيْتُنِي اللَّيْلَةَ وَأَنَا نَائِمٌ كَأَنِّي أُصَلِّي خَلْفَ شَجَرَةٍ، فَسَجَدْتُ فَسَجَدَتِ الشَّجَرَةُ لِسُجُودِي، وَسَمِعْتُهَا وَهِيَ تَقُولُ: اللَّهُمَّ اكْتُبْ لِي بِهَا عِنْدَكَ أَجْرًا، وَضَعْ عَنِّي بِهَا وِزْرًا، وَاجْعَلْهَا لِي عِنْدَكَ ذُخْرًا، وَتَقَبَّلْهَا مِنِّي كَمَا تَقَبَّلْتَهَا مِنْ عَبْدِكَ دَاوُدَ. قَالَ ابْنُ عَبَّاسٍ: فَقَرَأَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَجْدَةً ثُمَّ سَجَدَ، فَسَمِعْتُهُ وَهُوَ يَقُولُ مِثْلَ مَا أَخْبَرَهُ الرَّجُلُ عَنْ قَوْلِ الشَّجَرَةِ. (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരാൾ തിരുദൂതരുടെ തിരുസന്നിധിയിൽ വന്നു പറഞ്ഞു: തിരുദൂതരെ, രാത്രിയിൽ ഞാൻ സ്വപ്നം കണ്ടു. ഞാൻ ഒരു മരത്തിന്റെ പിന്നിലായി നിസ്കരിക്കുന്നു. ഞാൻ സുജൂദ് ചെയ്തപ്പോൾ ആ മരവും സുജൂദ് ചെയ്തു. ആ മരം പറയുന്നുണ്ടായിരുന്നു: അല്ലാഹുവേ, അത് കാരണമായി എനിക്ക് നീ നിന്റെ അടുക്കൽ പ്രതിഫലം എഴുതി വെക്കേണമേ, അത് കാരണമായി എന്റെ പാപഭാരം എന്നിൽ നിന്നും നീ ഇറക്കി വെക്കേണമേ, അതിനെ നിന്റെ അടുക്കൽ എനിക്കുള്ള സൂക്ഷിപ്പ് സ്വത്താക്കേണമേ, നീ അതിനെ എന്നിൽ നിന്ന് സ്വീകരിക്കേണമേ, നിന്റെ അടിമ ദാവൂദി(അ)ൽ നിന്നും സ്വീകരിച്ച പോലെ. ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: അപ്പോൾ നബി(സ) സജദഃയുടെ സൂക്തം ഓതുകയും സുജൂദ് ചെയ്യുകയും ചെയ്തു. ആ മരം പറഞ്ഞതായി അയാൾ അറിയിച്ചത് നബി(സ) സുജൂദിൽ പറഞ്ഞതായി ഞാൻ കേട്ടു. (തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 971, 971, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=110 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 263, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ فِي سُجُودِ الْقُرْآنِ بِاللَّيْلِ: "سَجَدَ وَجْهِيَ لِلَّذِي خَلَقَهُ وَشَقَّ سَمْعَهُ وَبَصَرَهُ بِحَوْلِهِ وَقُوَّتِهِ". حَسَنٌ صَحِيحٌ. (د,ت,ن,جه)', 'ആഇശ(റ): നബി(സ) രാത്രിയിൽ അവിടത്തെ തിലാവത്തിന്റെ സുജൂദിൽ പറയുമായിരുന്നു: "എന്റെ മുഖം, അതിനെ പടക്കുകയും അതിന്റെ കേൾവിയും കാഴ്ചയും തന്റെ ശക്തി കൊണ്ടും കഴിവ് കൊണ്ടും കീറിയുണ്ടാക്കുകയും ചെയ്തവന് വണങ്ങിയിരിക്കുന്നു." (ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 971, 971, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=110 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 264, 'عَنْ فَضَالَةَ بْنِ عُبَيْدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَاعِدٌ إِذْ دَخَلَ رَجُلٌ فَصَلَّى، فَقَالَ: اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "عَجِلْتَ أَيُّهَا الْمُصَلِّي، إِذَا صَلَّيْتَ فَقَعَدْتَ فَاحْمَدِ اللَّهَ بِمَا هُوَ أَهْلُهُ، وَصَلِّ عَلَيَّ، ثُمَّ ادْعُهُ". قَالَ: ثُمَّ صَلَّى رَجُلٌ آخَرُ بَعْدَ ذَلِكَ فَحَمِدَ اللَّهَ وَصَلَّى عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَيُّهَا الْمُصَلِّي ادْعُ تُجَبْ". حَسَنٌ. (ت)', 'ഫുളാലതുബ്നു ഉബൈദ്(റ): റസൂൽ(സ) ഇരിക്കുകയായിരുന്നു. അപ്പോൾ ഒരാൾ വന്നു നിസ്കരിച്ചു. എന്നിട്ട് പറഞ്ഞു: അല്ലാഹുവേ, എനിക്ക് നീ പൊറുത്ത് തരേണമേ, എന്നോട് കരുണ കാണിക്കുകയും ചെയ്യേണമേ. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിസ്കരിച്ചവനേ നീ ധൃതി കാണിച്ചിരിക്കുന്നു. നീ നിസ്കരിച്ചാൽ ഇരിക്കുകയും അല്ലാഹുവിനെ അവന് അർഹമായത് കൊണ്ട് സ്തുതിക്കുകയും, എന്റെ മേൽ സ്വലാത്ത് ചൊല്ലുകയും പിന്നെ പ്രാർത്ഥിക്കുകയും ചെയ്യണം." നിവേദകൻ പറയുന്നു: ശേഷം ഒരാൾ നിസ്കരിക്കുകയും അല്ലാഹുവിനെ സ്തുതിക്കുകയും നബി(സ)യുടെ മേൽ സ്വലാത്ത് ചൊല്ലുകയും ചെയ്തു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിസ്കരിച്ചവനേ, ദുആ ചെയ്യുക, ഉത്തരം നൽകപ്പെടും." (തു)', 'فَضَالَةَ بْنِ عُبَيْدٍ', 'ഫുളാലതുബ്നു ഉബൈദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 971, 972, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 265, 'عَنْ فَضَالَةَ بْنِ عُبَيْدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلًا يَدْعُو فِي صَلَاتِهِ، فَلَمْ يُصَلِّ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "عَجِلَ هَذَا". ثُمَّ دَعَاهُ، فَقَالَ لَهُ أَوْ لِغَيْرِهِ: "إِذَا صَلَّى أَحَدُكُمْ فَلْيَبْدَأْ بِتَحْمِيدِ اللَّهِ وَالثَّنَاءِ عَلَيْهِ، ثُمَّ لِيُصَلِّ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ لْيَدْعُ بَعْدُ بِمَا شَاءَ". حَسَنٌ صَحِيحٌ. (د,ت,ن)', 'ഫുളാലതുബ്നു ഉബൈദ്(റ): ഒരാൾ നബി(സ)യുടെ മേൽ സ്വലാത്ത് ചൊല്ലാതെ തന്റെ നിസ്കാരത്തിൽ ദുആ ചെയ്യുന്നതായി നബി(സ) കേട്ടു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇദ്ദേഹം ധൃതി കാണിച്ചിരിക്കുന്നു." പിന്നെ അവനെ വിളിച്ചു. എന്നിട്ട് അവനോട്, അല്ലെങ്കിൽ മറ്റൊരാളോട് പറഞ്ഞു: "നിങ്ങൾ ആരെങ്കിലും നിസ്കരിച്ചാൽ അല്ലാഹുവിനെ സ്തുതിച്ചും പ്രകീർത്തിച്ചും തുടങ്ങുകയും പിന്നെ നബി(സ)യുടെ മേൽ സ്വലാത്ത് ചൊല്ലുകയും പിന്നെ അവൻ ഉദ്ദേശിച്ചത് ദുആ ചെയ്യുകയും ചെയ്യട്ടെ." (ദ,തു,ന)', 'فَضَالَةَ بْنِ عُبَيْدٍ', 'ഫുളാലതുബ്നു ഉബൈദ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 972, 972, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 266, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ - رَفَعَهُ - قَالَ: "لَا أَحَدَ أَغْيَرُ مِنَ اللَّهِ، وَلِذَلِكَ حَرَّمَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ، وَلَا أَحَدَ أَحَبُّ إِلَيْهِ الْمَدْحُ مِنَ اللَّهِ، وَلِذَلِكَ مَدَحَ نَفْسَهُ". حَسَنٌ صَحِيحٌ. (ق,ت)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ) - നബി(സ)യിലേക്ക് ചേർത്തിപ്പറയുന്നു: "അല്ലാഹുവിനേക്കാളും ദേഷ്യപ്പെടുന്നവൻ മറ്റാരുമില്ല, അത് കൊണ്ട് തന്നെ എല്ലാ പ്രത്യക്ഷവും പരോക്ഷവുമായ ദുഷിച്ച പ്രവർത്തനങ്ങളെയും അവൻ നിഷിദ്ധമാക്കി, അല്ലാഹുവിനേക്കാൾ സ്തുതി കീർത്തനങ്ങൾ ഇഷ്ടപ്പെടുന്ന മറ്റാരും ഇല്ല, അത് കൊണ്ട് തന്നെയാണ് അല്ലാഹു തന്നെത്തന്നെ സ്തുതിച്ചത്." (ബു,മു,തു)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 972, 972, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=112 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 267, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَعْمَارُ أُمَّتِي مَا بَيْنَ السِّتِّينَ إِلَى السَّبْعِينَ، وَأَقَلُّهُمْ مَنْ يَجُوزُ ذَلِكَ". حَسَنٌ. (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "ഈ സമുദായത്തിന്റെ ആയുസ്സ് അറുപതിന്റെയും എഴുപതിന്റെയും ഇടയിലുള്ളതായിരിക്കും. അത് കടന്നു പോകുന്നവർ വളരെ തുച്ഛമേ ഉണ്ടാകൂ." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 972, 972, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 268, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ اللَّهَ يَقْبَلُ تَوْبَةَ الْعَبْدِ مَا لَمْ يُغَرْغِرْ". حَسَنٌ. (ت،جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറയുന്നു: "തന്റെ റൂഹ് തൊണ്ടക്കുഴിയിൽ എത്തുന്നത് വരെ ഒരു അടിമയുടെ തൗബ അല്ലാഹു സ്വീകരിക്കുന്നതാണ്." (തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 973, 973, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=114 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 269, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَلَّهُ أَفْرَحُ بِتَوْبَةِ أَحَدِكُمْ مِنْ أَحَدِكُمْ بِضَالَّتِهِ إِذَا وَجَدَهَا". حَسَنٌ صَحِيحٌ. (م،ت،جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "നിങ്ങളിലൊരാൾക്ക് തന്റെ നഷ്ടപ്പെട്ടു പോയ ഒട്ടകം തിരിച്ചു കിട്ടുമ്പോഴുണ്ടാകുന്ന സന്തോഷത്തേക്കാൾ, നിങ്ങളിലൊരാളുടെ തൗബകൊണ്ട് അല്ലാഹു സന്തോഷിക്കുന്നവനാണ്." (മു,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 973, 973, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=115 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 270, 'عَنْ أَبِي صِرْمَةَ، عَنْ أَبِي أَيُّوبَ - رَضِيَ اللَّهُ عَنْهُمَا - أَنَّهُ قَالَ حِينَ حَضَرَتْهُ الْوَفَاةُ: قَدْ كَتَمْتُ عَنْكُمْ شَيْئًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَوْلَا أَنَّكُمْ تُذْنِبُونَ لَخَلَقَ اللَّهُ خَلْقًا يُذْنِبُونَ، وَيَغْفِرُ لَهُمْ". حَسَنٌ. (م،ت)', 'അബൂസിർമത്(റ): മരണം ആസന്നമായപ്പോൾ അബൂഅയ്യൂബ്(റ) പറഞ്ഞു: റസൂൽ(സ)യിൽ നിന്ന് കേട്ട ഒരുകാര്യം നിങ്ങളിൽ നിന്ന് ഞാൻ മറച്ചു വെച്ചിട്ടുണ്ട്. റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "നിങ്ങൾ ദോശം ചെയ്യുന്നവരായിരുന്നില്ലെങ്കിൽ അല്ലാഹു ദോശം ചെയ്യുന്ന സൃഷ്ടികളെ പടക്കുകയും അവർക്ക് പൊറുത്ത് കൊടുക്കുകയും ചെയ്യുമായിരുന്നു." (മു,തു)', 'أَبِي صِرْمَةَ، عَنْ أَبِي أَيُّوبَ -', 'അബൂസിർമത്(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 973, 973, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=116 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 271, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "قَالَ اللَّهُ تَبَارَكَ وَتَعَالَى: يَا ابْنَ آدَمَ، إِنَّكَ مَا دَعَوْتَنِي وَرَجَوْتَنِي غَفَرْتُ لَكَ عَلَى مَا كَانَ فِيكَ، وَلَا أُبَالِي. يَا ابْنَ آدَمَ، لَوْ بَلَغَتْ ذُنُوبُكَ عَنَانَ السَّمَاءِ، ثُمَّ اسْتَغْفَرْتَنِي غَفَرْتُ لَكَ، وَلَا أُبَالِي. يَا ابْنَ آدَمَ، إِنَّكَ لَوْ أَتَيْتَنِي بِقُرَابِ الْأَرْضِ خَطَايَا، ثُمَّ لَقِيتَنِي لَا تُشْرِكُ بِي شَيْئًا، لَأَتَيْتُكَ بِقُرَابِهَا مَغْفِرَةً". حَسَنٌ. (ت)', 'അനസ്(റ): റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടിട്ടുണ്ട്: "അല്ലാഹു പറയുന്നു: ആദമിന്റെ മകനേ, നീ എന്നോട് ദുആ ചെയ്യുകയും എന്നെ പ്രതീക്ഷിച്ചിരിക്കുകയും ചെയ്യുന്ന കാലത്തോളം, നിന്നിലുണ്ടായിരുന്നതെല്ലാം നിനക്ക് ഞാൻ പൊറുത്ത് തരും, എനിക്ക് പ്രശ്നമില്ല. ആദമിന്റെ മകനേ, നിന്റെ ദോശങ്ങൾ ആകാശത്തിന്റെ ചക്രവാളത്തിൽ തട്ടുന്നതാണെങ്കിലും എന്നോട് പൊറുക്കലിനെ ചോദിച്ചാൽ നിനക്ക് ഞാൻ പൊറുത്തുതരും. എനിക്ക് പ്രശ്നമില്ല. ആദമിന്റെ മകനേ, ഭൂമിയെ നിറക്കുന്ന വിധം പാപങ്ങളുമായി നീ വരികയും എന്നോട് ഒന്നിനെയും പങ്കുവെക്കാതെ എന്നെ കണ്ട് മുട്ടുകയും ചെയ്താൽ നിന്നിലേക്ക് ഞാൻ അത്ര മോചനവുമായി വരും." (തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 973, 974, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=117 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 272, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "خَلَقَ اللَّهُ مِائَةَ رَحْمَةٍ، فَوَضَعَ رَحْمَةً وَاحِدَةً بَيْنَ خَلْقِهِ يَتَرَاحَمُونَ بِهَا، وَعِنْدَ اللَّهِ تِسْعٌ وَتِسْعُونَ رَحْمَةً". حَسَنٌ صَحِيحٌ. (م,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു നൂറ് കരുണയെ പടച്ചു. ഒന്നിനെ മാത്രം തന്റെ സൃഷ്ടികൾ തമ്മിൽ കരുണ ചെയ്യുന്നതിനായി വെച്ചു. അല്ലാഹുവിന്റെ അടുക്കലാണ് ബാക്കി 99 കരുണയും." (മു, തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 974, 974, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=118 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 273, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: "لَوْ يَعْلَمُ الْمُؤْمِنُ مَا عِنْدَ اللَّهِ مِنَ الْعُقُوبَةِ مَا طَمِعَ فِي الْجَنَّةِ أَحَدٌ، وَلَوْ يَعْلَمُ الْكَافِرُ مَا عِنْدَ اللَّهِ مِنَ الرَّحْمَةِ مَا قَنِطَ مِنَ الْجَنَّةِ أَحَدٌ". حَسَنٌ. (ت)', 'അബൂഹുറൈറ(റ): "ഒരു മുഅ്മിൻ അല്ലാഹുവിന്റെ ശിക്ഷയെക്കുറിച്ച് അറിയുകയാണെങ്കിൽ ഒരാളും സ്വർഗത്തെ ആഗ്രഹിക്കുകയില്ല, ഇനി ഒരു കാഫിർ അല്ലാഹുവിന്റെ കാരുണ്യത്തെ അറിയുകയാണെങ്കിൽ അവൻ സ്വർഗത്തിൽ നിന്ന് അവൻ നിരാശനാവുകയില്ല." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 974, 974, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=119 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 274, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ اللَّهَ حِينَ خَلَقَ الْخَلْقَ كَتَبَ بِيَدِهِ عَلَى نَفْسِهِ: أَنَّ رَحْمَتِي تَغْلِبُ غَضَبِي". (ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "അല്ലാഹു സൃഷ്ടികളെ പടച്ച സമയത്ത് തന്റെ കൈകൊണ്ട് തന്റെ നഫ്സിൽ എഴുതി. എന്റെ കാരുണ്യം എന്റെ ദേഷ്യത്തെ മറികടക്കും." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 974, 974, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=120 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 275, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "رَغِمَ أَنْفُ رَجُلٍ ذُكِرْتُ عِنْدَهُ فَلَمْ يُصَلِّ عَلَيَّ، وَرَغِمَ أَنْفُ رَجُلٍ دَخَلَ عَلَيْهِ رَمَضَانُ ثُمَّ انْسَلَخَ قَبْلَ أَنْ يُغْفَرَ لَهُ، وَرَغِمَ أَنْفُ رَجُلٍ أَدْرَكَ عِنْدَهُ أَبَوَاهُ - أَوْ أَحَدُهُمَا - الْكِبَرَ فَلَمْ يُدْخِلَاهُ الْجَنَّةَ". حَسَنٌ. (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാളുടെ സന്നിധിയിൽ എന്നെ പറയപ്പെടുകയും എന്റെ മേൽ സ്വലാത്ത് ചൊല്ലാതിരിക്കുകയും ചെയ്താൽ അവൻ നിന്ദ്യനായിരിക്കുന്നു. റമളാൻ കടന്നു വരികയും അവന്റെ ദോഷങ്ങൾ പൊറുക്കപ്പെടാതെ പോകുകയും ചെയ്താൽ അവനും നിന്ദ്യനായിരിക്കുന്നു. ഒരാൾക്ക് വൃദ്ധരായ മാതാപിതാക്കൾ, അല്ലെങ്കിൽ അതിൽ നിന്ന് ഒരാൾ, ഉണ്ടാകുകയും അവർ അവന്റെ സ്വർഗപ്രവേശത്തിന് കാരണമാകുകയും ചെയ്യാതിരുന്നാൽ അവനും നിസ്സാരനത്രേ." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 974, 975, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=121 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 276, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْبَخِيلُ الَّذِي ذُكِرْتُ عِنْدَهُ فَلَمْ يُصَلِّ عَلَيَّ". حَسَنٌ صَحِيحٌ. (ت)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്നെക്കുറിച്ച് പറയപ്പെടുകയും അനന്തരം എന്റെ മേൽ സ്വലാത്ത് ചൊല്ലാതിരിക്കുകയും ചെയ്തവനാണ് പിശുക്കൻ." (തു)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 975, 975, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=121 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 277, 'عَنْ عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "اللَّهُمَّ بَرِّدْ قَلْبِي بِالثَّلْجِ وَالْبَرَدِ وَالْمَاءِ الْبَارِدِ، اللَّهُمَّ نَقِّ قَلْبِي مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الأَبْيَضَ مِنَ الدَّنَسِ". حَسَنٌ صَحِيحٌ. (م,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു അബീഔഫാ(റ): തിരുദൂതർ(സ) പറയാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ, എന്റെ ഹൃദയത്തെ മഞ്ഞ് കൊണ്ടും ഐസ് കൊണ്ടും തണുത്ത വെള്ളം കൊണ്ടും തണുപ്പിക്കേണമേ. അല്ലാഹുവേ, ചളിയിൽ നിന്നും വെള്ള വസ്ത്രം ശുദ്ധിയാക്കിയത് പോലെ നീ എന്റെ ഹൃദയത്തെ പാപങ്ങളിൽ നിന്ന് ശുദ്ധിയാക്കേണമേ." (മു,തു,ന)', 'عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى', 'അബ്ദുല്ലാഹിബ്നു അബീഔഫാ(റ)', null, null, array['م','ت','ن']::text[], array['മു','തു','ന']::text[], null, null, 975, 975, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=122 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 278, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ جَلَسَ فِي مَجْلِسٍ فَكَثُرَ فِيهِ لَغَطُهُ، فَقَالَ قَبْلَ أَنْ يَقُومَ مِنْ مَجْلِسِهِ ذَلِكَ: سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ. إِلَّا غُفِرَ لَهُ مَا كَانَ فِي مَجْلِسِهِ ذَلِكَ". حَسَنٌ صَحِيحٌ. (د,ت,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "ഒരാൾ ഒരു സദസ്സിലിരിക്കുകയും അതിൽ അനാവശ്യമായ സംസാരം അധികരിക്കുകയും ചെയ്തു. അങ്ങനെ ആ മജ്‌ലിസിൽ നിന്ന് എഴുന്നേൽക്കുന്നതിന് മുമ്പ് അവൻ: ''അല്ലാഹുവേ, നീ എത്ര പരിശുദ്ധനാകുന്നു, സ്തുതികൾ നിനക്കാകുന്നു, നീയല്ലാതെ ആരാധ്യനില്ലെന്ന് ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു, നിന്നോട് ഞാൻ പൊറുക്കലിനെ ചോദിക്കുന്നു, നിന്നിലേക്ക് ഞാൻ ഖേദിച്ചു മടങ്ങുന്നു.'' എന്ന് പറഞ്ഞാൽ ആ മജ്‌ലിസിൽ ഉണ്ടായതെല്ലാം അവന് പൊറുക്കപ്പെടുന്നതായിരിക്കും. (ദ,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 975, 975, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=123 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 279, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ يُعَدُّ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْمَجْلِسِ الْوَاحِدِ مِائَةُ مَرَّةٍ مِنْ قَبْلِ أَنْ يَقُومَ: "رَبِّ اغْفِرْ لِي وَتُبْ عَلَيَّ، إِنَّكَ أَنْتَ التَّوَّابُ الْغَفُورُ". حَسَنٌ صَحِيحٌ. (د,ت)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) ഒരു മജ്‌ലിസിൽനിന്ന് എഴുന്നേൽക്കുന്നതിന് മുമ്പ് നൂറ് പ്രാവശ്യം അവിടുത്തേക്ക് വേണ്ടി ഇത് എണ്ണപ്പെടാറുണ്ടായിരുന്നു: "എന്റെ രക്ഷിതാവേ, എനിക്ക് നീ പൊറുത്ത് തരേണമേ, എന്റെ തൗബ സ്വീകരിക്കുകയും ചെയ്യേണമേ, തീർച്ചയായും നീ ഏറ്റവും പൊറുത്ത് കൊടുക്കുന്നവനും തൗബ സ്വീകരിക്കുന്നവനുമാകുന്നു." (ദ,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 975, 976, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=123 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 280, 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا نَقُولُ فِي الصَّلَاةِ قَبْلَ أَنْ يُفْرَضَ التَّشَهُّدُ: السَّلَامُ عَلَى اللَّهِ، السَّلَامُ عَلَى جِبْرِيلَ وَمِيكَائِيلَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَقُولُوا هَكَذَا، فَإِنَّ اللَّهَ عَزَّ وَجَلَّ هُوَ السَّلَامُ. وَلَكِنْ قُولُوا: التَّحِيَّاتُ لِلَّهِ، وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ". (ن)', 'ഇബ്‌നുമസ്‌ഊദ്(റ): തശഹ്ഹുദ് നിർബന്ധമാക്കപ്പെടുന്നതിന് മുമ്പ് ഞങ്ങൾ നിസ്‌കാരത്തിൽ ഇപ്രകാരം പറയുമായിരുന്നു: അല്ലാഹുവിന്റെ മേൽ രക്ഷയുണ്ടായിരിക്കട്ടെ, ജിബ്‌രീലിന്റെ(അ)യും മീക്കാഈലിന്റെയും മേൽ രക്ഷയുണ്ടായിരിക്കട്ടെ. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളങ്ങനെ പറയരുത്. രക്ഷയെന്നത് അല്ലാഹുവാണ്. പകരം നിങ്ങളിങ്ങനെ പറയുക: തിരുമുൾക്കാഴ്ചയും ഗുണവും അനുഗ്രഹവും അല്ലാഹുവിനാകുന്നു. നബിയേ, അങ്ങയുടെ മേൽ അല്ലാഹുവിന്റെ രക്ഷയും കരുണയും ബറകതും ഉണ്ടായിരിക്കട്ടെ. ഞങ്ങളുടെ മേലും അല്ലാഹുവിന്റെ സദ്‌വൃത്തരായ ദാസന്മാരുടെ മേലും അവന്റെ രക്ഷയുണ്ടാവട്ടെ. അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്ന് ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു. മുഹമ്മദ്(സ) അവന്റെ ദൂതനും ദാസനുമാണെന്നും ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു." (ന)', 'ابْنِ مَسْعُودٍ', 'ഇബ്‌നുമസ്‌ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 976, 976, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=124 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 281, 'عَنْ كَعْبِ بْنِ عُجْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قُلْنَا: يَا رَسُولَ اللَّهِ: السَّلَامُ عَلَيْكَ قَدْ عَرَفْنَاهُ، فَكَيْفَ الصَّلَاةُ؟ قَالَ: "قُولُوا: اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ. اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ". (ن)', 'കഅ്ബുബ്‌നു ഉജ്‌റ(റ): ഞങ്ങൾ ചോദിച്ചു: തിരുദൂതരെ, അങ്ങയുടെ മേൽ എങ്ങനെയാണ് സലാം ചൊല്ലേണ്ടതെന്ന് ഞങ്ങൾക്കറിയാം. പക്ഷെ ഞങ്ങളെങ്ങനെയാണ് സ്വലാത്ത് ചൊല്ലേണ്ടത്? തിരുമേനി(സ) പറഞ്ഞു: "നിങ്ങൾ പറയുക, അല്ലാഹുവേ, ഇബ്‌റാഹീം നബി(അ)യുടെ കുടുംബത്തെ അനുഗ്രഹിച്ചതു പോലെ മുഹമ്മദ് നബി(സ)യെയും അവരുടെ കുടുംബത്തെയും അനുഗ്രഹിക്കേണമേ. നീ സ്തുത്യർഹനും ഉന്നതനുമാണ്. അല്ലാഹുവേ, ഇബ്‌റാഹീം നബി(അ)യുടെ കുടുംബത്തിന് അഭിവൃദ്ധി നൽകിയത് പോലെ മുഹമ്മദ് നബി(സ)ക്കും അവരുടെ കുടുംബത്തിനും അഭിവൃദ്ധി നൽകേണമേ. നീ സ്തുത്യർഹനും ഉന്നതനുമാണ്." (ന)', 'كَعْبِ بْنِ عُجْرَةَ', 'കഅ്ബുബ്‌നു ഉജ്‌റ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 976, 976, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=124 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 282, 'عَنْ مَرْوَانَ: سَأَلَ أَبَا هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: كَيْفَ سَمِعْتَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي عَلَى الْجَنَازَةِ؟ قَالَ أَبُو هُرَيْرَةَ: "اللَّهُمَّ أَنْتَ رَبُّهَا، وَأَنْتَ خَلَقْتَهَا، وَأَنْتَ هَدَيْتَهَا لِلْإِسْلَامِ، وَأَنْتَ قَبَضْتَ رُوْحَهَا، وَأَنْتَ أَعْلَمُ بِسِرِّهَا وَعَلَانِيَتِهَا، جِئْنَاكَ شُفَعَاءَ فَاغْفِرْ لَهُ". (د)', 'മർവാൻ: അദ്ദേഹം അബൂഹുറൈറ(റ)വിനോട് ചോദിച്ചു: റസൂൽ(സ) ജനാസ നിസ്കരിക്കുന്നത് എങ്ങനെയാണ് താങ്കൾ കേട്ടത്? അബൂഹുറൈറ(റ) പറഞ്ഞു: "അല്ലാഹുവേ, നീയാണ് അതിന്റെ രക്ഷിതാവ്, നീയാണ് അതിനെ സൃഷ്ടിച്ചത്, നീയാണ് അതിനെ ഇസ്ലാമിലേക്ക് വഴി നടത്തിയത്, നീയാണ് അതിന്റെ ആത്മാവിനെ പിടിച്ചത്. നീ അതിന്റെ രഹസ്യവും പരസ്യവും അറിയുന്നവനാണ്, ഞങ്ങൾ ശിപാർശകരായി നിന്നിലേക്ക് വന്നു. അത് കൊണ്ട് നീ അദ്ദേഹത്തിന് പൊറുത്ത് കൊടുക്കേണമേ." (ദ)', 'مَرْوَانَ', 'മർവാൻ', null, null, array['د']::text[], array['ദ']::text[], null, null, 976, 977, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=125 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 283, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى جَنَازَةٍ، فَقَالَ: "اللَّهُمَّ اغْفِرْ لِحَيِّنَا وَمَيِّتِنَا، وَصَغِيرِنَا وَكَبِيرِنَا، وَذَكَرِنَا وَأُنْثَانَا، وَشَاهِدِنَا وَغَائِبِنَا. اللَّهُمَّ مَنْ أَحْيَيْتَهُ مِنَّا فَأَحْيِهِ عَلَى الْإِيمَانِ، وَمَنْ تَوَفَّيْتَهُ مِنَّا فَتَوَفَّهُ عَلَى الْإِسْلَامِ. اللَّهُمَّ لَا تَحْرِمْنَا أَجْرَهُ، وَلَا تُضِلَّنَا بَعْدَهُ". (د,ت,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) ജനാസ നമസ്കരിച്ചു. അപ്പോൾ പറഞ്ഞു: "അല്ലാഹുവേ, ഞങ്ങളിൽ ജീവിച്ചിരിക്കുന്നവർക്കും മരിച്ചുപോയവർക്കും, ചെറിയവനും വലിയവനും, ആണിനും പെണ്ണിനും, സന്നിഹിതരായവർക്കും അല്ലാത്തവർക്കും നീ പൊറുത്ത് കൊടുക്കേണമേ. അല്ലാഹുവേ, ഞങ്ങളിൽ ജീവിച്ചിരിക്കുന്നവരെ ഈമാനിലായി ജീവിപ്പിക്കുകയും മരിപ്പിക്കുന്നവരെ ഇസ്ലാമിലായി മരിപ്പിക്കുകയും ചെയ്യേണമേ. അല്ലാഹുവേ, അദ്ദേഹത്തിന്റെ പ്രതിഫലത്തെ നീ ഞങ്ങൾക്ക് നിഷേധിക്കരുതേ, അദ്ദേഹത്തിന് ശേഷം ഞങ്ങളെ വഴി തെറ്റിക്കരുതേ." (ദ,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 977, 977, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=125 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 284, 'عَنْ وَاثِلَةَ بْنِ الْأَسْقَعِ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّى بِنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى رَجُلٍ مِنَ الْمُسْلِمِينَ، فَسَمِعْتُهُ يَقُولُ: "اللَّهُمَّ إِنَّ فُلَانَ بْنَ فُلَانٍ فِي ذِمَّتِكَ، فَقِهِ فِتْنَةَ الْقَبْرِ". وَفِي رِوَايَةٍ: "فِي ذِمَّتِكَ وَحَبْلِ جِوَارِكَ، فَقِهِ مِنْ فِتْنَةِ الْقَبْرِ وَعَذَابِ النَّارِ، وَأَنْتَ أَهْلُ الْوَفَاءِ وَالْحَمْدِ. اللَّهُمَّ فَاغْفِرْ لَهُ وَارْحَمْهُ، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ". (جه)', 'വാസിലതുബ്നുൽ അസ്ഖഅ്(റ): മുസ്ലിമായ ഒരു വ്യക്തിയുടെ മേൽ നബി(സ) മയ്യിത് നിസ്കരിച്ചു. ഞങ്ങളും കൂടെയുണ്ടായിരുന്നു. അവിടന്ന് പറയുന്നുണ്ടായിരുന്നു: "അല്ലാഹുവേ, ഇന്നാലിന്നവന്റെ മകൻ നിന്റെ സംരക്ഷണത്തിലാണ്. അത് കൊണ്ട് നീ അദ്ദേഹത്തെ ഖബ്റിലെ പരീക്ഷണങ്ങളിൽ നിന്ന് സംരക്ഷിക്കേണമേ."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=284), 1, 'وَفِي رِوَايَةٍ: "فِي ذِمَّتِكَ وَحَبْلِ جِوَارِكَ، فَقِهِ مِنْ فِتْنَةِ الْقَبْرِ وَعَذَابِ النَّارِ، وَأَنْتَ أَهْلُ الْوَفَاءِ وَالْحَمْدِ. اللَّهُمَّ فَاغْفِرْ لَهُ وَارْحَمْهُ، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ". (جه)', 'മറ്റൊരു നിവേദനം: "നിന്റെ ഉത്തരവാദിത്തത്തിലും, നിന്റെ സഹായത്തിന്റെ സംരക്ഷണത്തിലും ആകുന്നു. അത് കൊണ്ട് നീ ഖബ്റിലെ പരീക്ഷണത്തിൽ നിന്നും നരക ശിക്ഷയിൽ നിന്നും അദ്ദേഹത്തെ രക്ഷിക്കേണമേ. നീ വാഗ്ദത്ത പൂർത്തീകരണത്തിനും സ്തുതിക്കും അർഹനാണ്. അല്ലാഹുവേ, അത് കൊണ്ട് അദ്ദേഹത്തിന് നീ പൊറുത്ത് കൊടുക്കുകയും അവനോട് കരുണ കാണിക്കുകയും ചെയ്യേണമേ. തീർച്ചയായും നീ കൂടുതൽ പൊറുക്കുന്നവനും കരുണ ചെയ്യുന്നവനുമാകുന്നു." (ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 285, 'عَنْ عَوْفِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى عَلَى جَنَازَةٍ يَقُولُ: "اللَّهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ، وَاعْفُ عَنْهُ وَعَافِهِ، وَأَكْرِمْ نُزُلَهُ، وَوَسِّعْ مُدْخَلَهُ، وَاغْسِلْهُ بِمَاءٍ وَثَلْجٍ وَبَرَدٍ، وَنَقِّهِ مِنَ الْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ. وَأَبْدِلْهُ دَارًا خَيْرًا مِنْ دَارِهِ، وَأَهْلًا خَيْرًا مِنْ أَهْلِهِ، وَزَوْجًا خَيْرًا مِنْ زَوْجِهِ، وَقِهِ عَذَابَ الْقَبْرِ وَعَذَابَ النَّارِ". قَالَ عَوْفٌ: فَتَمَنَّيْتُ أَنْ لَوْ كُنْتُ الْمَيِّتَ، لِدُعَاءِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِذَلِكَ الْمَيِّتِ. (ن)', 'ഔഫുബ്നു മാലിക്(റ): നബി(സ) ഒരു ജനാസ നിസ്കാരത്തിൽ മയ്യിത്തിന്ന് വേണ്ടി പ്രാർത്ഥിക്കുന്നത് ഞാൻ കേട്ടു. "അല്ലാഹുവേ, ഈ മയ്യിതിന് പൊറുത്ത് കൊടുക്കുകയും കരുണ കാണിക്കുകയും മാപ്പു നൽകുകയും രക്ഷ നൽകുകയും ഈ മയ്യിത്തിന്റെ വാസസ്ഥലത്തെ ആദരിക്കുകയും പ്രവേശന കവാടം വിശാലമാക്കുകയും വെള്ളം കൊണ്ടും മഞ്ഞു കൊണ്ടും ആലിപ്പഴം കൊണ്ടും അവനെ കുളിപ്പിക്കുകയും ചെയ്യേണമേ. വെള്ള വസ്ത്രത്തിലെ മാലിന്യം ശുദ്ധീകരിക്കുന്നത് പോലെ അവന്റെ പാപമാലിന്യത്തിൽ നിന്ന് അവനെ ശുദ്ധീകരിക്കേണമേ. അവന്റെ ഭവനത്തേക്കാൾ ഭദ്രമായൊരു ഭവനവും, കുടുംബത്തേക്കാൾ ഉത്തമമായ കുടുംബവും ഭാര്യയേക്കാൾ നല്ലവളായ ഭാര്യയെയും നൽകുകയും ഖബറിലെയും നരകത്തിലെയും ശിക്ഷയിൽ നിന്ന് അവരെ രക്ഷിക്കുകയും ചെയ്യേണമേ." ഔഫ്(റ) പറയുന്നു: പ്രവാചകൻ(സ) ആ മയ്യിതിന് വേണ്ടി പ്രാർത്ഥിച്ചത് കാരണം ആ മയ്യിത് ഞാനായിരുന്നെങ്കിലെന്ന് ഞാൻ ആഗ്രഹിച്ചു പോയി. (ന)', 'عَوْفِ بْنِ مَالِكٍ', 'ഔഫുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 977, 978, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=125 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 286, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا دَخَلَ الْخَلَاءَ، قَالَ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ - وَفِي رِوَايَةٍ: أَعُوذُ بِاللَّهِ مِنَ الْخُبُثِ وَالْخَبَائِثِ. (ق, د, ت, ن, جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) കക്കൂസിൽ പ്രവേശിക്കുമ്പോൾ പറയുമായിരുന്നു: "അല്ലാഹുവേ, നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു." മറ്റൊരു നിവേദനം: "ആൺ പെൺ ചെകുത്താന്മാരിൽ നിന്ന് അല്ലാഹുവിനോട് ഞാൻ കാവൽ ചോദിക്കുന്നു." (ബു,മു,ദ,തു,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 978, 978, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=126 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=286), 1, 'وَفِي رِوَايَةٍ: أَعُوذُ بِاللَّهِ مِنَ الْخُبُثِ وَالْخَبَائِثِ. (ق, د, ت, ن, جه)', 'മറ്റൊരു നിവേദനം: "ആൺ പെൺ ചെകുത്താന്മാരിൽ നിന്ന് അല്ലാഹുവിനോട് ഞാൻ കാവൽ ചോദിക്കുന്നു." (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 287, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خُدَّامَ أَنْفُسِنَا نَتَنَاوَبُ الرِّعَايَةَ رِعَايَةَ إِبِلِنَا، فَكَانَتْ عَلَيَّ رِعَايَةُ الْإِبِلِ، فَرَوَّحْتُهَا بِالْعَشِيِّ، فَأَدْرَكْتُ رَسُولَ اللَّهِ يَخْطُبُ النَّاسَ، فَسَمِعْتُهُ يَقُولُ: "مَا مِنْكُمْ مِنْ أَحَدٍ يَتَوَضَّأُ فَيُحْسِنُ الْوُضُوءَ، ثُمَّ يَقُومُ فَيَرْكَعُ رَكْعَتَيْنِ، يُقْبِلُ عَلَيْهِمَا بِقَلْبِهِ وَوَجْهِهِ إِلَّا قَدْ أَوْجَبَ". فَقُلْتُ بَخٍ بَخٍ! مَا أَجْوَدَ هَذِهِ، فَقَالَ رَجُلٌ مِنْ بَيْنِ يَدَيَّ: الَّتِي قَبْلَهَا يَا عُقْبَةُ أَجْوَدُ مِنْهَا، فَنَظَرْتُ فَإِذَا هُوَ عُمَرُ بْنُ الْخَطَّابِ، فَقُلْتُ: مَا هِيَ يَا أَبَا حَفْصٍ؟ قَالَ: إِنَّهُ قَالَ آنِفًا قَبْلَ أَنْ تَجِيءَ: "مَا مِنْكُمْ مِنْ أَحَدٍ يَتَوَضَّأُ فَيُحْسِنُ الْوُضُوءَ، ثُمَّ يَقُولُ حِينَ يَفْرُغُ مِنْ وُضُوئِهِ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، إِلَّا فُتِحَتْ لَهُ أَبْوَابُ الْجَنَّةِ الثَّمَانِيَةُ يَدْخُلُ مِنْ أَيِّهَا شَاءَ". وَفِي رِوَايَةٍ: قَالَ عِنْدَ قَوْلِهِ: "فَأَحْسَنَ الْوُضُوءَ"، "ثُمَّ رَفَعَ بَصَرَهُ إِلَى السَّمَاءِ فَقَالَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّد رَسُولُ اللَّهِ". وَسَاقَ الْحَدِيثَ. (م, د, ت, ن, جه)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): തിരുദൂതർ(സ)യുടെ സ്വയം സേവകരായിരുന്നു ഞങ്ങൾ. ഊഴം വെച്ചായിരുന്നു ഞങ്ങൾ ഒട്ടകങ്ങളെ പരിചരിച്ചിരുന്നത്. ഒരിക്കൽ എന്റെ ഊഴം വന്നു, വൈകുന്നേരം ഞാനവയെ കെട്ടിയിടാൻ പോയി. അപ്പോൾ നബി(സ) പ്രസംഗിക്കുന്നതായി ഞാൻ കേട്ടു: "നിങ്ങളിൽ നിന്നൊരാൾ പരിപൂർണ്ണമായി അംഗ ശുദ്ധിവരുത്തുന്നു, എന്നിട്ട് പരിപൂർണ്ണ മനസ്സാന്നിധ്യത്തോടെ മുഖം നേരെയാക്കി രണ്ട് റക്അത്ത് നിസ്കരിക്കുകയും ചെയ്യുന്നു, എങ്കിൽ സ്വർഗ്ഗം അവന് നിർബന്ധമായിത്തീരുന്നു.'''' അപ്പോൾ ഞാൻ ഹ! ഹ! ഇത് എത്ര നല്ലതാണ് എന്ന് പറഞ്ഞു. ഉടനെ എന്റെ മുന്നിൽ നിന്നൊരാൾ പറഞ്ഞു: ഉഖ്ബതേ, ഇതിനു മുമ്പുള്ളത് ഇതിലും നല്ലതാണ്. ഞാൻ നോക്കിയപ്പോൾ അത് ഉമർ(റ) ആയിരുന്നു. ഞാൻ ചോദിച്ചു: അബൂഹഫ്സെ, അത് എന്താണ്? ഉമർ(റ) പറഞ്ഞു: നീ വരുന്നതിന്റെ തൊട്ടുമുമ്പ് റസൂൽ(സ) പറഞ്ഞു: ''''നിങ്ങളിൽ നിന്നൊരാൾ പരിപൂർണ്ണമായി അംഗ ശുദ്ധിവരുത്തുന്നു, അംഗ ശുദ്ധി വരുത്തിക്കഴിഞ്ഞതിനു ശേഷം: അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്നും അവൻ ഏകനും പങ്കുകാരില്ലാത്തവനുമാണെന്നും മുഹമ്മദ് (സ) അവന്റെ ദൂതനും ദാസനുമാണെന്നും ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു എന്ന് പറയുകയും ചെയ്യുന്നുവെങ്കിൽ അവന് വേണ്ടി എട്ട് സ്വർഗകവാടങ്ങൾ തുറക്കപ്പെടും. അതിൽ അവനുദ്ദേശിച്ചതിൽ അവൻ പ്രവേശിക്കാം."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=287), 1, 'وَفِي رِوَايَةٍ: قَالَ عِنْدَ قَوْلِهِ: "فَأَحْسَنَ الْوُضُوءَ"، "ثُمَّ رَفَعَ بَصَرَهُ إِلَى السَّمَاءِ فَقَالَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّد رَسُولُ اللَّهِ". وَسَاقَ الْحَدِيثَ. (م, د, ت, ن, جه)', 'മറ്റൊരു നിവേദനം: "പരിപൂർണ്ണമായി അംഗ ശുദ്ധി വരുത്തി" എന്നതിന് ശേഷം നബി(സ) ഇങ്ങനെ പറഞ്ഞു: "പിന്നെ അവൻ തന്റെ കണ്ണുകളെ ആകാശത്തേക്കുയർത്തി, എന്നിട്ട് പറഞ്ഞു: അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്നും അവൻ ഏകനും പങ്കുകാരില്ലാത്തവനുമാണെന്നും മുഹമ്മദ്(സ) അല്ലാഹുവിന്റെ ദൂതനാണെന്നും ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു." പിന്നെ നിവേദകൻ ആ ഹദീസ് തുടർന്ന് പറയുകയും ചെയ്തു. (മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 288, 'عَنْ أَبِي حُمَيْدٍ - أَوْ: أَبِي أُسَيْدٍ - الأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا دَخَلَ أَحَدُكُمُ الْمَسْجِدَ فَلْيُسَلِّمْ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ لِيَقُلِ: اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ، فَإِذَا خَرَجَ فَلْيَقُلِ: اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ". (م, د, ت, ن, جه)', 'അബൂഹുമൈദിനിൽ അൻസാരി(റ) (അല്ലെങ്കിൽ: അബൂഉസൈദ്): റസൂൽ(സ) പറയുന്നു: "നിങ്ങൾ പള്ളിയിൽ പ്രവേശിക്കുമ്പോൾ നബി(സ)യുടെ മേൽ സലാം ചൊല്ലുക, ശേഷം പറയുക: അല്ലാഹുവേ, നിന്റെ കാരുണ്യത്തിന്റെ കവാടങ്ങളെ എനിക്ക് നീ തുറന്ന് തരേണമേ. ഇനി പള്ളിയിൽ പുറത്തേക്ക് വരികയാണെങ്കിൽ അവൻ പറയട്ടെ: അല്ലാഹുവേ, നിന്റെ ഔദാര്യത്തെ ഞാൻ ചോദിക്കുന്നു." (മു,ദ,തു,ന,ജ)', 'أَبِي حُمَيْدٍ - أَوْ', 'അബൂഹുമൈദിനിൽ അൻസാരി(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 979, 979, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=128 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 289, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ كَانَ إِذَا دَخَلَ الْمَسْجِدَ قَالَ: "أَعُوذُ بِاللَّهِ الْعَظِيمِ، وَبِوَجْهِهِ الْكَرِيمِ، وَسُلْطَانِهِ الْقَدِيمِ، مِنَ الشَّيْطَانِ الرَّجِيمِ". (د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പള്ളിയിൽ പ്രവേശിക്കുമ്പോൾ പറയാറുണ്ടായിരുന്നു: "ശ്രേഷ്ഠവാനായ അല്ലാഹുവിനെക്കൊണ്ടും, അവന്റെ പവിത്രമായ മുഖം കൊണ്ടും, പണ്ടേയുള്ള അവന്റെ ആധിപത്യം കൊണ്ടും ആട്ടിയോടിക്കപ്പെട്ട പിശാചിൽ നിന്ന് ഞാൻ അഭയം ചോദിക്കുന്നു." (ദ)', 'عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 979, 979, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=128 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 290, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْمَلَائِكَةُ تُصَلِّي عَلَى أَحَدِكُمْ مَا دَامَ فِي مُصَلَّاهُ الَّذِي صَلَّى فِيهِ، مَا لَمْ يُحْدِثْ أَوْ يَقُمْ: اللَّهُمَّ اغْفِرْ لَهُ، اللَّهُمَّ ارْحَمْهُ". (ق, د, ت, ن, جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "ഒരാൾ താൻ നിസ്കരിച്ച സ്ഥലത്ത് നിന്ന് എഴുന്നേൽക്കുകയോ അശുദ്ധി ഉണ്ടാവുകയോ ചെയ്യുന്നത് വരെ മലക്കുകൾ അവന് വേണ്ടി ഇങ്ങനെ പ്രാർത്ഥിച്ച് കൊണ്ടിരിക്കും: അല്ലാഹുവേ, അവന് നീ പൊറുത്ത് കൊടുക്കേണമേ, അവനോട് നീ കരുണയും ചെയ്യേണമേ." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 979, 979, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=129 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 291, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَزَالُ أَحَدُكُمْ فِي صَلَاةٍ مَا كَانَتِ الصَّلَاةُ تَحْبِسُهُ، لَا يَمْنَعُهُ أَنْ يَنْقَلِبَ إِلَى أَهْلِهِ إِلَّا الصَّلَاةُ". (م, د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "നിസ്കാരം ഒരാളെ തടഞ്ഞ് വെക്കുന്ന സമയം മുഴുവനും അവൻ നിസ്കാരത്തിലാകുന്നു. അവൻ തന്റെ വീട്ടിലേക്ക് മടങ്ങുന്നതിന് തടസ്സം അവന്റെ നിസ്കാരം മാത്രമായിരിക്കും." (മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 979, 979, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=129 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 292, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَزَالُ الْعَبْدُ فِي صَلَاةٍ مَا كَانَ فِي مُصَلَّاهُ يَنْتَظِرُ الصَّلَاةَ، تَقُولُ الْمَلَائِكَةُ: اللَّهُمَّ اغْفِرْ لَهُ، اللَّهُمَّ ارْحَمْهُ، حَتَّى يَنْصَرِفَ أَوْ يُحْدِثَ". فَقِيلَ: مَا يُحْدِثُ؟ قَالَ: يَفْسُو أَوْ يَضْرِطُ. (م,د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ അടിമ നിസ്കാരത്തെ പ്രതീക്ഷിച്ച് തന്റെ നമസ്കാര സ്ഥലത്ത് ഇരിക്കുന്ന സമയമത്രയും അവൻ നിസ്കാരത്തിലാണ്. അവിടെ നിന്ന് പിരിഞ്ഞ് പോകുന്നത് വരെ, അതല്ലെങ്കിൽ അശുദ്ധിയുണ്ടാകുന്നത് വരെ, മാലാഖമാർ അവന് വേണ്ടി പ്രാർത്ഥിച്ചുകൊണ്ടിരിക്കും: അല്ലാഹുവേ, അവന് പൊറുത്തു കൊടുക്കേണമേ. അവനോട് കരുണ കാണിക്കേണമേ." അപ്പോൾ അവിടുത്തോട് ചോദിക്കപ്പെട്ടു: "അശുദ്ധിയുണ്ടാകുന്നത് എന്താണ്? നബി(സ) പറഞ്ഞു: "ശബ്ദത്തോടെയോ ശബ്ദമില്ലാതെയോ പിന്നിലൂടെ കാറ്റ് പോവലാണ്". (മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 979, 980, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=129 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 293, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَالَ حِينَ يَسْمَعُ النِّدَاءَ: اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ وَالصَّلَاةِ الْقَائِمَةِ، آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ، وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ، إِلَّا حَلَّتْ لَهُ الشَّفَاعَةُ يَوْمَ الْقِيَامَةِ". (خ,د,ت,ن,جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) പറയുന്നു: "ബാങ്ക് കേൾക്കുമ്പോൾ ആരെങ്കിലും അല്ലാഹുവേ, ഈ പരിപൂർണ്ണമായ ദുആയുടെയും എന്നെന്നും നിലനിൽക്കുന്ന സ്വലാത്തിന്റെയും രക്ഷിതാവേ, സയ്യിദുനാ മുഹമ്മദ്(സ)ക്ക് വസീലയെയും ഫളീലയെയും (ഉന്നതമായ രണ്ട് സ്ഥാനങ്ങൾ) നീ നൽകേണമേ. നീ വാഗ്ദാനം ചെയ്ത മഹ്മൂദായ സ്ഥാനത്തെയും അവിടുത്തേക്ക് നൽകേണമേ എന്ന് പ്രാർത്ഥിച്ചാൽ, അവന് അന്ത്യനാളിൽ ശിപാർശ ഇറങ്ങുക തന്നെ ചെയ്യും". (ബു,ദ,തു,ന,ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 980, 980, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=130 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 294, 'عَنْ عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قُمْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْلَةً، فَقَامَ فَقَرَأَ سُورَةَ الْبَقَرَةِ: لَا يَمُرُّ بِآيَةِ رَحْمَةٍ إِلَّا وَقَفَ فَسَأَلَ، وَلَا يَمُرُّ بِآيَةِ عَذَابٍ إِلَّا وَقَفَ فَتَعَوَّذَ، قَالَ: ثُمَّ رَكَعَ بِقَدْرِ قِيَامِهِ، يَقُولُ فِي رُكُوعِهِ: "سُبْحَانَ ذِي الْجَبَرُوتِ وَالْمَلَكُوتِ وَالْكِبْرِيَاءِ وَالْعَظَمَةِ". ثُمَّ سَجَدَ بِقَدْرِ قِيَامِهِ، ثُمَّ قَالَ فِي سُجُودِهِ مِثْلَ ذَلِكَ، ثُمَّ قَامَ فَقَرَأَ بِآلِ عِمْرَانَ، ثُمَّ قَرَأَ سُورَةً سُورَةً. (د,ت,ن)', 'ഔഫുബ്നു മാലികിൽ അശ്ജഈ(റ): ഒരു രാത്രി ഞാൻ റസൂൽ(സ)യുടെ കൂടെ നിസ്കരിച്ചു. അവിടന്ന് അൽബഖറ സൂറത്ത് ഓതി. കരുണയുടെ സൂക്തം വന്നാൽ നിർത്തുകയും അല്ലാഹുവോട് കരുണചോദിക്കുകയും ചെയ്യും. ശിക്ഷയുടെ സൂക്തം വന്നാൽ നിർത്തുകയും കാവൽ ചോദിക്കുകയും ചെയ്യും. നിവേദകൻ പറയുന്നു: പിന്നെ തിരുമേനി(സ) ഖിയാമിന്റെ (നിർത്തത്തിന്റെ) അത്ര തന്നെ സമയം റുകൂഉം ചെയ്തു. അവിടുന്ന് പറയുന്നുണ്ടായിരുന്നു: "പരമാധികാരവും രാജാധികാരവും മഹത്വവും പ്രതാപവുമുള്ളവൻ എത്ര പരിശുദ്ധനാകുന്നു." പിന്നെ അവിടന്ന് ഖിയാമിന്റെ അത്ര തന്നെ സുജൂദ് ചെയ്ത് അത് പോലെ തന്നെ സുജൂദിലും പറഞ്ഞു. പിന്നെ അവിടന്ന് സുജൂദിൽ നിന്നെഴുന്നേൽക്കുകയും ആലുഇംറാൻ സൂറത്ത് ഓതുകയും പിന്നെ ഓരോരോ സൂറത്ത് ഓതുകയും ചെയ്തു. (ദ,തു,ന)', 'عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ', 'ഔഫുബ്നു മാലികിൽ അശ്ജഈ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 980, 980, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=131 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 295, 'عَنْ حُذَيْفَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ رَأَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ، فَكَانَ يَقُولُ: ”اللهُ أَكْبَرُ، ثَلَاثًا، ذُو الْمَلَكُوتِ وَالْجَبَرُوتِ وَالْكِبْرِيَاءِ وَالْعَظَمَةِ“. ثُمَّ اسْتَفْتَحَ فَقَرَأَ الْبَقَرَةَ، ثُمَّ رَكَعَ فَكَانَ رُكُوعُهُ نَحْوًا مِنْ قِيَامِهِ، وَكَانَ يَقُولُ فِي رُكُوعِهِ: ”سُبْحَانَ رَبِّيَ الْعَظِيمِ، سُبْحَانَ رَبِّيَ الْعَظِيمِ“. ثُمَّ رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ فَكَانَ قِيَامُهُ نَحْوًا مِنْ رُكُوعِهِ، يَقُولُ: ”لِرَبِّيَ الْحَمْدُ“. ثُمَّ سَجَدَ فَكَانَ سُجُودُهُ نَحْوًا مِنْ قِيَامِهِ، فَكَانَ يَقُولُ فِي سُجُودِهِ: ”سُبْحَانَ رَبِّيَ الْأَعْلَى“. ثُمَّ رَفَعَ رَأْسَهُ مِنَ السُّجُودِ، وَكَانَ يَقْعُدُ فِيمَا بَيْنَ السَّجْدَتَيْنِ نَحْوًا مِنْ سُجُودِهِ، وَكَانَ يَقُولُ: ”رَبِّ اغْفِرْ لِي، رَبِّ اغْفِرْ لِي“، فَصَلَّى أَرْبَعَ رَكَعَاتٍ، فَقَرَأَ فِيهِنَّ الْبَقَرَةَ، وَآلَ عِمْرَانَ، وَالنِّسَاءَ، وَالْمَائِدَةَ، أَوْ الْأَنْعَامَ. (د،ت،ن،جه)', 'ഹുദൈഫ(റ): റസൂൽ(സ) രാത്രി നിസ്കരിക്കുന്നത് അവർ കണ്ടു. നിസ്കാരത്തിൽ റസൂൽ(സ) പറയുന്നുണ്ടായിരുന്നു: "അല്ലാഹുവാണ് ഏറ്റവും വലിയവൻ (മൂന്ന് തവണ), മഹത്ത്വവും അഹങ്കാരവും സർവ്വാധിപത്യവും രാജകീയതയും ഉടയവൻ" പിന്നെ ഫാതിഹ ഓതി. ശേഷം അൽ ബഖറയും. പിന്നെ റുകൂഅ് ചെയ്തു. അതിന് നബി(സ)യുടെ നിർത്തത്തിന്റെ അത്രയും ദൈർഘ്യമുണ്ടായിരുന്നു. റുകൂഇൽ തിരുമേനി(സ) പറയുന്നുണ്ടായിരുന്നു: "ഉത്തമനായ എന്റെ നാഥനെ ഞാൻ വാഴ്ത്തുന്നു. ഉത്തമനായ എന്റെ നാഥനെ ഞാൻ വാഴ്ത്തുന്നു." ശേഷം റുകൂഇൽ നിന്നു തലയുയർത്തി. നിർത്തത്തിന് തിരുദൂതരുടെ റുകൂഇന്റെ ദൈർഘ്യമുണ്ടായിരുന്നു. തിരുമേനി(സ) പറയുന്നുണ്ടായിരുന്നു: "എന്റെ നാഥനാണ് സർവ്വ സ്തുതിയും." ശേഷം തിരുമേനി(സ) സുജൂദ് ചെയ്തു. സുജൂദിന് നിർത്തത്തിന്റെ ദൈർഘ്യമുണ്ടായിരുന്നു. സുജൂദിൽ റസൂൽ(സ) പറയുന്നുണ്ടായിരുന്നു: "ഏറ്റവും ഉന്നതനായ എന്റെ നാഥനെ ഞാൻ വാഴ്ത്തുന്നു." പിന്നെ സുജൂദിൽ നിന്നു തലയുയർത്തി. സുജൂദുകൾക്കിടയിലുള്ള ഇരുത്തത്തിന് സുജൂദിന്റേയത്രയും ദൈർഘ്യമുണ്ടായിരുന്നു. സുജൂദുകൾക്കിടയിലുള്ള ഇരുത്തത്തിൽ തിരുമേനി പറയുന്നുണ്ടായിരുന്നു: "നാഥാ പൊറുക്കണേ, നാഥാ പൊറുക്കണേ." അങ്ങനെ നബി(സ) നാല് റക്അത്ത് നിസ്കരിച്ചു. അതിൽ നബി(സ) അൽ ബഖറയും ആലു ഇംറാനും അന്നിസാഉം മാഇദയും, അല്ലെങ്കിൽ അൻആമും ഓതി. (ദ,തു,ന,ജ)', 'حُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 980, 981, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=131 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 296, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُكْثِرُ أَنْ يَقُولَ فِي رُكُوعِهِ وَسُجُودِهِ: ”سُبْحَانَكَ اللَّهُمَّ رَبَّنَا وَبِحَمْدِكَ، اللَّهُمَّ اغْفِرْ لِي“ يَتَأَوَّلُ الْقُرْآنَ. (ق،د،ن،جه)', 'ആഇശ(റ): ഖുർആന്റെ കൽപ്പനയനുസരിച്ച് റസൂൽ(സ) റുകൂഇലും സുജൂദിലും: "ഞങ്ങളുടെ രക്ഷിതാവായ അല്ലാഹുവേ, സ്തുതിക്കുന്നതോട് കൂടെ നിന്നെ ഞാൻ വാഴ്ത്തുന്നു. അല്ലാഹുവേ, നീ എനിക്ക് പൊറുത്ത് തരേണമേ." എന്ന് ചൊല്ലൽ അധികരിപ്പിക്കുമായിരുന്നു. (ബു,മു,ദ,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 981, 981, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=131 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 297, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ فِي سُجُودِهِ: ”اللَّهُمَّ اغْفِرْ لِي ذَنْبِي كُلَّهُ، دِقَّهُ وَجِلَّهُ، وَأَوَّلَهُ وَآخِرَهُ، عَلَانِيَتَهُ وَسِرَّهُ“. (م،د)', 'അബൂഹുറൈറ(റ): നബി(സ) അവിടുത്തെ സുജൂദിൽ പറയാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ, ചെറുതും വലുതുമായ, ആദ്യത്തെയും അവസാനത്തെയുമായ, പരസ്യവും രഹസ്യമായതുമായ എന്റെ എല്ലാ പാപങ്ങളും നീ എനിക്ക് പൊറുത്ത് തരേണമേ." (മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 981, 981, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=131 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 298, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: فَقَدْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةٍ، فَلَمَسْتُ الْمَسْجِدَ فَإِذَا هُوَ سَاجِدٌ وَقَدَمَاهُ مَنْصُوبَتَانِ، وَهُوَ يَقُولُ: ”أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَأَعُوذُ بِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ، وَأَعُوذُ بِكَ مِنْكَ، لَا أُحْصِي ثَنَاءً عَلَيْكَ، أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ“. (م،د،جه)', 'ആഇശ(റ) യിൽനിന്ന് അബൂഹുറൈറ(റ) നിവേദനം ചെയ്യുന്നു: മഹതി പറഞ്ഞു: ഒരു ദിവസം രാത്രി എനിക്ക് റസൂൽ(സ)യെ കിട്ടാതെയായി, അപ്പോൾ ഞാൻ പള്ളിയിൽ പരതി, അപ്പോഴതാ റസൂൽ(സ) സുജൂദിലാണ്, അവിടുത്തെ ഇരുപാദങ്ങളും നിവർത്തിവെക്കപ്പെട്ടിരിക്കുന്നു, നബി(സ) പറയുന്നു: "നിന്റെ തൃപ്തി കൊണ്ട് നിന്റെ ദേഷ്യത്തിൽ നിന്നും, നിന്റെ പാപമോചനം കൊണ്ട് നിന്റെ ശിക്ഷയിൽ നിന്നും, നിന്നെക്കൊണ്ട് (അനുഗ്രഹം), നിന്നിൽ നിന്നും (ശിക്ഷ) ഞാൻ കാവൽ ചോദിക്കുന്നു. നിനക്കുള്ള സ്തുതികീർത്തനങ്ങൾ ഞാൻ തിട്ടപ്പെടുത്തുന്നില്ല, (നിന്നെ യഥാവിധി സ്തുതിക്കാൻ ഞാനശക്തനാണ്.) നീ നിന്നെത്തന്നെ സ്തുതിച്ചത് പോലെയാണ് നീ." (മു,ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'ആഇശ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 981, 982, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=131 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 299, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَتَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَوَاكِي، فَقَالَ: "اللَّهُمَّ اسْقِنَا غَيْثًا مُّغِيثًا مَرِيئًا مَرِيعًا نَافِعًا غَيْرَ ضَارٍّ، عَاجِلًا غَيْرَ آجِلٍ". قَالَ: فَأَطْبَقَتْ عَلَيْهِمُ السَّمَاءُ. (د)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): കുറച്ച് സ്ത്രീകൾ നബി(സ)യുടെ അടുത്തേക്ക് കരഞ്ഞ് കൊണ്ട് വന്നു. അപ്പോൾ അവിടന്ന് പ്രാർത്ഥിച്ചു: "അല്ലാഹുവേ, കോരിച്ചൊരിയുന്ന ശാന്തമായ സുഖകരവും ഞങ്ങൾക്ക് ഉപകരിക്കുന്നതും ഉപദ്രവിക്കാത്തതുമായ സമൃദ്ധവുമായ മഴ ഇപ്പോൾ തന്നെ ഞങ്ങൾക്ക് വർഷിപ്പിച്ച് തരേണമേ." നിവേദകൻ പറയുന്നു: അപ്പോൾ തന്നെ അവരുടെമേൽ മഴ വർഷിച്ചു. (ദ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 982, 982, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=132 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 300, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: شَكَا النَّاسُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قُحُوطَ الْمَطَرِ، فَأَمَرَ بِمِنْبَرٍ فَوُضِعَ لَهُ فِي الْمُصَلَّى، وَوَعَدَ النَّاسَ يَوْمًا يَخْرُجُونَ فِيهِ. قَالَتْ عَائِشَةُ: فَخَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ بَدَا حَاجِبُ الشَّمْسِ، فَقَعَدَ عَلَى الْمِنْبَرِ، فَكَبَّرَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَحَمِدَ اللَّهَ عَزَّ وَجَلَّ، ثُمَّ قَالَ: "إِنَّكُمْ شَكَوْتُمْ جَدْبَ دِيَارِكُمْ وَاسْتِئْخَارَ الْمَطَرِ عَنْ إِبَّانِ زَمَانِهِ عَنْكُمْ، وَقَدْ أَمَرَكُمُ اللَّهُ عَزَّ وَجَلَّ أَنْ تَدْعُوهُ، وَوَعَدَكُمْ أَنْ يَسْتَجِيبَ لَكُمْ". ثُمَّ قَالَ: "{الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ. الرَّحْمَنِ الرَّحِيمِ. مَلِكِ يَوْمِ الدِّينِ} لَا إِلَهَ إِلَّا اللَّهُ يَفْعَلُ مَا يُرِيدُ، اللَّهُمَّ أَنْتَ اللَّهُ لَا إِلَهَ إِلَّا أَنْتَ الْغَنِيُّ وَنَحْنُ الْفُقَرَاءُ، أَنْزِلْ عَلَيْنَا الْغَيْثَ، وَاجْعَلْ مَا أَنْزَلْتَ لَنَا قُوَّةً وَبَلَاغًا إِلَى حِينٍ". ثُمَّ رَفَعَ يَدَيْهِ فَلَمْ يَزَلْ فِي الرَّفْعِ حَتَّى بَدَا بَيَاضُ إِبْطَيْهِ، ثُمَّ حَوَّلَ إِلَى النَّاسِ ظَهْرَهُ، وَقَلَبَ - أَوْ حَوَّلَ - رِدَاءَهُ وَهُوَ رَافِعٌ يَدَيْهِ، ثُمَّ أَقْبَلَ عَلَى النَّاسِ، وَنَزَلَ فَصَلَّى رَكْعَتَيْنِ، فَأَنْشَأَ اللَّهُ سَحَابَةً فَرَعَدَتْ وَبَرَقَتْ، ثُمَّ أَمْطَرَتْ بِإِذْنِ اللَّهِ، فَلَمْ يَأْتِ مَسْجِدَهُ حَتَّى سَالَتِ السُّيُولُ، فَلَمَّا رَأَى سُرْعَتَهُمْ إِلَى الْكِنِّ ضَحِكَ حَتَّى بَدَتْ نَوَاجِذُهُ، فَقَالَ: "أَشْهَدُ أَنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، وَأَنِّي عَبْدُ اللَّهِ وَرَسُولُهُ". (د)', 'ആഇശ(റ): ജനങ്ങൾ റസൂൽ(സ)യോട് മഴയില്ലാത്തതിനെ കുറിച്ച് പരാതി പറഞ്ഞു: അവിടന്ന് മിമ്പർ കൊണ്ടു വരാൻ ആവശ്യപ്പെട്ടു. നിസ്കാര സ്ഥലത്ത് അത് വെക്കുകയും ജനങ്ങൾക്ക് അവർ പുറപ്പെടേണ്ട ദിവസത്തെ കുറിച്ച് മുന്നറിയിപ്പ് നൽകുകയും ചെയ്തു. ആഇശ(റ) പറയുന്നു: സൂര്യന്റെ ആദ്യത്തെ പ്രകാശം കണ്ടപ്പോൾ റസൂൽ(സ) പുറപ്പെട്ടു, മിമ്പറിൽ ഇരുന്നു. തക്ബീർ ചൊല്ലി, അല്ലാഹുവിനെ സ്തുതിച്ചു. ശേഷം അവിടന്ന് പറഞ്ഞു: "തീർച്ചയായും നിങ്ങളുടെ വീടുകളിലെ ക്ഷാമത്തെയും മഴ അതിന്റെ കാലത്ത് വർഷിക്കാതിരിക്കുന്നതിനെക്കുറിച്ചും നിങ്ങൾ എന്നോട് പരാതി പറഞ്ഞു: അല്ലാഹു നിങ്ങളോട് ദുആ ചെയ്യാൻ കൽപ്പിച്ചിരിക്കുന്നു. ഉത്തരം ചെയ്യുമെന്ന് വാഗ്ദാനവും നൽകിയിരിക്കുന്നു." പിന്നെ അവിടന്ന് പ്രാർത്ഥിച്ചു. ''"ലോകങ്ങളുടെ രക്ഷിതാവായ അല്ലാഹുവിനാണ് സർവ്വ സ്തുതിയും. അവൻ കരുണാ വാരിധിയും പ്രതിഫല ദിവസത്തിന്റെ ഉടമസ്ഥനുമാണ്. ആരാധ്യൻ അല്ലാഹു മാത്രമാണ്. അവനുദ്ദേശിക്കുന്നത് അവൻ ചെയ്യും, അല്ലാഹുവേ, ആരാധ്യൻ നീ മാത്രമാണ്, നീ ഐശ്വര്യവാനാണ്, ഞങ്ങൾ ആവശ്യമുള്ളവരുമാണ്, ഞങ്ങൾക്ക് മഴ വർഷിപ്പിച്ച് തരേണമേ, നീ ഇറക്കിയതിനെ എന്നെന്നേക്കുമായി ഞങ്ങൾക്ക് ശക്തിയും അഭയവുമാക്കേണമേ." പിന്നെ അവിടുത്തെ തിരുകരങ്ങൾ ഉയർത്തി. കക്ഷത്തിലെ വെളുപ്പ് കാണുന്നത് വരെ തിരുമേനി(സ) ഉയർത്തിക്കൊണ്ടിരുന്നു. പിന്നെ പുറംഭാഗം ജനങ്ങളുടെ ഭാഗത്തേക്കാക്കുകയും കൈ ഉയർത്തി ഷാൾ തിരിച്ചിടുകയും ചെയ്തു. ശേഷം ജനങ്ങളിലേക്ക് തിരിഞ്ഞു, മിൻബറിൽ നിന്നിറങ്ങി, രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. അപ്പോൾ അല്ലാഹു മേഘത്തെയുണ്ടാക്കുകയും ഇടി ശബ്ദം മുഴങ്ങുകയും മിന്നലെരിയുകയും ചെയ്തു. ശേഷം അല്ലാഹുവിന്റെ അനുവാദത്താൽ മേഘം മഴ വർഷിപ്പിക്കുകയും ചെയ്തു. വെള്ളം നന്നായി ഒഴുകി, അത് കൊണ്ട് നബി(സ) പള്ളിയിൽ പോയില്ല. ജനങ്ങൾ മഴ വെള്ളം ശേഖരിക്കുന്ന ധൃതി കണ്ടപ്പോൾ നബി(സ) അണപ്പല്ല് കാണും വിധം ചിരിച്ചു. എന്നിട്ടവിടന്ന് പറഞ്ഞു: "അല്ലാഹു എല്ലാറ്റിനും കഴിവുള്ളവനും, ഞാൻ അല്ലാഹുവിന്റെ അടിമയും അവന്റെ റസൂലുമാണെന്ന് ഞാൻ സാക്ഷ്യം വഹിക്കുകയും ചെയ്യുന്നു." (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 982, 983, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=132 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 301, 'عَنِ الْحَسَنِ بْنِ عَلِيٍّ رَضِيَ اللهُ عَنْهُمَا قَالَ: عَلَّمَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَلِمَاتٍ أَقُولُهُنَّ فِي الْوِتْرِ -وَفِي رِوَايَةٍ: فِي قُنُوتِ الْوِتْرِ: "اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ، وَعَافِنِي فِيمَنْ عَافَيْتَ، وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لِي فِيمَا أَعْطَيْتَ، وَقِنِي شَرَّ مَا قَضَيْتَ، إِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ، تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ". (د, ت, ن, جه)', 'ഹസനുബ്നു അലിയ്യ്(റ): റസൂൽ(സ) എനിക്ക് ചില വചനങ്ങൾ പഠിപ്പിച്ച് തന്നു. ഞാനവ വിത്റിൽ - മറ്റൊരു നിവേദനത്തിൽ: വിത്റിലെ ഖുനൂതിൽ- ചൊല്ലാറുണ്ട്: "അല്ലാഹുവേ, നീ സന്മാർഗത്തിലാക്കിയവരുടെ കൂട്ടത്തിലായി എന്നെയും സന്മാർഗ്ഗത്തിലാക്കേണമേ, നീ സുഖം നൽകിയവരിലായി എനിക്കും നീ സുഖം നൽകേണമേ, നീ ഏറ്റെടുത്തവരിലായി എന്നെയും നീ ഏറ്റെടുക്കേണമേ, നീ നൽകിയതിൽ എനിക്ക് ബറകത്ത് നൽകേണമേ, നീ വിധിച്ചതിന്റെ നാശത്തിൽ നിന്നും എന്നെ സംരക്ഷിക്കേണമേ, നീ വിധിക്കുന്നവനാണ്, നിന്റെ മേൽ വിധിക്കപ്പെടുകയില്ല, നീ ഏറ്റെടുത്തവൻ നിന്ദ്യനാകുകയില്ല, നീ ശത്രുത വെച്ചവൻ അന്തസ്സുള്ളവനാകുകയില്ല, ഞങ്ങളുടെ രക്ഷിതാവേ, നീ പരിശുദ്ധവാനും ഉന്നതനുമാണ്." (ദ,തു,ന,ജ)', 'الْحَسَنِ بْنِ عَلِيٍّ', 'ഹസനുബ്നു അലിയ്യ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 983, 983, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=133 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=301), 1, 'وَفِي رِوَايَةٍ: فِي قُنُوتِ الْوِتْرِ: "اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ، وَعَافِنِي فِيمَنْ عَافَيْتَ، وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لِي فِيمَا أَعْطَيْتَ، وَقِنِي شَرَّ مَا قَضَيْتَ، إِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ، تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ". (د, ت, ن, جه)', 'മറ്റൊരു നിവേദനത്തിൽ: വിത്റിലെ ഖുനൂതിൽ- ചൊല്ലാറുണ്ട്: "അല്ലാഹുവേ, നീ സന്മാർഗത്തിലാക്കിയവരുടെ കൂട്ടത്തിലായി എന്നെയും സന്മാർഗ്ഗത്തിലാക്കേണമേ, നീ സുഖം നൽകിയവരിലായി എനിക്കും നീ സുഖം നൽകേണമേ, നീ ഏറ്റെടുത്തവരിലായി എന്നെയും നീ ഏറ്റെടുക്കേണമേ, നീ നൽകിയതിൽ എനിക്ക് ബറകത്ത് നൽകേണമേ, നീ വിധിച്ചതിന്റെ നാശത്തിൽ നിന്നും എന്നെ സംരക്ഷിക്കേണമേ, നീ വിധിക്കുന്നവനാണ്, നിന്റെ മേൽ വിധിക്കപ്പെടുകയില്ല, നീ ഏറ്റെടുത്തവൻ നിന്ദ്യനാകുകയില്ല, നീ ശത്രുത വെച്ചവൻ അന്തസ്സുള്ളവനാകുകയില്ല, ഞങ്ങളുടെ രക്ഷിതാവേ, നീ പരിശുദ്ധവാനും ഉന്നതനുമാണ്." (ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 302, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ فِي آخِرِ وِتْرِهِ: "اللَّهُمَّ إِنِّي أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ، وَأَعُوذُ بِكَ مِنْكَ، لَا أُحْصِي ثَنَاءً عَلَيْكَ، أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ". (د, ت, ن, جه)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): റസൂൽ(സ) അവിടത്തെ വിത്റിന്റെ അവസാനത്തിൽ പറയാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ, നിന്റെ തൃപ്തി കൊണ്ട് നിന്റെ ദേഷ്യത്തിൽ നിന്നും, നിന്റെ മോചനം കൊണ്ട് നിന്റെ ശിക്ഷയിൽ നിന്നും നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു. നിന്നെക്കൊണ്ട് (അനുഗ്രഹം) നിന്നിൽ നിന്ന് (ശിക്ഷ) ഞാൻ കാവൽ ചോദിക്കുന്നു, നിന്റെ സ്തുതികൾ നീ സ്വയം സ്തുതിച്ചത് പോലെ തന്നെയാണ്. (ദ,തു,ന,ജ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 983, 983, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=133 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 303, 'عَنْ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: كَانَ يَقْبِضُ عَلَى لِحْيَتِهِ فَيَقْطَعُ مَا زَادَ عَلَى الْكَفِّ، وَقَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَفْطَرَ قَالَ: "ذَهَبَ الظَّمَأُ، وَابْتَلَّتِ الْعُرُوقُ، وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ". (د)', 'ഇബ്‌നുഉമർ(റ): അദ്ദേഹം തന്റെ താടിപിടിച്ച് മുൻകയ്യിനേക്കാൾ കൂടുതലുള്ളതിനെ വെട്ടുമായിരുന്നു. അദ്ദേഹം പറയുമായിരുന്നു: റസൂൽ(സ) നോമ്പ് തുറന്നാൽ പറയുമായിരുന്നു: "ദാഹം പോയി, ഞരമ്പുകൾ നനഞ്ഞു. ഇൻശാ അല്ലാഹ്, പ്രതിഫലം ദൃഢമാകുകയും ചെയ്തു." (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്‌നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 984, 984, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=134 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 304, 'عَنْ مُعَاذِ بْنِ زُهْرَةَ: أَنَّهُ بَلَغَهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا أَفْطَرَ قَالَ: "اللَّهُمَّ لَكَ صُمْتُ، وَعَلَى رِزْقِكَ أَفْطَرْتُ". (مرسل) (د)', 'മുആദുബ്‌നു സുഹ്റ(റ): നബി(സ) നോമ്പ് തുറന്നാൽ ഇങ്ങനെ പറയുമായിരുന്നുവെന്ന് അദ്ദേഹം പറയുന്നു: "അല്ലാഹുവേ, നിനക്ക് ഞാൻ നോമ്പനുഷ്ഠിച്ചു, നീ തന്നത് കൊണ്ട് ഞാൻ നോമ്പ് തുറക്കുകയും ചെയ്തു." (ഹദീസ് മുർസലാകുന്നു.) (ദ)', 'مُعَاذِ بْنِ زُهْرَةَ', 'മുആദുബ്‌നു സുഹ്റ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 984, 984, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=134 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 305, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا اسْتَجَدَّ ثَوْبًا سَمَّاهُ بِاسْمِهِ: إِمَّا قَمِيصًا أَوْ عِمَامَةً، ثُمَّ يَقُولُ: "اللَّهُمَّ لَكَ الْحَمْدُ، أَنْتَ كَسَوْتَنِيهِ، أَسْأَلُكَ مِنْ خَيْرِهِ وَخَيْرِ مَا صُنِعَ لَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّهِ وَشَرِّ مَا صُنِعَ لَهُ". (د)', 'അബൂസഈദിൽ ഖുദ്‌രി(റ): റസൂൽ(സ) പുതിയ വസ്ത്രം ധരിക്കുകയാണെങ്കിൽ അതിന്റെ പേര് പറയുമായിരുന്നു, ഒന്നുകിൽ ഖമീസെന്ന് അല്ലെങ്കിൽ തലപ്പാവ് എന്ന്. ശേഷം പറയും: "അല്ലാഹുവേ, നിനക്കാണ് സർവ്വ സ്തുതിയും, നീ അതെനിക്ക് ധരിപ്പിച്ചു, അതിന്റെ നന്മയെയും അതുണ്ടാക്കപ്പെട്ടതിന്റെ നന്മയെയും നിന്നോട് ഞാൻ ചോദിക്കുന്നു. അതിന്റെ നാശത്തിൽ നിന്നും അത് സൃഷ്ടിക്കപ്പെട്ടതിന്റെ നാശത്തിൽ നിന്നും നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു." (ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 984, 984, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=135 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 306, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَكَلَ طَعَامًا ثُمَّ قَالَ: الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا الطَّعَامَ وَرَزَقَنِيهِ، مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ، غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ وَمَا تَأَخَّرَ. وَمَنْ لَبِسَ ثَوْبًا فَقَالَ: الْحَمْدُ لِلَّهِ الَّذِي كَسَانِي هَذَا الثَّوْبَ وَرَزَقَنِيهِ، مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ، غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ وَمَا تَأَخَّرَ". (د,ت,جه)', 'അനസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും ഭക്ഷണം കഴിച്ച്: എന്നിൽ നിന്നുള്ള കഴിവോ ശക്തിയോ ഇല്ലാതെ ഈ ഭക്ഷണം എനിക്ക് നൽകുകയും എന്നെ ഭക്ഷിപ്പിക്കുകയും ചെയ്ത അല്ലാഹുവിനാണ് സർവ്വ സ്തുതിയും എന്ന് പറഞ്ഞാൽ അവന്റെ മുൻകഴിഞ്ഞ പാപങ്ങളും ശേഷം ചെയ്യാനിരിക്കുന്നതും പൊറുക്കപ്പെടും. ആരെങ്കിലും വസ്ത്രം ധരിച്ച് എന്നിൽ നിന്ന് ഒരു ശക്തിയും കഴിവുമില്ലാതെ ഈ വസ്ത്രം എനിക്ക് നൽകുകയും എന്നെ ധരിപ്പിക്കുകയും ചെയ്ത അല്ലാഹുവിനാണ് സർവ്വ സ്തുതിയും, എന്ന് പറഞ്ഞാൽ അവന്റെ മുൻകഴിഞ്ഞതും വരാനിരിക്കുന്നതുമായ ദോഷങ്ങൾ പൊറുക്കപ്പെടുന്നതാണ്." (ദ,തു,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 984, 984, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=135 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 307, 'عَنْ عَبْدِ اللَّهِ بْنِ خُبَيْبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَصَابَنَا طَشٌّ وَظُلْمَةٌ، فَانْتَظَرْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِيُصَلِّيَ بِنَا،فَخَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِيُصَلِّيَ بِنَا فَقَالَ: "قُلْ". فَقُلْتُ: مَا أَقُولُ؟ قَالَ: "قُلْ {هُوَ اللَّهُ أَحَدٌ} وَالْمُعَوِّذَتَيْنِ حِينَ تُمْسِي وَحِينَ تُصْبِحُ، ثَلَاثًا، يَكْفِيكَ كُلَّ شَيْءٍ". وفي رواية قَالَ: كُنْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي طَرِيقِ مَكَّةَ، فَأَصَبْتُ خَلْوَةً مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَدَنَوْتُ مِنْهُ، فَقَالَ: "قُلْ"، فَقُلْتُ: مَا أَقُولُ؟ قَالَ: "قُلْ". قُلْتُ: مَا أَقُولُ؟ قَالَ: {قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ} حَتَّى خَتَمَهَا، ثُمَّ قَالَ: {قُلْ أَعُوذُ بِرَبِّ النَّاسِ} حَتَّى خَتَمَهَا، ثُمَّ قَالَ: "مَا تَعَوَّذَ النَّاسُ بِأَفْضَلَ مِنْهُمَا". (ن)', 'അബ്ദുല്ലാഹിബ്നു ഖുബൈബ്(റ): ഇരുട്ടും നേരിയ മഴയും ഞങ്ങളെ ബാധിച്ചു. ഞങ്ങൾക്ക് ഇമാമായി നിസ്കരിക്കാൻ തിരുമേനി(സ)യെ ഞങ്ങൾ കാത്തിരുന്നു. അങ്ങനെ ഞങ്ങളോട്കൂടെ നിസ്കരിക്കാൻ തിരുമേനി(സ) പുറപ്പെട്ടു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നീ പറയുക" ഞാൻ ചോദിച്ചു: ഞാനെന്താണ് പറയേണ്ടത്? തിരുമേനി(സ) പറഞ്ഞു: "പ്രഭാതത്തിലും പ്രദോഷത്തിലും മൂന്ന് തവണ വീതം ഇഖ്‌ലാസ് സൂറതും മുഅവ്വിദതൈനിയും ഓതുക, എല്ലാത്തിനെയും അത് നിനക്ക് മതിയാക്കിത്തരും." (ന)
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=307), 1, 'وَفِي رِوَايَةٍ قَالَ: كُنْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي طَرِيقِ مَكَّةَ، فَأَصَبْتُ خَلْوَةً مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَدَنَوْتُ مِنْهُ، فَقَالَ: "قُلْ"، فَقُلْتُ: مَا أَقُولُ؟ قَالَ: "قُلْ". قُلْتُ: مَا أَقُولُ؟ قَالَ: {قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ} حَتَّى خَتَمَهَا، ثُمَّ قَالَ: {قُلْ أَعُوذُ بِرَبِّ النَّاسِ} حَتَّى خَتَمَهَا، ثُمَّ قَالَ: "مَا تَعَوَّذَ النَّاسُ بِأَفْضَلَ مِنْهُمَا". (ن)', 'മറ്റൊരു നിവേദനം: മക്കയിലേക്കുള്ള വഴിയെ ഞാൻ തിരുമേനി(സ)യുടെ കൂടെയായിരുന്നു. ഞാൻ കുറച്ച് നേരം നബി(സ)യിൽ നിന്ന് മാറി നിന്നു. ശേഷം തിരുമേനി(സ)യുടെ അടുത്ത് ചെന്നു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നീ പറയുക." ഞാൻ ചോദിച്ചു: ഞാനെന്താണ് പറയേണ്ടത്?". അപ്പോൾ തിരുമേനി(സ) ഫലഖ് സൂറത് അവസാനം വരെ ഓതി. പിന്നെ തിരുമേനി(സ) ''നാസ്'' സൂറതും അവസാനം വരെ ഓതി. പിന്നീട് പറഞ്ഞു: "ഇവ രണ്ടിനേക്കാളും ശ്രേഷ്ഠമായതു കൊണ്ട് ജനങ്ങൾ കാവലിനെ ചോദിച്ചിട്ടില്ല." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 308, 'عَنِ ابْنِ عَابِسٍ الْجُهَنِيِّ رَضِيَ اللَّهُ عَنْهُ: أَخْبَرَهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهُ: يَا ابْنَ عَابِسٍ، أَلَا أَدُلُّكَ - أَوْ قَالَ أَلَا أُخْبِرُكَ - بِأَفْضَلِ مَا يَتَعَوَّذُ بِهِ الْمُتَعَوِّذُونَ؟". قَالَ: بَلَى يَا رَسُولَ اللَّهِ. قَالَ: "{قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ} وَ {قُلْ أَعُوذُ بِرَبِّ النَّاسِ} هَاتَيْنِ السُّورَتَيْنِ". (ن)', 'ഇബ്നുആബിസിൽ ജുഹനി(റ): റസൂൽ(സ) അവരോട് പറഞ്ഞു: "ഇബ്നുആബിസെ, കാവൽ ചോദിക്കുന്നവർ കാവൽ ചോദിക്കുന്ന ശ്രേഷ്ഠമായ മാർഗ്ഗം ഞാൻ നിനക്ക് അറിയിച്ചു തരട്ടെയോ?" അവർ പറഞ്ഞു: അതെ, റസൂലേ. റസൂൽ(സ) പറഞ്ഞു: "ഫലഖ്, നാസ് എന്നീ അധ്യായങ്ങൾ." (ന)', 'ابْنِ عَابِسٍ الْجُهَنِيِّ', 'ഇബ്നുആബിസിൽ ജുഹനി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 985, 985, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=137 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 309, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أُهْدِيَتْ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَغْلَةٌ شَهْبَاءُ فَرَكِبَهَا، وَأَخَذَ عُقْبَةُ يَقُودُهَا بِهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِعُقْبَةَ: "اقْرَأْ". قَالَ: وَمَا أَقْرَأُ يَا رَسُولَ اللَّهِ؟ قَالَ: "اقْرَأْ: {قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ. مِنْ شَرِّ مَا خَلَقَ}" فَأَعَادَهَا عَلَيَّ حَتَّى قَرَأْتُهَا، فَعَرَفَ أَنِّي لَمْ أَفْرَحْ بِهَا جِدًّا، قَالَ: "لَعَلَّكَ تَهَاوَنْتَ بِهَا". فَمَا قُمْتُ بِمِثْلِهَا. وفِي رِوَايَةٍ: أَنَّهُ سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُعَوِّذَتَيْنِ؟ قَالَ عُقْبَةُ: فَأَمَّنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِهِمَا فِي صَلَاةِ الْغَدَاةِ. وفِي رِوايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَرَأَ بِهِمَا فِي صَلَاةِ الصُّبْحِ.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=309), 1, 'وَفِي رِوَايَةٍ: أَنَّهُ سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُعَوِّذَتَيْنِ؟ قَالَ عُقْبَةُ: فَأَمَّنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِهِمَا فِي صَلَاةِ الْغَدَاةِ.', 'മറ്റൊരു നിവേദനം: അദ്ദേഹം റസൂൽ(സ) തങ്ങളോട് ''മുഅവ്വിദതൈനി''യെ സംബന്ധിച്ച് ചോദിച്ചു: ഉഖ്ബ(റ) പറയുന്നു: അങ്ങനെ സുബ്ഹി നമസ്കാരത്തിന് റസൂൽ(സ) ഞങ്ങൾക്ക് ഇമാമത് നിന്നത് ഇവ രണ്ട് കൊണ്ടുമായിരുന്നു. (റക്അത്തുകളിൽ ഓതിയ സൂറത് ഇവയായിരുന്നു).');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=309), 2, 'وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَرَأَ بِهِمَا فِي صَلَاةِ الصُّبْحِ.', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) അവ രണ്ടും സുബ്ഹി നിസ്കാരത്തിൽ ഓതി.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=309), 3, 'وَفِي رِوَايَةٍ: كُنْتُ أَقُودُ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي السَّفَرِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا عُقْبَةُ، أَلَا أُعَلِّمُكَ خَيْرَ سُورَتَيْنِ قُرِئَتَا". فَعَلَّمَنِي: {قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ} وَ{ قُلْ أَعُوذُ بِرَبِّ النَّاسِ}. فَلَمْ يَرَنِي سُرِرْتُ بِهِمَا جِدًّا، فَلَمَّا نَزَلَ لِصَلَاةِ الصُّبْحِ صَلَّى بِهِمَا صَلَاةَ الصُّبْحِ لِلنَّاسِ، فَلَمَّا فَرَغَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الصَّلَاةِ الْتَفَتَ إِلَيَّ فَقَالَ: "يَا عُقْبَةُ، كَيْفَ رَأَيْتَ؟".', 'മറ്റൊരു നിവേദന്: യാത്രയിൽ ഞാൻ റസൂൽ(സ)യെ ആനയിച്ച് കൊണ്ടിരിക്കുകയായിരുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഉഖ്ബാ, ഓതപ്പെട്ട ഏറ്റവും നല്ല രണ്ട് സൂറതുകൾ നിനക്ക് ഞാൻ പഠിപ്പിച്ച് തരട്ടെയോ?" അങ്ങനെ റസൂൽ(സ) എനിക്ക് ഫലഖ്, നാസ് സൂറഃകൾ പഠിപ്പിച്ച് തന്നു. അപ്പോൾ റസൂൽ(സ) എന്നെ അതീവ സന്തുഷ്ടനായി കണ്ടില്ല. സുബ്ഹി നിസ്കാരത്തിനിറങ്ങിയപ്പോൾ ജനങ്ങൾക്ക് ഇവ രണ്ട് കൊണ്ടുമാണ് സുബ്ഹി നിസ്കരിച്ചത്. നിസ്കാരം കഴിഞ്ഞപ്പോൾ റസൂൽ(സ) എന്നിലേക്ക് തിരിഞ്ഞു പറഞ്ഞു: "ഉഖ്ബാ, നിനക്കെങ്ങനെ അനുഭവപ്പെട്ടു."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=309), 4, 'وَفِي رِوَايَةٍ: بَيْنَا أَقُودُ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي نَقَبٍ مِنْ تِلْكَ النِّقَابِ إِذْ قَالَ: "أَلَا تَرْكَبُ يَا عُقْبَةُ؟". فَأَجْلَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ أَرْكَبَ مَرْكَبَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ قَالَ: "أَلَا تَرْكَبُ يَا عُقْبَةُ؟". فَأَشْفَقْتُ أَنْ يَكُونَ مَعْصِيَةً، فَنَزَلَ وَرَكِبْتُ هُنَيْهَةً. وَنَزَلْتُ، وَرَكِبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ قَالَ: "أَلَا أُعَلِّمُكَ سُورَتَيْنِ مِنْ خَيْرِ سُورَتَيْنِ قَرَأَ بِهِمَا النَّاسُ". فَأَقْرَأَنِي: {قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ} وَ{ قُلْ أَعُوذُ بِرَبِّ النَّاسِ}. فَأُقِيمَتِ الصَّلَاةُ فَتَقَدَّمَ فَقَرَأَ بِهِمَا، ثُمَّ مَرَّ بِي فَقَالَ: "كَيْفَ رَأَيْتَ يَا عُقْبَةَ بْنَ عَامِرٍ؟ اقْرَأْ بِهِمَا كُلَّمَا نِمْتَ وَقُمْتَ".', 'മറ്റൊരു നിവേദനം: ആ പർവ്വതത്തിനടിയിലുള്ള ഒരു വഴിയിലൂടെ ഞാൻ റസൂൽ(സ)യെ നയിച്ച് കൊണ്ടിരിക്കുന്നതിനിടയിൽ റസൂൽ(സ) ചോദിച്ചു: "ഉഖ്ബാ, നീ കയറുന്നില്ലേ?" അപ്പോൾ റസൂൽ(സ)യുടെ ഒരു വാഹനത്തിൽ കയറാൻ എനിക്ക് വല്ലായ്മ തോന്നി. പിന്നെയും റസൂൽ(സ) ചോദിച്ചു: "നീ കയറുന്നില്ലേ, ഉഖ്ബാ" അപ്പോൾ കയറാതിരിക്കുന്നത് തെറ്റാകുമോ എന്ന് ഞാൻ പേടിച്ചു. അങ്ങനെ റസൂൽ(സ) ഇറങ്ങി, അൽപ നേരം ഞാൻ കയറി. പിന്നെ ഞാൻ ഇറങ്ങി. റസൂൽ(സ) കയറി. പിന്നെ ചോദിച്ചു: "ജനങ്ങൾ പാരായണം ചെയ്ത രണ്ട് സൂറതുകളിൽ ഏറ്റവും നല്ല രണ്ട് സൂറതുകൾ നിനക്ക് ഞാൻ പഠിപ്പിച്ച് തരട്ടെയോ?" അങ്ങനെ ഫലഖ് സൂറതും നാസ് സൂറതും എനിക്ക് തിരുമേനി(സ) ഓതിത്തന്നു. നിസ്കാരത്തിന് ഇഖാമത് വിളിച്ചു. റസൂൽ(സ) കയറി നിന്ന് ഈ രണ്ട് സൂറതുകളും ഓതി. പിന്നെ എന്റെ അരികിലൂടെ നടന്നുപോയപ്പോൾ എന്നോട് ചോദിച്ചു: "ഉഖ്ബതുബ്നു ആമിറേ(റ), എങ്ങനെയുണ്ട്? നീ ഉറങ്ങുമ്പോഴും എഴുന്നേൽക്കുമ്പോഴുമൊക്കെ ഇത് ഓതുക."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=309), 5, 'وَفِي رِوَايَةٍ قَالَ: كُنْتُ أَمْشِي مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "يَا عُقْبَةُ، قُلْ". فَقُلْتُ: مَاذَا أَقُولُ يَا رَسُولَ اللَّهِ؟ فَسَكَتَ عَنِّي، ثُمَّ قَالَ: "يَا عُقْبَةُ، قُلْ". قُلْتُ: مَاذَا أَقُولُ يَا رَسُولَ اللَّهِ؟ فَسَكَتَ عَنِّي، فَقُلْتُ: اللَّهُمَّ ارْدُدْهُ عَلَيَّ. فَقَالَ: "يَا عُقْبَةُ، قُلْ". قُلْتُ: مَاذَا أَقُولُ يَا رَسُولَ اللَّهِ؟ فَقَالَ: {قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ}. فَقَرَأْتُهَا حَتَّى أَتَيْتُ عَلَى آخِرِهَا، ثُمَّ قَالَ: "قُلْ". قُلْتُ: مَاذَا أَقُولُ يَا رَسُولَ اللَّهِ؟ قَالَ: {قُلْ أَعُوذُ بِرَبِّ النَّاسِ}. فَقَرَأْتُهَا حَتَّى أَتَيْتُ عَلَى آخِرِهَا، ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ ذَلِكَ: "مَا سَأَلَ سَائِلٌ بِمِثْلِهِمَا، وَلَا اسْتَعَاذَ مُسْتَعِيذٌ بِمِثْلِهِمَا".', 'മറ്റൊരു നിവേദനം: ഉഖ്ബ(റ) പറഞ്ഞു: ഞാൻ റസൂൽ(സ)യോട് കൂടെ നടക്കുകയായിരുന്നു. റസൂൽ(സ) പറഞ്ഞു: "ഉഖ്ബാ, നീ പറയുക." ഞാൻ ചോദിച്ചു: ഞാനെന്താണ് പറയേണ്ടത്, അല്ലാഹുവിന്റെ തിരുദൂതരേ? അപ്പോൾ റസൂൽ(സ) കുറച്ച് നേരം മൗനം ദീക്ഷിച്ചു. പിന്നെ പറഞ്ഞു: "ഉഖ്ബാ, നീ പറയുക." ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാനെന്താണ് പറയേണ്ടത്? അപ്പോഴും റസൂൽ(സ) മിണ്ടാതിരുന്നു. അപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹുവേ, നീ എനിക്ക് ഒന്ന് കൂടി മടക്കിപ്പറയിപ്പിച്ച് തരൂ. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഉഖ്ബാ നീ പറയുക" ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ തിരുദൂതരേ, ഞാനെന്താണ് പറയേണ്ടത്? അപ്പോൾ റസൂൽ(സ) ഫലഖ് സൂറഃ അവസാനം വരെ ഓതി. പിന്നെ പറഞ്ഞു: "നീ പറയുക." ഞാൻ ചോദിച്ചു: ഞാനെന്താണ് പറയുക, അല്ലാഹുവിന്റെ തിരുദൂതരേ? അപ്പോൾ റസൂൽ(സ) നാസ് സൂറഃയും അവസാനം വരെ ഓതി. ആ സമയത്ത് റസൂൽ(സ) പറഞ്ഞു: "ചോദിക്കുന്ന ഒരാളും അവ പോലുള്ളവ കൊണ്ട് ചോദിച്ചിട്ടില്ല, അഭയം ചോദിക്കുന്ന ഒരാളും അവ പോലെയുള്ളത് കൊണ്ട് അഭയം ചോദിച്ചിട്ടില്ല."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=309), 6, 'وَفِي رِوَايَةٍ قَالَ: أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ رَاكِبٌ، فَوَضَعْتُ يَدِي عَلَى قَدَمِهِ، فَقُلْتُ: أَقْرِئْنِي سُورَةَ هُودٍ، أَقْرِئْنِي سُورَةَ يُوسُفَ. فَقَالَ: "لَنْ تَقْرَأَ شَيْئًا أَبْلَغَ عِنْدَ اللَّهِ عَزَّ وَجَلَّ مِنْ: {قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ}".', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) യാത്രക്കാരനായിരിക്കെ ഞാൻ ചെന്നു. അങ്ങനെ റസൂൽ(സ)യുടെ പാദത്തിൽ എന്റെ കൈ വെച്ചു. ഞാൻ പറഞ്ഞു: എനിക്ക് ഹൂദ്സൂറത് ഓതിത്തരിക, യൂസുഫ് സൂറത് എനിക്കോതിത്തരിക. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഫലഖ് സൂറഃയേക്കാൾ വലിയ മഹത്തരമായ ഒന്നും തന്നെ നീ ഓതുകയില്ല."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=309), 7, 'وَفِي رِوَايَةٍ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أُنْزِلَ عَلَيَّ آيَاتٌ لَمْ يُرَ مِثْلُهُنَّ: {قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ} إِلَى آخِرِ السُّورَةِ، وَ: {قُلْ أَعُوذُ بِرَبِّ النَّاسِ} إِلَى آخِرِ السُّورَةِ". (ن)', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) പറഞ്ഞു: "എനിക്ക് കുറച്ച് ആയത്തുകൾ ഇറക്കപ്പെട്ടു, അവ പോലെയുള്ളത് കാണപ്പെട്ടിട്ടില്ല. "ഫലഖ്സൂറത് അവസാനംവരെയും നാസ്സൂറത് അവസാനംവരെയും." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 310, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَدْعُو بِهَذِهِ الدَّعَوَاتِ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ، وَقَلْبٍ لَا يَخْشَعُ، وَدُعَاءٍ لَا يُسْمَعُ، وَنَفْسٍ لَا تَشْبَعُ، ثُمَّ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ هَؤُلَاءِ الْأَرْبَعِ". (ن)', 'അനസ്(റ): നബി(സ) ഈ പ്രാർത്ഥനകൾ കൊണ്ട് ദുആ ഇരക്കുമായിരുന്നു: "അല്ലാഹുവേ, ഉപകാരമില്ലാത്ത അറിവിൽ നിന്നും, ഭയഭക്തിയില്ലാത്ത ഹൃദയത്തിൽ നിന്നും, ഉത്തരം ചെയ്യപ്പെടാത്ത പ്രാർത്ഥനയിൽ നിന്നും വയറ് നിറയാത്ത ശരീരത്തിൽ നിന്നും നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു." എന്നിട്ട് പറയും: "അല്ലാഹുവേ, ഈ നാലു കാര്യങ്ങളിൽ നിന്നും നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു." (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 987, 988, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=138 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 311, 'عَنْ شَكَلِ بْنِ حُمَيْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا نَبِيَّ اللهِ، عَلِّمْنِي تَعَوُّذًا أَتَعَوَّذُ بِهِ. فَأَخَذَ بِيَدِي ثُمَّ قَالَ: "قُلْ: أَعُوذُ بِكَ مِنْ شَرِّ سَمْعِي، وَشَرِّ بَصَرِي، وَشَرِّ لِسَانِي، وَشَرِّ قَلْبِي، وَشَرِّ مَنِيِّي". قَالَ: حَتَّى حَفِظْتُهَا. (ن)', 'ശക്ലുബ്നു ഹുമൈദ്(റ): ഞാൻ നബി(സ) തങ്ങളുടെ അടുത്ത് ചെന്നു പറഞ്ഞു: അല്ലാഹുവിന്റെ പ്രവാചകരേ, എനിക്ക് കാവൽ ചോദിക്കാവുന്ന ഒരുകലിമ പഠിപ്പിച്ചുതരണം. റസൂൽ(സ) എന്റെ കൈപിടിച്ച് പറഞ്ഞു: "നീ പറയുക, എന്റെ കേൾവിയുടെ നാശത്തിൽ നിന്നും, കാഴ്ചയുടെ നാശത്തിൽ നിന്നും, എന്റെ നാവിന്റെ നാശത്തിൽ നിന്നും, എന്റെ ഹൃദയത്തിന്റെ നാശത്തിൽ നിന്നും, എന്റെ ഇന്ദ്രിയത്തിന്റെ നാശത്തിൽ നിന്നും ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു." അങ്ങനെ ഞാനത് മനഃപാഠമാക്കി. (ന)', 'شَكَلِ بْنِ حُمَيْدٍ', 'ശക്ലുബ്നു ഹുമൈദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 988, 988, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=139 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 312, 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَتَعَوَّذُ مِنْ خَمْسٍ: مِنَ الْبُخْلِ، وَالْجُبْنِ، وَسُوءِ الْعُمْرِ، وَفِتْنَةِ الصَّدْرِ، وَعَذَابِ الْقَبْرِ. (ن)', 'ഇബ്നുമസ്ഊദ്(റ): നബി(സ) അഞ്ച് കാര്യങ്ങളിൽ നിന്നും കാവൽ ചേദിക്കാറുണ്ടായിരുന്നു: ലുബ്ധത, ഭീരുത്വം, മോശമായ ആയുസ്സ്, നെഞ്ചിന്റെ(ഹൃദയത്തിന്റെ) ഫിത്ന, ഖബ്റിലെ ശിക്ഷ എന്നിവയിൽ നിന്ന്. (ന)', 'ابْنِ مَسْعُودٍ', 'ഇബ്നുമസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 988, 988, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=140 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 313, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللهُ عَنْهُ: كَانَ يُعَلِّمُ بَنِيهِ هَؤُلَاءِ الْكَلِمَاتِ، كَمَا يُعَلِّمُ الْمُعَلِّمُ الْغِلْمَانَ، وَيَقُولُ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، كَانَ يَتَعَوَّذُ بِهِنَّ دُبُرَ الصَّلَاةِ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْبُخْلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ، وَأَعُوذُ بِكَ أَنْ أُرَدَّ إِلَى أَرْذَلِ الْعُمْرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ". (ن)', 'സഅ്ദുബ്നു അബീവഖാസ്(റ): അദ്ദേഹം അധ്യാപകൻ കുട്ടികളെ പഠിപ്പിക്കുന്നത് പോലെ തന്റെ മക്കളെ ഈ വാചകങ്ങൾ പഠിപ്പിക്കുമായിരുന്നു. എന്നിട്ടവരോട് പറയും: തീർച്ചയായും റസൂൽ(സ) നിസ്കാരത്തിന് ശേഷവും ഈ വാചകങ്ങൾ കൊണ്ട് കാവൽ ചോദിക്കുമായിരുന്നു: "അല്ലാഹുവേ, ലുബ്ധതയിൽ നിന്ന് നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു, ഭീരുത്വത്തിൽ നിന്ന് ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു, ഏറ്റവും മോശപ്പെട്ട ആയുസ്സിലേക്ക് തള്ളപ്പെടുന്നതിൽ നിന്ന് ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു, ദുൻയാവിന്റെ പരീക്ഷണത്തിൽ നിന്ന് നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു, ഖബ്‌റിലെ ശിക്ഷയിൽ നിന്ന് നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു." (ന)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദുബ്നു അബീവഖാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 988, 989, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=140 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 314, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ دَعَوَاتٌ لَا يَدَعُهُنَّ، كَانَ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَفِي رِوَايَةٍ: وَالدَّيْنِ، وَغَلَبَةِ الرِّجَالِ". وفي رواية: كانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَدْعُو: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكَسَلِ وَ الْهَرَمِ، وَالْجُبْنِ وَ الْبُخْلِ، وَ فِتْنَةِ الدَّجَّالِ وَ عَذَابِ الْقَبْرِ". وفي رواية: كَانَ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْعَجْزِ وَ الْكَسَلِ وَ الْهَرَمِ، وَ الْبُخْلِ وَالجُبْنِ، وَأَعُوذُ بِكَ مِنْ عَذَابِ القَبْرِ ومِنْ فِتْنَةِ المَحْيَا وَ الْمَمَاتِ". (ن)', 'അനസ്(റ): റസൂൽ(സ) ഒരിക്കലും ഒഴിവാക്കാത്ത പ്രാർത്ഥനകളുണ്ടായിരുന്നു. റസൂൽ(സ) പറയുമായിരുന്നു: "അല്ലാഹുവേ, ദുഃഖം, വ്യസനം, അശക്തത, മടി, ലുബ്ധത, ഭീരുത്വം എന്നിവയിൽ നിന്ന് നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു." മറ്റൊരു നിവേദനം: "കടത്തിൽ നിന്നും ആളുകൾ അതിജയിക്കുന്നതിൽ നിന്നും." മറ്റൊരു റിപ്പോർട്ട്: നബി(സ) പ്രാർത്ഥിക്കാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ, മടി, വാർദ്ധക്യം (വാർദ്ധക്യ സഹജമായ വിഷമങ്ങൾ), ഭീരുത്വം, ലുബ്ധത, ദജ്ജാലിന്റെ ഫിത്ന, ഖബ്റിലെ ശിക്ഷ എന്നിവയിൽ നിന്ന് നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു. മറ്റൊരു റിപ്പോർട്ട്: റസൂൽ(സ) പറയുമായിരുന്നു: "അല്ലാഹുവേ, അശക്തത, മടി, വാർദ്ധക്യം, ലുബ്ധത, ഭീരുത്വം എന്നിവയിൽ നിന്ന് നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു. ഖബ്റിലെ ശിക്ഷയിൽ നിന്നും ജീവിതത്തിന്റെയും മരണത്തിന്റെയും ഫിത്നയിൽ നിന്നും നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു." (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 989, 989, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=140 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=314), 1, 'وَفِي رِوَايَةٍ: وَالدَّيْنِ، وَغَلَبَةِ الرِّجَالِ".', 'മറ്റൊരു നിവേദനം: "കടത്തിൽ നിന്നും ആളുകൾ അതിജയിക്കുന്നതിൽ നിന്നും."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=314), 2, 'وَفِي رِوَايَةٍ: كانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَدْعُو: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكَسَلِ وَ الْهَرَمِ، وَالْجُبْنِ وَ الْبُخْلِ، وَ فِتْنَةِ الدَّجَّالِ وَ عَذَابِ الْقَبْرِ".', 'മറ്റൊരു നിവേദന്: നബി(സ) പ്രാർത്ഥിക്കാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ, മടി, വാർദ്ധക്യം (വാർദ്ധക്യ സഹജമായ വിഷമങ്ങൾ), ഭീരുത്വം, ലുബ്ധത, ദജ്ജാലിന്റെ ഫിത്ന, ഖബ്റിലെ ശിക്ഷ എന്നിവയിൽ നിന്ന് നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=314), 3, 'وَفِي رِوَايَةٍ: كَانَ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْعَجْزِ وَ الْكَسَلِ وَ الْهَرَمِ، وَ الْبُخْلِ وَالجُبْنِ، وَأَعُوذُ بِكَ مِنْ عَذَابِ القَبْرِ ومِنْ فِتْنَةِ المَحْيَا وَ الْمَمَاتِ". (ن)', 'മറ്റൊരു നിവേദന്: റസൂൽ(സ) പറയുമായിരുന്നു: "അല്ലാഹുവേ, അശക്തത, മടി, വാർദ്ധക്യം, ലുബ്ധത, ഭീരുത്വം എന്നിവയിൽ നിന്ന് നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു. ഖബ്റിലെ ശിക്ഷയിൽ നിന്നും ജീവിതത്തിന്റെയും മരണത്തിന്റെയും ഫിത്നയിൽ നിന്നും നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 315, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: يَقُولُ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِأَبِي طَلْحَةَ: "الْتَمِسْ لِي غُلَامًا مِنْ غِلْمَانِكُمْ يَخْدُمُنِي". فَخَرَجَ بِي أَبُو طَلْحَةَ يَرْدُفُنِي وَرَاءَهُ فَكُنْتُ أَخْدُمُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كُلَّمَا نَزَلَ فَكُنْتُ أَسْمَعُهُ يُكْثِرُ أَنْ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَرَمِ وَالْحَزَنِ وَالْعَجْزِ وَالْكَسَلِ وَالْبُخْلِ وَالْجُبْنِ وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ". (ن)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) അബൂത്വൽഹ(റ)വിനോട് പറഞ്ഞു: നിങ്ങളുടെ കുട്ടികളിൽ നിന്നും എനിക്ക് ഖിദ്മത് ചെയ്യുന്ന ഒരു കുട്ടിയെ എനിക്ക് വേണ്ടി അന്വേഷിക്കുക. അങ്ങനെ അബൂത്വൽഹ(റ) എന്നെ തന്റെ പിന്നിലിരുത്തി പുറപ്പെട്ടു. റസൂൽ(സ) ഇറങ്ങുമ്പോഴൊക്കെ റസൂൽ(സ)ക്ക് ഞാൻ പരിചരിച്ചുകൊണ്ടിരുന്നു. അപ്പോഴൊക്കെ റസൂൽ(സ): "അല്ലാഹുവേ, വാർദ്ധക്യത്തിൽ നിന്നും, ദുഃഖത്തിൽ നിന്നും, മടി, അശക്തത, ഭീരുത്വം, ലുബ്ധത, കടങ്ങൾ അധികരിക്കൽ, ആളുകൾ അതിജയിക്കൽ എന്നിവയിൽ നിന്നും നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു." എന്ന് ധാരാളം പറയുന്നതായി ഞാൻ കേട്ടുകൊണ്ടിരുന്നു. (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 989, 989, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=140 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 316, 'عَنْ زَيْدِ بْنِ أَرْقَمَ رَضِيَ اللهُ عَنْهُ قَالَ: لَا أُعَلِّمُكُمْ إِلَّا مَا كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُعَلِّمُنَا، يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ وَالْهَرَمِ وَعَذَابِ الْقَبْرِ. اللَّهُمَّ آتِ نَفْسِي تَقْوَاهَا، وَزَكِّهَا أَنْتَ خَيْرُ مَنْ زَكَّاهَا، أَنْتَ وَلِيُّهَا وَمَوْلَاهَا. اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ قَلْبٍ لَا يَخْشَعُ، وَمِنْ نَفْسٍ لَا تَشْبَعُ، وَعِلْمٍ لَا يَنْفَعُ، وَدَعْوَةٍ لَا يُسْتَجَابُ لَهَا». (ن)', 'സൈദുബ്നു അർഖം(റ): റസൂൽ(സ) ഞങ്ങളെ പഠിപ്പിച്ചിരുന്നതല്ലാതെ ഞാൻ നിങ്ങളെ പഠിപ്പിക്കുകയില്ല. റസൂൽ(സ) പറയുന്നു: "അല്ലാഹുവേ, അശക്തത, മടി, ലുബ്ധത, ഭീരുത്വം, വാർദ്ധക്യം, ഖബ്റിലെ ശിക്ഷ എന്നിവയിൽ നിന്ന് നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു. അല്ലാഹുവേ, എന്റെ ശരീരത്തിന് യഥാർത്ഥ തഖ്‌വ നൽകുകയും അതിനെ സംസ്കരിക്കുകയും ചെയ്യേണമേ. ശരീരത്തെ സംസ്കരിക്കുന്നവരിൽ ഏറ്റവും ഉത്തമൻ നീയാണ്, അതിന്റെ രക്ഷാധികാരിയും യജമാനനും നീയാണ്. അല്ലാഹുവേ, ഭക്തി വരാത്ത ഹൃദയത്തിൽ നിന്നും, വയർ നിറയാത്ത ശരീരത്തിൽ നിന്നും, ഉപകാരമില്ലാത്ത അറിവിൽ നിന്നും, ഉത്തരം ചെയ്യപ്പെടാത്ത പ്രാർത്ഥനയിൽ നിന്നും നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു." (ന)', 'زَيْدِ بْنِ أَرْقَمَ', 'സൈദുബ്നു അർഖം(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 989, 990, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=140 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 317, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْفَقْرِ، وَأَعُوذُ بِكَ مِنَ الْقِلَّةِ وَالذِّلَّةِ، وَأَعُوذُ بِكَ أَنْ أَظْلِمَ أَوْ أُظْلَمَ". وَفِي رِوَايَةٍ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "تَعَوَّذُوا بِاللَّهِ مِنَ الْفَقْرِ وَالْقِلَّةِ وَالذِّلَّةِ، وَأَنْ تَظْلِمَ أَوْ تُظْلَمَ". وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْقِلَّةِ وَالْفَقْرِ وَالذِّلَّةِ، وَأَعُوذُ بِكَ أَنْ أَظْلِمَ أَوْ أُظْلَمَ". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുമായിരുന്നു: "അല്ലാഹുവേ, ദാരിദ്ര്യത്തിൽ നിന്ന് നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു, നിന്ദ്യതയിൽ നിന്നും കുറവുകളിൽ നിന്നും നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു, അക്രമിക്കുകയോ, അക്രമിക്കപ്പെടുകയോ ചെയ്യുന്നതിൽ നിന്നും നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=317), 1, 'وَفِي رِوَايَةٍ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "تَعَوَّذُوا بِاللَّهِ مِنَ الْفَقْرِ وَالْقِلَّةِ وَالذِّلَّةِ، وَأَنْ تَظْلِمَ أَوْ تُظْلَمَ".', 'മറ്റൊരു നിവേദനം: നബി(സ) പറഞ്ഞു: "ദാരിദ്ര്യത്തിൽ നിന്നും, കുറവിൽ നിന്നും, നിന്ദ്യതയിൽ നിന്നും നീ അക്രമിക്കുകയോ, അക്രമിക്കപ്പെടുകയോ ചെയ്യുന്നതിൽ നിന്നും നിങ്ങൾ അല്ലാഹുവിനോട് അഭയം ചോദിക്കുക."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=317), 2, 'وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْقِلَّةِ وَالْفَقْرِ وَالذِّلَّةِ، وَأَعُوذُ بِكَ أَنْ أَظْلِمَ أَوْ أُظْلَمَ". (ن)', 'മറ്റൊരു നിവേദനം: നബി തങ്ങൾ പറയുമായിരുന്നു: "അല്ലാഹുവേ, കുറവിൽ നിന്നും ദാരിദ്ര്യത്തിൽ നിന്നും നിന്ദ്യതയിൽ നിന്നും ഞാൻ നിന്നോട് അഭയം ചോദിക്കുന്നു. ഞാൻ അക്രമിക്കുകയോ, അക്രമിക്കപ്പെടുകയോ ചെയ്യുന്നതിൽ നിന്നും നിന്നോട് അഭയം ചോദിക്കുന്നു." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 318, 'عَنْ مُسْلِمِ بْنِ أَبِي بَكْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ كَانَ سَمِعَ وَالِدَهُ رَضِيَ اللهُ عَنْهُ يَقُولُ فِي دُبُرِ الصَّلَاةِ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، وَعَذَابِ الْقَبْرِ". فَجَعَلْتُ أَدْعُو بِهِنَّ، فَقَالَ: يَا بُنَيَّ، أَنَّى عَلِمْتَ هَؤُلَاءِ الْكَلِمَاتِ؟ قُلْتُ: يَا أَبَتِ، سَمِعْتُكَ تَدْعُو بِهِنَّ فِي دُبُرِ الصَّلَاةِ، فَأَخَذْتُهُنَّ عَنْكَ. قَالَ: فَالْزَمْهُنَّ يَا بُنَيَّ، فَإِنَّ نَبِيَّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَدْعُو بِهِنَّ فِي دُبُرِ الصَّلَاةِ. (ن)', 'മുസ്‌ലിമുബ്നു അബീബക്‌റ(റ): തന്റെ പിതാവ് നിസ്കാര ശേഷം പറയുന്നതായി അദ്ദേഹം കേട്ടു: ''അല്ലാഹുവേ, സത്യ നിഷേധത്തിൽ നിന്നും ദാരിദ്ര്യത്തിൽ നിന്നും ഖബ്‌റിലെ ശിക്ഷയിൽ നിന്നും നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു.'' അങ്ങനെ ഞാൻ അപ്രകാരം പ്രാർത്ഥിക്കാൻ തുടങ്ങി. പിതാവ് പറഞ്ഞു: പൊന്നു മോനേ, നിനക്ക് എവിടെ നിന്നാണ് ഈ വാക്കുകൾ പഠിപ്പിക്കപ്പെട്ടത്? ഞാൻ പറഞ്ഞു: വന്ദ്യ പിതാവേ, നിസ്കാരശേഷം അങ്ങ് ഇവ ദുആ ചെയ്യുന്നത് ഞാൻ കേട്ടു, അങ്ങനെ ഞാൻ നിങ്ങളിൽ നിന്നും അത് മനഃപാഠമാക്കി. പിതാവ് പറഞ്ഞു: പൊന്നുമോനേ, ഇവ എപ്പോഴും കൊണ്ടു നടക്കുക. കാരണം നബി(സ) നിസ്കാരത്തിന് ശേഷം ഇവ പ്രാർത്ഥിക്കാറുണ്ടായിരുന്നു. (ന)', 'مُسْلِمِ بْنِ أَبِي بَكْرَةَ', 'മുസ്‌ലിമുബ്നു അബീബക്‌റ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 990, 990, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=141 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 319, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَثِيرًا مَا يَدْعُو بِهؤُلَاءِ الْكَلِمَاتِ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ فِتْنَةِ النَّارِ وَعَذَابِ النَّارِ، وَفِتْنَةِ الْقَبْرِ وَعَذَابِ الْقَبْرِ، وَشَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ، وَشَرِّ فِتْنَةِ الْفَقْرِ، وَشَرِّ فِتْنَةِ الْغِنَى. اللَّهُمَّ اغْسِلْ خَطَايَايَ بِمَاءِ الثَّلْجِ وَالْبَرَدِ، وَأَنْقِ قَلْبِي مِنَ الْخَطَايَا كَمَا أَنْقَيْتَ الثَّوْبَ الْأَبْيَضَ مِنَ الدَّنَسِ. وَبَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ. اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكَسَلِ وَالْهَرَمِ، وَالْمَأْثَمِ وَالْمَغْرَمِ." (ن)', 'ആഇശ(റ): നബി(സ) തങ്ങൾ ഈ വാക്കുകൾ കൊണ്ട് ധാരാളം പ്രാർത്ഥിക്കുമായിരുന്നു. "അല്ലാഹുവേ, നരകത്തിന്റെ പരീക്ഷണത്തിൽ നിന്നും, നരകശിക്ഷയിൽ നിന്നും, ഖബ്‌റിലെ പരീക്ഷണത്തിൽ നിന്നും, ഖബ്‌റിലെ ശിക്ഷയിൽ നിന്നും, ലോകം മുഴുവൻ ചുറ്റുന്ന ദജ്ജാലിന്റെ ഫിത്‌നയുടെ നാശത്തിൽ നിന്നും നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു. അല്ലാഹുവേ, മഞ്ഞ് കൊണ്ടും (ആലിപ്പഴം) തണുത്ത വെള്ളം കൊണ്ടും എന്റെ പാപങ്ങളെ നീ കഴുകണേ. അഴുക്കുകളിൽ നിന്നും വെള്ള വസ്ത്രത്തെ നീ ശുദ്ധിയാക്കുന്നത് പോലെ പാപമാലിന്യങ്ങളിൽ നിന്നും എന്റെ ഹൃദയത്തെ നീ ശുദ്ധിയാക്കേണമേ. ഉദയാസ്തമന സ്ഥാനങ്ങളെ പരസ്പരം നീ അകറ്റിനിർത്തിയ പോലെ എന്നിൽ നിന്ന് എന്റെ പാപങ്ങളെ നീ അകറ്റി നിർത്തേണമേ. അല്ലാഹുവേ, അലസത, വാർദ്ധക്യ സഹജമായ വിഷമങ്ങൾ, കുറ്റകൃത്യം, കടബാധ്യത എന്നിവയിൽ നിന്ന് നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 991, 991, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=142 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 320, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْجُوعِ، فَإِنَّهُ بِئْسَ الضَّجِيعُ. وَأَعُوذُ بِكَ مِنَ الْخِيَانَةِ، فَإِنَّهَا بِئْسَتِ الْبِطَانَةُ." (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) തങ്ങൾ പറയുമായിരുന്നു: "അല്ലാഹുവേ, വിശപ്പിൽ നിന്ന് നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു. കാരണം, അത് ഏറ്റവും മോശപ്പെട്ട സഹചാരിയാണ്. വഞ്ചനയിൽ നിന്ന് നിന്നോട് ഞാൻ അഭയം ചോദിക്കുന്നു. കാരണം മനുഷ്യൻ ഒളിപ്പിച്ചു വെക്കുന്ന ഏറ്റവും മോശപ്പെട്ട വസ്തുവാണത്." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 991, 991, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=143 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 321, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَدْعُو: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الشِّقَاقِ وَالنِّفَاقِ وَسُوءِ الْأَخْلَاقِ." (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പ്രാർത്ഥിക്കുമായിരുന്നു: "ഭിന്നിപ്പിൽ നിന്നും കാപട്യത്തിൽ നിന്നും ചീത്ത സ്വഭാവത്തിൽ നിന്നും നിന്നോട് ഞാൻ തേടുന്നു." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 991, 991, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=144 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 322, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "أَعُوذُ بِاللَّهِ مِنَ الْكُفْرِ وَالدَّيْنِ". قَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ، أَتَعْدِلُ الدَّيْنَ بِالْكُفْرِ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "نَعَمْ". (ن)', 'അബൂസഈദ്(റ): റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "കടത്തിൽ നിന്നും സത്യനിഷേധത്തിൽ നിന്നും ഞാൻ അല്ലാഹുവിനോട് കാവൽ ചോദിക്കുന്നു." ഒരു വ്യക്തി ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, സത്യനിഷേധവും കടവും സമമാണോ? റസൂൽ(സ) പറഞ്ഞു: "അതെ" (ന)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 992, 992, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=145 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 323, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَدْعُو بِهؤُلَاءِ الْكَلِمَاتِ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ، وَغَلَبَةِ الْعَدُوِّ، وَشَمَاتَةِ الْأَعْدَاءِ". (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) തങ്ങൾ ഈ വാക്കുകൾ കൊണ്ട് പ്രാർത്ഥിക്കുമായിരുന്നു: "അല്ലാഹുവേ, കടങ്ങൾ അധികമാകുന്നതിൽ നിന്നും ശത്രുക്കൾ വർദ്ധിക്കുന്നതിൽ നിന്നും ശത്രുക്കൾ സന്തോഷിക്കുന്നതിൽ നിന്നും നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു." (ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 992, 992, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=145 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 324, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: قَالَتْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَكْثَرَ مَا يَتَعَوَّذُ مِنَ الْمَغْرَمِ وَالْمَأْثَمِ. قُلْتُ: يَا رَسُولَ اللَّهِ، مَا أَكْثَرَ مَا تَتَعَوَّذُ مِنَ الْمَغْرَمِ؟ قَالَ: إِنَّهُ مَنْ غَرِمَ حَدَّثَ فَكَذَبَ وَوَعَدَ فَأَخْلَفَ". (ن)', 'ആഇശ(റ): റസൂൽ(സ) കടത്തിൽ നിന്നും കുറ്റകൃത്യത്തിൽ നിന്നും ധാരാളം കാവൽ ചോദിക്കുമായിരുന്നു. ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങ് കടത്തിൽ നിന്നും ഇത്രമാത്രം കാവൽ ചോദിക്കുന്നത് എന്താണ്? റസൂൽ(സ) പറഞ്ഞു: "തീർച്ചയായും ആരെങ്കിലും കടക്കാരനായാൽ അവൻ സംസാരിച്ചാൽ കളവ് പറയും, വാഗ്ദത്തം ചെയ്താൽ ലംഘിക്കുകയും ചെയ്യും." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 992, 992, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=145 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 325, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: قَالَتْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَكْثَرَ مَا يَتَعَوَّذُ مِنَ الْمَغْرَمِ وَالْمَأْثَمِ. قُلْتُ: يَا رَسُولَ اللَّهِ، مَا أَكْثَرَ مَا تَتَعَوَّذُ مِنَ الْمَغْرَمِ؟ قَالَ: إِنَّهُ مَنْ غَرِمَ حَدَّثَ فَكَذَبَ وَوَعَدَ فَأَخْلَفَ". (ن)', 'ആഇശ(റ): റസൂൽ(സ) കടത്തിൽ നിന്നും കുറ്റകൃത്യത്തിൽ നിന്നും ധാരാളം കാവൽ ചോദിക്കുമായിരുന്നു. ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങ് കടത്തിൽ നിന്നും ഇത്രമാത്രം കാവൽ ചോദിക്കുന്നത് എന്താണ്? റസൂൽ(സ) പറഞ്ഞു: "തീർച്ചയായും ആരെങ്കിലും കടക്കാരനായാൽ അവൻ സംസാരിച്ചാൽ കളവ് പറയും, വാഗ്ദത്തം ചെയ്താൽ ലംഘിക്കുകയും ചെയ്യും." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 992, 992, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=145 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 326, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا خَرَجَ مِنْ بَيْتِهِ قَالَ: "بِسْمِ اللَّهِ، رَبِّ أَعُوذُ بِكَ مِنْ أَنْ أَزِلَّ أَوْ أَضِلَّ، أَوْ أَظْلِمَ أَوْ أُظْلَمَ، أَوْ أَجْهَلَ أَوْ يُجْهَلَ عَلَيَّ". (ن)', 'ഉമ്മുസലമ(റ): നബി(സ) വീട്ടിൽ നിന്നിറങ്ങുമ്പോൾ ഇങ്ങനെ പറയുമായിരുന്നു: "അല്ലാഹുവിന്റെ നാമത്തിൽ, എന്റെ രക്ഷിതാവേ, ഞാൻ വഴുതിപ്പോകുകയോ, വഴി പിഴപ്പിക്കപ്പെടുകയോ ചെയ്യുന്നതിൽ നിന്നും ഞാൻ അക്രമിക്കുകയോ, അക്രമിക്കപ്പെടുകയോ ചെയ്യുന്നതിൽ നിന്നും, ഞാൻ അജ്ഞനാവുകയോ, എനിക്ക് അജ്ഞാതമാക്കപ്പെടുകയോ ചെയ്യുന്നതിൽ നിന്നും നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു.” (ന)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 992, 993, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=146 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 327, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَعَوَّذُ مِنْ هَذِهِ الثَّلَاثَةِ: مِنْ دَرَكِ الشَّقَاءِ، وَشَمَاتَةِ الْأَعْدَاءِ، وَسُوءِ الْقَضَاءِ، وَجَهْدِ الْبَلَاءِ. قَالَ سُفْيَانُ: هُوَ ثَلَاثَةٌ، فَذَكَرْتُ أَرْبَعَةً لِأَنِّي لَا أَحْفَظُ الْوَاحِدَ الَّذِي لَيْسَ فِيهِ. (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) മൂന്ന് കാര്യങ്ങളിൽ നിന്ന് കാവൽ ചോദിക്കാറുണ്ടായിരുന്നു: വിധി മോശത്തിൽ നിന്ന്, ശത്രുക്കൾ സന്തോഷിക്കുന്നതിൽ നിന്ന്, പരാജയം ഭവിക്കുന്നതിൽ നിന്ന്, കഠിനമായ പരീക്ഷണങ്ങളിൽ നിന്ന്. സുഫ്‌യാൻ(റ) പറഞ്ഞു: ഇത് മൂന്നെണ്ണമാണ്, ഞാൻ നാലെണ്ണമാണ് പറഞ്ഞത്, ഇതിലില്ലാത്ത ഒന്ന് ഏതാണെന്ന് ഞാനോർക്കുന്നില്ല. (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 993, 993, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=147 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 328, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْجُنُونِ وَالْجُذَامِ وَالْبَرَصِ وَسَيِّئِ الْأَسْقَامِ". (ن)', 'അനസ്(റ): "അല്ലാഹുവേ, ഭ്രാന്തിൽ നിന്നും കുഷ്ഠത്തിൽ നിന്നും വെള്ളപ്പാണ്ടിൽ നിന്നും മോശപ്പെട്ട എല്ലാ അസുഖങ്ങളിൽ നിന്നും നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു." എന്ന് നബി(സ) പറയാറുണ്ടായിരുന്നു. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 993, 993, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=148 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 329, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَعَوَّذُ مِنْ عَيْنِ الْجَانِّ وَعَيْنِ الْإِنْسِ، فَلَمَّا نَزَلَتِ الْمُعَوَّذَتَانِ أَخَذَ بِهِمَا وَتَرَكَ مَا سِوَى ذَلِكَ. (ن)', 'അബൂസഈദ്(റ): റസൂൽ(സ) തങ്ങൾ ജിന്ന് വർഗ്ഗത്തിന്റെയും മനുഷ്യവർഗത്തിന്റെയും കണ്ണിൽ നിന്നും അഭയം ചോദിക്കാറുണ്ടായിരുന്നു. അങ്ങനെ മുഅവ്വിദതൈനി (സൂറതുൽഫലഖ്, സൂറതുന്നാസ്) ഇറങ്ങിയപ്പോൾ അത് കൈക്കൊള്ളുകയും മറ്റുള്ളത് ഉപേക്ഷിക്കുകയും ചെയ്തു. (ന)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 993, 993, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=148 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 330, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَعَوَّذُ بِهَؤُلَاءِ الْكَلِمَاتِ، كَانَ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكَسَلِ وَالْهَرَمِ، وَالْجُبْنِ وَالْبُخْلِ، وَسُوءِ الْكِبَرِ، وَفِتْنَةِ الدَّجَّالِ، وَعَذَابِ الْقَبْرِ". (ن)', 'അനസ്(റ): റസൂൽ(സ) തങ്ങൾ ഈ വാക്യങ്ങൾ കൊണ്ട് അഭയം ചോദിക്കാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ, അലസത, വാർദ്ധക്യസഹജമായ വിഷമങ്ങൾ, ഭീരുത്വം, ലുബ്ധത, മോശപ്പെട്ട അഹങ്കാരം, ദജ്ജാലിന്റെ ഫിത്ന, ഖബ്‌റിലെ ശിക്ഷ എന്നിവയിൽ നിന്ന് നിന്നോട് ഞാൻ അഭയം ചോദിക്കുന്നു." (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 993, 993, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=149 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 331, 'عَنْ عَبْدِ اللَّهِ بْنِ سَرْجِسَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا سَافَرَ قَالَ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ، وَكَآبَةِ الْمُنْقَلَبِ، وَالْحَوْرِ بَعْدَ الْكَوْرِ، وَدَعْوَةِ الْمَظْلُومِ، وَسُوءِ الْمَنْظَرِ فِي الْأَهْلِ وَالْمَالِ - وفي رواية - وَالْوَلَدِ". (ن)', 'അബ്ദുല്ലാഹിബ്നു സർജിസ്(റ): റസൂൽ(സ) യാത്രക്കൊരുങ്ങിയാൽ "അല്ലാഹുവേ, യാത്രയുടെ ക്ലേശങ്ങളിൽ നിന്നും, ദുഃഖകരമായ മടക്കത്തിൽ നിന്നും, അഭിവൃദ്ധിക്ക് ശേഷം വരുന്ന നാശത്തിൽ നിന്നും അക്രമിക്കപ്പെട്ടവന്റെ പ്രാർത്ഥനയിൽ നിന്നും, കുടുംബത്തിലും സമ്പത്തിലുമുള്ള നീചമായ കാഴ്ചയിൽ നിന്നും, നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു." മറ്റൊരു നിവേദനത്തിൽ "സന്താനങ്ങളിലുള്ള നീചമായ കാഴ്ചയിൽ നിന്നും കാവൽ ചോദിക്കുന്നു" എന്നാണുള്ളത്. (ന)', 'عَبْدِ اللَّهِ بْنِ سَرْجِسَ', 'അബ്ദുല്ലാഹിബ്നു സർജിസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 994, 994, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=150 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=331), 1, 'وَفِي رِوَايَةٍ - وَالْوَلَدِ". (ن)', 'മറ്റൊരു നിവേദനത്തിൽ "സന്താനങ്ങളിലുള്ള നീചമായ കാഴ്ചയിൽ നിന്നും കാവൽ ചോദിക്കുന്നു" എന്നാണുള്ളത്. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 332, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا سَافَرَ فَرَكِبَ رَاحِلَتَهُ قَالَ بِإِصْبِعِهِ - وَمَدَّ شُعْبَةُ بِإِصْبِعِهِ - قَالَ: "اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ، وَالْخَلِيفَةُ فِي الْأَهْلِ وَالْمَالِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ وَكَآبَةِ الْمُنْقَلَبِ". (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) യാത്ര പുറപ്പെടുമ്പോൾ വാഹനത്തിൽ കയറി തന്റെ വിരൽ ചുണ്ടി പറയുമായിരുന്നു: - ശുഅ്ബ അതുപോലെ വിരൽ നീട്ടി - "അല്ലാഹുവേ, യാത്രയിലെ സഹവാസിയും, സമ്പത്തിന്റെയും കുടുംബത്തിലെയും പ്രതിനിധിയും നീയാണ്, അല്ലാഹുവേ യാത്രയുടെ ക്ലേശങ്ങളിൽ നിന്നും (ജീവിത) ചലനങ്ങളിലുള്ള പ്രയാസങ്ങളിൽ നിന്നും നിന്നോട് ഞാൻ അഭയം ചോദിക്കുന്നു." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 994, 994, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=150 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 333, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "تَعَوَّذُوا بِاللَّهِ مِنْ جَارِ السَّوْءِ فِي دَارِ الْمُقَامِ، فَإِنَّ جَارَ الْبَادِيَةِ يَتَحَوَّلُ عَنْكَ". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ താമസിക്കുന്ന സ്ഥലത്തെ ചീത്ത അയൽവാസിയിൽ നിന്നും അല്ലാഹുവിൽ അഭയം പ്രാപിക്കുക. കാരണം, നിശ്ചയമായും അയൽക്കാരൻ നിന്നിൽ നിന്നും അകന്നുപോകും." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 994, 994, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=151 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 334, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: دَخَلْتُ الْمَسْجِدَ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيهِ، فَجِئْتُ فَجَلَسْتُ إِلَيْهِ، فَقَالَ: "يَا أَبَا ذَرٍّ، تَعَوَّذْ بِاللَّهِ مِنْ شَرِّ شَيَاطِينِ الْجِنِّ وَالْإِنْسِ". قُلْتُ: أَوْ لِلْإِنْسِ شَيَاطِينُ؟ قَالَ: "نَعَمْ". (ن)', 'അബുദർറ്(റ): റസൂൽ(സ) പള്ളിയിലുണ്ടായിരിക്കെ ഞാൻ പള്ളിയിൽ പ്രവേശിച്ചു. ഞാൻ റസൂൽ(സ)യുടെ അടുത്ത് ചെന്ന് അരികിലിരുന്നു. റസൂൽ(സ) പറഞ്ഞു: “അബുദർറേ, മനുഷ്യരിലെയും ജിന്നുകളിലെയും പിശാചുക്കളിൽ നിന്ന് അല്ലാഹുവിൽ നീ അഭയം ചോദിക്കുക.” ഞാൻ ചോദിച്ചു: മനുഷ്യരിലുമുണ്ടോ പിശാചുക്കൾ? നബി(സ) പറഞ്ഞു: “അതെ.” (ന)', 'أَبِي ذَرٍّ', 'അബുദർറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 994, 995, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=152 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 335, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَسْتَعِيذُ بِاللَّهِ مِنْ عَذَابِ الْقَبْرِ، وَمِنْ فِتْنَةِ الدَّجَّالِ. وَقَالَ: "إِنَّكُمْ تُفْتَنُونَ فِي قُبُورِكُمْ". (ن)', 'ആഇശ(റ): നബി(സ) ഖബ്‌റിലെ ശിക്ഷയിൽ നിന്നും, ദജ്ജാലിന്റെ ഫിത്നയിൽ നിന്നും അല്ലാഹുവിനോട് അഭയം ചോദിക്കുമായിരുന്നു. നബി(സ) പറഞ്ഞു: "നിശ്ചയമായും നിങ്ങൾ നിങ്ങളുടെ ഖബ്‌റുകളിൽ പരീക്ഷിക്കപ്പെടും." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 995, 995, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=153 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 336, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "عُوذُوا بِاللَّهِ مِنْ عَذَابِ الْقَبْرِ، عُوذُوا بِاللَّهِ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، عُوذُوا بِاللَّهِ مِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ". وفي رواية: كَانَ يَتَعَوَّذُ مِنْ خَمْسٍ، يَقُولُ: "عُوذُوا بِاللَّهِ مِنْ عَذَابِ الْقَبْرِ، وَمِنْ عَذَابِ جَهَنَّمَ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَمِنْ شَرِّ الْمَسِيحِ الدَّجَّالِ". وفي رواية: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ أَطَاعَنِي فَقَدْ أَطَاعَ اللَّهَ، وَمَنْ عَصَانِي فَقَدْ عَصَى اللَّهَ". وَكَانَ يَتَعَوَّذُ مِنْ عَذَابِ الْقَبْرِ، وَعَذَابِ جَهَنَّمَ، وَفِتْنَةِ الْأَحْيَاءِ وَالأَمْوَاتِ، وَفِتْنَةِ الْمَسِيحِ الدَّجَّالِ . وفي رواية قَالَ: وَقَالَ - يَعْنِي - النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اسْتَعِيذُوا بِاللَّهِ مِنْ خَمْسٍ: مِنْ عَذَابِ جَهَنَّمَ، وَعَذَابِ الْقَبْرِ، وَفِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَفِتْنَةِ الْمَسِيحِ الدَّجَّالِ". (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഖബ്‌റിലെ ശിക്ഷയിൽ നിന്ന് നിങ്ങൾ അല്ലാഹുവിനോട് കാവൽ ചോദിക്കുക, ജീവിത മരണങ്ങളിലെ ഫിത്നയിൽ നിന്ന് നിങ്ങൾ അല്ലാഹുവിനോട് കാവൽ ചോദിക്കുക. ലോകം ചുറ്റുന്ന ദജ്ജാലിന്റെ ഫിത്നയിൽ നിന്ന് നിങ്ങൾ അല്ലാഹുവിനോട് കാവൽ ചോദിക്കുക."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=336), 1, 'وَفِي رِوَايَةٍ: كَانَ يَتَعَوَّذُ مِنْ خَمْسٍ، يَقُولُ: "عُوذُوا بِاللَّهِ مِنْ عَذَابِ الْقَبْرِ، وَمِنْ عَذَابِ جَهَنَّمَ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَمِنْ شَرِّ الْمَسِيحِ الدَّجَّالِ".', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) അഞ്ച് കാര്യങ്ങളിൽ നിന്ന് അഭയം ചോദിക്കുമായിരുന്നു: റസൂൽ(സ) പറയും: "നിങ്ങൾ ഖബ്‌റിലെ ശിക്ഷയിൽ നിന്നും നരകശിക്ഷയിൽ നിന്നും ജീവിതമരണങ്ങളിലെ ഫിത്നയിൽ നിന്നും മസീഹുദ്ദജ്ജാലിന്റെ നാശത്തിൽ നിന്നും അല്ലാഹുവിനോട് അഭയം ചോദിക്കുക."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=336), 2, 'وَفِي رِوَايَةٍ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ أَطَاعَنِي فَقَدْ أَطَاعَ اللَّهَ، وَمَنْ عَصَانِي فَقَدْ عَصَى اللَّهَ". وَكَانَ يَتَعَوَّذُ مِنْ عَذَابِ الْقَبْرِ، وَعَذَابِ جَهَنَّمَ، وَفِتْنَةِ الْأَحْيَاءِ وَالأَمْوَاتِ، وَفِتْنَةِ الْمَسِيحِ الدَّجَّالِ .', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "എന്നെ ആരെങ്കിലും അനുസരിച്ചാൽ തീർച്ചയായും അവൻ അല്ലാഹുവിനെ അനുസരിച്ചിരിക്കുന്നു, ആരെങ്കിലും എന്നോട് അനുസരണക്കേട് കാണിച്ചാൽ തീർച്ചയായും അവൻ അല്ലാഹുവിനോട് അനുസരണക്കേട് കാണിച്ചിരിക്കുന്നു." നബി(സ) ഖബർ ശിക്ഷയിൽ നിന്നും, നരക ശിക്ഷയിൽ നിന്നും, ജീവിച്ചിരിക്കുന്നവരുടെയും മരിച്ചവരുടെയും ഫിത്നയിൽ നിന്നും, മസീഹുദ്ദജ്ജാലിന്റെ ഫിത്നയിൽ നിന്നും കാവൽ ചോദിക്കുമായിരുന്നു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=336), 3, 'وَفِي رِوَايَةٍ قَالَ: وَقَالَ - يَعْنِي - النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اسْتَعِيذُوا بِاللَّهِ مِنْ خَمْسٍ: مِنْ عَذَابِ جَهَنَّمَ، وَعَذَابِ الْقَبْرِ، وَفِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَفِتْنَةِ الْمَسِيحِ الدَّجَّالِ". (ن)', 'മറ്റൊരു നിവേദനം: നബി(സ) പറഞ്ഞു: "അഞ്ച് കാര്യങ്ങളിൽ നിന്നും നിങ്ങൾ അല്ലാഹുവിനോട് കാവൽ ചോദിക്കുക: നരക ശിക്ഷ, ഖബർ ശിക്ഷ, ജീവിതത്തിലെ ഫിത്ന, മരണത്തിലെ ഫിത്ന, മസീഹുദ്ദജ്ജാലിന്റെ ഫിത്ന." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 337, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اللَّهُمَّ رَبَّ جَبْرَائِيلَ وَمِيكَائِيلَ، وَرَبَّ إِسْرَافِيلَ، أَعُوذُ بِكَ مِنْ حَرِّ النَّارِ، وَمِنْ عَذَابِ الْقَبْرِ". (ن)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഇസ്റാഫീലി(അ)ന്റെയും ജിബ്‌രീൽ(അ)ന്റെയും മീകാഈൽ(അ)ന്റെയും നാഥനായ അല്ലാഹുവേ, നിന്നോട് നരകത്തിന്റെ ചൂടിൽ നിന്നും, ഖബ്‌റിലെ ശിക്ഷയിൽ നിന്നും ഞാൻ അഭയം ചോദിക്കുന്നു." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 996, 996, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=153 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 338, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: قَالَ: سَمِعْتُ أَبَا الْقَاسِمِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ فِي صَلَاتِهِ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ فِتْنَةِ الْقَبْرِ، وَمِنْ فِتْنَةِ الدَّجَّالِ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَمِنْ حَرِّ جَهَنَّمَ". (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) നിസ്കാരത്തിൽ പറയുന്നതായി ഞാൻ കേട്ടു: "അല്ലാഹുവേ, ഖബ്‌റിലെ ഫിത്‌നയിൽ നിന്നും ദജ്ജാലിന്റെ ഫിത്‌നയിൽ നിന്നും, ജീവിതത്തിലെയും മരണത്തിലെയും ഫിത്‌നയിൽ നിന്നും നരകത്തിന്റെ ചൂടിൽ നിന്നും നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 996, 996, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=153 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 339, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ سَأَلَ اللَّهَ الْجَنَّةَ ثَلَاثَ مَرَّاتٍ قَالَتِ الْجَنَّةُ: اللَّهُمَّ أَدْخِلْهُ الْجَنَّةَ. وَمَنِ اسْتَجَارَ مِنَ النَّارِ ثَلَاثَ مَرَّاتٍ قَالَتِ النَّارُ: اللَّهُمَّ أَجِرْهُ مِنَ النَّارِ". (ن)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും അല്ലാഹുവിനോട് മൂന്ന് പ്രാവശ്യം സ്വർഗ്ഗം ചോദിച്ചാൽ സ്വർഗ്ഗം പറയും: അല്ലാഹുവേ, അവനെ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കണേ, ആരെങ്കിലും നരകത്തെ തൊട്ട് മൂന്ന് പ്രാവശ്യം കാവൽ ചോദിച്ചാൽ നരകം പറയും: അല്ലാഹുവേ, നരകത്തെ തൊട്ട് അവനെ കാക്കണേ. (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 996, 996, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=153 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 340, 'عَنْ شَدَّادِ بْنِ أَوْسٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ سَيِّدَ الِاسْتِغْفَارِ أَنْ يَقُولَ الْعَبْدُ: اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي، وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِذَنْبِي، وَأَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، فَاغْفِرْ لِي، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ. فَإِنْ قَالَهَا حِينَ يُصْبِحُ مُوقِنًا بِهَا فَمَاتَ دَخَلَ الْجَنَّةَ، وَإِنْ قَالَهَا حِينَ يُمْسِي مُوقِنًا بِهَا دَخَلَ الْجَنَّةَ". (ن)', 'ശദ്ദാദുബ്‌നു ഔസ്(റ): നബി(സ) പറഞ്ഞു: "പാപമോചന പ്രാർത്ഥനയിലെ പ്രധാന പ്രാർത്ഥന: ഒരു അടിമ പറയലാണ്: അല്ലാഹുവേ, നീയാണെന്റെ നാഥൻ, നീയല്ലാതെ ഒരു ആരാധ്യനുമില്ല. നീ എന്നെ സൃഷ്ടിച്ചു, ഞാൻ നിന്റെ അടിമയാണ്, എന്റെ കഴിവിന്റെ പരമാവധി നിന്നോടുള്ള കരാറിലും ഉടമ്പടിയിലുമാണ് നീങ്ങിക്കൊണ്ടിരിക്കുന്നത്, നീ സൃഷ്ടിച്ചവയുടെ നാശത്തിൽ നിന്ന് നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു, ഞാൻ ചെയ്ത പാപങ്ങൾ നിനക്ക് മുന്നിൽ ഞാൻ സമ്മതിക്കുന്നു. നീ എനിക്ക് ചെയ്ത അനുഗ്രഹവും ഞാൻ സമ്മതിക്കുന്നു, അത് കൊണ്ട് എനിക്ക് പൊറുത്ത് തരണേ. കാരണം നീയല്ലാതെ ആരും പാപങ്ങൾ പൊറുക്കുകയില്ല." ഇത് ആരെങ്കിലും മനസ്സുറപ്പിച്ചവനായി പ്രഭാതത്തിൽ പറഞ്ഞ്, ശേഷം മരണപ്പെട്ടാൽ അവൻ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുന്നതാണ്. ദൃഢചിത്തനായി പ്രദോഷ സമയത്താണ് ചൊല്ലിയതെങ്കിൽ അവൻ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുന്നതാണ്." (ന)', 'شَدَّادِ بْنِ أَوْسٍ', 'ശദ്ദാദുബ്‌നു ഔസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 996, 996, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=154 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 341, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، وَقَدْ سُئِلَتْ: مَا كَانَ أَكْثَرُ مَا يَدْعُو بِهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَبْلَ مَوْتِهِ؟ قَالَتْ: كَانَ أَكْثَرُ مَا كَانَ يَدْعُو بِهِ - وَفِي رِوَايَةٍ: كَانَ أَكْثَرُ دُعَائِهِ أَنْ يَقُولَ: - "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا عَمِلْتُ، وَمِنْ شَرِّ مَا لَمْ أَعْمَلْ". - وفي رواية - بَعْدُ". (ن)', 'ആഇശ(റ): മഹതി ചോദിക്കപ്പെട്ടു: റസൂൽ(സ) മരണത്തിന് മുമ്പ് ഏറ്റവുമധികം പ്രാർത്ഥിച്ചിരുന്ന ദുആ ഏതാണ്? മഹതി പറഞ്ഞു: റസൂൽ(സ) അധികവും പ്രാർത്ഥിക്കാറുണ്ടായിരുന്നത് ഈ ദുആയാണ്: "അല്ലാഹുവേ, ഞാൻ പ്രവർത്തിച്ചതിന്റെ നാശത്തിൽ നിന്നും, ഞാൻ പ്രവർത്തിച്ചിട്ടില്ലാത്തതിന്റെ നാശത്തിൽ നിന്നും നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=341), 1, 'وَفِي رِوَايَةٍ: كَانَ أَكْثَرُ دُعَائِهِ أَنْ يَقُولَ: - "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا عَمِلْتُ، وَمِنْ شَرِّ مَا لَمْ أَعْمَلْ". -', 'മറ്റൊരു നിവേദനത്തിൽ: ''ഇത് വരെ'' (പ്രവർത്തിച്ചിട്ടില്ലാത്ത) എന്നും ചേർക്കപ്പെട്ടിരിക്കുന്നു. (ന)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=13 and h.hadith_no=341), 2, 'وَفِي رِوَايَةٍ - بَعْدُ". (ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 342, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ - بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي". (يعنى بذلك الْخَسْفَ) (ن)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പ്രാർത്ഥിക്കുന്നതായി ഞാൻ കേട്ടു: "അല്ലാഹുവേ, നിന്നോട് നിന്റെ മഹത്വം കൊണ്ട് എന്റെ താഴ്ഭാഗത്ത് കൂടെ ചതിക്കപ്പെടുന്നതിൽ നിന്നും ഞാൻ കാവൽ ചോദിക്കുന്നു." റസൂൽ(സ) അതു കൊണ്ട് ഉദ്ദേശിച്ചത് ഭൂമി വിഴുങ്ങുന്നതിനെയാണ്. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 997, 997, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=155 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 343, 'عَنْ أَبِي الْيَسَرِ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ - يَدْعُو - يَقُولُ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ - الْهَرَمِ وَ - التَّرَدِّي، وَالْهَدْمِ - وَالْغَمِّ - وَالْغَرَقِ وَالْحَرِيقِ، وَأَعُوذُ بِكَ أَنْ يَتَخَبَّطَنِي الشَّيْطَانُ عِنْدَ الْمَوْتِ، وَأَعُوذُ بِكَ أَنْ - أُقْتَلَ - أَمُوتَ فِي سَبِيلِكَ مُدْبِرًا، وَأَعُوذُ بِكَ أَنْ أَمُوتَ لَدِيغًا". (ن)', 'അബുൽ യസ്ർ(റ): റസൂൽ(സ) പ്രാർത്ഥിക്കാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ, വാർദ്ധക്യത്തിൽ നിന്നും (വാർദ്ധക്യ സഹജമായ അവശതകൾ), ഇടിഞ്ഞ് വീഴുന്നതിൽ നിന്നും, തകർക്കപ്പെടുന്നതിൽ നിന്നും ആധിയിൽ നിന്നും മുങ്ങി മരിക്കുന്നതിൽ നിന്നും തീ പിടിക്കുന്നതിൽ നിന്നും നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു. മരണ സമയത്ത് എന്നിൽ പിശാച് ആധിപത്യം ചെലുത്തുന്നതിൽ നിന്നും നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു. നിന്റെ മാർഗ്ഗത്തിൽ നിന്ന് പിന്തിരിഞ്ഞവനായ നിലയിൽ കൊല്ലപ്പെടുകയോ മരിക്കുകയോ ചെയ്യുന്നതിൽ നിന്നും നിന്നോട് ഞാൻ അഭയം ചോദിക്കുന്നു. (വിഷ ജന്തുക്കളാൽ) കടിയേൽക്കപ്പെട്ടവനായി മരിക്കുന്നതിൽ നിന്നും നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു." (ന)', 'أَبِي الْيَسَرِ', 'അബുൽ യസ്ർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 997, 997, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=156 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 344, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: طَلَبْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةٍ فِي فِرَاشِي فَلَمْ أُصِبْهُ، فَضَرَبْتُ بِيَدِي عَلَى رَأْسِ الْفِرَاشِ، فَوَقَعَتْ يَدِي عَلَى أَخْمَصِ قَدَمَيْهِ، فَإِذَا هُوَ سَاجِدٌ يَقُولُ: "أَعُوذُ بِعَفْوِكَ مِنْ عِقَابِكَ، وَأَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَأَعُوذُ بِكَ مِنْكَ». (ن)', 'ആഇശ(റ): ഞാൻ ഒരു രാത്രി റസൂൽ(സ)യെ എന്റെ വിരിപ്പിൽ പരതി. പക്ഷെ, റസൂലിനെ എനിക്ക് കിട്ടിയില്ല, അപ്പോൾ എന്റെ കൈ കൊണ്ട് വിരിപ്പിന്റെ തല ഭാഗത്ത് ഞാനടിച്ചു. എന്റെ കൈ റസൂൽ(സ)യുടെ കാൽപാദത്തിനടിയിലാണ് തട്ടിയത്. അപ്പോൾ റസൂൽ(സ) സുജൂദിലാണ്. റസൂൽ(സ) സുജൂദിൽ ഇപ്രകാരം പറഞ്ഞു കൊണ്ടിരിക്കുന്നു: "നിന്റെ മാപ്പ് മുൻനിർത്തി നിന്റെ ശിക്ഷയിൽ നിന്ന് നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു. നിന്റെ തൃപ്തി മുൻനിറുത്തി നിന്റെ കോപത്തിൽ നിന്നും ഞാൻകാവൽ ചോദിക്കുന്നു. നിന്നെ (നിന്റെ ഔദാര്യവും അനുഗ്രഹവും) മുൻ നിർത്തി നിന്നിൽ നിന്ന് (നിന്റെ ശിക്ഷയിൽ നിന്ന്) നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 997, 998, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=157 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 345, 'عَنْ عَاصِمِ بْنِ حُمَيْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْتُ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: بِمَا كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَفْتَتِحُ قِيَامَ اللَّيْلِ؟ قَالَتْ: سَأَلْتَنِي عَنْ شَيْءٍ مَا سَأَلَنِي عَنْهُ أَحَدٌ، كَانَ يُكَبِّرُ عَشْرًا، وَيُسَبِّحُ عَشْرًا، وَيَسْتَغْفِرُ عَشْرًا، وَيَقُولُ: "اللَّهُمَّ اغْفِرْ لِي وَاهْدِنِي وَارْزُقْنِي وَعَافِنِي". وَيَتَعَوَّذُ مِنْ ضِيقِ الْمَقَامِ يَوْمَ الْقِيَامَةِ. (ن)', 'ആസിമുബ്നു ഹുമൈദ്(റ): ഞാൻ ആഇശ(റ)യോട് ചോദിച്ചു: റസൂൽ(സ) ''ഖിയാമുല്ലൈൽ'' - രാത്രി നമസ്കാരം എങ്ങനെയാണ് തുടങ്ങിയിരുന്നത്? മഹതി പറഞ്ഞു: ഒരാളും എന്നോട് ചോദിക്കാത്ത ഒരു ചോദ്യമാണ് നിങ്ങൾ ചോദിച്ചത്. റസൂൽ(സ) പത്ത് തക്ബീർ ചൊല്ലും. പത്ത് തസ്ബീഹ് ചൊല്ലും, പത്ത് വട്ടം പാപമോചനം ചോദിക്കും, എന്നിട്ട് പറയും: "അല്ലാഹുവേ, എനിക്ക് പൊറുത്ത് തരികയും എന്നെ സൻമാർഗ്ഗത്തിലാക്കുകയും നിന്റെ വിഭവങ്ങൾ എനിക്ക് നൽകുകയും എന്നെ സൗഖ്യത്തിലാക്കുകയും ചെയ്യണേ." ശേഷം അന്ത്യനാളിലെ വിഷമ ഘട്ടത്തിൽ നിന്ന് അഭയം ചോദിക്കുകയും ചെയ്യും. (ന)', 'عَاصِمِ بْنِ حُمَيْدٍ', 'ആസിമുബ്നു ഹുമൈദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 998, 998, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=158 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 346, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ مِنْ دُعَاءِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ، وَتَحَوُّلِ عَافِيَتِكَ، وَفُجَاءَةِ نِقْمَتِكَ، وَجَمِيعِ سَخَطِكَ". (م)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): ഇത് റസൂൽ(സ)യുടെ ദുആയിൽപെട്ടതായിരുന്നു: "അല്ലാഹുവേ, നിന്റെ അനുഗ്രഹം നീങ്ങുന്നതിൽനിന്നും, നിന്റെ ഭാഗത്തുനിന്നുള്ള നല്ല ആരോഗ്യം മാറിപ്പോകുന്നതിൽനിന്നും നിന്റെ പെട്ടെന്നുള്ള പരീക്ഷണത്തിൽനിന്നും നിന്റെ എല്ലാ കോപത്തിൽനിന്നും നിന്നോട് ഞാൻ കാവൽ ചോദിക്കുന്നു." (മു)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 998, 998, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=159 where b.volume_id=2 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
